window.CGDD_DATA = {"flow":"%% Stray_Rat script flow\n%% Generated by CGDD/Export Trace Docs. Do not edit by hand.\nflowchart TD\n  AudioManager(\"<b>AudioManager</b><br/>Central audio hub: one-shot SFX, 3D cat/guard footstep loops, and the idle squeak.\")\n  CatCheeseEndScreen(\"<b>CatCheeseEndScreen</b><br/>Win/lose overlay for the legacy cat game: freezes time and shows Game Failed / You Win.\")\n  CatCheeseGame(\"<b>CatCheeseGame</b><br/>Legacy cat-and-cheese game: a cat patrols and the player collects 3 cheeses without being caught.\")\n  CatCheeseTitle(\"<b>CatCheeseTitle</b><br/>Title screen: shows the game name/blurb, starts the game via button or Space/Enter.\")\n  CheeseHud(\"<b>CheeseHud</b><br/>Legacy HUD: top-right cheese counter for the cat-and-cheese game.\")\n  Entry(\"<b>Entry</b><br/>Entry point: Start button that loads SampleScene.\")\n  FirstPersonMove(\"<b>FirstPersonMove</b><br/>Legacy first-person mover for the scene's old FirstPersonController (superseded by NbPlayer).\")\n  Nb(\"<b>Nb</b><br/>Residential-block level data: world bounds, block grid, walkways, spawn, cheese spots, cat routes.\")\n  NbBriefing(\"<b>NbBriefing</b><br/>Pre-fridge rules screen: freezes the player and the door until dismissed by any key/click.\")\n  NbBuilder(\"<b>NbBuilder</b><br/>Builds the residential-block environment: grass, walkways, walls, gate, lamps, trees, bins, planters.\")\n  NbColliders(\"<b>NbColliders</b><br/>Recomputes the 12 model buildings' BoxColliders from local bounds (fixes a transposed-size bug).\")\n  NbFood(\"<b>NbFood</b><br/>Builds fridge food out of raw geometry (carrot, tomato, apple, ...); decoration only, no colliders.\")\n  NbFoodArt(\"<b>NbFoodArt</b><br/>Places imported grocery models as fridge shelf decoration (solid, ignore-raycast, off the cheese lanes).\")\n  NbFridge(\"<b>NbFridge</b><br/>Fridge level: six shelves, stair ascent, cover props, and the door that floods light on a timer.\")\n  NbGuard(\"<b>NbGuard</b><br/>Yard night guard: random patrol, sweeping flashlight cone, chases and catches the mouse.\")\n  NbGuardArt(\"<b>NbGuardArt</b><br/>Loads the Mixamo guard model and hand-samples its walk animation onto the yard guard.\")\n  NbKitchen(\"<b>NbKitchen</b><br/>Kitchen level: six benches, five 1.2 m aisles, lethal light pools, dark-corner cats.\")\n  NbLevels(\"<b>NbLevels</b><br/>Difficulty tables: 10 levels per scene (cheese/cats/speed/sight/guards/exposure/rot/door).\")\n  NbLighting(\"<b>NbLighting</b><br/>Re-lights the scene at night: a single moonlight key, faint fill, fog, and a night-sky clear colour.\")\n  NbMap(\"<b>NbMap</b><br/>Bottom-right minimap: player arrow, cat/cheese dots, scale bar, per-scene bounds.\")\n  NbMode(\"<b>NbMode</b><br/>Neighbourhood game manager: builds the scene, runs the 10-level loop, spawns cheese/cats/guards, resolves win/loss.\")\n  NbPlayer(\"<b>NbPlayer</b><br/>First-person mouse controller: builds its own body and camera; walk/run/jump, look, idle squeak.\")\n  NbScene(\"<b>NbScene</b><br/>Scene shell: selects the active scene (Street/Yard/Kitchen/Fridge), holds its bounds/spawn/targets/routes, hides the street original.\")\n  NbSceneSelect(\"<b>NbSceneSelect</b><br/>Scene-select page after the title: pick Street/Yard/Fridge, each with its own best-level progress.\")\n  NbUi(\"<b>NbUi</b><br/>In-game HUD: cheese count, toasts, health pips, exposure/rot/door meters, win/fail overlay.\")\n  NbYard(\"<b>NbYard</b><br/>Backyard level: scattered cover points around a wide-open centre, patrolled by guards with flashlights.\")\n  Reset(\"<b>Reset</b><br/>Reset button: hides the current screen and brings the title screen back.\")\n  NbCat(\"<b>NbCat</b><br/>script missing\")\n  NbCheese(\"<b>NbCheese</b><br/>script missing\")\n  NbGame(\"<b>NbGame</b><br/>script missing\")\n  NbHud(\"<b>NbHud</b><br/>script missing\")\n  NbProgress(\"<b>NbProgress</b><br/>script missing\")\n\n  AudioManager --> NbCat\n  AudioManager --> NbGuard\n  CatCheeseEndScreen --> CheeseHud\n  CatCheeseGame --> CheeseHud\n  CatCheeseGame --> CatCheeseEndScreen\n  CatCheeseTitle --> NbSceneSelect\n  NbBriefing --> NbGame\n  NbBriefing --> NbPlayer\n  NbBriefing --> NbUi\n  NbBuilder --> Nb\n  NbColliders --> Nb\n  NbFood --> Nb\n  NbFoodArt --> NbFridge\n  NbFoodArt --> NbFood\n  NbFridge --> NbFood\n  NbFridge --> NbFoodArt\n  NbFridge --> NbLighting\n  NbGuard --> NbGame\n  NbGuard --> NbGuardArt\n  NbGuard --> AudioManager\n  NbGuardArt --> NbGuard\n  NbKitchen --> NbScene\n  NbKitchen --> Nb\n  NbLevels --> NbScene\n  NbLighting --> NbScene\n  NbLighting --> NbFridge\n  NbMap --> NbGame\n  NbMap --> NbScene\n  NbMap --> NbCat\n  NbMap --> NbCheese\n  NbMap --> NbUi\n  NbMode --> NbScene\n  NbMode --> NbLevels\n  NbMode --> NbBuilder\n  NbMode --> NbPlayer\n  NbMode --> NbGuard\n  NbMode --> NbCat\n  NbMode --> NbCheese\n  NbMode --> NbHud\n  NbMode --> NbMap\n  NbMode --> NbLighting\n  NbMode --> NbFridge\n  NbMode --> NbFood\n  NbMode --> NbFoodArt\n  NbMode --> NbColliders\n  NbMode --> NbBriefing\n  NbMode --> NbSceneSelect\n  NbMode --> AudioManager\n  NbPlayer --> NbGame\n  NbPlayer --> AudioManager\n  NbScene --> NbYard\n  NbScene --> NbKitchen\n  NbScene --> NbFridge\n  NbScene --> NbBuilder\n  NbSceneSelect --> NbGame\n  NbSceneSelect --> NbScene\n  NbSceneSelect --> NbProgress\n  NbSceneSelect --> NbUi\n  NbUi --> NbGame\n  NbUi --> NbScene\n  NbUi --> NbLevels\n  NbUi --> NbFridge\n  NbYard --> NbScene\n  NbYard --> Nb\n\n  classDef manager fill:#f0a202,stroke:#1a140e,color:#1a140e,stroke-width:2.5px\n  classDef actor fill:#fff8ea,stroke:#1a140e,color:#1a140e,stroke-width:2px\n  classDef world fill:#9cba6a,stroke:#1a140e,color:#1a140e,stroke-width:2px\n  classDef ui fill:#efe6cf,stroke:#c4841a,color:#1a140e,stroke-width:2px\n  classDef other fill:#efe6cf,stroke:#1a140e,color:#1a140e,stroke-width:2px\n  class AudioManager manager\n  class NbPlayer actor\n  class CheeseHud,NbBuilder,NbUi,NbHud ui\n  class CatCheeseEndScreen,CatCheeseGame,CatCheeseTitle,Entry,FirstPersonMove,Nb,NbBriefing,NbColliders,NbFood,NbFoodArt,NbFridge,NbGuard,NbGuardArt,NbKitchen,NbLevels,NbLighting,NbMap,NbMode,NbScene,NbSceneSelect,NbYard,Reset,NbCat,NbCheese,NbGame,NbProgress other\n","tunables":"# Tunables\n\nGenerated from `@tune` headers by the menu `CGDD/Export Trace Docs`. Hand edits are overwritten on the next export.\n\n| Script | Field | Type | Range | Default | Note |\n| --- | --- | --- | --- | --- | --- |\n| AudioManager | HearRange | float | 5-60 | 20 | max audible distance (m) for cat/guard footsteps |\n| CatCheeseGame | eatRadius | float | 0.3-3 | 0.9 | cheese pickup radius m |\n| CatCheeseGame | catchRadius | float | 0.5-5 | 1.2 | cat catch radius m |\n| CatCheeseGame | CatSpeed | float | 0.3-6 | 1.6 | cat patrol speed m/s |\n| NbFridge | Layers | int | 2-12 | 6 | number of shelves |\n| NbFridge | LayerH | float | 0.2-2 | 0.56 | shelf spacing (floor-to-floor) m |\n| NbFridge | StepsPerLayer | int | 1-10 | 4 | stair steps between shelves |\n| NbGuard | Speed | float | 0.3-3 | 0.95 | patrol walk speed m/s |\n| NbGuard | Sweep | float | 0.1-3 | 0.55 | flashlight sweep pace (higher = faster) |\n| NbGuard | Range | float | 5-40 | 18 | flashlight beam range m |\n| NbGuard | Half | float | 2-45 | 11 | beam cone half-angle deg |\n| NbGuard | Damage | float | 1-100 | 25 | exposure gained per second in the beam |\n| NbGuard | ChaseSpeed | float | 1-6 | 2.9 | chase speed m/s (below player run) |\n| NbKitchen | BenchW | float | 1-10 | 4.8 | bench width m |\n| NbKitchen | AisleW | float | 0.3-3 | 1.2 | aisle width m |\n| NbLevels | BiteDamage | int | 1-50 | 10 | health lost per catch |\n| NbLevels | StartHp | int | 10-500 | 100 | starting health |\n| NbLevels | Count | int | 1-20 | 10 | levels per scene |\n| NbLighting | KeyPower | float | 0-1.5 | 0.62 | moon key light intensity |\n| NbLighting | FillPower | float | 0-0.5 | 0.07 | fill light intensity |\n| NbMode | DoorWarnTime | float | 1-6 | 3 | fridge door-open warning seconds |\n| NbMode | CatHeight | float | 0.5-3 | 0.95 | cat height m (feeds cat body probe scale) |\n| NbPlayer | WalkSpeed | float | 1-4 | 2.3 | walk speed m/s |\n| NbPlayer | RunMul | float | 1-3 | 1.7 | run multiplier on WalkSpeed |\n| NbPlayer | JumpSpeed | float | 1-6 | 3.2 | jump take-off velocity m/s |\n| NbPlayer | Gravity | float | -40--5 | -20 | gravity acceleration m/s2 |\n| NbPlayer | LookSens | float | 0.02-0.5 | 0.1 | mouse look sensitivity deg/pixel |\n\n","challenge":"# How the challenge changes\n\nLook first at whether win and loss change, then at whether the player's verb changes. If neither changes, it is the same game, just tighter or looser.\n\n| Change | Win/loss changed | Verb changed | Data | Script.field |\n| --- | --- | --- | --- | --- |\n| Start: (describe baseline feel) | — (baseline) | — (player verb) | field=default | ScriptName.field |\n","devlog":"# DEVLOG\n\nOnly append. Do not edit old sections. Two samples stay so students can see the format.\n\nOnly changes to the game itself are logged: the verb, win and loss, pressure, and what the player can feel.\nSite language, diagram styling, and click-to-read-script do not go into an Interaction or a Stage Reflection.\n\nEach gameplay change should add a section `## Interaction NNN — title` (the Agent can append this when it changes the game).\nAdd `## Stage Reflection NNN — title` only when you ask for one: Keep / Change / Cut, and which AI suggestions you accepted or rejected. That reflection stays on the game.\n\n## Interaction 000 — EXAMPLE (sample, do not delete)\n\n- Date: —\n- Who asked: teacher (sample)\n- Request: Tighten one tunable and see if it is still the same game.\n- What changed: Sample only. The current code was not changed. A real change would touch only one `@tune` field.\n- Result: The player's verb did not change. Win and loss did not change. Pressure changed, not the skeleton.\n\n## Stage Reflection 000 — EXAMPLE (sample, do not delete)\n\n### Keep\n- A core verb you can say in one sentence, and a clear win/loss.\n\n### Change\n- To make it harder, turn an existing `@tune` first. Do not add a new system yet.\n\n### Cut\n- No shop, no deep inventory, no optimization that is off-lesson.\n\n### AI\n- Accept: tune feel with existing fields; avoid opening new scripts.\n- Reject: GraphView, object pools, long hand-written scene YAML. This class is about script relationships and tunable numbers.\n","scripts":{"AudioManager":{"path":"Assets/Scripts/AudioManager.cs","role":"Central audio hub: one-shot SFX, 3D cat/guard footstep loops, and the idle squeak.","source":"// @role Central audio hub: one-shot SFX, 3D cat/guard footstep loops, and the idle squeak.\n// @calls NbCat NbGuard\n// @tune HearRange:float:5-60:max audible distance (m) for cat/guard footsteps\n\nusing System.Collections.Generic;\nusing UnityEngine;\n\npublic enum SoundType\n{\n    CAT_Hiss,\n    CAT_Meow,\n    CAT_walk,\n    RAT_squeak,\n    RAT_running,\n    nom,\n    MAN_footsteps,\n    MAN_running,\n    MAN_yell,\n    MAN_talking,\n    FRIDGE_open,\n    FRIDGE_close,\n    hum\n}\n\n[RequireComponent(typeof(AudioSource))]\n\npublic class AudioManager : MonoBehaviour\n{\n    [SerializeField] private AudioClip[] audioList;\n    private static AudioManager instance;\n    private AudioSource audiosource;\n\n    \n    private const float HearRange = 20f;    // 多远开始听得到（米）\n\n    private class Step\n    {\n        public AudioSource source;\n        public Vector3 lastPos;\n    }\n\n    private readonly Dictionary<Transform, Step> _steps = new Dictionary<Transform, Step>();\n    private float _scanT;\n\n    private void Awake()\n    {\n        instance = this;\n    }\n    // Start is called once before the first execution of Update after the MonoBehaviour is created\n    void Start()\n    {\n        audiosource = GetComponent<AudioSource>();\n    }\n\n    // Update is  called once per frame\n    void Update()\n    {\n        if (instance != this) return;\n\n        // 换关会把猫和人整批销毁再重建，所以每 0.5 秒重新认一次场上还有谁\n        _scanT -= Time.deltaTime;\n        if (_scanT <= 0f)\n        {\n            _scanT = 0.5f;\n            Rescan();\n        }\n\n        // 每帧只做一件事：这一格挪动了就出声，站着就静音\n        foreach (KeyValuePair<Transform, Step> kv in _steps)\n        {\n            Transform body = kv.Key;\n            Step s = kv.Value;\n            if (body == null) continue;\n\n            bool moving = (body.position - s.lastPos).sqrMagnitude > 1e-6f;\n            s.lastPos = body.position;\n\n            // 距离和方向都交给 3D 衰减，这里只开关\n            s.source.volume = moving ? 1f : 0f;\n        }\n    }\n\n    void Rescan()\n    {\n        // 回收已经消失的（换关时猫 / 人会被 Destroy）\n        List<Transform> dead = null;\n        foreach (KeyValuePair<Transform, Step> kv in _steps)\n        {\n            if (kv.Key != null) continue;\n            if (dead == null) dead = new List<Transform>();\n            dead.Add(kv.Key);\n        }\n        if (dead != null)\n            for (int i = 0; i < dead.Count; i++) _steps.Remove(dead[i]);\n\n        // 捞出场上每一只猫、每一个保安\n        foreach (NbCat cat in FindObjectsByType<NbCat>(FindObjectsSortMode.None))\n            Attach(cat.transform, SoundType.CAT_walk);\n\n        foreach (NbGuard man in FindObjectsByType<NbGuard>(FindObjectsSortMode.None))\n            Attach(man.transform, SoundType.MAN_footsteps);\n    }\n\n    void Attach(Transform body, SoundType sound)\n    {\n        if (_steps.ContainsKey(body)) return;\n\n        GameObject go = new GameObject(\"Audio\");\n        go.transform.SetParent(body, false);\n\n        AudioSource src = go.AddComponent<AudioSource>();\n        src.clip = audioList[(int)sound];\n        src.loop = true;\n        src.spatialBlend = 1f;                    // 3D：音量随距离、左右声道随方向\n        src.rolloffMode = AudioRolloffMode.Linear;\n        src.minDistance = 1f;\n        src.maxDistance = HearRange;              // 20 m 处刚好静音\n        src.dopplerLevel = 0f;\n        src.volume = 0f;\n        src.Play();\n\n        _steps.Add(body, new Step { source = src, lastPos = body.position });\n    }\n\n    public static float GetSoundLength(SoundType sound)\n    {\n        return instance.audioList[(int)sound].length;\n    }\n\n    public static void PlaySound(SoundType sound, float volume = 1)\n    {\n        instance.audiosource.PlayOneShot(instance.audioList[(int)sound], volume);\n    }\n\n    public static void StopSound()\n    {\n        instance.audiosource.Stop();\n    }\n\n    /// 玩家闲置时的吱吱叫。走共享声源的**主音轨**（不是 PlayOneShot），\n    /// 这样 StopSound() 才能把它立刻截断 —— PlayOneShot 的音是 Stop 停不掉的。\n    public static void PlaySqueak()\n    {\n        instance.audiosource.clip = instance.audioList[(int)SoundType.RAT_squeak];\n        instance.audiosource.loop = false;\n        instance.audiosource.Play();\n    }\n}\n"},"CatCheeseEndScreen":{"path":"Assets/Scripts/CatCheeseEndScreen.cs","role":"Win/lose overlay for the legacy cat game: freezes time and shows Game Failed / You Win.","source":"// @role Win/lose overlay for the legacy cat game: freezes time and shows Game Failed / You Win.\r\n// @calls CheeseHud\r\n\r\n// CatCheeseEndScreen.cs — 游戏内的成败覆盖层（运行时自装配，不改场景文件）\r\n//\r\n// 为什么不切到 UI_Screens 里的 End Screen 页：\r\n//   ① 那两个页面写的是 \"You got caught!\" / \"You made it home!\"，不是想要的 \"Game Failed\"；\r\n//   ② 更要紧的是 —— UI_Screens 不在 Build Settings 的 Scenes In Build 里（那里只有 SampleScene），\r\n//      SceneManager.LoadScene(\"UI_Screens\") 会直接抛\r\n//      「Scene 'UI_Screens' couldn't be loaded because it has not been added to the build settings」，\r\n//      画面上什么都不会发生。这就是上一版「被抓 → 失败页」没反应的原因。\r\n//\r\n// 所以结果直接画在当前游戏画面上（和右上角 HUD 同一套字体/配色，Kindly Crunch 只有 ASCII，不能写中文）：\r\n//   被猫抓到     → 大字 \"Game Failed\"\r\n//   集齐所有奶酪 → 大字 \"You Win\"\r\n// 出现时：冻结时间（Time.timeScale = 0）、放开鼠标、停掉玩家移动；按 R 重开本关。\r\n//\r\n// ⚠️ TMP 的描边不走 uGUI 的 Outline/Shadow 组件（那些只对 legacy Text 生效，加了不报错也不生效），\r\n//    只能启用 SDF 材质的 OUTLINE_ON 关键字 + 写 _OutlineWidth / _OutlineColor。见 ApplyOutline。\r\n\r\nusing TMPro;\r\nusing UnityEngine;\r\nusing UnityEngine.InputSystem;\r\nusing UnityEngine.SceneManagement;\r\nusing UnityEngine.UI;\r\n\r\ninternal class CatCheeseEndScreen : MonoBehaviour\r\n{\r\n    // 与 CheeseHud 同一套配色：失败红、成功用奶酪黄 #FBD765\r\n    static readonly Color LoseColor = new Color(1f, 0.35f, 0.32f, 1f);\r\n    static readonly Color WinColor = new Color(0.984f, 0.843f, 0.396f, 1f);\r\n    static readonly Color SubColor = new Color(1f, 1f, 1f, 0.88f);\r\n    static readonly Color32 OutlineColor = new Color32(22, 13, 5, 255);\r\n\r\n    const string LoseTitle = \"Game Failed\";\r\n    const string WinTitle = \"You Win\";\r\n    const string LoseSub = \"the cat got you   -   press R to try again\";\r\n    const string WinSub = \"all cheese collected   -   press R to play again\";\r\n\r\n    [Header(\"文字\")]\r\n    public float titleSize = 150f;\r\n    public float subSize = 42f;\r\n\r\n    [Header(\"层级 / 动效\")]\r\n    public int sortingOrder = 100;        // 要压过 CheeseHud 的 50\r\n    public float fadeInDuration = 0.45f;\r\n\r\n    static CatCheeseEndScreen _instance;\r\n\r\n    TextMeshProUGUI _title;\r\n    CanvasGroup _group;\r\n    Sprite _white;\r\n    float _fade;\r\n\r\n    // 若工程关了 Domain Reload，静态字段不会自动重置 —— 显式清一次，免得第二次 Play 弹不出来\r\n    [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)]\r\n    static void ResetStatics() { _instance = null; }\r\n\r\n    /// 弹出结果覆盖层（一局只会弹一次）\r\n    internal static void Show(bool win)\r\n    {\r\n        if (_instance != null) return;\r\n        GameObject go = new GameObject(\"CatCheeseEndScreen (auto)\");\r\n        _instance = go.AddComponent<CatCheeseEndScreen>();\r\n        _instance.Build(win);\r\n    }\r\n\r\n    void Build(bool win)\r\n    {\r\n        // —— 收尾：冻住场景、停掉玩家、放开鼠标 ——\r\n        Time.timeScale = 0f;\r\n        FreezePlayer();\r\n\r\n        // —— 画布（比 HUD 更高一层，全屏压暗在最下面）——\r\n        GameObject canvasGo = new GameObject(\"End Canvas (auto)\", typeof(Canvas), typeof(CanvasScaler));\r\n        canvasGo.transform.SetParent(transform, false);\r\n        Canvas canvas = canvasGo.GetComponent<Canvas>();\r\n        canvas.renderMode = RenderMode.ScreenSpaceOverlay;\r\n        canvas.sortingOrder = sortingOrder;\r\n\r\n        CanvasScaler scaler = canvasGo.GetComponent<CanvasScaler>();\r\n        scaler.uiScaleMode = CanvasScaler.ScaleMode.ScaleWithScreenSize;\r\n        scaler.referenceResolution = new Vector2(1920f, 1080f);\r\n        scaler.matchWidthOrHeight = 0.5f;\r\n\r\n        _group = canvasGo.AddComponent<CanvasGroup>();\r\n        _group.alpha = 0f;                 // 淡入\r\n        _group.blocksRaycasts = false;\r\n        _group.interactable = false;\r\n\r\n        _white = MakeWhiteSprite();\r\n        RectTransform dim = NewRect(\"Dim\", canvasGo.transform);\r\n        dim.anchorMin = Vector2.zero;\r\n        dim.anchorMax = Vector2.one;\r\n        dim.offsetMin = Vector2.zero;\r\n        dim.offsetMax = Vector2.zero;\r\n        Image dimImage = dim.gameObject.AddComponent<Image>();\r\n        dimImage.sprite = _white;\r\n        dimImage.type = Image.Type.Simple;\r\n        dimImage.color = new Color(0f, 0f, 0f, 0.70f);   // 白盒场景偏白，压暗才看得清大字\r\n        dimImage.raycastTarget = false;\r\n\r\n        TMP_FontAsset font = ResolveFont();\r\n\r\n        // —— 大字：Game Failed / You Win ——\r\n        _title = MakeText(\"Title\", canvasGo.transform, font, titleSize, win ? WinColor : LoseColor);\r\n        _title.text = win ? WinTitle : LoseTitle;\r\n        _title.rectTransform.sizeDelta = new Vector2(1800f, titleSize * 1.5f);\r\n        _title.rectTransform.anchoredPosition = new Vector2(0f, 60f);\r\n\r\n        // —— 小字：操作提示 ——\r\n        TextMeshProUGUI sub = MakeText(\"Sub\", canvasGo.transform, font, subSize, SubColor);\r\n        sub.text = win ? WinSub : LoseSub;\r\n        sub.rectTransform.sizeDelta = new Vector2(1800f, subSize * 2f);\r\n        sub.rectTransform.anchoredPosition = new Vector2(0f, -80f);\r\n\r\n        Debug.LogFormat(\"[CatCheese] {0} —— 结果画面已显示（按 R 重开本关）。\",\r\n            win ? \"集齐所有奶酪，挑战成功\" : \"被猫抓到，挑战失败\");\r\n    }\r\n\r\n    void FreezePlayer()\r\n    {\r\n        foreach (FirstPersonMove move in Object.FindObjectsByType<FirstPersonMove>(FindObjectsInactive.Include, FindObjectsSortMode.None))\r\n            move.enabled = false;          // 停掉移动（它的 OnDisable 会顺手把鼠标放开）\r\n\r\n        Cursor.lockState = CursorLockMode.None;\r\n        Cursor.visible = true;\r\n    }\r\n\r\n    void Update()\r\n    {\r\n        // 淡入要注意：此时 timeScale 已经是 0，只能用 unscaledDeltaTime\r\n        if (_group != null && _fade < 1f)\r\n        {\r\n            _fade = Mathf.Clamp01(_fade + Time.unscaledDeltaTime / Mathf.Max(fadeInDuration, 0.01f));\r\n            _group.alpha = _fade;\r\n        }\r\n\r\n        // 大字轻微呼吸，让它看起来\"活着\"\r\n        if (_title != null)\r\n        {\r\n            float k = 1f + 0.03f * Mathf.Sin(Time.unscaledTime * 2f * Mathf.PI);\r\n            _title.rectTransform.localScale = new Vector3(k, k, 1f);\r\n        }\r\n\r\n        Keyboard kb = Keyboard.current;\r\n        if (kb != null && kb.rKey.wasPressedThisFrame) Restart();\r\n    }\r\n\r\n    void Restart()\r\n    {\r\n        Time.timeScale = 1f;               // 必须先还回来，否则新一局是静止的\r\n        _instance = null;\r\n        SceneManager.LoadScene(SceneManager.GetActiveScene().name);\r\n    }\r\n\r\n    TextMeshProUGUI MakeText(string goName, Transform parent, TMP_FontAsset font, float size, Color color)\r\n    {\r\n        RectTransform rt = NewRect(goName, parent);\r\n        TextMeshProUGUI t = rt.gameObject.AddComponent<TextMeshProUGUI>();\r\n        if (font != null) t.font = font;\r\n        t.fontSize = size;\r\n        t.color = color;\r\n        t.alignment = TextAlignmentOptions.Center;\r\n        t.textWrappingMode = TextWrappingModes.NoWrap;\r\n        t.overflowMode = TextOverflowModes.Overflow;\r\n        t.raycastTarget = false;\r\n        ApplyOutline(t, OutlineColor, 0.20f);\r\n        return t;\r\n    }\r\n\r\n    /// TMP 描边只能这样加：启用 OUTLINE_ON 关键字 + 写材质属性。\r\n    /// 只设 text.outlineWidth 没用 —— 字体资源里的材质默认没开这个关键字。\r\n    static void ApplyOutline(TextMeshProUGUI t, Color32 color, float width)\r\n    {\r\n        Material m = t.fontMaterial;       // 取实例（每份 Text 一份，不动共享材质）\r\n        if (m == null || !m.HasProperty(\"_OutlineWidth\")) return;\r\n        m.EnableKeyword(\"OUTLINE_ON\");\r\n        m.SetFloat(\"_OutlineWidth\", width);\r\n        m.SetColor(\"_OutlineColor\", color);\r\n    }\r\n\r\n    static TMP_FontAsset ResolveFont()\r\n    {\r\n        HudFontRef r = Resources.Load<HudFontRef>(\"GameProps/HudFont\");\r\n        if (r != null && r.font != null) return r.font;\r\n\r\n        Debug.LogWarning(\"[CatCheese] 取不到 Resources/GameProps/HudFont 里的字体引用，结果画面退回 TMP 默认字体（仍会显示，只是字体和 HUD 不同）。\");\r\n        return TMP_Settings.defaultFontAsset;\r\n    }\r\n\r\n    static RectTransform NewRect(string goName, Transform parent)\r\n    {\r\n        GameObject go = new GameObject(goName, typeof(RectTransform));\r\n        RectTransform rt = (RectTransform)go.transform;\r\n        rt.SetParent(parent, false);\r\n        rt.anchorMin = rt.anchorMax = rt.pivot = new Vector2(0.5f, 0.5f);\r\n        rt.anchoredPosition = Vector2.zero;\r\n        return rt;\r\n    }\r\n\r\n    static Sprite MakeWhiteSprite()\r\n    {\r\n        Texture2D tex = new Texture2D(1, 1, TextureFormat.RGBA32, false);\r\n        tex.SetPixel(0, 0, Color.white);\r\n        tex.Apply();\r\n        tex.hideFlags = HideFlags.HideAndDontSave;\r\n        Sprite s = Sprite.Create(tex, new Rect(0f, 0f, 1f, 1f), new Vector2(0.5f, 0.5f));\r\n        s.hideFlags = HideFlags.HideAndDontSave;\r\n        return s;\r\n    }\r\n\r\n    void OnDestroy()\r\n    {\r\n        // 自建的贴图/Sprite 要自己销毁，否则每次切场景泄漏一张\r\n        if (_white != null)\r\n        {\r\n            if (_white.texture != null) Destroy(_white.texture);\r\n            Destroy(_white);\r\n            _white = null;\r\n        }\r\n    }\r\n}\r\n"},"CatCheeseGame":{"path":"Assets/Scripts/CatCheeseGame.cs","role":"Legacy cat-and-cheese game: a cat patrols and the player collects 3 cheeses without being caught.","source":"// @role Legacy cat-and-cheese game: a cat patrols and the player collects 3 cheeses without being caught.\r\n// @calls CheeseHud CatCheeseEndScreen\r\n// @tune eatRadius:float:0.3-3:cheese pickup radius m\r\n// @tune catchRadius:float:0.5-5:cat catch radius m\r\n// @tune CatSpeed:float:0.3-6:cat patrol speed m/s\r\n\r\n// CatCheeseGame.cs — 猫吃奶酪玩法 v2（运行时自装配，不改场景文件、不改课程工具）\r\n//\r\n// 玩法：场景里放一个名为「CatMoveSpace」的空物体（Position 为中心、Scale 为尺寸的长方体，\r\n//       即猫的移动空间）；猫在这个区域内巡逻，区域内自动摆放 3 块奶酪。\r\n//       玩家（第一人称）收集完 3 块奶酪且不被猫抓到 → 胜利；被猫靠近（<1.2 m）→ 失败。\r\n// 成败画面复用 UI_Screens.unity 里现成的 End Screen_Win / End Screen_Lose。\r\n//\r\n// 猫模型：Resources/GameProps/Cat walk.glb（需 glTFast 包导入，已装 6.9.1）\r\n// 奶酪模型：Resources/GameProps/Cheese_0001_LOD0.fbx + 同目录 albedo 贴图\r\n// 模型缺失时自动用占位方块代替，游戏仍然可玩。\r\n//\r\n// ⚠️ 尺寸与贴地一律走「网格实测」，绝不使用 Renderer.bounds：\r\n//    猫是蒙皮模型，Renderer.bounds 由骨骼矩阵推出（会带上骨骼上的非单位缩放、还顺绑定姿势旋转），\r\n//    实测偏差可达数百倍；而且实例化当帧它可能还没刷新。用它算缩放 → 猫变成巨物，算贴地 → 底面偏移错 ⇒ 悬在空中。\r\n//    正确做法：MeshFilter/SkinnedMeshRenderer 的 sharedMesh.bounds 八个角 × renderer.localToWorldMatrix。\r\n\r\nusing System.Collections;\r\nusing UnityEngine;\r\nusing UnityEngine.Animations;\r\nusing UnityEngine.Playables;\r\nusing UnityEngine.SceneManagement;\r\n\r\n/// 上一局结果：-1 无；0 被抓（失败）；1 集齐奶酪（成功）\r\ninternal static class CatCheeseResult\r\n{\r\n    internal static int Last = -1;\r\n}\r\n\r\ninternal static class CatCheeseBootstrap\r\n{\r\n    internal const string SampleSceneName = \"SampleScene\";\r\n    internal const string UiSceneName = \"UI_Screens\";\r\n\r\n    [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]\r\n    static void Bootstrap()\r\n    {\r\n        SceneManager.sceneLoaded += (scene, mode) => Handle(scene);\r\n        Scene active = SceneManager.GetActiveScene();\r\n        if (active.isLoaded) Handle(active);\r\n    }\r\n\r\n    static void Handle(Scene scene)\r\n    {\r\n        // 居民区关卡接管后，旧的「猫吃奶酪」整套装配让位；把 Enabled 改回 false 就能复现旧玩法\r\n        if (NbMode.Enabled) return;\r\n\r\n        if (scene.name == SampleSceneName) CatCheeseSetup.Install();\r\n        else if (scene.name == UiSceneName) ApplyEndScreen(scene);\r\n    }\r\n\r\n    /// 在 UI_Screens 里点亮对应的结算页（复用学生做好的页面）\r\n    static void ApplyEndScreen(Scene scene)\r\n    {\r\n        int r = CatCheeseResult.Last;\r\n        if (r < 0) return; // 正常从标题进入，不干预场景保存的默认状态\r\n        SetActiveInScene(scene, \"End Screen_Win\", r == 1);\r\n        SetActiveInScene(scene, \"End Screen_Lose\", r == 0);\r\n        SetActiveInScene(scene, \"Title\", false);\r\n        SetActiveInScene(scene, \"Title Screen\", false);\r\n        Debug.LogFormat(\"[CatCheese] {0} 已切换到结算页：{1}\",\r\n            r == 1 ? \"集齐 3 块奶酪，挑战成功！\" : \"被猫抓到，挑战失败！\",\r\n            r == 1 ? \"End Screen_Win\" : \"End Screen_Lose\");\r\n    }\r\n\r\n    static void SetActiveInScene(Scene scene, string objName, bool on)\r\n    {\r\n        GameObject go = FindInScene(scene, objName);\r\n        if (go != null) go.SetActive(on);\r\n        else Debug.LogWarning(\"[CatCheese] UI_Screens 里找不到名为「\" + objName + \"」的物体，请检查页面命名。\");\r\n    }\r\n\r\n    /// GameObject.Find 找不到未激活物体，这里按场景遍历（含未激活）\r\n    internal static GameObject FindInScene(Scene scene, string objName)\r\n    {\r\n        foreach (GameObject root in scene.GetRootGameObjects())\r\n        {\r\n            if (root.name == objName) return root;\r\n            Transform direct = root.transform.Find(objName);\r\n            if (direct != null) return direct.gameObject;\r\n        }\r\n        foreach (GameObject root in scene.GetRootGameObjects())\r\n        {\r\n            Transform[] all = root.GetComponentsInChildren<Transform>(true);\r\n            foreach (Transform t in all)\r\n                if (t.name == objName) return t.gameObject;\r\n        }\r\n        return null;\r\n    }\r\n}\r\n\r\ninternal static class CatCheeseSetup\r\n{\r\n    internal const string SpaceName = \"CatMoveSpace\";\r\n\r\n    const float CatHeight = 0.5f;      // 猫归一化后的身高（米）\r\n    const float CheeseHeight = 0.35f;  // 奶酪归一化后的高度（米）\r\n    const float CatSpeed = 1.6f;       // 巡逻速度 m/s\r\n    const float EdgeMargin = 0.6f;     // 巡逻点距区域边缘的留白\r\n    internal static readonly int PropLayer = LayerMask.NameToLayer(\"Ignore Raycast\"); // 生成物不挡地面射线\r\n    // 生成物的层掩码：Ignore Raycast 这一层被 Physics.DefaultRaycastLayers 排除掉（地面探测必须看不见生成物），\r\n    // 所以「猫绕开障碍」的扫掠要显式把这一层加回来，否则扫掠永远打不到奶酪。\r\n    internal static readonly int PropMask = PropLayer < 0 ? 0 : (1 << PropLayer);\r\n\r\n    internal static void Install()\r\n    {\r\n        CatCheeseResult.Last = -1; // 新的一局\r\n\r\n        // —— 读取猫的移动空间（position+scale 长方体）——\r\n        Scene scene = SceneManager.GetActiveScene();\r\n        GameObject space = CatCheeseBootstrap.FindInScene(scene, SpaceName);\r\n        if (space == null)\r\n        {\r\n            Debug.LogError(\"[CatCheese] 场景里没有找到名为「\" + SpaceName + \"」的空物体——请先创建它（Position=中心，Scale=尺寸），再进 Play。本次不生成玩法。\");\r\n            return;\r\n        }\r\n        Vector3 c = space.transform.position;\r\n        Vector3 s = space.transform.lossyScale;\r\n        Bounds area = new Bounds(c, s);\r\n        if (area.size.x < 0.5f || area.size.z < 0.5f)\r\n            Debug.LogWarningFormat(\"[CatCheese] 「{0}」的范围只有 {1:F1}×{2:F1} m（Scale 即尺寸），似乎太小——记得把 Scale 调成想要的区域大小。\",\r\n                SpaceName, area.size.x, area.size.z);\r\n        Debug.LogFormat(\"[CatCheese] 已读取「{0}」：中心 ({1:F1}, {2:F1}, {3:F1})，尺寸 {4:F1}×{5:F1}×{6:F1} m。\",\r\n            SpaceName, c.x, c.y, c.z, s.x, s.y, s.z);\r\n\r\n        // —— 猫 ——（先按骨骼对朝向，再缩放贴地：绕 Y 旋转不改变竖直范围）\r\n        GameObject cat = SpawnModel(\"GameProps/Cat walk\", new Color(0.16f, 0.12f, 0.10f), \"Cat (auto)\");\r\n        OrientCatByBones(cat, Vector3.forward);\r\n        Bounds catBox = FitAndGround(cat, CatHeight, area.center, \"猫 (auto)\");\r\n        CatPatrol patrol = cat.AddComponent<CatPatrol>();\r\n        patrol.Configure(area, EdgeMargin, CatSpeed);\r\n        patrol.ConfigureBody(catBox, cat.transform.position.y); // 让猫会绕开奶酪，而不是穿过去\r\n        PlayWalkAnimation(cat);\r\n\r\n        // —— 3 块奶酪：分散在区域内的固定比例点 ——\r\n        Vector3[] spots =\r\n        {\r\n            PointInArea(area, 0.20f, 0.20f),\r\n            PointInArea(area, 0.80f, 0.50f),\r\n            PointInArea(area, 0.50f, 0.85f),\r\n        };\r\n        Transform[] cheeses = new Transform[spots.Length];\r\n        for (int i = 0; i < spots.Length; i++)\r\n        {\r\n            GameObject ch = SpawnModel(\"GameProps/Cheese_0001_LOD0\", new Color(0.95f, 0.75f, 0.15f), \"Cheese \" + (i + 1) + \" (auto)\");\r\n            WireCheeseTexture(ch);\r\n            FitAndGround(ch, CheeseHeight, spots[i], \"奶酪 \" + (i + 1) + \" (auto)\");\r\n            AddSolidBoxCollider(ch); // 实体碰撞体：必须在缩放贴地之后加，尺寸才对\r\n            cheeses[i] = ch.transform;\r\n        }\r\n\r\n        CatCheeseGame game = new GameObject(\"CatCheeseGame (auto)\").AddComponent<CatCheeseGame>();\r\n        game.cat = cat.transform;\r\n        game.cheeses = cheeses;\r\n        game.hud = CheeseHud.Create(cheeses.Length);   // 右上角奶酪计数\r\n\r\n        Debug.LogFormat(\"[CatCheese] 开局：猫（高 {0:F2} m）在区域内以 {1:F1} m/s 巡逻；{2} 块奶酪已摆放。集齐它们且别被猫抓到！\",\r\n            CatHeight, CatSpeed, cheeses.Length);\r\n    }\r\n\r\n    /// 区域内 (fx, fz) ∈ [0,1]² 的相对位置转世界坐标（y 用区域中部）\r\n    static Vector3 PointInArea(Bounds area, float fx, float fz)\r\n    {\r\n        Vector3 e = area.extents;\r\n        return new Vector3(area.center.x + (fx - 0.5f) * 2f * e.x, area.center.y, area.center.z + (fz - 0.5f) * 2f * e.z);\r\n    }\r\n\r\n    /// 从高空向下打射线，取「最低」的那个命中点当地面。\r\n    /// 取最低而不是第一个：这样天花板/墙顶/玩家头顶都不会被误当地面（地面在所有遮挡物之下）。\r\n    internal static bool TryGroundY(Vector3 p, out float groundY)\r\n    {\r\n        groundY = p.y;\r\n        int n = Physics.RaycastNonAlloc(new Vector3(p.x, p.y + 300f, p.z), Vector3.down, _hits, 600f,\r\n                                        Physics.DefaultRaycastLayers, QueryTriggerInteraction.Ignore);\r\n        bool found = false;\r\n        float lowest = float.MaxValue;\r\n        for (int i = 0; i < n; i++)\r\n        {\r\n            float h = _hits[i].point.y;\r\n            if (h < lowest) { lowest = h; found = true; }\r\n        }\r\n        if (found) groundY = lowest;\r\n        return found;\r\n    }\r\n    static readonly RaycastHit[] _hits = new RaycastHit[32];\r\n\r\n    /// 网格实测世界包围盒（不用 Renderer.bounds）：\r\n    /// MeshFilter/SkinnedMeshRenderer 的 sharedMesh.bounds 八个角 × renderer.localToWorldMatrix\r\n    internal static bool TryMeasureWorldBounds(GameObject root, out Bounds b)\r\n    {\r\n        b = new Bounds();\r\n        bool any = false;\r\n        Renderer[] rs = root.GetComponentsInChildren<Renderer>(true);\r\n        for (int i = 0; i < rs.Length; i++)\r\n        {\r\n            Renderer r = rs[i];\r\n            if (r == null) continue;\r\n            Bounds lb;\r\n            SkinnedMeshRenderer smr = r as SkinnedMeshRenderer;\r\n            if (smr != null)\r\n            {\r\n                if (smr.sharedMesh != null) lb = smr.sharedMesh.bounds;\r\n                else lb = smr.localBounds;\r\n            }\r\n            else\r\n            {\r\n                MeshFilter mf = r.GetComponent<MeshFilter>();\r\n                if (mf != null && mf.sharedMesh != null) lb = mf.sharedMesh.bounds;\r\n                else lb = r.localBounds;\r\n            }\r\n            if (lb.size.sqrMagnitude <= 0f) continue;\r\n            Matrix4x4 m = r.transform.localToWorldMatrix;\r\n            Vector3 mn = lb.min, mx = lb.max;\r\n            for (int k = 0; k < 8; k++)\r\n            {\r\n                Vector3 w = m.MultiplyPoint3x4(new Vector3((k & 1) == 0 ? mn.x : mx.x,\r\n                                                           (k & 2) == 0 ? mn.y : mx.y,\r\n                                                           (k & 4) == 0 ? mn.z : mx.z));\r\n                if (!any) { b = new Bounds(w, Vector3.zero); any = true; }\r\n                else b.Encapsulate(w);\r\n            }\r\n        }\r\n        return any;\r\n    }\r\n\r\n    /// 按网格实测把模型归一化到目标高度，再把底面贴到地面。\r\n    /// 返回**贴好之后的**世界包围盒（失败时返回零尺寸盒），调用方用它来加碰撞体 / 定扫掠参数。\r\n    internal static Bounds FitAndGround(GameObject go, float targetHeight, Vector3 xz, string label)\r\n    {\r\n        Bounds raw;\r\n        if (!TryMeasureWorldBounds(go, out raw) || raw.size.y <= 1e-6f)\r\n        {\r\n            Debug.LogWarning(\"[CatCheese] \" + label + \"：量不到网格尺寸，不改缩放、不贴地。\");\r\n            return new Bounds(go.transform.position, Vector3.zero);\r\n        }\r\n\r\n        float k = targetHeight / raw.size.y;\r\n        go.transform.localScale = go.transform.localScale * k;\r\n\r\n        Bounds fit;\r\n        if (!TryMeasureWorldBounds(go, out fit))\r\n        {\r\n            Debug.LogWarning(\"[CatCheese] \" + label + \"：缩放后量不到包围盒，跳过贴地。\");\r\n            return new Bounds(go.transform.position, Vector3.zero);\r\n        }\r\n\r\n        float groundY;\r\n        bool hit = TryGroundY(xz, out groundY);\r\n        Vector3 before = go.transform.position;\r\n        Vector3 pos = before;\r\n        pos.x = xz.x;\r\n        pos.z = xz.z;\r\n        pos.y += groundY - fit.min.y; // 让模型底面正好落在 groundY\r\n        go.transform.position = pos;\r\n\r\n        // FootOffset = 根位置到模型底面的距离（与当前所在高度无关，故就算上面算错了它也是对的）\r\n        GroundStick gs = go.AddComponent<GroundStick>();\r\n        gs.FootOffset = pos.y - fit.min.y;\r\n\r\n        Debug.LogFormat(\"[CatCheese] {0}：网格实测 {1:F3}×{2:F3}×{3:F3} m → ×{4:F5} 缩到高 {5:F2} m；底面贴到{6} y={7:F3}（根位置 y={8:F3}）\",\r\n            label, raw.size.x, raw.size.y, raw.size.z, k, targetHeight,\r\n            hit ? \"射线命中的地面\" : \"【射线没命中，用了原点高度】\", groundY, pos.y);\r\n\r\n        fit.center += pos - before; // fit 是在「搬动之前」量出来的，补上位移才是最终位置\r\n        return fit;\r\n    }\r\n\r\n    /// 给生成物挂一个「贴合模型外形」的实体 BoxCollider —— 撞上去不会穿模。\r\n    /// 尺寸取网格实测的世界包围盒，再换算回根节点本地空间，所以缩放/旋转都是对的。\r\n    /// 层仍留在 Ignore Raycast：那层只对射线隐形（地面探测必须看不见生成物），物理碰撞照常生效。\r\n    /// 返回挂上的那个碰撞体：调用方可能要拿它做 Physics.IgnoreCollision（比如让老鼠穿过奶酪）。\r\n    internal static Collider AddSolidBoxCollider(GameObject go)\r\n    {\r\n        Bounds b;\r\n        if (!TryMeasureWorldBounds(go, out b) || b.size.sqrMagnitude <= 0f)\r\n        {\r\n            Debug.LogWarning(\"[CatCheese] \" + go.name + \"：量不到包围盒，没加碰撞体。\");\r\n            return null;\r\n        }\r\n\r\n        BoxCollider bc = go.GetComponent<BoxCollider>();\r\n        if (bc == null) bc = go.AddComponent<BoxCollider>(); // 占位方块自带一个，直接复用\r\n\r\n        Transform t = go.transform;\r\n        Vector3 mn = b.min, mx = b.max;\r\n        Vector3 lmin = new Vector3(float.MaxValue, float.MaxValue, float.MaxValue);\r\n        Vector3 lmax = new Vector3(float.MinValue, float.MinValue, float.MinValue);\r\n        for (int k = 0; k < 8; k++)\r\n        {\r\n            Vector3 w = new Vector3((k & 1) == 0 ? mn.x : mx.x,\r\n                                    (k & 2) == 0 ? mn.y : mx.y,\r\n                                    (k & 4) == 0 ? mn.z : mx.z);\r\n            Vector3 l = t.InverseTransformPoint(w);\r\n            lmin = Vector3.Min(lmin, l);\r\n            lmax = Vector3.Max(lmax, l);\r\n        }\r\n\r\n        bc.isTrigger = false;\r\n        bc.center = (lmin + lmax) * 0.5f;\r\n        bc.size = lmax - lmin;\r\n        Debug.LogFormat(\"[CatCheese] {0}：已加实体碰撞体（本地尺寸 {1:F3}×{2:F3}×{3:F3} m，中心 ({4:F3}, {5:F3}, {6:F3})）。\",\r\n            go.name, bc.size.x, bc.size.y, bc.size.z, bc.center.x, bc.center.y, bc.center.z);\r\n        return bc;\r\n    }\r\n\r\n    /// 生成模型；资源缺失时退化为占位方块（游戏仍可玩）。缩放与贴地由 FitAndGround 负责。\r\n    internal static GameObject SpawnModel(string resourcePath, Color fallbackColor, string goName)\r\n    {\r\n        GameObject prefab = Resources.Load<GameObject>(resourcePath);\r\n        GameObject go = null;\r\n        if (prefab != null)\r\n        {\r\n            go = Object.Instantiate(prefab);\r\n            go.name = goName;\r\n            Debug.Log(\"[CatCheese] 已从 Resources 生成「\" + resourcePath + \"」。\");\r\n        }\r\n        if (go == null)\r\n        {\r\n            go = GameObject.CreatePrimitive(PrimitiveType.Cube);\r\n            go.name = goName + \" (占位)\";\r\n            // 保留自带的 BoxCollider：占位方块本来就是「这东西该有的体积」，\r\n            // 之后 AddSolidBoxCollider 会按实测包围盒把它校正到正确尺寸。\r\n            go.GetComponent<Renderer>().sharedMaterial = MakeUrpMat(fallbackColor);\r\n            Debug.LogWarning(\"[CatCheese] Resources 里没有「\" + resourcePath + \"」（glTFast 可能还没解析完或模型未导入），已用占位方块代替。\");\r\n        }\r\n        SetLayerRecursively(go, PropLayer); // 生成物不参与射线，避免猫/奶酪互相当地面\r\n        return go;\r\n    }\r\n\r\n    static void SetLayerRecursively(GameObject go, int layer)\r\n    {\r\n        if (layer < 0) return;\r\n        go.layer = layer;\r\n        for (int i = 0; i < go.transform.childCount; i++)\r\n            SetLayerRecursively(go.transform.GetChild(i).gameObject, layer);\r\n    }\r\n\r\n    /// 奶酪贴图：FBX 导入不会自动连外部贴图，运行时手动接 albedo\r\n    internal static void WireCheeseTexture(GameObject cheese)\r\n    {\r\n        Texture2D albedo = Resources.Load<Texture2D>(\"GameProps/Cheese_0001_albedo\");\r\n        if (albedo == null)\r\n        {\r\n            Debug.LogWarning(\"[CatCheese] 没找到奶酪 albedo 贴图（GameProps/Cheese_0001_albedo），奶酪用默认白模。\");\r\n            return;\r\n        }\r\n        foreach (Renderer r in cheese.GetComponentsInChildren<Renderer>())\r\n        {\r\n            Material m = r.material; // 实例化，避免改到共享材质\r\n            m.mainTexture = albedo;\r\n        }\r\n    }\r\n\r\n    /// 用骨骼自动判别猫的正面（脚尖方向最可靠，头-盆骨兜底），对齐到移动方向\r\n    internal static void OrientCatByBones(GameObject cat, Vector3 moveDir)\r\n    {\r\n        Vector3 fwd = Vector3.zero;\r\n        int found = 0;\r\n        foreach (string side in new[] { \"L\", \"R\" })\r\n        {\r\n            Transform foot = FindBone(cat.transform, \"cat_bip-\" + side + \"-Foot\");\r\n            Transform toe = FindBone(cat.transform, \"cat_bip-\" + side + \"-Toe0\");\r\n            if (foot != null && toe != null)\r\n            {\r\n                Vector3 v = toe.position - foot.position;\r\n                v.y = 0f;\r\n                if (v.sqrMagnitude > 1e-8f) { fwd += v.normalized; found++; }\r\n            }\r\n        }\r\n        if (found == 0)\r\n        {\r\n            Transform pelvis = FindBone(cat.transform, \"cat_bip-Pelvis\");\r\n            Transform head = FindBone(cat.transform, \"cat_bip-Head\");\r\n            if (pelvis != null && head != null)\r\n            {\r\n                Vector3 v = head.position - pelvis.position;\r\n                v.y = 0f;\r\n                if (v.sqrMagnitude > 1e-6f) { fwd = v.normalized; found = 1; }\r\n            }\r\n        }\r\n        if (found > 0)\r\n        {\r\n            fwd = (fwd / found).normalized;\r\n            Quaternion fix = Quaternion.FromToRotation(fwd, moveDir); // 两个水平向量之间 ⇒ 只会绕 Y 转\r\n            cat.transform.rotation = fix * cat.transform.rotation;\r\n            Debug.Log(\"[CatCheese] 已按骨骼自动对齐猫的朝向。\");\r\n        }\r\n        else\r\n        {\r\n            cat.transform.rotation = Quaternion.LookRotation(moveDir);\r\n            Debug.LogWarning(\"[CatCheese] 没找到猫的骨骼节点，按默认朝向放置（若猫横着走，运行后把 Cat (auto) 绕 Y 转 180° 即可）。\");\r\n        }\r\n    }\r\n\r\n    static Transform FindBone(Transform t, string exactName)\r\n    {\r\n        if (t.name == exactName) return t;\r\n        for (int i = 0; i < t.childCount; i++)\r\n        {\r\n            Transform r = FindBone(t.GetChild(i), exactName);\r\n            if (r != null) return r;\r\n        }\r\n        return null;\r\n    }\r\n\r\n    /// 播放走路动画：优先 legacy Animation 组件，否则用 PlayableGraph（无需 AnimatorController）\r\n    internal static void PlayWalkAnimation(GameObject cat)\r\n    {\r\n        Animation legacy = cat.GetComponentInChildren<Animation>(true);\r\n        if (legacy != null && legacy.clip != null)\r\n        {\r\n            legacy.wrapMode = WrapMode.Loop;\r\n            if (!legacy.isPlaying) legacy.Play();\r\n            Debug.Log(\"[CatCheese] 猫走路动画已播放（legacy Animation，clip=\" + legacy.clip.name + \"）。\");\r\n            return;\r\n        }\r\n\r\n        AnimationClip[] clips = Resources.LoadAll<AnimationClip>(\"GameProps/Cat walk\");\r\n        if (clips == null || clips.Length == 0)\r\n        {\r\n            Debug.LogWarning(\"[CatCheese] 没找到猫的动画片段（GLB 可能还没被 glTFast 导入），猫暂时只平移不播动画。\");\r\n            return;\r\n        }\r\n        AnimationClip clip = clips[0];\r\n        foreach (AnimationClip c in clips)\r\n            if (c.name.ToLower().Contains(\"walk\")) { clip = c; break; }\r\n\r\n        Animator animator = cat.GetComponentInChildren<Animator>(true);\r\n        if (animator == null) animator = cat.AddComponent<Animator>();\r\n        animator.applyRootMotion = false; // 巡逻位移由 CatPatrol 驱动，不吃根运动\r\n\r\n        PlayableGraph graph = PlayableGraph.Create(\"CatWalkGraph\");\r\n        AnimationPlayableOutput output = AnimationPlayableOutput.Create(graph, \"catWalk\", animator);\r\n        AnimationClipPlayable playable = AnimationClipPlayable.Create(graph, clip);\r\n        playable.SetApplyPlayableIK(false);\r\n        output.SetSourcePlayable(playable);\r\n        graph.Play();\r\n        cat.AddComponent<PlayableGraphKeeper>().graph = graph;\r\n        Debug.Log(\"[CatCheese] 猫走路动画已播放（PlayableGraph，clip=\" + clip.name + \"）。\");\r\n    }\r\n\r\n    static Material MakeUrpMat(Color c)\r\n    {\r\n        Shader shader = Shader.Find(\"Universal Render Pipeline/Lit\");\r\n        if (shader == null) shader = Shader.Find(\"Standard\");\r\n        Material m = new Material(shader);\r\n        m.color = c;\r\n        return m;\r\n    }\r\n}\r\n\r\n/// 每帧把物体贴到脚下地面；FootOffset 由 CatCheeseSetup 用网格实测写入（根位置到模型底面）\r\ninternal class GroundStick : MonoBehaviour\r\n{\r\n    internal float FootOffset;\r\n    bool _verified;\r\n\r\n    void LateUpdate()\r\n    {\r\n        Vector3 p = transform.position;\r\n        float groundY;\r\n        if (CatCheeseSetup.TryGroundY(p, out groundY))\r\n        {\r\n            float target = groundY + FootOffset;\r\n            if (Mathf.Abs(p.y - target) > 0.0005f)\r\n                transform.position = new Vector3(p.x, target, p.z);\r\n        }\r\n\r\n        if (!_verified)\r\n        {\r\n            _verified = true;\r\n            Bounds b;\r\n            float g;\r\n            if (CatCheeseSetup.TryMeasureWorldBounds(gameObject, out b) && CatCheeseSetup.TryGroundY(transform.position, out g))\r\n            {\r\n                float gap = b.min.y - g;\r\n                if (Mathf.Abs(gap) > 0.03f)\r\n                    Debug.LogWarningFormat(\"[CatCheese] 贴地复核偏差：「{0}」底面 y={1:F3}，地面 y={2:F3}，差 {3:F3} m —— 若看着仍悬空/陷地，把这一行发我。\",\r\n                        name, b.min.y, g, gap);\r\n                else\r\n                    Debug.LogFormat(\"[CatCheese] 贴地复核通过：「{0}」底面 y={1:F3}，地面 y={2:F3}。\", name, b.min.y, g);\r\n            }\r\n        }\r\n    }\r\n}\r\n\r\n/// 猫在区域内随机取点巡逻：走到一个点、停顿一下、再走向下一个点，转身平滑。\r\n/// 走位时扫掠前方，遇到奶酪这类实体障碍就沿其表面滑过去 —— 是「绕开」，不是「穿过去」。\r\ninternal class CatPatrol : MonoBehaviour\r\n{\r\n    Bounds _area;\r\n    float _margin, _speed, _wait;\r\n    Vector3 _target;\r\n    bool _hasTarget;\r\n    float _dodge;               // 连续「绕行」了多久（用来判断是不是绕不出去了）\r\n\r\n    // —— 避障扫掠参数（由 ConfigureBody 按模型实测写入）——\r\n    int _propMask;              // 生成物所在层的掩码\r\n    float _castY = 0.25f;       // 扫掠球心相对根位置的高度\r\n    float _castR = 0.12f;       // 扫掠半径 ≈ 半身宽\r\n    float _look = 0.55f;        // 前视距离 ≈ 半身长 + 余量\r\n\r\n    public void Configure(Bounds area, float margin, float speed)\r\n    {\r\n        _area = area; _margin = margin; _speed = speed;\r\n    }\r\n\r\n    /// 由 CatCheeseSetup 在「缩放 + 贴地」完成后调用：把猫的实测体型换算成扫掠参数。\r\n    public void ConfigureBody(Bounds worldBox, float rootY)\r\n    {\r\n        if (worldBox.size.sqrMagnitude <= 0f)\r\n        {\r\n            Debug.LogWarning(\"[CatCheese] 猫：量不到体型，本次不做避障扫掠（会从奶酪里穿过去）。\");\r\n            return;\r\n        }\r\n        float halfW = Mathf.Min(worldBox.size.x, worldBox.size.z) * 0.5f; // 半身宽\r\n        float halfL = Mathf.Max(worldBox.size.x, worldBox.size.z) * 0.5f; // 半身长\r\n        _castR = Mathf.Clamp(halfW + 0.05f, 0.09f, 0.40f); // +5 cm 余量，免得身体边缘蹭到奶酪\r\n        _look = Mathf.Clamp(halfL + 0.30f, 0.35f, 1.50f);\r\n        _castY = (worldBox.min.y + worldBox.max.y) * 0.5f - rootY;\r\n        _propMask = CatCheeseSetup.PropMask;\r\n        Debug.LogFormat(\"[CatCheese] 猫的避障扫掠：半径 {0:F3} m、前视 {1:F3} m、球心高 {2:F3} m、层掩码 {3}。\",\r\n            _castR, _look, _castY, _propMask);\r\n    }\r\n\r\n    void Update()\r\n    {\r\n        if (_wait > 0f)\r\n        {\r\n            _wait -= Time.deltaTime;\r\n            return;\r\n        }\r\n        if (!_hasTarget) PickNext();\r\n\r\n        Vector3 pos = transform.position;\r\n        Vector3 to = _target - pos;\r\n        to.y = 0f;\r\n        float step = _speed * Time.deltaTime;\r\n        if (to.sqrMagnitude <= step * step)\r\n        {\r\n            transform.position = new Vector3(_target.x, pos.y, _target.z);\r\n            _hasTarget = false;\r\n            _dodge = 0f;\r\n            _wait = Random.Range(0.4f, 1.2f); // 到点后张望一下再走\r\n            return;\r\n        }\r\n\r\n        Vector3 dir = to.normalized;\r\n        Vector3 steer = Avoid(dir);\r\n\r\n        // 老是在绕行（方向被改掉超过 ~11°）而且绕了 2.5 s 还没绕到 → 换个目标点，\r\n        // 否则目标点在障碍背后时会贴着奶酪原地打转。\r\n        _dodge = Vector3.Dot(steer, dir) < 0.98f ? _dodge + Time.deltaTime : 0f;\r\n        if (_dodge > 2.5f)\r\n        {\r\n            _dodge = 0f;\r\n            _hasTarget = false;\r\n            return;\r\n        }\r\n\r\n        transform.position = pos + steer * step;\r\n        Quaternion look = Quaternion.LookRotation(steer);\r\n        transform.rotation = Quaternion.Slerp(transform.rotation, look, 8f * Time.deltaTime);\r\n    }\r\n\r\n    /// 前方球扫掠：撞到障碍就把前进方向投影到障碍表面 → 沿切线滑过去（经典 collide-and-slide）。\r\n    Vector3 Avoid(Vector3 dir)\r\n    {\r\n        if (_propMask == 0) return dir;\r\n\r\n        RaycastHit h;\r\n        if (!Physics.SphereCast(transform.position + Vector3.up * _castY, _castR, dir,\r\n                                out h, _look, _propMask, QueryTriggerInteraction.Ignore))\r\n            return dir;\r\n        if (h.collider == null || h.collider.transform.root == transform.root) return dir; // 撞到自己的部件，忽略\r\n\r\n        Vector3 n = h.normal;\r\n        n.y = 0f;\r\n        if (n.sqrMagnitude > 1e-4f)\r\n        {\r\n            Vector3 slide = Vector3.ProjectOnPlane(dir, n.normalized);\r\n            slide.y = 0f;\r\n            if (slide.sqrMagnitude > 1e-4f) return slide.normalized;\r\n        }\r\n        // 法线太竖直（扫到顶面）→ 没有可用切线，挑一条固定的侧向绕开\r\n        return new Vector3(-dir.z, 0f, dir.x).normalized;\r\n    }\r\n\r\n    void PickNext()\r\n    {\r\n        Vector3 min = _area.min + Vector3.one * _margin;\r\n        Vector3 max = _area.max - Vector3.one * _margin;\r\n        if (max.x < min.x) { float m = (min.x + max.x) * 0.5f; min.x = max.x = m; }\r\n        if (max.z < min.z) { float m = (min.z + max.z) * 0.5f; min.z = max.z = m; }\r\n\r\n        _target = new Vector3(Random.Range(min.x, max.x), transform.position.y, Random.Range(min.z, max.z));\r\n        // 目标点别落在奶酪里（否则会贴着它原地打转），试几次换一个\r\n        for (int i = 0; i < 8 && Blocked(_target); i++)\r\n            _target = new Vector3(Random.Range(min.x, max.x), transform.position.y, Random.Range(min.z, max.z));\r\n        _hasTarget = true;\r\n    }\r\n\r\n    /// 这个点是不是压在障碍上\r\n    bool Blocked(Vector3 p)\r\n    {\r\n        if (_propMask == 0) return false;\r\n        Vector3 o = p + Vector3.up * _castY;\r\n        int n = Physics.OverlapSphereNonAlloc(o, _castR + 0.15f, _overlap, _propMask, QueryTriggerInteraction.Ignore);\r\n        for (int i = 0; i < n; i++)\r\n            if (_overlap[i] != null && _overlap[i].transform.root != transform.root) return true;\r\n        return false;\r\n    }\r\n    static readonly Collider[] _overlap = new Collider[16];\r\n}\r\n\r\n/// 保住 PlayableGraph 的引用并在销毁时释放\r\ninternal class PlayableGraphKeeper : MonoBehaviour\r\n{\r\n    internal PlayableGraph graph;\r\n\r\n    void OnDestroy()\r\n    {\r\n        if (graph.IsValid()) graph.Destroy();\r\n    }\r\n}\r\n\r\n/// 胜负判定：收集 3 块奶酪、被猫抓则失败\r\ninternal class CatCheeseGame : MonoBehaviour\r\n{\r\n    internal Transform cat;\r\n    internal Transform[] cheeses;\r\n    internal CheeseHud hud;          // 右上角计数（可能为 null，判空再用）\r\n\r\n    [Header(\"吃到时的反馈\")]\r\n    public bool popOnEat = true;         // 被咬掉的小动画（先鼓一下再缩没）\r\n    public float eatPopDuration = 0.22f;\r\n\r\n    [Header(\"判定半径（觉得猫太凶 / 吃不到奶酪就调这里）\")]\r\n    public float catchRadius = 1.2f;   // 与猫的水平距离小于此值 → 被抓\r\n    public float eatRadius = 0.9f;     // 与奶酪的水平距离小于此值 → 吃到\r\n\r\n    const float CatTopY = 0.45f;     // 猫背高度（归一化 0.5 m 身高留一点余量）\r\n    const float PlayerHalf = 0.9f;   // 玩家胶囊中心到脚底\r\n    const float SameLevelY = 1.6f;   // 只有和奶酪高度差在这么以内才算同一层\r\n\r\n    bool _done;\r\n    bool _winPending;\r\n    bool _spawnReported;\r\n    bool[] _eaten;                   // 已经吃掉的那些（动画期间也算，避免重复计数）\r\n    int _collected;\r\n\r\n    void Update()\r\n    {\r\n        if (_done) return;\r\n\r\n        Vector3 playerCenter;\r\n        if (!TryGetPlayerCenter(out playerCenter)) return;\r\n        float feetY = playerCenter.y - PlayerHalf;\r\n\r\n        // —— 开局自检：出生点离猫多远（上次 Play 一块奶酪都没吃到就说明可能一出生就在猫旁边）——\r\n        if (!_spawnReported)\r\n        {\r\n            _spawnReported = true;\r\n            if (cat != null)\r\n            {\r\n                float d = HorizontalDist(playerCenter, cat.position);\r\n                Debug.LogFormat(\"[CatCheese] 出生点距猫 {0:F2} m（抓取半径 {1:F2} m，吃奶酪半径 {2:F2} m）——{3}\",\r\n                    d, catchRadius, eatRadius,\r\n                    d <= catchRadius ? \"★一出生就在抓取范围内！把玩家出生点挪远，或把 CatMoveSpace 挪开★\" : \"安全\");\r\n            }\r\n        }\r\n\r\n        // —— 被抓判定（跳到猫背上方不算）——\r\n        if (cat != null)\r\n        {\r\n            Vector3 catPos = cat.position;\r\n            bool jumpedOver = feetY > catPos.y + CatTopY;\r\n            if (!jumpedOver && HorizontalDist(playerCenter, catPos + Vector3.up * 0.25f) < catchRadius)\r\n            {\r\n                Lose();\r\n                return;\r\n            }\r\n        }\r\n\r\n        // —— 吃奶酪判定（逐块收集：靠近就消失，右上角计数 +1）——\r\n        if (cheeses != null)\r\n        {\r\n            if (_eaten == null) _eaten = new bool[cheeses.Length];\r\n\r\n            for (int i = 0; i < cheeses.Length; i++)\r\n            {\r\n                if (_eaten[i]) continue;            // 已经吃掉的别再判定（正在播动画的那块也算）\r\n                Transform ch = cheeses[i];\r\n                if (ch == null) continue;\r\n                bool sameLevel = Mathf.Abs(feetY - ch.position.y) < SameLevelY;\r\n                if (sameLevel && HorizontalDist(playerCenter, ch.position) < eatRadius)\r\n                {\r\n                    Eat(i, ch);\r\n                }\r\n\r\n            }\r\n\r\n            // 集齐了：等「被咬掉」的动画播完再切结算页，否则最后一块刚碰到就被切走、看不到它消失\r\n            if (_collected >= cheeses.Length && !_winPending)\r\n            {\r\n                _winPending = true;\r\n                StartCoroutine(WinAfterDelay(popOnEat ? eatPopDuration + 0.12f : 0f));\r\n            }\r\n        }\r\n    }\r\n\r\n    /// 吃掉一块：立刻计入数量并更新右上角，然后播「被咬掉」的小动画再隐藏\r\n    void Eat(int index, Transform ch)\r\n    {\r\n        _eaten[index] = true;      // 先标记，动画期间不会被重复判定\r\n        _collected++;\r\n        if (hud != null) hud.SetCollected(_collected);\r\n        Debug.LogFormat(\"[CatCheese] 吃到第 {0}/{1} 块奶酪！\", _collected, cheeses.Length);\r\n\r\n        if (popOnEat && ch.gameObject.activeInHierarchy) StartCoroutine(EatPop(ch));\r\n        else ch.gameObject.SetActive(false);\r\n    }\r\n\r\n    /// 被咬掉的小动画：先微微鼓一下再缩没，然后隐藏。\r\n    /// 只动缩放不动位置 —— 奶酪身上有 GroundStick 在 LateUpdate 里每帧贴地，改位置会被它顶回去。\r\n    IEnumerator EatPop(Transform ch)\r\n    {\r\n        float d = Mathf.Max(eatPopDuration, 0.01f);\r\n        Vector3 s0 = ch.localScale;\r\n        float t = 0f;\r\n        while (t < d)\r\n        {\r\n            if (ch == null) yield break;\r\n            t += Time.deltaTime;\r\n            float k = Mathf.Clamp01(t / d);\r\n            float scale = (1f + 0.4f * Mathf.Sin(k * Mathf.PI)) * (1f - k);   // 1 → 略鼓 → 0\r\n            ch.localScale = s0 * Mathf.Max(scale, 0.0001f);\r\n            yield return null;\r\n        }\r\n        if (ch != null) ch.gameObject.SetActive(false);\r\n    }\r\n\r\n    IEnumerator WinAfterDelay(float delay)\r\n    {\r\n        if (delay > 0f) yield return new WaitForSeconds(delay);\r\n        Win();\r\n    }\r\n\r\n    bool TryGetPlayerCenter(out Vector3 center)\r\n    {\r\n        CharacterController cc = FindFirstObjectByType<CharacterController>();\r\n        if (cc != null)\r\n        {\r\n            center = cc.transform.position + Vector3.up * PlayerHalf;\r\n            return true;\r\n        }\r\n        Camera cam = Camera.main;\r\n        if (cam != null)\r\n        {\r\n            center = cam.transform.position;\r\n            return true;\r\n        }\r\n        center = Vector3.zero;\r\n        return false;\r\n    }\r\n\r\n    static float HorizontalDist(Vector3 a, Vector3 b)\r\n    {\r\n        float dx = a.x - b.x, dz = a.z - b.z;\r\n        return Mathf.Sqrt(dx * dx + dz * dz);\r\n    }\r\n\r\n    void Win()\r\n    {\r\n        if (_done) return;\r\n        _done = true;\r\n        CatCheeseResult.Last = 1;\r\n        Debug.Log(\"[CatCheese] 集齐所有奶酪 —— 挑战成功！\");\r\n        CatCheeseEndScreen.Show(true);   // 直接在游戏画面上弹「You Win」\r\n    }\r\n\r\n    void Lose()\r\n    {\r\n        if (_done) return;\r\n        _done = true;\r\n        CatCheeseResult.Last = 0;\r\n        Debug.Log(\"[CatCheese] 被猫抓到了 —— 挑战失败。\");\r\n        CatCheeseEndScreen.Show(false);  // 直接在游戏画面上弹「Game Failed」\r\n    }\r\n}\r\n"},"CatCheeseTitle":{"path":"Assets/Scripts/CatCheeseTitle.cs","role":"Title screen: shows the game name/blurb, starts the game via button or Space/Enter.","source":"// @role Title screen: shows the game name/blurb, starts the game via button or Space/Enter.\r\n// @calls NbSceneSelect\r\n\r\n// CatCheeseTitle.cs — 游戏标题页（运行时自装配，不改场景文件）\r\n//\r\n// 内容取自 \"CGDD Game World Conceptualization\"：游戏名 Stray Rat、创作者 Maile & Xinyuan、\r\n// 概念一句话（扮一只流浪老鼠在公寓走廊觅食、躲猫）。\r\n// 文案全部英文 —— HUD 用的 Kindly Crunch 字体没有中文字形（写中文会渲染成空白，且不报错）。\r\n//\r\n// 开始方式（requirement 里的 \"a button to start the game (or other methods)\"）：\r\n//   ① 点 START GAME 按钮（鼠标左键按在按钮矩形内）\r\n//   ② 按 SPACE / ENTER\r\n// 都不走 EventSystem —— 本项目只启用新 Input System，旧 StandaloneInputModule 会失效；\r\n// 而运行时自建 EventSystem 还得给 InputSystemUIInputModule 配 actions，太脆。\r\n// 这里直接用 RectTransformUtility.RectangleContainsScreenPoint + Mouse/Keyboard.current，零依赖。\r\n//\r\n// 标题页期间：Time.timeScale = 0（猫停住、判定不推进）+ 把玩家的 AcceptInput 关掉 + 每帧解锁光标，\r\n// 所以「人还没开始，猫先走过来把玩家抓了」不会发生；也不依赖两个 Bootstrap 的先后顺序。\r\n// 注意「玩家不能动」用的是 AcceptInput 开关，不是 timeScale —— 新玩家读 unscaledDeltaTime，\r\n// 世界冻着它照样能走，两件事互不连坐。\r\n//\r\n// 只在本次 Play 第一次进入 SampleScene 时出现；按 R 重开一局不再弹（static _shownOnce）。\r\n\r\nusing System.Collections;\r\nusing TMPro;\r\nusing UnityEngine;\r\nusing UnityEngine.InputSystem;\r\nusing UnityEngine.SceneManagement;\r\nusing UnityEngine.UI;\r\n\r\ninternal class CatCheeseTitle : MonoBehaviour\r\n{\r\n    // 配色沿用工程现成的 UI 方案：按钮 #BF733A、强调 #FBD765。\r\n    // 白盒场景里亮字压不住，所以用暖黑全屏底把场景挡掉（顺带也挡住了右上角的 HUD）。\r\n    static readonly Color Accent = new Color(0.984f, 0.843f, 0.396f, 1f);   // #FBD765\r\n    static readonly Color Body = new Color(1f, 1f, 1f, 0.92f);\r\n    static readonly Color Dim = new Color(1f, 1f, 1f, 0.60f);\r\n    static readonly Color BtnIdle = new Color(0.749f, 0.451f, 0.227f, 1f);  // #BF733A\r\n    static readonly Color BtnHover = new Color(0.878f, 0.561f, 0.310f, 1f);\r\n    static readonly Color Backdrop = new Color(0.078f, 0.051f, 0.031f, 0.94f);\r\n    static readonly Color32 OutlineColor = new Color32(28, 16, 6, 255);\r\n\r\n    const string GameName = \"STRAY RAT\";\r\n    const string Tagline = \"a residential block, after dark\";\r\n    // 文案里只出现字母 / 数字 / 空格 / 句号逗号斜杠 —— 这套字体（Kindly Crunch）没有完整 ASCII，\r\n    // 破折号、波浪号、中点之类的装饰符号会渲染成空白且不报错。\r\n    const string Blurb =\r\n        \"Three places, ten levels each.  A residential block, a backyard patrol, a kitchen at night.\\n\" +\r\n        \"Carry the food home before the cats or the torch finds you.  A bite costs 10 health.\\n\" +\r\n        \"Pick your district after you press start.  Nothing is locked.\";\r\n    const string Creators = \"by Maile & Xinyuan\";\r\n    const string ButtonLabel = \"START GAME\";\r\n    const string Hint = \"click START GAME  (or anywhere)      or press any key\";\r\n\r\n    [Header(\"字号\")]\r\n    public float titleSize = 170f;\r\n    public float taglineSize = 46f;\r\n    public float blurbSize = 40f;\r\n    public float creatorsSize = 44f;\r\n    public float buttonLabelSize = 48f;\r\n    public float hintSize = 32f;\r\n\r\n    [Header(\"布局\")]\r\n    public float buttonWidth = 420f;\r\n    public float buttonHeight = 110f;\r\n    public int sortingOrder = 200;          // 压过 HUD(50) 和结算层(100)\r\n    public float inputDelay = 0.45f;        // 防误触：刚进来先不响应输入\r\n\r\n    public float autoStartAfter = 12f;      // 没人操作就自己开始（0 = 永不自动开始）\r\n\r\n    static bool _shownOnce;\r\n    static CatCheeseTitle _instance;\r\n\r\n    /// 标题页是不是还挡在前面。\r\n    /// NbGame 靠它区分「世界是被标题页冻住的」和「世界本来就该静止」——\r\n    /// 分不清这两件事，就会把\"没人点开始\"误诊成\"玩家走不动\"。\r\n    internal static bool Showing { get; private set; }\r\n\r\n    RectTransform _buttonRect;\r\n    Image _buttonImage;\r\n    CanvasGroup _group;\r\n    Sprite _white;\r\n    float _bornAt;\r\n    bool _starting;\r\n\r\n    [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)]\r\n    static void ResetStatics()\r\n    {\r\n        _shownOnce = false;\r\n        _instance = null;\r\n        Showing = false;\r\n    }\r\n\r\n    [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]\r\n    static void Bootstrap()\r\n    {\r\n        SceneManager.sceneLoaded += (scene, mode) => Install(scene);\r\n        Scene active = SceneManager.GetActiveScene();\r\n        if (active.isLoaded) Install(active);\r\n    }\r\n\r\n    static void Install(Scene scene)\r\n    {\r\n        if (scene.name != \"SampleScene\") return;\r\n        if (_shownOnce) return;             // 按 R 重开一局：直接开始，不再拦一道标题页\r\n        if (_instance != null) return;\r\n\r\n        _shownOnce = true;\r\n        _instance = new GameObject(\"CatCheeseTitle (auto)\").AddComponent<CatCheeseTitle>();\r\n        _instance.Build();\r\n    }\r\n\r\n    void Build()\r\n    {\r\n        _bornAt = Time.unscaledTime;\r\n        Showing = true;\r\n        Time.timeScale = 0f;                // 猫停住、判定不推进（标题页期间世界静止）\r\n        FreezePlayer();\r\n\r\n        GameObject canvasGo = new GameObject(\"Title Canvas (auto)\", typeof(Canvas), typeof(CanvasScaler));\r\n        canvasGo.transform.SetParent(transform, false);\r\n        Canvas canvas = canvasGo.GetComponent<Canvas>();\r\n        canvas.renderMode = RenderMode.ScreenSpaceOverlay;\r\n        canvas.sortingOrder = sortingOrder;\r\n\r\n        CanvasScaler scaler = canvasGo.GetComponent<CanvasScaler>();\r\n        scaler.uiScaleMode = CanvasScaler.ScaleMode.ScaleWithScreenSize;\r\n        scaler.referenceResolution = new Vector2(1920f, 1080f);\r\n        scaler.matchWidthOrHeight = 0.5f;\r\n\r\n        _group = canvasGo.AddComponent<CanvasGroup>();\r\n        _group.alpha = 1f;\r\n\r\n        _white = MakeWhiteSprite();\r\n\r\n        // —— 全屏底（也顺便把场景和右上角 HUD 挡住）——\r\n        RectTransform bg = NewRect(\"Backdrop\", canvasGo.transform);\r\n        bg.anchorMin = Vector2.zero;\r\n        bg.anchorMax = Vector2.one;\r\n        bg.offsetMin = Vector2.zero;\r\n        bg.offsetMax = Vector2.zero;\r\n        Image dim = bg.gameObject.AddComponent<Image>();\r\n        dim.sprite = _white;\r\n        dim.type = Image.Type.Simple;\r\n        dim.color = Backdrop;\r\n        dim.raycastTarget = false;\r\n\r\n        TMP_FontAsset font = ResolveFont();\r\n\r\n        // —— 游戏名 ——\r\n        TextMeshProUGUI title = MakeText(\"Title\", canvasGo.transform, font, titleSize, Accent, TextAlignmentOptions.Center);\r\n        title.text = GameName;\r\n        title.characterSpacing = 6f;\r\n        title.rectTransform.sizeDelta = new Vector2(1800f, titleSize * 1.4f);\r\n        title.rectTransform.anchoredPosition = new Vector2(0f, 268f);\r\n\r\n        // —— 一句话定位 ——\r\n        TextMeshProUGUI tagline = MakeText(\"Tagline\", canvasGo.transform, font, taglineSize, Body, TextAlignmentOptions.Center);\r\n        tagline.text = Tagline;\r\n        tagline.rectTransform.sizeDelta = new Vector2(1800f, taglineSize * 2f);\r\n        tagline.rectTransform.anchoredPosition = new Vector2(0f, 150f);\r\n\r\n        // —— 分隔线 ——\r\n        RectTransform rule = NewRect(\"Rule\", canvasGo.transform);\r\n        rule.sizeDelta = new Vector2(760f, 4f);\r\n        rule.anchoredPosition = new Vector2(0f, 96f);\r\n        Image ruleImg = rule.gameObject.AddComponent<Image>();\r\n        ruleImg.sprite = _white;\r\n        ruleImg.type = Image.Type.Simple;\r\n        ruleImg.color = new Color(Accent.r, Accent.g, Accent.b, 0.55f);\r\n        ruleImg.raycastTarget = false;\r\n\r\n        // —— 玩法简介（basic information）——\r\n        TextMeshProUGUI blurb = MakeText(\"Blurb\", canvasGo.transform, font, blurbSize, Body, TextAlignmentOptions.Center);\r\n        blurb.text = Blurb;\r\n        blurb.lineSpacing = 14f;\r\n        blurb.rectTransform.sizeDelta = new Vector2(1500f, blurbSize * 5f);\r\n        blurb.rectTransform.anchoredPosition = new Vector2(0f, -8f);\r\n\r\n        // —— 创作者 ——\r\n        TextMeshProUGUI creators = MakeText(\"Creators\", canvasGo.transform, font, creatorsSize, Accent, TextAlignmentOptions.Center);\r\n        creators.text = Creators;\r\n        creators.rectTransform.sizeDelta = new Vector2(1500f, creatorsSize * 2f);\r\n        creators.rectTransform.anchoredPosition = new Vector2(0f, -186f);\r\n\r\n        // —— START 按钮 ——\r\n        _buttonRect = NewRect(\"StartButton\", canvasGo.transform);\r\n        _buttonRect.sizeDelta = new Vector2(buttonWidth, buttonHeight);\r\n        _buttonRect.anchoredPosition = new Vector2(0f, -318f);\r\n        _buttonImage = _buttonRect.gameObject.AddComponent<Image>();\r\n        _buttonImage.sprite = _white;\r\n        _buttonImage.type = Image.Type.Simple;\r\n        _buttonImage.color = BtnIdle;\r\n        _buttonImage.raycastTarget = false;\r\n\r\n        TextMeshProUGUI btnText = MakeText(\"StartLabel\", _buttonRect, font, buttonLabelSize, Color.white, TextAlignmentOptions.Center);\r\n        btnText.text = ButtonLabel;\r\n        btnText.rectTransform.anchorMin = Vector2.zero;\r\n        btnText.rectTransform.anchorMax = Vector2.one;\r\n        btnText.rectTransform.offsetMin = Vector2.zero;\r\n        btnText.rectTransform.offsetMax = Vector2.zero;\r\n\r\n        // —— 底部提示（\"or other methods\" 里的按键方式）——\r\n        TextMeshProUGUI hint = MakeText(\"Hint\", canvasGo.transform, font, hintSize, Dim, TextAlignmentOptions.Center);\r\n        hint.text = Hint;\r\n        hint.rectTransform.sizeDelta = new Vector2(1600f, hintSize * 2f);\r\n        hint.rectTransform.anchoredPosition = new Vector2(0f, -442f);\r\n\r\n        Debug.LogFormat(\"[CatCheese] 标题页已显示：{0} / {1} / {2}（点 START GAME 或按 SPACE / ENTER 开始）\",\r\n            GameName, Tagline, Creators);\r\n    }\r\n\r\n    void Update()\r\n    {\r\n        if (_starting) return;\r\n\r\n        // 钉住：不管 FirstPersonMove 的 Start 有没有先跑过，标题页期间都别让玩家动、别让光标被锁、\r\n        // 别让世界推进（三个 Bootstrap 的先后顺序是不保证的，所以每帧重申一次）\r\n        Time.timeScale = 0f;\r\n        Cursor.lockState = CursorLockMode.None;\r\n        Cursor.visible = true;\r\n        FreezePlayer();\r\n\r\n        Mouse mouse = Mouse.current;\r\n        if (mouse != null && _buttonImage != null)\r\n        {\r\n            bool over = RectTransformUtility.RectangleContainsScreenPoint(_buttonRect, mouse.position.ReadValue());\r\n            _buttonImage.color = over ? BtnHover : BtnIdle;\r\n        }\r\n\r\n        if (Time.unscaledTime - _bornAt < inputDelay) return;   // 防误触\r\n\r\n        // 判定比原来宽得多：**点屏幕任何地方**、**按任何键**都算开始。\r\n        // 以前只认\"点在按钮矩形里\"或 SPACE/ENTER —— 差几个像素就\"点了没反应\"，\r\n        // 而这时世界是 timeScale=0 冻着的，玩家看到的正是\"画面在、怎么按都不动\"。\r\n        bool clicked = mouse != null && mouse.leftButton.wasPressedThisFrame;\r\n        Keyboard kb = Keyboard.current;\r\n        bool pressed = kb != null && kb.anyKey.wasPressedThisFrame;\r\n\r\n        if (clicked || pressed) { StartGame(); return; }\r\n\r\n        // 兜底：一直没人动就自己开始。\r\n        // 没有这一条时，只要标题页没被关掉，世界就永远冻着 —— 而屏幕上看不出\"是标题页没关\"。\r\n        if (autoStartAfter > 0f && Time.unscaledTime - _bornAt > autoStartAfter)\r\n        {\r\n            Debug.LogFormat(\"[CatCheese] 标题页停留 {0:F0} 秒没有任何输入，自动开始（免得世界一直冻在 timeScale=0）。\",\r\n                autoStartAfter);\r\n            StartGame();\r\n        }\r\n    }\r\n\r\n    void StartGame()\r\n    {\r\n        _starting = true;\r\n        Showing = false;\r\n        Debug.Log(\"[CatCheese] 标题页收起 —— 进入场景选择。\");\r\n\r\n        // **这里故意不交还操作权。** 接下来是场景选择页，玩家在这一屏不该能走；\r\n        // 操作权在\"选中场景\"那一刻交（NbGame.LoadLevel 会设 AcceptInput = true）。\r\n        // 旧版在这里直接打开，结果选择页浮在上面、底下的人还能跑 —— 会走到场景边缘去。\r\n        if (NbPlayer.I != null) NbPlayer.I.AcceptInput = false;\r\n\r\n        Cursor.lockState = CursorLockMode.None;\r\n        Cursor.visible = true;\r\n\r\n        Time.timeScale = 1f;\r\n\r\n        NbSceneSelect.Show();\r\n        StartCoroutine(FadeOut());\r\n    }\r\n\r\n    IEnumerator FadeOut()\r\n    {\r\n        float d = 0.25f, t = 0f;\r\n        while (t < d)\r\n        {\r\n            t += Time.unscaledDeltaTime;\r\n            if (_group != null) _group.alpha = Mathf.Clamp01(1f - t / d);\r\n            yield return null;\r\n        }\r\n        _instance = null;\r\n        Destroy(gameObject);\r\n    }\r\n\r\n    void FreezePlayer()\r\n    {\r\n        // 只关\"能不能操作\"这一个开关，不碰 timeScale、也不 disable 任何组件。\r\n        // 新玩家（NbPlayer）的移动读的是 unscaledDeltaTime，所以\"世界冻着\"和\"人不能动\"\r\n        // 是两件独立的事 —— 这样标题页永远不会顺带把玩家永久锁死。\r\n        if (NbPlayer.I != null) NbPlayer.I.AcceptInput = false;\r\n    }\r\n\r\n    TextMeshProUGUI MakeText(string goName, Transform parent, TMP_FontAsset font, float size, Color color, TextAlignmentOptions align)\r\n    {\r\n        RectTransform rt = NewRect(goName, parent);\r\n        TextMeshProUGUI t = rt.gameObject.AddComponent<TextMeshProUGUI>();\r\n        if (font != null) t.font = font;\r\n        t.fontSize = size;\r\n        t.color = color;\r\n        t.alignment = align;\r\n        t.textWrappingMode = TextWrappingModes.NoWrap;\r\n        t.overflowMode = TextOverflowModes.Overflow;\r\n        t.raycastTarget = false;\r\n        ApplyOutline(t, OutlineColor, 0.18f);\r\n        return t;\r\n    }\r\n\r\n    /// TMP 描边只能这样加：启用 OUTLINE_ON 关键字 + 写材质属性。\r\n    /// 只设 text.outlineWidth 无效（字体资源里的材质默认没开这个关键字），加 Outline/Shadow 组件更没用 ——\r\n    /// TMP 根本不走 uGUI 的 mesh effect 通道，而且一声不响。\r\n    static void ApplyOutline(TextMeshProUGUI t, Color32 color, float width)\r\n    {\r\n        Material m = t.fontMaterial;\r\n        if (m == null || !m.HasProperty(\"_OutlineWidth\")) return;\r\n        m.EnableKeyword(\"OUTLINE_ON\");\r\n        m.SetFloat(\"_OutlineWidth\", width);\r\n        m.SetColor(\"_OutlineColor\", color);\r\n    }\r\n\r\n    static TMP_FontAsset ResolveFont()\r\n    {\r\n        HudFontRef r = Resources.Load<HudFontRef>(\"GameProps/HudFont\");\r\n        if (r != null && r.font != null) return r.font;\r\n\r\n        Debug.LogWarning(\"[CatCheese] 取不到 Resources/GameProps/HudFont 里的字体引用，标题页退回 TMP 默认字体。\");\r\n        return TMP_Settings.defaultFontAsset;\r\n    }\r\n\r\n    static RectTransform NewRect(string goName, Transform parent)\r\n    {\r\n        GameObject go = new GameObject(goName, typeof(RectTransform));\r\n        RectTransform rt = (RectTransform)go.transform;\r\n        rt.SetParent(parent, false);\r\n        rt.anchorMin = rt.anchorMax = rt.pivot = new Vector2(0.5f, 0.5f);\r\n        rt.anchoredPosition = Vector2.zero;\r\n        return rt;\r\n    }\r\n\r\n    static Sprite MakeWhiteSprite()\r\n    {\r\n        Texture2D tex = new Texture2D(1, 1, TextureFormat.RGBA32, false);\r\n        tex.SetPixel(0, 0, Color.white);\r\n        tex.Apply();\r\n        tex.hideFlags = HideFlags.HideAndDontSave;\r\n        Sprite s = Sprite.Create(tex, new Rect(0f, 0f, 1f, 1f), new Vector2(0.5f, 0.5f));\r\n        s.hideFlags = HideFlags.HideAndDontSave;\r\n        return s;\r\n    }\r\n\r\n    void OnDestroy()\r\n    {\r\n        // 这一页没了就不再冻世界。少这一行，只要它不是走 StartGame 消失的\r\n        // （比如重开场景、被别的东西删掉），Showing 会一直停在 true，NbGame 就再也不敢放开 timeScale。\r\n        if (_instance == this) _instance = null;\r\n        Showing = false;\r\n\r\n        if (_white != null)\r\n        {\r\n            if (_white.texture != null) Destroy(_white.texture);\r\n            Destroy(_white);\r\n            _white = null;\r\n        }\r\n    }\r\n}\r\n"},"CheeseHud":{"path":"Assets/Scripts/CheeseHud.cs","role":"Legacy HUD: top-right cheese counter for the cat-and-cheese game.","source":"// @role Legacy HUD: top-right cheese counter for the cat-and-cheese game.\r\n\r\n// CheeseHud.cs — 右上角的奶酪计数（运行时自装配，不改场景文件）\r\n//\r\n// 显示：右上角一行小字「cheese」+ 一行大字「1 / 3」。吃到一块时数字会弹一下并闪成奶酪黄。\r\n//\r\n// 字体：优先用工程 UI 里那款 Kindly Crunch（Assets/Fonts/TMP_KindlyCrunch.asset），\r\n//       这样 HUD 和 UI_Screens 里的结算页字体完全一致。运行时只能 Resources.Load，\r\n//       所以用 Resources/GameProps/HudFont.asset 做引用中转（见 HudFontRef.cs）。\r\n//       取不到时退回 TMP 默认字体，HUD 照常显示，只是字体不同。\r\n//\r\n// 可读性：白盒场景墙面偏白，纯白文字会看不见。所以默认\r\n//         ① 加一块半透明深色小底板（backingAlpha，调成 0 就是纯文字）\r\n//         ② 给文字开 SDF 描边（outlineText）\r\n//\r\n// ⚠️ TMP 的文字不走 uGUI 的 Outline/Shadow 组件通道（那些只对 legacy Text 生效，\r\n//    加了也不会有任何效果、也不报错）。要给 TMP 加描边只能改 SDF 材质：\r\n//    启用 OUTLINE_ON 关键字 + 设 _OutlineWidth / _OutlineColor。见 ApplyOutline。\r\n\r\nusing TMPro;\r\nusing UnityEngine;\r\nusing UnityEngine.UI;\r\n\r\ninternal class CheeseHud : MonoBehaviour\r\n{\r\n    // 色调取自 UI_Screens 里现成的方案：按钮 #BF733A、强调 #FBD765\r\n    static readonly Color LabelColor   = new Color(0.984f, 0.843f, 0.396f, 1f); // #FBD765\r\n    static readonly Color CountColor   = new Color(1f, 1f, 1f, 1f);\r\n    static readonly Color PulseColor   = new Color(1f, 0.906f, 0.478f, 1f);     // 吃到时闪的奶酪黄\r\n    static readonly Color BackingColor = new Color(0.16f, 0.11f, 0.07f, 1f);    // 深棕黑，配合 backingAlpha\r\n    static readonly Color32 OutlineColor = new Color32(28, 16, 6, 255);\r\n\r\n    [Header(\"布局\")]\r\n    public float cornerMargin = 36f;\r\n    public int sortingOrder = 50;          // SampleScene 里没有别的画布，正数即可\r\n\r\n    [Header(\"文字\")]\r\n    public string label = \"cheese\";\r\n    public float labelSize = 30f;\r\n    public float countSize = 64f;\r\n    public string countFormat = \"{0} / {1}\";   // {0}=已吃到，{1}=总数\r\n\r\n    [Header(\"可读性（压在偏白的白盒画面上）\")]\r\n    [Range(0f, 1f)] public float backingAlpha = 0.42f;  // 0 = 不要底板，纯文字\r\n    public bool outlineText = true;                     // SDF 描边\r\n\r\n    [Header(\"吃到时的反馈\")]\r\n    public float popScale = 0.30f;\r\n    public float popDuration = 0.28f;\r\n\r\n    RectTransform _countRect;\r\n    TextMeshProUGUI _labelText;\r\n    TextMeshProUGUI _countText;\r\n    Sprite _white;\r\n    int _total;\r\n    int _collected;\r\n    float _pop;   // 1 → 0，吃到时用\r\n\r\n    /// 造一个右上角奶酪计数；调用方用 SetCollected 更新\r\n    internal static CheeseHud Create(int total)\r\n    {\r\n        GameObject go = new GameObject(\"CheeseHud (auto)\");\r\n        CheeseHud hud = go.AddComponent<CheeseHud>();\r\n        hud.Build(total);\r\n        return hud;\r\n    }\r\n\r\n    void Build(int total)\r\n    {\r\n        _total = Mathf.Max(total, 0);\r\n        TMP_FontAsset font = ResolveFont();\r\n\r\n        GameObject canvasGo = new GameObject(\"CheeseHud Canvas (auto)\", typeof(Canvas), typeof(CanvasScaler));\r\n        canvasGo.transform.SetParent(transform, false);\r\n        Canvas canvas = canvasGo.GetComponent<Canvas>();\r\n        canvas.renderMode = RenderMode.ScreenSpaceOverlay;\r\n        canvas.sortingOrder = sortingOrder;\r\n\r\n        CanvasScaler scaler = canvasGo.GetComponent<CanvasScaler>();\r\n        scaler.uiScaleMode = CanvasScaler.ScaleMode.ScaleWithScreenSize;\r\n        scaler.referenceResolution = new Vector2(1920f, 1080f);\r\n        scaler.matchWidthOrHeight = 0.5f;\r\n\r\n        RectTransform root = NewRect(\"HudRoot\", canvasGo.transform);\r\n        root.anchorMin = root.anchorMax = root.pivot = new Vector2(1f, 1f);   // 贴右上角\r\n        root.anchoredPosition = new Vector2(-cornerMargin, -cornerMargin);\r\n        root.sizeDelta = new Vector2(280f, labelSize + countSize + 40f);\r\n\r\n        // —— 可选底板（默认开一点点：白盒场景偏白，纯白字会看不见）——\r\n        if (backingAlpha > 0.001f)\r\n        {\r\n            _white = MakeWhiteSprite();\r\n            RectTransform bg = NewRect(\"Backing\", root);\r\n            bg.anchorMin = Vector2.zero;\r\n            bg.anchorMax = Vector2.one;\r\n            bg.offsetMin = new Vector2(-18f, -14f);   // 往外扩一圈，让文字不贴边\r\n            bg.offsetMax = new Vector2(18f, 14f);\r\n            Image backing = bg.gameObject.AddComponent<Image>();\r\n            backing.sprite = _white;\r\n            backing.type = Image.Type.Simple;\r\n            backing.color = new Color(BackingColor.r, BackingColor.g, BackingColor.b, backingAlpha);\r\n            backing.raycastTarget = false;\r\n        }\r\n\r\n        // —— 小字标签 ——\r\n        _labelText = MakeText(\"Label\", root, font, labelSize, LabelColor);\r\n        _labelText.text = label;\r\n        RectTransform lr = _labelText.rectTransform;\r\n        lr.anchorMin = lr.anchorMax = lr.pivot = new Vector2(1f, 1f);\r\n        lr.sizeDelta = new Vector2(root.sizeDelta.x, labelSize + 10f);\r\n        lr.anchoredPosition = Vector2.zero;\r\n\r\n        // —— 大号计数（右对齐：数字变长时往左长，不会跑出屏幕）——\r\n        _countText = MakeText(\"Count\", root, font, countSize, CountColor);\r\n        _countRect = _countText.rectTransform;\r\n        _countRect.anchorMin = _countRect.anchorMax = _countRect.pivot = new Vector2(1f, 1f);\r\n        _countRect.sizeDelta = new Vector2(root.sizeDelta.x, countSize + 18f);\r\n        _countRect.anchoredPosition = new Vector2(0f, -(labelSize + 10f));\r\n\r\n        Refresh();\r\n        Debug.LogFormat(\"[CheeseHud] 右上角奶酪计数已就位（共 {0} 块）。\", _total);\r\n    }\r\n\r\n    /// 更新已吃到的数量（吃掉一块就调一次）\r\n    internal void SetCollected(int collected)\r\n    {\r\n        _collected = Mathf.Clamp(collected, 0, _total);\r\n        Refresh();\r\n        _pop = 1f;\r\n    }\r\n\r\n    void Refresh()\r\n    {\r\n        if (_countText != null) _countText.text = string.Format(countFormat, _collected, _total);\r\n    }\r\n\r\n    void Update()\r\n    {\r\n        if (_pop <= 0f) return;\r\n\r\n        // 用 unscaledDeltaTime：万一有人把 timeScale 设成 0（比如加了暂停），HUD 也不会僵住\r\n        _pop = Mathf.Max(0f, _pop - Time.unscaledDeltaTime / Mathf.Max(popDuration, 0.01f));\r\n\r\n        float k = Mathf.Sin(_pop * Mathf.PI);   // _pop 1→0 时 k 走 0→1→0，天然缓入缓出\r\n        if (_countRect != null) _countRect.localScale = Vector3.one * (1f + popScale * k);\r\n        if (_countText != null) _countText.color = Color.Lerp(CountColor, PulseColor, k);\r\n    }\r\n\r\n    TextMeshProUGUI MakeText(string goName, Transform parent, TMP_FontAsset font, float size, Color color)\r\n    {\r\n        RectTransform rt = NewRect(goName, parent);\r\n        TextMeshProUGUI t = rt.gameObject.AddComponent<TextMeshProUGUI>();\r\n        if (font != null) t.font = font;\r\n        t.fontSize = size;\r\n        t.color = color;\r\n        t.alignment = TextAlignmentOptions.TopRight;\r\n        t.textWrappingMode = TextWrappingModes.NoWrap;\r\n        t.overflowMode = TextOverflowModes.Overflow;\r\n        t.raycastTarget = false;                 // 纯显示，别挡任何点击\r\n        if (outlineText) ApplyOutline(t, OutlineColor, 0.18f);\r\n        return t;\r\n    }\r\n\r\n    /// TMP 的描边只能这样加：启用 OUTLINE_ON 关键字 + 写材质属性。\r\n    /// 只设 text.outlineWidth 是没用的 —— SetOutlineThickness 只写浮点、不启用关键字，\r\n    /// 而字体资源里的材质默认没开这个关键字。\r\n    static void ApplyOutline(TextMeshProUGUI t, Color32 color, float width)\r\n    {\r\n        Material m = t.fontMaterial;             // 取实例（每份 Text 一份，不动共享材质）\r\n        if (m == null || !m.HasProperty(\"_OutlineWidth\")) return;\r\n        m.EnableKeyword(\"OUTLINE_ON\");\r\n        m.SetFloat(\"_OutlineWidth\", width);\r\n        m.SetColor(\"_OutlineColor\", color);\r\n    }\r\n\r\n    static TMP_FontAsset ResolveFont()\r\n    {\r\n        HudFontRef r = Resources.Load<HudFontRef>(\"GameProps/HudFont\");\r\n        if (r != null && r.font != null) return r.font;\r\n\r\n        Debug.LogWarning(\"[CheeseHud] 取不到 Resources/GameProps/HudFont 里的字体引用，退回 TMP 默认字体（HUD 仍会显示，只是字体与结算页不同）。\");\r\n        TMP_FontAsset def = TMP_Settings.defaultFontAsset;\r\n        if (def == null)\r\n            Debug.LogError(\"[CheeseHud] TMP 默认字体也是空的 —— 请确认 Assets/TextMesh Pro 已导入（Window > TextMeshPro > Import TMP Essential Resources）。\");\r\n        return def;\r\n    }\r\n\r\n    static RectTransform NewRect(string goName, Transform parent)\r\n    {\r\n        GameObject go = new GameObject(goName, typeof(RectTransform));\r\n        RectTransform rt = (RectTransform)go.transform;\r\n        rt.SetParent(parent, false);\r\n        return rt;\r\n    }\r\n\r\n    static Sprite MakeWhiteSprite()\r\n    {\r\n        Texture2D tex = new Texture2D(1, 1, TextureFormat.RGBA32, false);\r\n        tex.SetPixel(0, 0, Color.white);\r\n        tex.Apply();\r\n        tex.hideFlags = HideFlags.HideAndDontSave;\r\n        Sprite s = Sprite.Create(tex, new Rect(0f, 0f, 1f, 1f), new Vector2(0.5f, 0.5f));\r\n        s.hideFlags = HideFlags.HideAndDontSave;\r\n        return s;\r\n    }\r\n\r\n    void OnDestroy()\r\n    {\r\n        // 自建的贴图/Sprite 要自己销毁，否则每次切场景泄漏一张\r\n        if (_white != null)\r\n        {\r\n            if (_white.texture != null) Destroy(_white.texture);\r\n            Destroy(_white);\r\n            _white = null;\r\n        }\r\n    }\r\n}\r\n"},"Entry":{"path":"Assets/Scripts/Entry.cs","role":"Entry point: Start button that loads SampleScene.","source":"// @role Entry point: Start button that loads SampleScene.\r\n\r\nusing UnityEngine;\r\nusing UnityEngine.SceneManagement;\r\nusing UnityEngine.UI;\r\n\r\npublic class Entry : MonoBehaviour\r\n{\r\n    public Button start;\r\n    // Start is called once before the first execution of Update after the MonoBehaviour is created\r\n    void Start()\r\n    {\r\n        start.onClick.AddListener(startGame);\r\n    }\r\n\r\n    // Update is called once per frame\r\n    void Update()\r\n    {\r\n        \r\n    }\r\n\r\n    void startGame()\r\n    {\r\n        SceneManager.LoadScene(\"SampleScene\");\r\n    }\r\n\r\n    private void OnDestroy()\r\n    {\r\n        start.onClick.RemoveListener(startGame);\r\n    }\r\n}\r\n"},"FirstPersonMove":{"path":"Assets/Scripts/FirstPersonMove.cs","role":"Legacy first-person mover for the scene's old FirstPersonController (superseded by NbPlayer).","source":"// @role Legacy first-person mover for the scene's old FirstPersonController (superseded by NbPlayer).\r\n\r\n// FirstPersonMove.cs — 给场景里的 FirstPersonController 加第一人称移动（运行时自装配）\r\n//\r\n// 键位：WASD / 方向键走路，Shift 跑 ×2，Space 跳，鼠标转视角，Esc 释放鼠标、点击画面重新锁定。\r\n// 约束：本项目只启用新 Input System（activeInputHandler: 1），全部用 UnityEngine.InputSystem，\r\n//       用旧版 Input.* 会直接抛异常。\r\n// 自装配：Bootstrap 在 SampleScene 加载后按名字找「FirstPersonController」，没挂本组件就补上；\r\n//         缺 CharacterController 也补上；同时移除 FlyCamera 实例（它的 Start 会禁用其它相机，和玩家相机打架）。\r\n// 也可以手动拖到任意物体上用，不依赖 Bootstrap。\r\n\r\nusing UnityEngine;\r\nusing UnityEngine.InputSystem;\r\nusing UnityEngine.SceneManagement;\r\n\r\npublic class FirstPersonMove : MonoBehaviour\r\n{\r\n    [Header(\"移动\")]\r\n    public float walkSpeed = 3.5f;\r\n    public float runMultiplier = 2f;\r\n\r\n    [Header(\"跳跃 / 重力\")]\r\n    public float jumpVelocity = 5f;\r\n    public float gravity = -18f;\r\n\r\n    [Header(\"视角\")]\r\n    public bool enableMouseLook = true;\r\n    public float lookSensitivity = 0.12f; // 度/像素，与 FlyCamera 一致\r\n\r\n    CharacterController _cc;\r\n    Transform _head;\r\n    float _pitch;\r\n    float _vy;\r\n    bool _cursorLocked;\r\n\r\n    // 刚锁光标 / 窗口刚拿回焦点的那一帧，鼠标 delta 是一次巨大的跳变（macOS 上尤其明显）。\r\n    // 一帧就能把俯仰顶到 −89°，画面变成\"低头看自己脚下一块地砖\" ——\r\n    // 地砖没有花纹、光照又平，整屏就是一个均匀的灰面，走起来画面几乎不变，\r\n    // 看上去就是\"卡在这儿动不了\"。所以这段时间内的 delta 一律丢弃。\r\n    float _ignoreMouseUntil;\r\n\r\n    // 眼高。玩家原点在**脚底**（CharacterController 的 center 是 (0, 0.9, 0)），\r\n    // 而场景里相机的本地 y 只有 0.26 —— 眼睛离地 0.3 m，视角跟趴在地上一样。\r\n    internal const float EyeHeight = 1.62f;\r\n\r\n    void Start()\r\n    {\r\n        _cc = GetComponent<CharacterController>();\r\n        if (_cc == null)\r\n        {\r\n            _cc = gameObject.AddComponent<CharacterController>();\r\n            _cc.height = 1.8f;\r\n            _cc.radius = 0.3f;\r\n            _cc.center = new Vector3(0f, 0.9f, 0f);\r\n            _cc.slopeLimit = 45f;\r\n            _cc.stepOffset = 0.35f;\r\n            _cc.skinWidth = 0.03f;\r\n            _cc.minMoveDistance = 0f;\r\n            Debug.Log(\"[FirstPersonMove] 你没加 CharacterController，已自动补一个（h1.8/r0.3）。\");\r\n        }\r\n\r\n        // 视角用子级相机（你 Hierarchy 里的 Main Camera）；找不到就造一个\r\n        Camera cam = GetComponentInChildren<Camera>(true);\r\n        if (cam != null)\r\n        {\r\n            _head = cam.transform;\r\n        }\r\n        else\r\n        {\r\n            var headGo = new GameObject(\"Head (auto)\");\r\n            headGo.transform.SetParent(transform, false);\r\n            headGo.transform.localPosition = new Vector3(0f, 1.6f, 0f);\r\n            headGo.AddComponent<Camera>().nearClipPlane = 0.05f;\r\n            headGo.AddComponent<AudioListener>();\r\n            _head = headGo.transform;\r\n            Debug.LogWarning(\"[FirstPersonMove] FirstPersonController 下没有相机，已自动造一个 Head (auto)。\");\r\n        }\r\n        // 眼高：只在明显偏低时才纠正（别人手摆的高度不覆盖）。\r\n        // 低了会发生什么：整屏只有脚下一块地砖 + 路灯的一圈光晕，没有任何边缘，\r\n        // 人眼分不出\"在动\"和\"没动\"，这就是前几轮\"卡住\"的真身之一。\r\n        Vector3 lp = _head.localPosition;\r\n        if (lp.y < 0.9f)\r\n        {\r\n            _head.localPosition = new Vector3(lp.x, EyeHeight, lp.z);\r\n            Debug.LogFormat(\"[FirstPersonMove] 相机本地高度只有 {0:F2} m（玩家原点在脚底）—— 已抬到眼高 {1:F2} m。\",\r\n                lp.y, EyeHeight);\r\n        }\r\n\r\n        _pitch = _head.localEulerAngles.x;\r\n        if (_pitch > 180f) _pitch -= 360f;\r\n        if (Mathf.Abs(_pitch) > 60f) _pitch = 0f;    // 场景里那台相机横歪 88°，别把歪的姿势带进来\r\n\r\n        LockCursor();\r\n        Debug.Log(\"[FirstPersonMove] 已接管「\" + name + \"」：WASD/方向键移动，Shift 跑，Space 跳，鼠标转视角，Esc 释放鼠标。\");\r\n    }\r\n\r\n    void Update()\r\n    {\r\n        var kb = Keyboard.current;\r\n        if (kb == null) return; // 失焦或没有键盘的帧直接跳过\r\n\r\n        // —— 鼠标锁定管理 ——\r\n        if (kb.escapeKey.wasPressedThisFrame) UnlockCursor();\r\n        var mouse = Mouse.current;\r\n        if (!_cursorLocked && mouse != null && mouse.leftButton.wasPressedThisFrame) LockCursor();\r\n\r\n        // —— 视角 ——\r\n        if (enableMouseLook && _cursorLocked && mouse != null)\r\n        {\r\n            Vector2 d = mouse.delta.ReadValue();\r\n\r\n            // 锁光标后的头几帧 + 单帧超大跳变：一律当成噪声丢掉（详见 _ignoreMouseUntil 的注释）\r\n            if (Time.unscaledTime < _ignoreMouseUntil || d.sqrMagnitude > 120f * 120f) d = Vector2.zero;\r\n\r\n            float yaw = d.x * lookSensitivity;\r\n            _pitch = Mathf.Clamp(_pitch - d.y * lookSensitivity, -89f, 89f);\r\n            transform.Rotate(0f, yaw, 0f);              // 偏航转身体（你的胶囊）\r\n            _head.localEulerAngles = new Vector3(_pitch, 0f, 0f); // 俯仰转头\r\n        }\r\n\r\n        // —— 键盘转向兜底 ——\r\n        // 鼠标视角一旦失灵（光标没锁上、设备没连、系统把 delta 吃掉），人还能左右看，\r\n        // 不至于\"画面不变 ⇒ 以为卡死\"。Q/E 各 90°/s。\r\n        float yawKey = 0f;\r\n        if (kb.qKey.isPressed) yawKey -= 90f;\r\n        if (kb.eKey.isPressed) yawKey += 90f;\r\n        if (Mathf.Abs(yawKey) > 0.01f) transform.Rotate(0f, yawKey * Time.deltaTime, 0f);\r\n\r\n        // —— 平面移动（相对身体朝向）——\r\n        float h = 0f, v = 0f;\r\n        if (kb.wKey.isPressed || kb.upArrowKey.isPressed) v += 1f;\r\n        if (kb.sKey.isPressed || kb.downArrowKey.isPressed) v -= 1f;\r\n        if (kb.aKey.isPressed || kb.leftArrowKey.isPressed) h -= 1f;\r\n        if (kb.dKey.isPressed || kb.rightArrowKey.isPressed) h += 1f;\r\n\r\n        Vector3 move = (transform.right * h + transform.forward * v);\r\n        if (move.sqrMagnitude > 1f) move.Normalize();\r\n        float speed = walkSpeed * ((kb.leftShiftKey.isPressed || kb.rightShiftKey.isPressed) ? runMultiplier : 1f);\r\n\r\n        // —— 跳跃与重力 ——\r\n        if (_cc.isGrounded)\r\n        {\r\n            if (_vy < 0f) _vy = -2f; // 贴地小下压，保证 isGrounded 稳定\r\n            if (_cursorLocked && kb.spaceKey.wasPressedThisFrame) _vy = jumpVelocity;\r\n        }\r\n        _vy += gravity * Time.deltaTime;\r\n\r\n        Vector3 motion = move * speed * Time.deltaTime + Vector3.up * (_vy * Time.deltaTime);\r\n        _cc.Move(motion);\r\n    }\r\n\r\n    void LockCursor()\r\n    {\r\n        Cursor.lockState = CursorLockMode.Locked;\r\n        Cursor.visible = false;\r\n        _cursorLocked = true;\r\n        _ignoreMouseUntil = Time.unscaledTime + 0.35f;   // 丢掉锁定瞬间那次跳变\r\n    }\r\n\r\n    /// 由关卡脚本调用：把视角摆正（俯仰归零、身体朝向不动）。\r\n    /// PlacePlayer 以前直接写 `head.localRotation`，但本脚本每帧又会用 `_pitch` 覆盖回去 ——\r\n    /// `_pitch` 里的旧值（可能已经是 −89°）会立刻把刚摆正的镜头再压到地上。\r\n    /// 所以要摆正就得连 `_pitch` 一起清，这才有了这个方法。\r\n    internal void ResetLook()\r\n    {\r\n        _pitch = 0f;\r\n        if (_head != null)\r\n        {\r\n            _head.localRotation = Quaternion.identity;\r\n            Vector3 lp = _head.localPosition;\r\n            if (lp.y < 0.9f) _head.localPosition = new Vector3(lp.x, EyeHeight, lp.z);\r\n        }\r\n        _ignoreMouseUntil = Time.unscaledTime + 0.35f;\r\n    }\r\n\r\n    /// 由标题页 / 结算页调用：立刻把鼠标交还玩家（等价于玩家点了一下画面）。\r\n    /// 光标状态与 _cursorLocked 必须一起改 —— 只锁光标、不改 _cursorLocked，会得到\r\n    /// 「光标被锁住、但转鼠标视角没反应」这种很难自己看出来的状态。\r\n    internal void LockCursorNow() => LockCursor();\r\n\r\n    void UnlockCursor()\r\n    {\r\n        Cursor.lockState = CursorLockMode.None;\r\n        Cursor.visible = true;\r\n        _cursorLocked = false;\r\n    }\r\n\r\n    void OnDisable()\r\n    {\r\n        Cursor.lockState = CursorLockMode.None;\r\n        Cursor.visible = true;\r\n    }\r\n\r\n    // ———— 运行时自装配 ————\r\n\r\n    [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]\r\n    static void Bootstrap()\r\n    {\r\n        SceneManager.sceneLoaded += (scene, mode) => Install(scene);\r\n        Scene active = SceneManager.GetActiveScene();\r\n        if (active.isLoaded) Install(active);\r\n    }\r\n\r\n    static void Install(Scene scene)\r\n    {\r\n        if (scene.name != \"SampleScene\") return;\r\n\r\n        // 居民区关卡已经换成 NbPlayer（自己 new 一个玩家、自带身体和相机）。\r\n        // 这里必须彻底让路：否则它会再给场景里那个 FirstPersonController 补一个\r\n        // CharacterController、锁一次光标、并把 FlyCamera 一起清掉 —— 全是白做的，\r\n        // 而且锁光标会和 NbPlayer 抢。\r\n        if (NbMode.Enabled)\r\n        {\r\n            Debug.Log(\"[FirstPersonMove] 本关已由 NbPlayer 接管，旧的第一人称不再装配。\");\r\n            return;\r\n        }\r\n\r\n        GameObject player = null;\r\n        foreach (GameObject root in scene.GetRootGameObjects())\r\n        {\r\n            if (root.name == \"FirstPersonController\") { player = root; break; }\r\n            Transform t = root.transform.Find(\"FirstPersonController\");\r\n            if (t != null) { player = t.gameObject; break; }\r\n        }\r\n        foreach (GameObject root in scene.GetRootGameObjects())\r\n        {\r\n            if (player != null) break;\r\n            Transform[] all = root.GetComponentsInChildren<Transform>(true);\r\n            foreach (Transform t in all)\r\n                if (t.name == \"FirstPersonController\") { player = t.gameObject; break; }\r\n        }\r\n        if (player == null)\r\n        {\r\n            Debug.LogWarning(\"[FirstPersonMove] 场景里没有叫「FirstPersonController」的物体，本次不装配（脚本也可以手动拖上去用）。\");\r\n            return;\r\n        }\r\n        if (player.GetComponent<FirstPersonMove>() != null) return;\r\n        player.AddComponent<FirstPersonMove>();\r\n\r\n        // FlyCamera 的 Start 会禁用场景里其它相机（包括你的 Main Camera），有它在玩家就瞎了 → 移除\r\n        foreach (FlyCameraController fly in Object.FindObjectsByType<FlyCameraController>(FindObjectsInactive.Include, FindObjectsSortMode.None))\r\n        {\r\n            Debug.Log(\"[FirstPersonMove] 已移除 FlyCamera 实例（它的 Start 会禁用其它相机，和玩家相机冲突）。宿主：\" + fly.name);\r\n            Object.Destroy(fly.gameObject);\r\n        }\r\n    }\r\n}\r\n"},"Nb":{"path":"Assets/Scripts/Neighbourhood.cs","role":"Residential-block level data: world bounds, block grid, walkways, spawn, cheese spots, cat routes.","source":"// @role Residential-block level data: world bounds, block grid, walkways, spawn, cheese spots, cat routes.\r\n\r\n// Neighbourhood.cs — 「居民区」关卡的空间定义 + 搭场景用的几何小工具\r\n//\r\n// 布局不是拍脑袋定的：**先把 12 个楼栋的 BoxCollider 世界包络量出来，再从包络反推过道。**\r\n// 这一版的数据来自换过模型之后的实测值 —— 真实模型是 16.9~17.4 宽、7.7~14.7 深，\r\n// 而且整排在 z 上比白盒偏了 9.5 m。旧版按白盒的 16×14 网格算，于是过道铺装、奶酪、\r\n// 猫全压在楼体里（猫甚至出生在楼里），这关一度根本走不通。\r\n//\r\n//   楼群本体    x 50.22…114.75   z −75.08…−0.88\r\n//   纵向通道 A  x 68.80…73.90（中轴 71.35）\r\n//   纵向通道 B  x 91.00…96.40（中轴 93.70）\r\n//   横向通道 1  z −22.90…−15.30（中轴 −19.10）\r\n//   横向通道 2  z −42.40…−36.10（中轴 −39.25）\r\n//   横向通道 3  z −60.40…−55.70（中轴 −58.05）\r\n//   围墙再往外推 3.6 m ⇒ 一圈环形通道（中轴 x 48.41 / 116.58，z 0.91 / −76.89）\r\n//\r\n// 奶酪、猫的路线、小地图上的方块全部读这组常量，所以三处永远对得上。\r\n// 所有尺寸单位都是米，地面 y = 0。\r\n\r\nusing System.Collections.Generic;\r\nusing UnityEngine;\r\n\r\ninternal static class Nb\r\n{\r\n    // ───────────────────────── 范围 ─────────────────────────\r\n\r\n    internal const float XMin = 46.6f;\r\n    internal const float XMax = 118.4f;\r\n    internal const float ZMin = -78.7f;\r\n    internal const float ZMax = 2.7f;\r\n\r\n    internal const float Width = XMax - XMin;     // 71.8\r\n    internal const float Depth = ZMax - ZMin;     // 81.4\r\n\r\n    // 楼群本体的实测包络：环形通道就夹在它和围墙之间\r\n    internal const float BlockX0 = 50.22f;\r\n    internal const float BlockX1 = 114.75f;\r\n    internal const float BlockZ0 = -75.08f;\r\n    internal const float BlockZ1 = -0.88f;\r\n\r\n    // ───────────────────────── 楼栋网格 ─────────────────────────\r\n    // 3 列 × 4 排。每栋尺寸不一样（换过模型之后就不再是统一的 16×14），\r\n    // 所以宽度/进深按列、按排各存一个数，小地图用它画方块才不会画歪。\r\n\r\n    internal const int Cols = 3;\r\n    internal const int Rows = 4;\r\n    internal const int Slots = Cols * Rows;                        // 12\r\n\r\n    internal static readonly float[] ColX = { 59.47f, 82.38f, 105.62f };\r\n    internal static readonly float[] RowZ = { -8.68f, -29.50f, -49.00f, -68.50f };\r\n    internal static readonly float[] ColW = { 18.50f, 16.92f, 18.26f };\r\n    internal static readonly float[] RowD = { 14.38f, 13.16f, 13.16f, 14.67f };\r\n\r\n    internal static Vector3 SlotCenter(int i)\r\n    {\r\n        return new Vector3(ColX[i % Cols], 0f, RowZ[i / Cols]);\r\n    }\r\n\r\n    // ───────────────────────── 过道 ─────────────────────────\r\n\r\n    internal const float VAx0 = 68.80f, VAx1 = 73.90f, VAcx = 71.35f;   // 纵向 A\r\n    internal const float VBx0 = 91.00f, VBx1 = 96.40f, VBcx = 93.70f;   // 纵向 B\r\n\r\n    internal const float H1z0 = -22.90f, H1z1 = -15.30f, H1cz = -19.10f;\r\n    internal const float H2z0 = -42.40f, H2z1 = -36.10f, H2cz = -39.25f;\r\n    internal const float H3z0 = -60.40f, H3z1 = -55.70f, H3cz = -58.05f;\r\n\r\n    // 环形通道的中轴\r\n    internal const float RingWx = 48.41f, RingEx = 116.58f;\r\n    internal const float RingNz = 0.91f, RingSz = -76.89f;\r\n\r\n    // ───────────────────────── 门与出生点 ─────────────────────────\r\n\r\n    internal const float GateX0 = 68.50f;   // 前墙的门洞，正好对上纵向通道 A\r\n    internal const float GateX1 = 74.20f;\r\n\r\n    // 整片居民区的几何中心（围墙包围盒的中点）—— 出生点就钉在这里\r\n    internal const float CenterX = (XMin + XMax) * 0.5f;   // 82.50\r\n    internal const float CenterZ = (ZMin + ZMax) * 0.5f;   // -38.00\r\n\r\n    // 起点在居民区**正中间**，落在横向通道 2 的路面上（z −42.40…−36.10 之间）。\r\n    // 左右两侧各约 11 m 就是纵向通道 A / B 的十字口，所以一睁眼就站在整个街区的十字轴上；\r\n    // 朝东（+x）是因为东边 13 m 有盏亮着的路灯 + 两个花坛，画面里有参照物，\r\n    // 比对着空过道更容易看出\"我在动\"。\r\n    // y 取 0.10：H2 铺装顶面是 0.048，留 5 cm 让人自己落下去，别一开始就嵌在砖里。\r\n    internal static readonly Vector3 PlayerStart = new Vector3(CenterX, 0.10f, CenterZ);\r\n    internal static readonly Vector3 PlayerForward = new Vector3(1f, 0f, 0f);\r\n\r\n    // ───────────────────────── 10 个奶酪点（全在过道上）─────────────────────────\r\n    //\r\n    // **数组顺序就是出场顺序**：第 n 关取前 (n+1) 个点，所以这里必须按「离出生点由近到远」排。\r\n    // 顺序反过来会让第 1 关的两块奶酪落在街区最南端（40 m 外、还隔着两只猫），\r\n    // 而第 9 关反而在家门口 —— 难度曲线会当场倒过来。\r\n    // 距离基准是出生点 (82.50, -38.00)，平面直线距离写在每行末尾。\r\n\r\n    internal static readonly Vector3[] CheeseSpots =\r\n    {\r\n        new Vector3(VBcx, 0f, -33.0f),   // 东巷，出生点正东 11 m            12.3 m\r\n        new Vector3(VAcx, 0f, -45.5f),   // 西巷，斜后方                    13.4 m\r\n        new Vector3(VAcx, 0f, -25.0f),   // 西巷，斜前方                    17.1 m\r\n        new Vector3(82.40f, 0f, H3cz),   // 横向通道 3 正中（往南一条街）     20.1 m\r\n        new Vector3(VBcx, 0f, -63.0f),   // 东巷最南端                      28.3 m\r\n        new Vector3(VAcx, 0f, -66.0f),   // 西巷最南端                      30.1 m\r\n        new Vector3(VBcx, 0f,  -8.0f),   // 东巷最北端（大门那头）           32.1 m\r\n        new Vector3(55.50f, 0f, H1cz),   // 横向通道 1 西端                 32.9 m\r\n        new Vector3(110.0f, 0f, H1cz),   // 横向通道 1 东端                 33.4 m\r\n        new Vector3(VAcx, 0f,  -5.0f),   // 西巷最北端，贴着大门            34.5 m\r\n    };\r\n\r\n    // ───────────────────────── 10 条猫的巡逻路线 ─────────────────────────\r\n    //\r\n    // **路线是\"按段切开\"的，不是\"一条通道一整只猫\"。** 两条纵向通道各切成 3 段\r\n    // （北 / 中 / 南），三条横向通道各 1 条，外加环形通道 1 条 ⇒ 正好 10 段。\r\n    // 这样第 n 关放 n 只猫时，猫是从\"最不碍事\"的段往\"最碍事\"的段铺开的：\r\n    //   · 第 1 关只有西巷中段一只 —— 你先在安全区里看清它是怎么来回走的\r\n    //   · 第 5 关前五段铺满，五条通道各一只 —— 第一次出现\"绕不开\"\r\n    //   · 第 10 关连 H2（你出生那条）都有猫，全场没有一条通道是空的\r\n    // 旧版是 5 条整通道 + 环形，猫一多就只能两只叠在同一条路线上一起走 —— 看着像复制粘贴。\r\n    //\r\n    // 每段都是两点直线来回（StepRoute 到端点掉头），不需要额外寻路。\r\n\r\n    internal static readonly Vector3[][] CatRoutes =\r\n    {\r\n        new[] { new Vector3(VAcx, 0f, -26.0f), new Vector3(VAcx, 0f, -50.0f) },   // 0 西巷·中段\r\n        new[] { new Vector3(VBcx, 0f, -26.0f), new Vector3(VBcx, 0f, -50.0f) },   // 1 东巷·中段\r\n        new[] { new Vector3(VAcx, 0f,  -3.0f), new Vector3(VAcx, 0f, -26.0f) },   // 2 西巷·北段（靠大门）\r\n        new[] { new Vector3(VBcx, 0f,  -3.0f), new Vector3(VBcx, 0f, -26.0f) },   // 3 东巷·北段\r\n        new[] { new Vector3(52.00f, 0f, H1cz), new Vector3(113.0f, 0f, H1cz) },   // 4 横 1\r\n        new[] { new Vector3(52.00f, 0f, H3cz), new Vector3(113.0f, 0f, H3cz) },   // 5 横 3\r\n        new[] { new Vector3(VAcx, 0f, -50.0f), new Vector3(VAcx, 0f, -74.0f) },   // 6 西巷·南段\r\n        new[] { new Vector3(VBcx, 0f, -50.0f), new Vector3(VBcx, 0f, -74.0f) },   // 7 东巷·南段\r\n        new[]                                                                    // 8 环形通道\r\n        {\r\n            new Vector3(RingWx, 0f, RingNz), new Vector3(RingWx, 0f, RingSz),\r\n            new Vector3(RingEx, 0f, RingSz), new Vector3(RingEx, 0f, RingNz),\r\n        },\r\n        new[] { new Vector3(52.00f, 0f, H2cz), new Vector3(113.0f, 0f, H2cz) },   // 9 横 2（穿过出生点）\r\n    };\r\n\r\n    // 场地容量 = 上面两张表的长度：奶酪点 10 个、路线 10 条。\r\n    // 第 9、10 关会把奶酪点全用上，第 10 关会把路线全用上 —— 再加关卡就得先加这里的点。\r\n\r\n    // ───────────────────────── 判断 ─────────────────────────\r\n\r\n    internal static float FlatDist(Vector3 a, Vector3 b)\r\n    {\r\n        float dx = a.x - b.x, dz = a.z - b.z;\r\n        return Mathf.Sqrt(dx * dx + dz * dz);\r\n    }\r\n\r\n    internal static Vector3 Grounded(Vector3 p)\r\n    {\r\n        float y;\r\n        if (CatCheeseSetup.TryGroundY(p, out y)) return new Vector3(p.x, y, p.z);\r\n        return new Vector3(p.x, 0f, p.z);\r\n    }\r\n\r\n    // ───────────────────────── 几何工具 ─────────────────────────\r\n\r\n    // 装饰物统一放 Ignore Raycast：只对射线隐形（地面探测/猫的视线不能被打扰），\r\n    // 物理碰撞照常 —— 不过装饰物连碰撞体都直接删掉，免得把过道堵死。\r\n    static int _decorLayer = -2;\r\n    internal static int DecorLayer\r\n    {\r\n        get\r\n        {\r\n            if (_decorLayer == -2) _decorLayer = LayerMask.NameToLayer(\"Ignore Raycast\");\r\n            return _decorLayer;\r\n        }\r\n    }\r\n\r\n    static readonly Dictionary<Color, Material> Mats = new Dictionary<Color, Material>();\r\n\r\n    internal static Material Mat(Color c)\r\n    {\r\n        Material m;\r\n        if (Mats.TryGetValue(c, out m) && m != null) return m;\r\n\r\n        Shader sh = Shader.Find(\"Universal Render Pipeline/Lit\");\r\n        if (sh == null) sh = Shader.Find(\"Standard\");\r\n        m = new Material(sh);\r\n        m.name = \"Nb_\" + ColorUtility.ToHtmlStringRGB(c);\r\n        if (m.HasProperty(\"_BaseColor\")) m.SetColor(\"_BaseColor\", c);\r\n        if (m.HasProperty(\"_Color\")) m.SetColor(\"_Color\", c);\r\n        if (m.HasProperty(\"_Smoothness\")) m.SetFloat(\"_Smoothness\", 0.12f);\r\n        if (m.HasProperty(\"_Metallic\")) m.SetFloat(\"_Metallic\", 0f);\r\n        // FBX/URP 的材质球默认带贴图槽，这里没有贴图，把 _BaseMap 留空即可\r\n        Mats[c] = m;\r\n        return m;\r\n    }\r\n\r\n    /// 自发光材质（路灯玻璃用）：URP/Lit 得同时写 _EmissionColor 和打开 _EMISSION 关键字，\r\n    /// 只设颜色不启关键字的话编辑器里看不出问题、屏幕上一片死黑。\r\n    /// 不走 Mat 的缓存 —— 那个按颜色共享，改一份会把所有同色的东西一起点亮。\r\n    internal static Material MatEmissive(Color c, float strength)\r\n    {\r\n        Shader sh = Shader.Find(\"Universal Render Pipeline/Lit\");\r\n        if (sh == null) sh = Shader.Find(\"Standard\");\r\n        Material m = new Material(sh);\r\n        m.name = \"Nb_Emissive_\" + ColorUtility.ToHtmlStringRGB(c);\r\n        if (m.HasProperty(\"_BaseColor\")) m.SetColor(\"_BaseColor\", c);\r\n        if (m.HasProperty(\"_Color\")) m.SetColor(\"_Color\", c);\r\n        if (m.HasProperty(\"_Smoothness\")) m.SetFloat(\"_Smoothness\", 0.25f);\r\n        if (m.HasProperty(\"_EmissionColor\"))\r\n        {\r\n            m.EnableKeyword(\"_EMISSION\");\r\n            m.SetColor(\"_EmissionColor\", c * strength);\r\n            m.globalIlluminationFlags = MaterialGlobalIlluminationFlags.RealtimeEmissive;\r\n        }\r\n        return m;\r\n    }\r\n\r\n    /// 方块。solid = true 时保留碰撞体并留在 Default 层（用来挡人、挡视线）。\r\n    internal static GameObject Box(Transform parent, string name, Vector3 local, Vector3 size, Color color, bool solid = true)\r\n    {\r\n        GameObject go = GameObject.CreatePrimitive(PrimitiveType.Cube);\r\n        go.name = name;\r\n        go.transform.SetParent(parent, false);\r\n        go.transform.localPosition = local;\r\n        go.transform.localScale = size;\r\n        Style(go, color, solid);\r\n        return go;\r\n    }\r\n\r\n    /// 圆柱（Unity 原始圆柱高 2、直径 1，所以 y 要除 2）。\r\n    internal static GameObject Cyl(Transform parent, string name, Vector3 local, float diameter, float height, Color color, bool solid = true)\r\n    {\r\n        GameObject go = GameObject.CreatePrimitive(PrimitiveType.Cylinder);\r\n        go.name = name;\r\n        go.transform.SetParent(parent, false);\r\n        go.transform.localPosition = local;\r\n        go.transform.localScale = new Vector3(diameter, height * 0.5f, diameter);\r\n        Style(go, color, solid);\r\n        return go;\r\n    }\r\n\r\n    /// 球（Unity 原始球直径 1）。\r\n    internal static GameObject Ball(Transform parent, string name, Vector3 local, float diameter, Color color, bool solid = true)\r\n    {\r\n        GameObject go = GameObject.CreatePrimitive(PrimitiveType.Sphere);\r\n        go.name = name;\r\n        go.transform.SetParent(parent, false);\r\n        go.transform.localPosition = local;\r\n        go.transform.localScale = Vector3.one * diameter;\r\n        Style(go, color, solid);\r\n        return go;\r\n    }\r\n\r\n    static void Style(GameObject go, Color color, bool solid)\r\n    {\r\n        Renderer r = go.GetComponent<Renderer>();\r\n        if (r != null) r.sharedMaterial = Mat(color);\r\n\r\n        if (solid)\r\n        {\r\n            go.layer = 0;\r\n            return;\r\n        }\r\n\r\n        Collider c = go.GetComponent<Collider>();\r\n        if (c != null) Kill(c);\r\n        int layer = DecorLayer;\r\n        if (layer >= 0) go.layer = layer;\r\n    }\r\n\r\n    /// 删物体/组件：编辑模式下 `Object.Destroy` 是**不生效**的（Unity 会往 Console 刷\r\n    /// 「Destroy may not be called from edit mode!」而物体还在），所以烘焙场景时走 DestroyImmediate。\r\n    /// 装饰物\"删掉碰撞体\"全靠这一句，走错分支就会给 160 个树/灯/花坛全留下碰撞体 —— 过道会被堵死。\r\n    internal static void Kill(Object o)\r\n    {\r\n        if (o == null) return;\r\n        if (Application.isPlaying) Object.Destroy(o);\r\n        else Object.DestroyImmediate(o);\r\n    }\r\n}\r\n"},"NbBriefing":{"path":"Assets/Scripts/NbBriefing.cs","role":"Pre-fridge rules screen: freezes the player and the door until dismissed by any key/click.","source":"// @role Pre-fridge rules screen: freezes the player and the door until dismissed by any key/click.\r\n// @calls NbGame NbPlayer NbUi\r\n\r\n// NbBriefing.cs — 进场前的玩法说明（目前只有冰箱用）\r\n//\r\n// 为什么这一关必须有它：\r\n//   街区/后院的规则可以边走边学（看见猫就躲、看见手电就绕）。冰箱的核心规则**看不见**——\r\n//   \"门会在 3 秒后打开\"这件事没有任何先验，玩家第一次一定会在空地上被照一次，\r\n//   然后以为是随机掉血。那不是难度，那是没有教会玩家就开始考试。\r\n//\r\n// 交互刻意做得最笨：**任意键 / 点击任意处**关闭。没有按钮、没有\"下一步\"。\r\n//   因为这一页的全部内容是一段规则，玩家只会读一遍，多余的 UI 只会推迟他进入游戏。\r\n//\r\n// 它会冻结玩家（AcceptInput = false），并且**同时冻结门**（NbGame.DoorUpdate 里\r\n// 第一句就 return）—— 否则玩家读规则读到一半，倒计时走完，读完先挨一下。\r\n//\r\n// 字号/换行都是按 1920×1080 的参考分辨率调的，正文每行手动断句 ——\r\n// TMP 的自动换行在没有中文字体的工程里会把长句切成很难看的形状。\r\n\r\nusing System.Collections;\r\nusing TMPro;\r\nusing UnityEngine;\r\nusing UnityEngine.InputSystem;\r\nusing UnityEngine.UI;\r\n\r\ninternal class NbBriefing : MonoBehaviour\r\n{\r\n    internal static NbBriefing I;\r\n    internal static bool Showing { get; private set; }\r\n\r\n    const string Kicker = \"BEFORE  YOU  GO  IN\";\r\n    const string Title  = \"THE  FRIDGE\";\r\n\r\n    const string Body =\r\n        \"You are a mouse in a fridge.  Six shelves go up,\\n\" +\r\n        \"and the cheese is on them.  Everything else in here is just food.\\n\" +\r\n        \"\\n\" +\r\n        \"There is no cat in here.  But someone keeps opening the door.\\n\" +\r\n        \"\\n\" +\r\n        \"Three seconds before it opens, two things happen:\\n\" +\r\n        \"the gap under the door starts to glow, and the bar at the bottom\\n\" +\r\n        \"of the screen starts counting down.  There is no sound.\\n\" +\r\n        \"That is your warning - you get three seconds, not more.\\n\" +\r\n        \"\\n\" +\r\n        \"When the door opens, light floods the whole fridge.\\n\" +\r\n        \"If you are standing in the open, you lose 10 health.\\n\" +\r\n        \"Hide behind something solid: a milk crate, a melon,\\n\" +\r\n        \"a bread box, a block of butter.  Four on every shelf.\\n\" +\r\n        \"\\n\" +\r\n        \"Standing in a corner does not hide you.\\n\" +\r\n        \"Neither does standing still.  Something has to be in the way.\\n\" +\r\n        \"\\n\" +\r\n        \"To go up, use the staircase in the middle of the fridge.\\n\" +\r\n        \"Four steps per shelf - just walk up, no jumping needed.\\n\" +\r\n        \"Each shelf opens off the side of the stair.\\n\" +\r\n        \"\\n\" +\r\n        \"Bring back every piece of cheese to clear the level.\";\r\n\r\n    const string Foot = \"PRESS  ANY  KEY   /   CLICK  TO  START\";\r\n\r\n    CanvasGroup _group;\r\n    float _born;\r\n    bool _closing;\r\n\r\n    // ───────────────────────── 创建 ─────────────────────────\r\n\r\n    internal static NbBriefing Show()\r\n    {\r\n        if (I != null) return I;\r\n\r\n        GameObject go = new GameObject(\"Briefing (auto)\");\r\n        NbBriefing b = go.AddComponent<NbBriefing>();\r\n        b.Build();\r\n        return b;\r\n    }\r\n\r\n    void Awake()\r\n    {\r\n        I = this;\r\n    }\r\n\r\n    void OnDestroy()\r\n    {\r\n        if (I == this) I = null;\r\n        Showing = false;\r\n    }\r\n\r\n    void Build()\r\n    {\r\n        Showing = true;\r\n        _born = Time.unscaledTime;\r\n\r\n        // 冻结玩家。这一步是这一页存在的意义之一 —— 说明是\"开始之前\"给的，\r\n        // 不是叠在游戏上的浮层。\r\n        if (NbPlayer.I != null) NbPlayer.I.AcceptInput = false;\r\n\r\n        GameObject canvasGo = new GameObject(\"Briefing Canvas (auto)\",\r\n            typeof(Canvas), typeof(CanvasScaler), typeof(CanvasGroup));\r\n        canvasGo.transform.SetParent(transform, false);\r\n\r\n        Canvas canvas = canvasGo.GetComponent<Canvas>();\r\n        canvas.renderMode = RenderMode.ScreenSpaceOverlay;\r\n        canvas.sortingOrder = 55;                 // 压过 HUD(40)/小地图(41)，低于场景选择页(60)\r\n\r\n        CanvasScaler scaler = canvasGo.GetComponent<CanvasScaler>();\r\n        scaler.uiScaleMode = CanvasScaler.ScaleMode.ScaleWithScreenSize;\r\n        scaler.referenceResolution = new Vector2(1920f, 1080f);\r\n        scaler.matchWidthOrHeight = 0.5f;\r\n\r\n        _group = canvasGo.GetComponent<CanvasGroup>();\r\n\r\n        Transform c = canvasGo.transform;\r\n\r\n        RectTransform shade = NbUi.Rect(\"Shade\", c);\r\n        shade.anchorMin = Vector2.zero;\r\n        shade.anchorMax = Vector2.one;\r\n        shade.offsetMin = Vector2.zero;\r\n        shade.offsetMax = Vector2.zero;\r\n        Image sh = shade.gameObject.AddComponent<Image>();\r\n        sh.color = new Color(0.03f, 0.04f, 0.06f, 0.94f);\r\n        sh.raycastTarget = false;\r\n\r\n        RectTransform card = NbUi.Rect(\"Card\", c);\r\n        card.anchorMin = card.anchorMax = card.pivot = new Vector2(0.5f, 0.5f);\r\n        card.anchoredPosition = Vector2.zero;\r\n        card.sizeDelta = new Vector2(1040f, 880f);\r\n\r\n        Image bg = card.gameObject.AddComponent<Image>();\r\n        bg.sprite = NbUi.Round;\r\n        bg.type = Image.Type.Sliced;\r\n        bg.color = new Color(0.06f, 0.07f, 0.09f, 0.96f);\r\n        bg.raycastTarget = false;\r\n\r\n        // 顶部一条冷光（冰箱的灯色），让这一页和那一关是同一个人设计的\r\n        RectTransform bar = NbUi.Rect(\"Accent\", card);\r\n        bar.anchorMin = bar.anchorMax = bar.pivot = new Vector2(0.5f, 1f);\r\n        bar.anchoredPosition = new Vector2(0f, -26f);\r\n        bar.sizeDelta = new Vector2(140f, 5f);\r\n        Image bi = bar.gameObject.AddComponent<Image>();\r\n        bi.sprite = NbUi.Round;\r\n        bi.type = Image.Type.Sliced;\r\n        bi.color = new Color(0.62f, 0.82f, 1f);\r\n        bi.raycastTarget = false;\r\n\r\n        TextMeshProUGUI kick = NbUi.Text(\"Kicker\", card, Kicker, 20f,\r\n            new Color(0.62f, 0.82f, 1f, 0.85f), TextAlignmentOptions.Center);\r\n        Place(kick.rectTransform, new Vector2(0f, 366f), new Vector2(900f, 28f));\r\n\r\n        TextMeshProUGUI title = NbUi.Text(\"Title\", card, Title, 52f,\r\n            new Color(1f, 0.98f, 0.94f), TextAlignmentOptions.Center);\r\n        Place(title.rectTransform, new Vector2(0f, 314f), new Vector2(900f, 62f));\r\n\r\n        TextMeshProUGUI body = NbUi.Text(\"Body\", card, Body, 22f,\r\n            new Color(1f, 1f, 1f, 0.82f), TextAlignmentOptions.TopLeft);\r\n        body.lineSpacing = 8f;\r\n        Place(body.rectTransform, new Vector2(0f, 262f), new Vector2(940f, 520f));\r\n        body.rectTransform.pivot = new Vector2(0.5f, 1f);\r\n        body.rectTransform.anchoredPosition = new Vector2(0f, 262f);\r\n\r\n        TextMeshProUGUI foot = NbUi.Text(\"Foot\", card, Foot, 20f,\r\n            new Color(1f, 1f, 1f, 0.45f), TextAlignmentOptions.Center);\r\n        Place(foot.rectTransform, new Vector2(0f, -396f), new Vector2(900f, 30f));\r\n\r\n        Debug.Log(\"[Nb] 玩法说明已显示（冰箱）—— 任意键或点击开始，门在关闭说明之前不会走。\");\r\n    }\r\n\r\n    static void Place(RectTransform rt, Vector2 pos, Vector2 size)\r\n    {\r\n        rt.anchorMin = rt.anchorMax = rt.pivot = new Vector2(0.5f, 0.5f);\r\n        rt.anchoredPosition = pos;\r\n        rt.sizeDelta = size;\r\n    }\r\n\r\n    // ───────────────────────── 关闭 ─────────────────────────\r\n\r\n    void Update()\r\n    {\r\n        if (_closing) return;\r\n        if (Time.unscaledTime - _born < 0.6f) return;      // 躲开进场那一帧的误触\r\n\r\n        Keyboard kb = Keyboard.current;\r\n        Mouse mouse = Mouse.current;\r\n\r\n        bool go = (kb != null && kb.anyKey.wasPressedThisFrame)\r\n               || (mouse != null && mouse.leftButton.wasPressedThisFrame);\r\n        if (go) StartCoroutine(FadeOut());\r\n    }\r\n\r\n    IEnumerator FadeOut()\r\n    {\r\n        _closing = true;\r\n\r\n        float d = 0.25f, t = 0f;\r\n        while (t < d)\r\n        {\r\n            t += Time.unscaledDeltaTime;\r\n            if (_group != null) _group.alpha = Mathf.Clamp01(1f - t / d);\r\n            yield return null;\r\n        }\r\n\r\n        // 先放开 Showing 再销毁：EnsurePlayable 每帧都在看这个标志，\r\n        // 反过来的话会有几帧\"说明没了但人还不能动\"。\r\n        Showing = false;\r\n        if (NbPlayer.I != null)\r\n        {\r\n            NbPlayer.I.AcceptInput = true;\r\n            NbPlayer.I.LockCursor();\r\n        }\r\n        Debug.Log(\"[Nb] 玩法说明关闭，门开始倒计时。\");\r\n\r\n        Destroy(gameObject);\r\n    }\r\n}\r\n"},"NbBuilder":{"path":"Assets/Scripts/NeighbourhoodBuilder.cs","role":"Builds the residential-block environment: grass, walkways, walls, gate, lamps, trees, bins, planters.","source":"// @role Builds the residential-block environment: grass, walkways, walls, gate, lamps, trees, bins, planters.\r\n// @calls Nb\r\n\r\n// NeighbourhoodBuilder.cs — 把 12 栋楼之间的空地搭成一个封闭的居民区\r\n//\r\n// 只负责\"环境\"：草地、过道铺装、围墙+大门、路灯、树、垃圾桶、花坛。\r\n// 楼栋本身由编辑器脚本 Assets/Editor/StreetFromModels.cs 换成真实模型（那一半走场景资源，\r\n// 运行时没法实例化不在 Resources 里的 FBX）。\r\n//\r\n// 全部是原始几何拼的，不依赖任何美术资源；颜色统一在文件顶部，改一处就换整个街区的调子。\r\n//\r\n// **两处入口，同一份几何**：\r\n//   ① 运行时的 `Build()`：场景里没有烘好的版本时，开机自己搭一份（老做法，兜底）；\r\n//   ② 编辑器的 `Tools/Street/Bake Neighbourhood Props`：把同一份几何**写进场景文件**，\r\n//      这样不按 Play、直接打开 SampleScene 就能看见树和路灯，Play 的第一帧也在。\r\n//      `Build()` 开头会先找这份烘好的东西，找到就沿用，不会再生成第二套（那会 z-fighting）。\r\n\r\nusing UnityEngine;\r\n\r\n// 公开（public）是因为 Assets/Editor 下的烘焙脚本在另一个程序集里，要调 Build()；\r\n// 运行时其它脚本仍按 internal 的用法调，不受影响。\r\npublic static class NbBuilder\r\n{\r\n    static readonly Color Grass   = new Color(0.34f, 0.48f, 0.30f);\r\n    static readonly Color Pave    = new Color(0.66f, 0.65f, 0.62f);\r\n    static readonly Color PaveDark= new Color(0.55f, 0.54f, 0.52f);\r\n    static readonly Color WallCol = new Color(0.56f, 0.45f, 0.40f);\r\n    static readonly Color WallCap = new Color(0.74f, 0.70f, 0.64f);\r\n    static readonly Color Iron    = new Color(0.20f, 0.21f, 0.23f);\r\n    static readonly Color LampWarm= new Color(1.00f, 0.86f, 0.58f);\r\n    static readonly Color Trunk   = new Color(0.33f, 0.24f, 0.17f);\r\n    static readonly Color LeafA   = new Color(0.28f, 0.46f, 0.24f);\r\n    static readonly Color LeafB   = new Color(0.36f, 0.55f, 0.29f);\r\n    static readonly Color BinCol  = new Color(0.24f, 0.36f, 0.30f);\r\n\r\n    // 编辑器烘焙和运行时装配共用同一个根名 —— 运行时就是靠这个名字判断\"场景里已经有一份了\"。\r\n    public const string RootName = \"Neighbourhood (auto)\";\r\n\r\n    public static Transform Build(Transform parent)\r\n    {\r\n        Transform baked = FindExisting();\r\n        if (baked != null)\r\n        {\r\n            Debug.LogFormat(\"[Nb] 场景里已经有搭好的居民区「{0}」（{1} 个渲染器），直接沿用，不再重复生成。\" +\r\n                            \"要按代码重搭，先删掉它或跑菜单 Tools/Street/Bake Neighbourhood Props。\",\r\n                RootName, baked.GetComponentsInChildren<Renderer>(true).Length);\r\n            return baked;\r\n        }\r\n\r\n        Transform root = new GameObject(RootName).transform;\r\n        root.SetParent(parent, false);\r\n\r\n        BuildGround(root);\r\n        BuildGroundDetail(root);\r\n        BuildWalls(root);\r\n        BuildLamps(root);\r\n        BuildTrees(root);\r\n        BuildProps(root);\r\n\r\n        Debug.LogFormat(\"[Nb] 居民区环境已搭好：{0:F1} x {1:F1} m，12 栋楼之间 {2} 段过道，围墙 + 1 个大门。\" +\r\n                        \"（只在场景里没有烘好的版本时才会走到这一步）\",\r\n            Nb.Width, Nb.Depth, 5);\r\n        return root;\r\n    }\r\n\r\n    /// 场景里是否已经有烘好的居民区（编辑期写进场景文件的那一份）。\r\n    /// 不进 Play 就能在 Scene / Game 视图里看见树、路灯、花坛，靠的就是它。\r\n    /// 用 `scene.GetRootGameObjects()` 而不是 `GameObject.Find`：后者**找不到未激活的物体**，\r\n    /// 万一有人把这一坨关掉了，运行时会在旁边再生成一套完全重叠的（z-fighting 闪成一片）。\r\n    internal static Transform FindExisting()\r\n    {\r\n        UnityEngine.SceneManagement.Scene scene = UnityEngine.SceneManagement.SceneManager.GetActiveScene();\r\n        if (!scene.IsValid()) return null;\r\n        GameObject[] roots = scene.GetRootGameObjects();\r\n        for (int i = 0; i < roots.Length; i++)\r\n            if (roots[i] != null && roots[i].name == RootName) return roots[i].transform;\r\n        return null;\r\n    }\r\n\r\n    // ───────────────────────── 地面与铺装 ─────────────────────────\r\n\r\n    static void BuildGround(Transform p)\r\n    {\r\n        // 整片草地（比围墙再大一圈，省得边界露白）\r\n        Nb.Box(p, \"Lawn\", new Vector3((Nb.XMin + Nb.XMax) * 0.5f, 0.005f, (Nb.ZMin + Nb.ZMax) * 0.5f),\r\n            new Vector3(Nb.Width + 4f, 0.01f, Nb.Depth + 4f), Grass, true);\r\n\r\n        // 铺装全部按「楼群实测包络」切缝，不再用固定 16×14 的网格：\r\n        // 楼栋外沿 BlockX0/X1、BlockZ0/Z1，过道就是这些外沿之间的空档。\r\n        float ix0 = Nb.XMin + 0.30f, ix1 = Nb.XMax - 0.30f;\r\n        float iz0 = Nb.ZMin + 0.30f, iz1 = Nb.ZMax - 0.30f;\r\n\r\n        // 环形通道：贴墙一圈，四段拼起来（内侧顶到楼群外沿）\r\n        PaveRect(p, \"Ring W\", ix0, Nb.BlockX0, iz0, iz1, 0.040f);\r\n        PaveRect(p, \"Ring E\", Nb.BlockX1, ix1, iz0, iz1, 0.040f);\r\n        PaveRect(p, \"Ring N\", Nb.BlockX0, Nb.BlockX1, Nb.BlockZ1, iz1, 0.040f);\r\n        PaveRect(p, \"Ring S\", Nb.BlockX0, Nb.BlockX1, iz0, Nb.BlockZ0, 0.040f);\r\n\r\n        // 两条纵向通道（贯穿整片楼群）\r\n        PaveRect(p, \"Alley V West\", Nb.VAx0, Nb.VAx1, Nb.BlockZ0, Nb.BlockZ1, 0.044f);\r\n        PaveRect(p, \"Alley V East\", Nb.VBx0, Nb.VBx1, Nb.BlockZ0, Nb.BlockZ1, 0.044f);\r\n\r\n        // 三条横向通道（排与排之间）\r\n        PaveRect(p, \"Alley H 1\", Nb.BlockX0, Nb.BlockX1, Nb.H1z0, Nb.H1z1, 0.048f);\r\n        PaveRect(p, \"Alley H 2\", Nb.BlockX0, Nb.BlockX1, Nb.H2z0, Nb.H2z1, 0.048f);\r\n        PaveRect(p, \"Alley H 3\", Nb.BlockX0, Nb.BlockX1, Nb.H3z0, Nb.H3z1, 0.048f);\r\n\r\n        // 门洞前的一小片水泥地，让大门外不是悬空的草皮\r\n        Nb.Box(p, \"Gate Apron\", new Vector3((Nb.GateX0 + Nb.GateX1) * 0.5f, 0.012f, Nb.ZMax + 1.6f),\r\n            new Vector3(Nb.GateX1 - Nb.GateX0 + 1.2f, 0.024f, 3.4f), PaveDark, true);\r\n    }\r\n\r\n    /// 一段水泥铺装：x0..x1 / z0..z1 的矩形。\r\n    /// `top` 是顶面高度 —— 几段铺装互相重叠（环道和纵向道交叉）时必须在 y 上错开几千分之一，\r\n    /// 否则两个共面的面会 z-fighting 闪成一片。\r\n    static void PaveRect(Transform p, string name, float x0, float x1, float z0, float z1, float top)\r\n    {\r\n        float h = 0.02f;\r\n        Nb.Box(p, name, new Vector3((x0 + x1) * 0.5f, top - h * 0.5f, (z0 + z1) * 0.5f),\r\n            new Vector3(x1 - x0, h, z1 - z0), Pave, true);\r\n\r\n        // 长边各压一条深色收边，读起来像\"路缘\"\r\n        if (z1 - z0 >= x1 - x0)\r\n        {\r\n            Nb.Box(p, name + \" Curb A\", new Vector3((x0 + x1) * 0.5f, top + 0.004f, z0 + 0.09f),\r\n                new Vector3(x1 - x0, 0.03f, 0.18f), PaveDark, false);\r\n            Nb.Box(p, name + \" Curb B\", new Vector3((x0 + x1) * 0.5f, top + 0.004f, z1 - 0.09f),\r\n                new Vector3(x1 - x0, 0.03f, 0.18f), PaveDark, false);\r\n        }\r\n        else\r\n        {\r\n            Nb.Box(p, name + \" Curb A\", new Vector3(x0 + 0.09f, top + 0.004f, (z0 + z1) * 0.5f),\r\n                new Vector3(0.18f, 0.03f, z1 - z0), PaveDark, false);\r\n            Nb.Box(p, name + \" Curb B\", new Vector3(x1 - 0.09f, top + 0.004f, (z0 + z1) * 0.5f),\r\n                new Vector3(0.18f, 0.03f, z1 - z0), PaveDark, false);\r\n        }\r\n    }\r\n\r\n    // ───────────────────────── 地面细节（低机位专用）─────────────────────────\r\n\r\n    // 老鼠视角（眼高 0.16 m）下，画面下半部几乎全是路面。\r\n    // 如果路面是一个纯色平面，走起来画面上没有任何东西在动 —— 这正是之前几轮\r\n    // \"看着像卡住\"的根源。所以沿过道撒一层**贴地的参照物**：石子、裂纹、落叶、井盖。\r\n    //\r\n    // 全部是无碰撞的装饰（显式传 solid=false ⇒ 删碰撞体 + Ignore Raycast 层）：\r\n    // 不挡人、不挡猫的视线、也不参与地面探测（TryGroundY 只打 DefaultRaycastLayers）。\r\n    // 位置用固定种子的线性同余生成，**每次搭出来的都一样** —— 否则每局地形细节都在变，\r\n    // 烘焙进场景和运行时生成的两份也会对不上。\r\n\r\n    static readonly Color PebbleCol = new Color(0.44f, 0.42f, 0.38f);\r\n    static readonly Color CrackCol  = new Color(0.24f, 0.23f, 0.22f);\r\n    static readonly Color LeafA2    = new Color(0.36f, 0.28f, 0.15f);\r\n    static readonly Color LeafB2    = new Color(0.30f, 0.36f, 0.18f);\r\n\r\n    static void BuildGroundDetail(Transform p)\r\n    {\r\n        // { x0, x1, z0, z1, 铺装顶面 y } —— 与 BuildGround 里 PaveRect 的调用一一对应\r\n        float[,] lanes =\r\n        {\r\n            { Nb.VAx0, Nb.VAx1, Nb.BlockZ0, Nb.BlockZ1, 0.044f },   // 纵向 A\r\n            { Nb.VBx0, Nb.VBx1, Nb.BlockZ0, Nb.BlockZ1, 0.044f },   // 纵向 B\r\n            { Nb.BlockX0, Nb.BlockX1, Nb.H1z0, Nb.H1z1, 0.048f },   // 横向 1\r\n            { Nb.BlockX0, Nb.BlockX1, Nb.H2z0, Nb.H2z1, 0.048f },   // 横向 2\r\n            { Nb.BlockX0, Nb.BlockX1, Nb.H3z0, Nb.H3z1, 0.048f },   // 横向 3\r\n            { Nb.XMin + 0.30f, Nb.BlockX0, Nb.ZMin + 0.30f, Nb.ZMax - 0.30f, 0.040f },  // 环道西\r\n            { Nb.BlockX1, Nb.XMax - 0.30f, Nb.ZMin + 0.30f, Nb.ZMax - 0.30f, 0.040f },  // 环道东\r\n            { Nb.BlockX0, Nb.BlockX1, Nb.BlockZ1, Nb.ZMax - 0.30f, 0.040f },            // 环道北\r\n            { Nb.BlockX0, Nb.BlockX1, Nb.ZMin + 0.30f, Nb.BlockZ0, 0.040f },            // 环道南\r\n        };\r\n\r\n        int seed = 20261017;\r\n        int n = 0;\r\n\r\n        for (int L = 0; L < lanes.GetLength(0); L++)\r\n        {\r\n            float x0 = lanes[L, 0], x1 = lanes[L, 1], z0 = lanes[L, 2], z1 = lanes[L, 3], top = lanes[L, 4];\r\n            float area = (x1 - x0) * (z1 - z0);\r\n            int count = Mathf.Clamp(Mathf.RoundToInt(area / 22f), 4, 34);\r\n\r\n            for (int i = 0; i < count; i++)\r\n            {\r\n                float x = Mathf.Lerp(x0 + 0.35f, x1 - 0.35f, Rnd(ref seed));\r\n                float z = Mathf.Lerp(z0 + 0.35f, z1 - 0.35f, Rnd(ref seed));\r\n                float pick = Rnd(ref seed);\r\n                float yaw = Rnd(ref seed) * 360f;\r\n\r\n                if (pick < 0.46f)\r\n                {\r\n                    // 石子：压扁的小方块，贴地 4~7 cm\r\n                    float w = 0.05f + 0.055f * Rnd(ref seed);\r\n                    GameObject g = Nb.Box(p, \"Pebble \" + n, new Vector3(x, top + 0.012f, z),\r\n                        new Vector3(w, 0.045f, w * 1.15f), PebbleCol, false);\r\n                    g.transform.localRotation = Quaternion.Euler(0f, yaw, 0f);\r\n                }\r\n                else if (pick < 0.78f)\r\n                {\r\n                    // 裂纹：细长的深色条，0.4~1.3 m\r\n                    float len = 0.4f + 0.9f * Rnd(ref seed);\r\n                    GameObject g = Nb.Box(p, \"Crack \" + n, new Vector3(x, top + 0.004f, z),\r\n                        new Vector3(0.035f, 0.006f, len), CrackCol, false);\r\n                    g.transform.localRotation = Quaternion.Euler(0f, yaw, 0f);\r\n                }\r\n                else\r\n                {\r\n                    // 落叶\r\n                    GameObject g = Nb.Box(p, \"Leaf \" + n, new Vector3(x, top + 0.009f, z),\r\n                        new Vector3(0.10f, 0.006f, 0.07f), Rnd(ref seed) < 0.5f ? LeafA2 : LeafB2, false);\r\n                    g.transform.localRotation = Quaternion.Euler(0f, yaw, 0f);\r\n                }\r\n                n++;\r\n            }\r\n        }\r\n\r\n        // 井盖：5 个，钉在过道交叉口 + 出生点正前方 4.5 m 处。\r\n        // 它们既是参照物，也是\"我到底走了多远\"的天然里程碑。\r\n        float[,] grates =\r\n        {\r\n            { 78.00f, Nb.H2cz },      // 出生点朝东 4.5 m —— 一开局正前方就有一个\r\n            { Nb.VAcx, Nb.H1cz },\r\n            { Nb.VAcx, Nb.H3cz },\r\n            { Nb.VBcx, Nb.H2cz },\r\n            { Nb.VBcx, Nb.H1cz },\r\n        };\r\n        for (int i = 0; i < grates.GetLength(0); i++)\r\n        {\r\n            float gx = grates[i, 0], gz = grates[i, 1];\r\n            float top = (Mathf.Abs(gx - Nb.VAcx) < 3f || Mathf.Abs(gx - Nb.VBcx) < 3f) ? 0.048f : 0.044f;\r\n            Nb.Box(p, \"Grate \" + i, new Vector3(gx, top + 0.007f, gz),\r\n                new Vector3(0.56f, 0.014f, 0.56f), Iron, false);\r\n            Nb.Box(p, \"Grate Rim \" + i, new Vector3(gx, top + 0.004f, gz),\r\n                new Vector3(0.68f, 0.008f, 0.68f), new Color(0.30f, 0.29f, 0.27f), false);\r\n        }\r\n\r\n        Debug.LogFormat(\"[Nb] 地面细节：{0} 个石子/裂纹/落叶 + {1} 个井盖（全部无碰撞、Ignore Raycast 层）。\",\r\n            n, grates.GetLength(0));\r\n    }\r\n\r\n    /// 固定种子的线性同余（0..1）。不用 Random：要保证每次搭出来完全一致，\r\n    /// 否则烘焙进场景的那份和运行时补的那份会错位。\r\n    static float Rnd(ref int s)\r\n    {\r\n        s = s * 1103515245 + 12345;\r\n        return ((s >> 8) & 0xFFFFFF) / (float)0x1000000;\r\n    }\r\n\r\n    // ───────────────────────── 围墙与大门 ─────────────────────────\r\n\r\n    static void BuildWalls(Transform p)\r\n    {\r\n        const float h = 2.5f, t = 0.4f;\r\n        float zc = Nb.ZMax + 0.2f;      // 前墙稍微外移，给门柱留厚度\r\n        float zb = Nb.ZMin - 0.2f;\r\n\r\n        Wall(p, \"Wall Front W\", new Vector3((Nb.XMin + Nb.GateX0) * 0.5f, h * 0.5f, zc),\r\n            new Vector3(Nb.GateX0 - Nb.XMin, h, t));\r\n        Wall(p, \"Wall Front E\", new Vector3((Nb.GateX1 + Nb.XMax) * 0.5f, h * 0.5f, zc),\r\n            new Vector3(Nb.XMax - Nb.GateX1, h, t));\r\n        Wall(p, \"Wall Back\", new Vector3((Nb.XMin + Nb.XMax) * 0.5f, h * 0.5f, zb),\r\n            new Vector3(Nb.XMax - Nb.XMin, h, t));\r\n        Wall(p, \"Wall West\", new Vector3(Nb.XMin - 0.2f, h * 0.5f, (Nb.ZMin + Nb.ZMax) * 0.5f),\r\n            new Vector3(t, h, Nb.Depth));\r\n        Wall(p, \"Wall East\", new Vector3(Nb.XMax + 0.2f, h * 0.5f, (Nb.ZMin + Nb.ZMax) * 0.5f),\r\n            new Vector3(t, h, Nb.Depth));\r\n\r\n        // 门柱 + 过梁：让\"大门\"这件事在远处也能看出来\r\n        float px0 = Nb.GateX0 - 0.35f, px1 = Nb.GateX1 + 0.35f;\r\n        Nb.Box(p, \"Gate Post W\", new Vector3(px0, 1.6f, zc), new Vector3(0.7f, 3.2f, 0.9f), WallCol, true);\r\n        Nb.Box(p, \"Gate Post E\", new Vector3(px1, 1.6f, zc), new Vector3(0.7f, 3.2f, 0.9f), WallCol, true);\r\n        Nb.Box(p, \"Gate Post W Cap\", new Vector3(px0, 3.28f, zc), new Vector3(0.92f, 0.16f, 1.1f), WallCap, false);\r\n        Nb.Box(p, \"Gate Post E Cap\", new Vector3(px1, 3.28f, zc), new Vector3(0.92f, 0.16f, 1.1f), WallCap, false);\r\n        Nb.Box(p, \"Gate Lintel\", new Vector3((px0 + px1) * 0.5f, 3.05f, zc),\r\n            new Vector3(px1 - px0 + 0.7f, 0.34f, 0.5f), WallCol, false);\r\n    }\r\n\r\n    static void Wall(Transform p, string name, Vector3 center, Vector3 size)\r\n    {\r\n        Nb.Box(p, name, center, size, WallCol, true);\r\n        // 压顶：比墙体宽 8 cm，像真围墙的水泥帽\r\n        Nb.Box(p, name + \" Cap\", new Vector3(center.x, size.y + 0.07f, center.z),\r\n            new Vector3(size.x + 0.08f, 0.14f, size.z + 0.08f), WallCap, false);\r\n    }\r\n\r\n    // ───────────────────────── 路灯 ─────────────────────────\r\n\r\n    static void BuildLamps(Transform p)\r\n    {\r\n        // 灯杆必须站在过道**里面**：A 道 x 68.80…73.90、B 道 x 91.00…96.40（实测楼体包络）。\r\n        // 灯头再朝巷子中间偏 0.9 m，光才照在路面上而不是照在墙上。\r\n        Lamp(p, \"Lamp V West 0\", new Vector3(69.35f, 0f, Nb.H1cz), 1f);\r\n        Lamp(p, \"Lamp V West 1\", new Vector3(69.35f, 0f, Nb.H3cz), 1f);\r\n        Lamp(p, \"Lamp V East 0\", new Vector3(95.85f, 0f, Nb.H2cz), -1f);\r\n        Lamp(p, \"Lamp V East 1\", new Vector3(95.85f, 0f, Nb.H1cz), -1f);\r\n    }\r\n\r\n    /// side = +1 时灯臂朝 +x，-1 朝 -x（让灯头伸向过道中间）\r\n    static void Lamp(Transform p, string name, Vector3 at, float side)\r\n    {\r\n        Transform root = new GameObject(name).transform;\r\n        root.SetParent(p, false);\r\n        root.localPosition = at;\r\n\r\n        Nb.Cyl(root, \"Pole\", new Vector3(0f, 1.7f, 0f), 0.14f, 3.4f, Iron, false);\r\n        Nb.Box(root, \"Arm\", new Vector3(side * 0.45f, 3.32f, 0f), new Vector3(0.9f, 0.1f, 0.1f), Iron, false);\r\n        Nb.Box(root, \"Head\", new Vector3(side * 0.9f, 3.2f, 0f), new Vector3(0.42f, 0.16f, 0.26f), Iron, false);\r\n        // 灯罩玻璃要自发光：夜里布光是暗的，靠材质自己亮才看得出\"灯是开的\"\r\n        GameObject glass = Nb.Box(root, \"Glass\", new Vector3(side * 0.9f, 3.11f, 0f),\r\n            new Vector3(0.32f, 0.06f, 0.18f), LampWarm, false);\r\n        Renderer gr = glass.GetComponent<Renderer>();\r\n        if (gr != null) gr.sharedMaterial = Nb.MatEmissive(LampWarm, 2.4f);\r\n    }\r\n\r\n    // ───────────────────────── 树 ─────────────────────────\r\n\r\n    static void BuildTrees(Transform p)\r\n    {\r\n        // 环形通道里种一圈，顺便把\"围墙内只有沥青\"的空旷感压掉。\r\n        // 注意树要**贴墙那侧**（墙在 46.6 / 118.4），把环道中轴让出来 —— 环形通道那只猫就是沿中轴兜圈的。\r\n        float twx = Nb.XMin + 1.20f, tex = Nb.XMax - 1.20f;\r\n        float tzn = Nb.ZMax - 1.00f, tzs = Nb.ZMin + 1.00f;\r\n\r\n        float[] westZ = { -6.0f, -26.0f, -46.0f, -68.0f };\r\n        float[] eastZ = { -2.0f, -24.0f, -44.0f, -66.0f };\r\n        for (int i = 0; i < westZ.Length; i++) Tree(p, \"Tree W \" + i, new Vector3(twx, 0f, westZ[i]), i);\r\n        for (int i = 0; i < eastZ.Length; i++) Tree(p, \"Tree E \" + i, new Vector3(tex, 0f, eastZ[i]), i + 3);\r\n\r\n        // 南北两条环道各摆三棵（避开大门正对的位置，别一进门就被树挡死）\r\n        float[] northX = { 56.0f, 84.0f, 104.0f };\r\n        float[] southX = { 58.0f, 82.0f, 106.0f };\r\n        for (int i = 0; i < northX.Length; i++) Tree(p, \"Tree N \" + i, new Vector3(northX[i], 0f, tzn), i + 5);\r\n        for (int i = 0; i < southX.Length; i++) Tree(p, \"Tree S \" + i, new Vector3(southX[i], 0f, tzs), i + 7);\r\n    }\r\n\r\n    static void Tree(Transform p, string name, Vector3 at, int seed)\r\n    {\r\n        float k = 0.86f + 0.05f * (seed % 5);        // 高矮错开一点，不要一片复制的树\r\n        Transform root = new GameObject(name).transform;\r\n        root.SetParent(p, false);\r\n        root.localPosition = at;\r\n\r\n        Nb.Cyl(root, \"Trunk\", new Vector3(0f, 1.3f * k, 0f), 0.34f * k, 2.6f * k, Trunk);\r\n        Nb.Ball(root, \"Crown A\", new Vector3(0f, 3.5f * k, 0f), 3.1f * k, (seed & 1) == 0 ? LeafA : LeafB, false);\r\n        Nb.Ball(root, \"Crown B\", new Vector3(0.5f * ((seed % 3) - 1), 4.35f * k, 0.4f * ((seed % 4) - 1.5f)),\r\n            2.05f * k, (seed & 1) == 0 ? LeafB : LeafA, false);\r\n    }\r\n\r\n    // ───────────────────────── 垃圾桶 / 花坛 ─────────────────────────\r\n\r\n    static void BuildProps(Transform p)\r\n    {\r\n        // 垃圾桶：贴着过道边缘放，不占中线（A 道 x 68.80…73.90，B 道 91.00…96.40，桶半径 0.86）\r\n        Vector3[] bins =\r\n        {\r\n            new Vector3(69.75f, 0f, -12.0f), new Vector3(72.95f, 0f, -17.0f),\r\n            new Vector3(69.75f, 0f, -30.0f), new Vector3(72.95f, 0f, -44.5f),\r\n            new Vector3(92.00f, 0f, -12.0f), new Vector3(95.40f, 0f, -31.0f),\r\n            new Vector3(92.00f, 0f, -47.5f), new Vector3(95.40f, 0f, -63.0f),\r\n        };\r\n        for (int i = 0; i < bins.Length; i++)\r\n        {\r\n            Transform root = new GameObject(\"Bin \" + i).transform;\r\n            root.SetParent(p, false);\r\n            root.localPosition = bins[i];\r\n            Nb.Cyl(root, \"Body\", new Vector3(0f, 0.55f, 0f), 0.86f, 1.1f, BinCol);\r\n            Nb.Cyl(root, \"Lid\", new Vector3(0f, 1.14f, 0f), 0.94f, 0.08f, Iron);\r\n        }\r\n\r\n        // 花坛：放在过道与楼栋的交接处，纯装饰（1.5 宽，所以两边都留了 0.9 的余量）\r\n        Vector3[] planters =\r\n        {\r\n            new Vector3(69.90f, 0f, Nb.H1cz + 3.6f), new Vector3(72.70f, 0f, Nb.H1cz + 3.6f),\r\n            new Vector3(92.40f, 0f, Nb.H2cz - 2.8f), new Vector3(95.00f, 0f, Nb.H2cz - 2.8f),\r\n            new Vector3(69.90f, 0f, Nb.H3cz + 2.4f), new Vector3(72.70f, 0f, Nb.H3cz + 2.4f),\r\n        };\r\n        for (int i = 0; i < planters.Length; i++)\r\n        {\r\n            Transform root = new GameObject(\"Planter \" + i).transform;\r\n            root.SetParent(p, false);\r\n            root.localPosition = planters[i];\r\n            Nb.Box(root, \"Box\", new Vector3(0f, 0.28f, 0f), new Vector3(1.5f, 0.56f, 0.8f), WallCap);\r\n            Nb.Box(root, \"Soil\", new Vector3(0f, 0.57f, 0f), new Vector3(1.3f, 0.06f, 0.62f), new Color(0.24f, 0.18f, 0.13f), false);\r\n            for (int b = 0; b < 3; b++)\r\n                Nb.Ball(root, \"Bush \" + b, new Vector3(-0.42f + b * 0.42f, 0.74f, 0f), 0.62f, LeafB, false);\r\n        }\r\n    }\r\n}\r\n"},"NbColliders":{"path":"Assets/Scripts/NbColliders.cs","role":"Recomputes the 12 model buildings' BoxColliders from local bounds (fixes a transposed-size bug).","source":"// @role Recomputes the 12 model buildings' BoxColliders from local bounds (fixes a transposed-size bug).\r\n// @calls Nb\r\n\r\n// NbColliders.cs — 运行时给「换过模型的 12 栋楼」重量一次碰撞体\r\n//\r\n// 为什么需要这一步（这不是\"保险起见\"，是修一个真实存在的 bug）：\r\n//\r\n//   StreetFromModels.AddBodyCollider 原来用 **Renderer.bounds**（世界 AABB）量楼体，\r\n//   再除以 holder 的缩放 k 存进 BoxCollider.size。可 BoxCollider.size 是**本地空间**的量，\r\n//   而 holder 上还挂着 0°/90°/270° 的偏航 —— 存进去的\"世界尺寸\"会**被再转一次**。\r\n//   日志是干净的（它打印的是量到的世界尺寸 16.9 x 10.1 x 7.7），可落到场景里的盒子\r\n//   实际是 7.7 x 10.1 x 16.9：横竖**转置**了。\r\n//\r\n//   后果有两个，而且方向相反：\r\n//     · 长边方向少了 4.6 m 覆盖 ⇒ 玩家能从楼的正侧面走进楼里（穿模）\r\n//     · 短边方向多了 4.6 m      ⇒ 过道里凭空站着一道隐形墙（撞上去、猫也贴着它滑）\r\n//\r\n// 修法：把每个网格的**本地包围盒** 8 个角乘上 (holder.worldToLocalMatrix × renderer.localToWorldMatrix)，\r\n// 在 holder 的本地空间里重新求一次 AABB。这样旋转和缩放都在矩阵里自然抵消，\r\n// 存进 size/center 就是对的。编辑器脚本也同步改成同样的算法（下次重建也不会再错）。\r\n//\r\n// 2026-10-17 补：**按名字在整个层级里找楼，而不是只认 root 的直接子物体。**\r\n//   实测过的一次事故：Hierarchy 里一次误拖把 industrial_03 拖进了 west_02，\r\n//   于是 west_02 的包围盒把工业仓库一起圈了进去 —— 本地 x 从 3.32 变成 12.39，\r\n//   世界长度 7.71 → 28.77 m，横着堵死整条 H1 过道（奶酪 #8、猫 5 号路线全在盒子里）。\r\n//   同时 industrial_03 因为不再是直接子物体而被\"跳过\"（日志还写着\"量不到网格\"，很误导）。\r\n//   现在两个都按\"独立一栋\"处理，并且会把这种嵌套单独警告出来。\r\n//\r\n// 这一步只读场景、只改 BoxCollider 的 center/size，不改任何 Transform / 渲染 / 层。\r\n\r\nusing System.Collections.Generic;\r\nusing UnityEngine;\r\n\r\ninternal static class NbColliders\r\n{\r\n    // 老脚本建出来的根节点名；改名了就在日志里说清楚，别静默跳过\r\n    const string RootName = \"Street Models (auto)\";\r\n\r\n    // 楼的名字前缀（west_00 / abandoned_01 / industrial_03 …）\r\n    static readonly string[] Prefixes = { \"west_\", \"abandoned_\", \"industrial_\" };\r\n\r\n    struct Foot\r\n    {\r\n        internal string Name;\r\n        internal Bounds Box;\r\n    }\r\n\r\n    /// <summary>\r\n    /// 校正之后每栋楼的**世界 AABB**（平面范围就是它的占地）。\r\n    /// 小地图（NbMap）直接画这个，不再用「3 列 × 4 排 + 每列一个宽度」那套网格近似 ——\r\n    /// 12 栋楼是三个不同模型，实际是 16.9×7.7 / 13.1×13.2 / 16.9×13.1 混排，\r\n    /// 用统一网格画出来每块都会偏进过道里，看着就是\"方块和楼对不上\"。\r\n    /// Normalize() 每局开头重填一次，所以这里永远是这一帧场景里的真值。\r\n    /// </summary>\r\n    internal static readonly List<Bounds> Footprints = new List<Bounds>();\r\n\r\n    internal static int Normalize()\r\n    {\r\n        Footprints.Clear();\r\n\r\n        GameObject root = GameObject.Find(RootName);\r\n        if (root == null)\r\n        {\r\n            Debug.LogWarningFormat(\"[Nb] 场景里找不到「{0}」，跳过楼体碰撞体校正。\", RootName);\r\n            return 0;\r\n        }\r\n\r\n        // ① 先在整个层级里把「楼」找齐（含被误拖进另一栋里的那种）\r\n        List<Transform> holders = FindHolders(root.transform);\r\n        if (holders.Count == 0)\r\n        {\r\n            Debug.LogWarning(\"[Nb] 「Street Models (auto)」下一栋楼都没找到，跳过校正。\");\r\n            return 0;\r\n        }\r\n\r\n        var feet = new List<Foot>();\r\n        int fixedN = 0, added = 0, skipped = 0;\r\n\r\n        for (int i = 0; i < holders.Count; i++)\r\n        {\r\n            Transform holder = holders[i];\r\n            if (holder == null) continue;\r\n\r\n            // ② 被拖到别处的，单独说一句 —— 不是致命错误，但值得让作者知道\r\n            if (holder.parent != root.transform)\r\n            {\r\n                Debug.LogWarningFormat(\r\n                    \"[Nb] 楼「{0}」没挂在「{1}」下面，而是挂在「{2}」下面。\" +\r\n                    \"已按独立一栋处理；建议在 Hierarchy 里把它拖回「{1}」（多半是拖拽时手滑）。\",\r\n                    holder.name, RootName,\r\n                    holder.parent != null ? holder.parent.name : \"?\");\r\n            }\r\n\r\n            Bounds local;\r\n            if (!LocalBounds(holder, holders, out local) || local.size.sqrMagnitude <= 0.0001f)\r\n            {\r\n                skipped++;\r\n                Debug.LogWarningFormat(\"[Nb] 楼「{0}」量不到网格（下面一个 Renderer 都没有？），跳过。\", holder.name);\r\n                continue;\r\n            }\r\n\r\n            BoxCollider bc = holder.GetComponent<BoxCollider>();\r\n            if (bc == null)\r\n            {\r\n                bc = holder.gameObject.AddComponent<BoxCollider>();\r\n                added++;\r\n            }\r\n\r\n            Vector3 oldSize = bc.size;\r\n            bc.isTrigger = false;\r\n            bc.enabled = true;\r\n            bc.center = local.center;\r\n            bc.size = local.size;\r\n\r\n            // 世界 AABB（旋转后的）：日志里报这个，才方便和\"过道有多宽\"对得上\r\n            Bounds world = ToWorldBounds(holder, bc);\r\n            Foot f;\r\n            f.Name = holder.name;\r\n            f.Box = world;\r\n            feet.Add(f);\r\n            Footprints.Add(world);\r\n            fixedN++;\r\n\r\n            Debug.LogFormat(\"[Nb] 楼体碰撞体校正「{0}」：本地 {1:F2}×{2:F2}×{3:F2} → 世界 {4:F2}×{5:F2}×{6:F2}，\" +\r\n                            \"x {7:F2}…{8:F2}  z {9:F2}…{10:F2}（原 size {11:F2}×{12:F2}×{13:F2}）\",\r\n                holder.name, bc.size.x, bc.size.y, bc.size.z,\r\n                world.size.x, world.size.y, world.size.z,\r\n                world.min.x, world.max.x, world.min.z, world.max.z,\r\n                oldSize.x, oldSize.y, oldSize.z);\r\n        }\r\n\r\n        Debug.LogFormat(\"[Nb] 楼体碰撞体：校正 {0} 栋（新增 {1} 个 BoxCollider），跳过 {2} 栋（量不到网格）。\",\r\n            fixedN, added, skipped);\r\n\r\n        CheckFree(feet, \"出生点\", new[] { Nb.PlayerStart });\r\n        CheckFree(feet, \"奶酪\", Nb.CheeseSpots);\r\n        CheckFree(feet, \"猫的路线\", Flatten(Nb.CatRoutes));\r\n        return fixedN;\r\n    }\r\n\r\n    // ───────────────────────── 找楼 ─────────────────────────\r\n\r\n    /// 递归找所有名字像楼的对象。**不能用 GetChild(i)** —— 只认直接子物体时，\r\n    /// 一次误拖就会让\"被拖走的那栋\"消失、\"外面的那栋\"吃掉它的尺寸（见文件头）。\r\n    static List<Transform> FindHolders(Transform root)\r\n    {\r\n        var list = new List<Transform>();\r\n        Transform[] all = root.GetComponentsInChildren<Transform>(true);\r\n        for (int i = 0; i < all.Length; i++)\r\n        {\r\n            Transform t = all[i];\r\n            if (t == null || t == root) continue;\r\n            if (!IsBuildingName(t.name)) continue;\r\n            list.Add(t);\r\n        }\r\n        return list;\r\n    }\r\n\r\n    /// 只认 `前缀 + 纯数字`（west_00 / abandoned_01 / industrial_03…）。\r\n    /// 不能只判 StartsWith：FBX 里常有叫 \"west_wall_01\" 的子网格，\r\n    /// 认错一次就会把一栋楼拆成两个盒子（父的那半反而变小）。\r\n    static bool IsBuildingName(string n)\r\n    {\r\n        if (string.IsNullOrEmpty(n)) return false;\r\n        for (int i = 0; i < Prefixes.Length; i++)\r\n        {\r\n            string pre = Prefixes[i];\r\n            if (!n.StartsWith(pre)) continue;\r\n\r\n            string tail = n.Substring(pre.Length);\r\n            int sp = tail.IndexOf(' ');            // 重名时 Unity 会加 \" (1)\"\r\n            if (sp > 0) tail = tail.Substring(0, sp);\r\n            if (tail.Length == 0) return false;\r\n\r\n            for (int c = 0; c < tail.Length; c++)\r\n                if (tail[c] < '0' || tail[c] > '9') return false;\r\n            return true;\r\n        }\r\n        return false;\r\n    }\r\n\r\n    // ───────────────────────── 量本地包围盒 ─────────────────────────\r\n\r\n    /// 在 holder 的本地空间里求「本栋楼自己的网格」的 AABB。\r\n    /// 用 sharedMesh.bounds 而不是 Renderer.bounds：后者是**世界**轴对齐盒，已经被旋转过，\r\n    /// 再拿去当本地尺寸就会得到本文开头说的那种转置盒子。\r\n    /// holders 用来排除嵌在本栋里的**另一栋楼**（否则两栋会互相圈进对方的盒子里）。\r\n    static bool LocalBounds(Transform holder, List<Transform> holders, out Bounds local)\r\n    {\r\n        local = new Bounds();\r\n        bool any = false;\r\n        Matrix4x4 toLocal = holder.worldToLocalMatrix;\r\n\r\n        Renderer[] rs = holder.GetComponentsInChildren<Renderer>(true);\r\n        for (int i = 0; i < rs.Length; i++)\r\n        {\r\n            Renderer r = rs[i];\r\n            if (r == null || !r.enabled || !r.gameObject.activeInHierarchy) continue;\r\n            if (r.GetComponent<Camera>() != null) continue;\r\n            if (InNestedHolder(holder, r.transform, holders)) continue;\r\n\r\n            Bounds lb;\r\n            SkinnedMeshRenderer smr = r as SkinnedMeshRenderer;\r\n            if (smr != null)\r\n            {\r\n                if (smr.sharedMesh == null) continue;\r\n                lb = smr.sharedMesh.bounds;\r\n            }\r\n            else\r\n            {\r\n                MeshFilter mf = r.GetComponent<MeshFilter>();\r\n                if (mf == null || mf.sharedMesh == null) continue;\r\n                lb = mf.sharedMesh.bounds;\r\n            }\r\n            if (lb.size.sqrMagnitude <= 0f) continue;\r\n\r\n            Matrix4x4 m = toLocal * r.transform.localToWorldMatrix;\r\n            Vector3 mn = lb.min, mx = lb.max;\r\n            for (int c = 0; c < 8; c++)\r\n            {\r\n                Vector3 p = m.MultiplyPoint3x4(new Vector3((c & 1) == 0 ? mn.x : mx.x,\r\n                                                           (c & 2) == 0 ? mn.y : mx.y,\r\n                                                           (c & 4) == 0 ? mn.z : mx.z));\r\n                if (!any) { local = new Bounds(p, Vector3.zero); any = true; }\r\n                else local.Encapsulate(p);\r\n            }\r\n        }\r\n        return any;\r\n    }\r\n\r\n    /// 这个 renderer 是不是属于\"嵌在本栋里面的另一栋楼\"\r\n    static bool InNestedHolder(Transform holder, Transform r, List<Transform> holders)\r\n    {\r\n        for (int i = 0; i < holders.Count; i++)\r\n        {\r\n            Transform h = holders[i];\r\n            if (h == null || h == holder) continue;\r\n            if (!h.IsChildOf(holder)) continue;     // 只关心真正嵌在本栋层级里的\r\n            if (r.IsChildOf(h)) return true;\r\n        }\r\n        return false;\r\n    }\r\n\r\n    static Bounds ToWorldBounds(Transform holder, BoxCollider bc)\r\n    {\r\n        Vector3 c = bc.center, e = bc.size * 0.5f;\r\n        Bounds b = new Bounds();\r\n        bool any = false;\r\n        for (int i = 0; i < 8; i++)\r\n        {\r\n            Vector3 lp = c + new Vector3((i & 1) == 0 ? -e.x : e.x,\r\n                                         (i & 2) == 0 ? -e.y : e.y,\r\n                                         (i & 4) == 0 ? -e.z : e.z);\r\n            Vector3 wp = holder.TransformPoint(lp);\r\n            if (!any) { b = new Bounds(wp, Vector3.zero); any = true; }\r\n            else b.Encapsulate(wp);\r\n        }\r\n        return b;\r\n    }\r\n\r\n    // ───────────────────────── 自检：路面上不该有楼 ─────────────────────────\r\n\r\n    /// 出生点 / 奶酪 / 猫的路线全都在过道上。任何一项落进楼体盒子里，\r\n    /// 表现都是\"一开局就卡在墙里\"或\"奶酪永远捡不到\" —— 而画面看上去没有任何异常。\r\n    static void CheckFree(List<Foot> feet, string what, Vector3[] points)\r\n    {\r\n        if (points == null) return;\r\n        int bad = 0;\r\n        for (int i = 0; i < points.Length; i++)\r\n        {\r\n            Vector3 p = points[i];\r\n            // 只比平面：楼体盒子往上 10 m，用 3D 包含会把站在楼边的点也算进去\r\n            for (int b = 0; b < feet.Count; b++)\r\n            {\r\n                Bounds w = feet[b].Box;\r\n                if (p.x < w.min.x - 0.25f || p.x > w.max.x + 0.25f) continue;\r\n                if (p.z < w.min.z - 0.25f || p.z > w.max.z + 0.25f) continue;\r\n                Debug.LogWarningFormat(\"[Nb] 自检·{0} #{1}（{2:F2}, {3:F2}）落在「{4}」的碰撞体里 —— 会卡住/够不到。\",\r\n                    what, i + 1, p.x, p.z, feet[b].Name);\r\n                bad++;\r\n                break;\r\n            }\r\n        }\r\n        if (bad == 0 && points.Length > 0)\r\n            Debug.LogFormat(\"[Nb] 自检·{0} {1} 个点全部落在空地/过道上（不在任何楼体盒子里）。\", what, points.Length);\r\n    }\r\n\r\n    static Vector3[] Flatten(Vector3[][] routes)\r\n    {\r\n        if (routes == null) return null;\r\n        var list = new List<Vector3>();\r\n        for (int i = 0; i < routes.Length; i++)\r\n            if (routes[i] != null) list.AddRange(routes[i]);\r\n        return list.ToArray();\r\n    }\r\n}\r\n"},"NbFood":{"path":"Assets/Scripts/NbFood.cs","role":"Builds fridge food out of raw geometry (carrot, tomato, apple, ...); decoration only, no colliders.","source":"// @role Builds fridge food out of raw geometry (carrot, tomato, apple, ...); decoration only, no colliders.\n// @calls Nb\n\n// NbFood.cs — 冰箱里的食物（纯几何体拼的，不依赖任何模型资源）\n//\n// 为什么不用模型：Resources/GameProps 里只有「Cat walk」和「Cheese_0001_LOD0」两样东西。\n// 冰箱这一关要的是「瓜果蔬菜牛奶」，用模型既要再导一批 FBX、又要再调一遍归一化/贴地，\n// 而这一关的目标物只有 0.2~0.3 m 大、玩家又只能贴到 0.2 m 的距离看 —— 几何体拼完全够，\n// 而且颜色就是我调的那几个数，不存在\"贴图偏色\"。\n//\n// 每个食物的约定：\n//   · 根物体原点在**底面中心**（和 Nb.Box 那套一致），Spawn 传进来的 at 就是它站的地方\n//   · 尺寸以 s 为基准（s=0.26 时一个番茄约 0.13 m，对 0.30 m 高的老鼠是半个身位）\n//   · 所有零件都是装饰层（无碰撞体、不参与射线）—— 目标物不该挡路，也不该挡门光\n//\n// **不要给这里加碰撞体。** 收集判定靠 0.62 m 的平面距离，加了碰撞体反而会把玩家顶开，\n// 而这一关的走道只有层高 0.53 m，顶一下就够不着了。\n\nusing UnityEngine;\n\ninternal static class NbFood\n{\n    /// 品种表。名字会进日志和 HUD 提示，所以用全大写英文（TMP 用的是那套只含 ASCII 的字体）。\n    internal static readonly string[] Names =\n    {\n        \"CARROT\", \"TOMATO\", \"APPLE\", \"LEMON\", \"MILK\", \"LETTUCE\",\n        \"CORN\", \"BERRY\", \"BREAD\", \"MELON\", \"EGGS\", \"MUSHROOM\",\n    };\n\n    internal static int Kinds { get { return Names.Length; } }\n\n    /// 在 parent 下造一个食物。`at` 是底面中心（世界坐标）。\n    internal static GameObject Spawn(Transform parent, Vector3 at, int kind, float s, string name)\n    {\n        GameObject root = new GameObject(name);\n        root.transform.SetParent(parent, false);\n        root.transform.position = at;\n        root.transform.rotation = Quaternion.identity;\n        root.transform.localScale = Vector3.one;\n\n        int k = ((kind % Kinds) + Kinds) % Kinds;\n        switch (k)\n        {\n            case 0: Carrot(root.transform, s);     break;\n            case 1: Tomato(root.transform, s);     break;\n            case 2: Apple(root.transform, s);      break;\n            case 3: Lemon(root.transform, s);      break;\n            case 4: Milk(root.transform, s);       break;\n            case 5: Lettuce(root.transform, s);    break;\n            case 6: Corn(root.transform, s);       break;\n            case 7: Berry(root.transform, s);      break;\n            case 8: Bread(root.transform, s);      break;\n            case 9: Melon(root.transform, s);      break;\n            case 10: Eggs(root.transform, s);      break;\n            default: Mushroom(root.transform, s);  break;\n        }\n        return root;\n    }\n\n    // ───────────────────────── 调色板 ─────────────────────────\n    // 全部比\"真实颜色\"暗一档：冰箱里只有冷白灯，纯饱和色在这种光下会糊成一片白点。\n\n    static readonly Color Orange = new Color(0.72f, 0.36f, 0.10f);\n    static readonly Color Red    = new Color(0.62f, 0.13f, 0.12f);\n    static readonly Color Yellow = new Color(0.76f, 0.66f, 0.16f);\n    static readonly Color Green  = new Color(0.20f, 0.40f, 0.16f);\n    static readonly Color GreenD = new Color(0.12f, 0.28f, 0.11f);\n    static readonly Color Cream  = new Color(0.86f, 0.85f, 0.80f);\n    static readonly Color Blue   = new Color(0.16f, 0.27f, 0.46f);\n    static readonly Color Brown  = new Color(0.36f, 0.22f, 0.11f);\n    static readonly Color BrownD = new Color(0.24f, 0.15f, 0.08f);\n    static readonly Color White  = new Color(0.90f, 0.89f, 0.85f);\n    static readonly Color Grey   = new Color(0.42f, 0.43f, 0.44f);\n\n    // ───────────────────────── 品种 ─────────────────────────\n\n    static void Carrot(Transform t, float s)\n    {\n        Nb.Cyl(t, \"Body\", new Vector3(0f, 0.34f * s, 0f), 0.20f * s, 0.68f * s, Orange, false);\n        Nb.Cyl(t, \"Tip\", new Vector3(0f, 0.03f * s, 0f), 0.07f * s, 0.08f * s, Orange, false);\n        Nb.Ball(t, \"Leaf a\", new Vector3(0.03f * s, 0.70f * s, 0f), 0.16f * s, Green, false);\n        Nb.Ball(t, \"Leaf b\", new Vector3(-0.04f * s, 0.75f * s, 0.02f * s), 0.14f * s, GreenD, false);\n        Nb.Ball(t, \"Leaf c\", new Vector3(0f, 0.73f * s, -0.04f * s), 0.13f * s, GreenD, false);\n    }\n\n    static void Tomato(Transform t, float s)\n    {\n        Nb.Ball(t, \"Body\", new Vector3(0f, 0.26f * s, 0f), 0.52f * s, Red, false);\n        Nb.Ball(t, \"Cap\", new Vector3(0f, 0.50f * s, 0f), 0.16f * s, GreenD, false);\n        Nb.Box(t, \"Stem\", new Vector3(0f, 0.54f * s, 0f), new Vector3(0.04f, 0.10f, 0.04f) * s, Green, false);\n    }\n\n    static void Apple(Transform t, float s)\n    {\n        Nb.Ball(t, \"Body\", new Vector3(0f, 0.25f * s, 0f), 0.50f * s, Red, false);\n        Nb.Box(t, \"Stem\", new Vector3(0f, 0.53f * s, 0f), new Vector3(0.035f, 0.12f, 0.035f) * s, BrownD, false);\n        Nb.Ball(t, \"Leaf\", new Vector3(0.07f * s, 0.56f * s, 0f), 0.14f * s, Green, false);\n    }\n\n    static void Lemon(Transform t, float s)\n    {\n        Nb.Ball(t, \"Body\", new Vector3(0f, 0.20f * s, 0f), 0.42f * s, Yellow, false);\n        Nb.Ball(t, \"Nub a\", new Vector3(0.21f * s, 0.20f * s, 0f), 0.09f * s, Yellow, false);\n        Nb.Ball(t, \"Nub b\", new Vector3(-0.21f * s, 0.20f * s, 0f), 0.09f * s, Yellow, false);\n    }\n\n    static void Milk(Transform t, float s)\n    {\n        Nb.Box(t, \"Carton\", new Vector3(0f, 0.52f * s, 0f),\n            new Vector3(0.44f, 1.04f, 0.40f) * s, Cream, false);\n        Nb.Box(t, \"Label\", new Vector3(0f, 0.44f * s, -0.205f * s),\n            new Vector3(0.40f, 0.42f, 0.02f) * s, Blue, false);\n        // 折角屋顶：两块斜板拼出来，比一个平顶更像纸盒\n        Nb.Box(t, \"Roof a\", new Vector3(0f, 1.08f * s, -0.10f * s),\n            new Vector3(0.44f, 0.10f, 0.24f) * s, Cream, false);\n        Nb.Box(t, \"Roof b\", new Vector3(0f, 1.08f * s, 0.10f * s),\n            new Vector3(0.44f, 0.10f, 0.24f) * s, Cream, false);\n    }\n\n    static void Lettuce(Transform t, float s)\n    {\n        Nb.Ball(t, \"Core\", new Vector3(0f, 0.24f * s, 0f), 0.50f * s, Green, false);\n        Nb.Ball(t, \"Leaf a\", new Vector3(0.14f * s, 0.20f * s, 0.06f * s), 0.34f * s, GreenD, false);\n        Nb.Ball(t, \"Leaf b\", new Vector3(-0.12f * s, 0.22f * s, -0.08f * s), 0.32f * s, GreenD, false);\n        Nb.Ball(t, \"Leaf c\", new Vector3(0f, 0.34f * s, 0.10f * s), 0.28f * s, Green, false);\n    }\n\n    static void Corn(Transform t, float s)\n    {\n        Nb.Cyl(t, \"Cob\", new Vector3(0f, 0.14f * s, 0f), 0.24f * s, 0.62f * s, Yellow, false);\n        Nb.Box(t, \"Husk a\", new Vector3(0.10f * s, 0.12f * s, 0f),\n            new Vector3(0.05f, 0.30f, 0.26f) * s, GreenD, false);\n        Nb.Box(t, \"Husk b\", new Vector3(-0.10f * s, 0.12f * s, 0f),\n            new Vector3(0.05f, 0.30f, 0.26f) * s, GreenD, false);\n        Nb.Cyl(t, \"Stem\", new Vector3(0f, 0.62f * s, 0f), 0.06f * s, 0.12f * s, Green, false);\n    }\n\n    static void Berry(Transform t, float s)\n    {\n        Nb.Ball(t, \"Body\", new Vector3(0f, 0.18f * s, 0f), 0.36f * s, Red, false);\n        Nb.Ball(t, \"Tip\", new Vector3(0f, 0.02f * s, 0f), 0.14f * s, Red, false);\n        Nb.Ball(t, \"Cap\", new Vector3(0f, 0.34f * s, 0f), 0.20f * s, GreenD, false);\n        Nb.Box(t, \"Stem\", new Vector3(0f, 0.40f * s, 0f), new Vector3(0.03f, 0.08f, 0.03f) * s, Green, false);\n    }\n\n    static void Bread(Transform t, float s)\n    {\n        Nb.Box(t, \"Loaf\", new Vector3(0f, 0.24f * s, 0f),\n            new Vector3(0.86f, 0.48f, 0.44f) * s, Brown, false);\n        Nb.Box(t, \"Crust\", new Vector3(0f, 0.47f * s, 0f),\n            new Vector3(0.88f, 0.06f, 0.46f) * s, BrownD, false);\n        Nb.Box(t, \"Score a\", new Vector3(-0.18f * s, 0.50f * s, 0f),\n            new Vector3(0.06f, 0.02f, 0.40f) * s, BrownD, false);\n        Nb.Box(t, \"Score b\", new Vector3(0.10f * s, 0.50f * s, 0f),\n            new Vector3(0.06f, 0.02f, 0.40f) * s, BrownD, false);\n    }\n\n    static void Melon(Transform t, float s)\n    {\n        Nb.Ball(t, \"Rind\", new Vector3(0f, 0.40f * s, 0f), 0.80f * s, GreenD, false);\n        Nb.Ball(t, \"Stripe a\", new Vector3(0f, 0.40f * s, 0f), 0.82f * s, Green, false);\n        Nb.Box(t, \"Stem\", new Vector3(0f, 0.78f * s, 0f), new Vector3(0.05f, 0.10f, 0.05f) * s, BrownD, false);\n    }\n\n    static void Eggs(Transform t, float s)\n    {\n        Nb.Box(t, \"Tray\", new Vector3(0f, 0.17f * s, 0f),\n            new Vector3(0.74f, 0.34f, 0.52f) * s, Grey, false);\n        Nb.Box(t, \"Lid\", new Vector3(0f, 0.35f * s, 0f),\n            new Vector3(0.76f, 0.05f, 0.54f) * s, White, false);\n        for (int i = 0; i < 3; i++)\n            Nb.Ball(t, \"Egg \" + i, new Vector3((-0.22f + i * 0.22f) * s, 0.30f * s, 0f),\n                0.16f * s, White, false);\n    }\n\n    static void Mushroom(Transform t, float s)\n    {\n        Nb.Cyl(t, \"Stalk\", new Vector3(0f, 0.14f * s, 0f), 0.16f * s, 0.28f * s, White, false);\n        Nb.Ball(t, \"Cap\", new Vector3(0f, 0.30f * s, 0f), 0.42f * s, Brown, false);\n        Nb.Box(t, \"Gill\", new Vector3(0f, 0.26f * s, 0f),\n            new Vector3(0.34f, 0.02f, 0.34f) * s, White, false);\n    }\n}\n"},"NbFoodArt":{"path":"Assets/Scripts/NbFoodArt.cs","role":"Places imported grocery models as fridge shelf decoration (solid, ignore-raycast, off the cheese lanes).","source":"// @role Places imported grocery models as fridge shelf decoration (solid, ignore-raycast, off the cheese lanes).\r\n// @calls NbFridge NbFood\r\n\r\n// NbFoodArt.cs — 冰箱里的商品装饰（用你自己导进来的三个食物包，纯装饰，不参与玩法）\r\n//\r\n// ───────────────────────── 这些东西是什么 ─────────────────────────\r\n// 工程根目录下有三个素材包，原样放在 Assets/ 里 Unity 是 **加载不到** 的（运行时没有\r\n// AssetDatabase）。所以这里用了一份「Resources 副本」：\r\n//\r\n//   Assets/Resources/Food/Grocery/SM_Food_Collection_01.fbx   41 件：罐头 / 香肠 / 麦片 / 蛋白粉 …\r\n//   Assets/Resources/Food/Vintage/food.fbx                    10 件：番茄 / 玉米 / 牛奶 / 三文鱼 …\r\n//   Assets/Resources/Food/Pastry/pastry.glb                    1 件：六个面包合成的一坨\r\n//   Assets/Resources/Food/*/Tex/*.png                          对应的贴图（只拷了 base color）\r\n//\r\n// 原目录一个字没动。要换素材/加素材，改这里的表就行。\r\n//\r\n// ───────────────────────── 为什么要自己写材质 ─────────────────────────\r\n// FBX 里记的贴图路径是作者机器上的绝对路径（C:\\Users\\pekar\\Desktop\\Blender\\Food\\food1.png），\r\n// Unity 只能按**文件名**去项目里找，food1.png / rusted can.png 这些根本不存在 ⇒\r\n// 材质会带一张空贴图进来；而这类 FBX 的材质描述在 URP 工程里还会被建成 Standard 材质\r\n// ⇒ 屏幕上是一堆洋红色的东西（而编辑器里看不出任何报错）。\r\n// 所以：贴图由本文件按表直接指定，材质自己 new 成 URP/Lit。\r\n//\r\n// 贴图归属不是我瞎猜的 —— 每张图都打开看过：\r\n//   T_Food_Collection_01_C  = 罐头/香肠/麦片/蛋白粉/糖果（Food_Collection 那一组）\r\n//   T_Bottles_Collection_01_C = 酒瓶/油瓶/啤酒/牛奶瓶/清洁剂（Bottles 那一组）\r\n//   Vintage 那套是一物一图（food.png 是番茄/玉米/牛奶/三文鱼四格合集）\r\n//\r\n// ───────────────────────── 摆放原则 ─────────────────────────\r\n// **只在三处摆**，因为这三处永远不会和掩体重叠：\r\n//   ① 每层后壁的两排（9 个堆头 ×3 件）—— 一进门看到的那面\"货墙\"\r\n//   ② 每层左右内壁（各 3 个堆头 ×2 件）—— 冰箱两侧本来就是放瓶子的地方\r\n//   ③ 每层台阶两侧的平台（左右各 2 件）—— 爬楼梯时正好在视线高度上\r\n// 掩体的 z 被夹在 [后壁 + 2.4, 前沿 − 2.0]，所以 ① ② 天然落在掩体范围之外；\r\n// 每个坑位最后还会再查一次\"离本层奶酪够不够远\"（BlocksCheese）。\r\n// 七层合计约 470 件，密度只由下面那五个常量决定。\r\n//\r\n// 大小由 `SizeMul` 一个系数统管（表里的 h 是**原始**高度，摆的时候才乘）。\r\n// 改大小时堆内间距、抖动、避奶酪半径会跟着一起长 —— 只放大模型不放大间距，\r\n// 一堆三件会插进彼此体内，看起来像\"模型加载坏了\"。\r\n//\r\n// 全部零件：**实心**（每件挂一个贴合模型局部包围盒的 BoxCollider），\r\n// 玩家撞上去会被挡住，不会再从罐头中间穿过去。\r\n//\r\n// 但\"实心\"必须同时满足两条，否则这一关会当场坏掉 —— 两条都是踩过的坑：\r\n//\r\n//   ① **全部留在 Ignore Raycast 层。** `CatCheeseSetup.TryGroundY` 与猫的视线用的是\r\n//      `Physics.DefaultRaycastLayers`（不含这一层）。留在这一层，地面探测就永远打在\r\n//      地板上、不会打在罐头顶上 —— 否则奶酪会被\"贴\"到某个瓶盖上。\r\n//   ② **门光判定 `IsHidden()` 必须把这一层排除掉。** 它是从门口朝玩家打 SphereCast\r\n//      找遮挡物；474 件实心商品如果算数，站在一听可乐后面就等于\"藏好了\"，\r\n//      整关只剩\"随便往货架边一站\"，难度直接归零。\r\n//      所以那一处用的是 DefaultRaycastLayers 而不是 ~0（见 NeighbourhoodGame.IsHidden）。\r\n//\r\n// 反过来说：只要这两条还成立，商品的碰撞体就只影响\"人走得过去吗\"，\r\n// 不影响\"光打不打得到我\"—— 而\"人走不过去\"正是穿模的反面。\r\n\r\nusing System.Collections.Generic;\r\nusing UnityEngine;\r\n\r\ninternal static class NbFoodArt\r\n{\r\n    // ───────────────────────── 商品表 ─────────────────────────\r\n\r\n    struct Spec\r\n    {\r\n        internal string item;   // FBX 里的节点名（大小写/下划线/空格不敏感，前缀匹配）\r\n        internal string tex;    // Resources 里的贴图路径，空 = 不贴图\r\n        internal float h;       // 目标高度（米）—— **乘 SizeMul 之前**的原始值\r\n\r\n        internal Spec(string i, string t, float h) { item = i; tex = t; this.h = h; }\r\n    }\r\n\r\n    const string GroceryPack = \"Food/Grocery/SM_Food_Collection_01\";\r\n    const string VintagePack = \"Food/Vintage/food\";\r\n    const string PastryPack  = \"Food/Pastry/pastry\";\r\n\r\n    const string TexFood    = \"Food/Grocery/Tex/T_Food_Collection_01_C\";\r\n    const string TexBottles = \"Food/Grocery/Tex/T_Bottles_Collection_01_C\";\r\n    const string TexDir     = \"Food/Vintage/Tex/\";\r\n\r\n    /// 41 件的杂货包。这里只挑**贴图归属能确定**的那几件（表里没写的一律不用）。\r\n    static readonly Spec[] Grocery =\r\n    {\r\n        new Spec(\"SM_Canned_Food_05\", TexFood,    0.17f),\r\n        new Spec(\"SM_Canned_Food_07\", TexFood,    0.17f),\r\n        new Spec(\"SM_Canned_Food_09\", TexFood,    0.15f),\r\n        new Spec(\"SM_Canned_Food_11\", TexFood,    0.18f),\r\n        new Spec(\"SM_Canned_Food_13\", TexFood,    0.16f),\r\n        new Spec(\"SM_Sausages_01\",    TexFood,    0.13f),\r\n        new Spec(\"SM_Porridge_01\",    TexFood,    0.21f),\r\n        new Spec(\"SM_Protein_Jar_01\", TexFood,    0.23f),\r\n        new Spec(\"SM_Pasta_01\",       TexFood,    0.20f),\r\n        new Spec(\"SM_Candies_01\",     TexFood,    0.14f),\r\n        new Spec(\"SM_Wine_Bottle_01\", TexBottles, 0.28f),\r\n        new Spec(\"SM_Olive_Oil_01\",   TexBottles, 0.24f),\r\n        new Spec(\"SM_Beer_Bottle_01\", TexBottles, 0.26f),\r\n        new Spec(\"SM_Milk_Bottle_01\", TexBottles, 0.25f),\r\n    };\r\n\r\n    /// 老式罐头皮那套：10 件，一物一图，最不用猜的一组。\r\n    static readonly Spec[] Vintage =\r\n    {\r\n        new Spec(\"Tomatoes\", TexDir + \"food\",       0.17f),\r\n        new Spec(\"Corn\",     TexDir + \"food\",       0.17f),\r\n        new Spec(\"Milk\",     TexDir + \"food\",       0.18f),\r\n        new Spec(\"Salmon\",   TexDir + \"food\",       0.16f),\r\n        new Spec(\"Cake\",     TexDir + \"cake\",       0.14f),\r\n        new Spec(\"Cherry\",   TexDir + \"cherry\",     0.13f),\r\n        new Spec(\"Egg\",      TexDir + \"egg\",        0.12f),\r\n        new Spec(\"Cookie\",   TexDir + \"Cookie\",     0.11f),\r\n        new Spec(\"Raisins\",  TexDir + \"rasins\",     0.12f),\r\n        new Spec(\"Fish\",     TexDir + \"fishsticks\", 0.15f),\r\n    };\r\n\r\n    // ───────────────────────── 摆放密度 ─────────────────────────\r\n    //\r\n    // 这几个数是**唯一该动的地方**。原来每层 12 件（后壁 8 + 台阶两侧 4），\r\n    // 26 m 宽的后壁上摊 8 件 —— 那不是货架，那是\"撒了点东西\"。\r\n    // 现在改成**成堆**：一个堆头 3 件肩并肩（间距 BackGap），堆头之间留空。\r\n    // 挤成一块一块才像货架是满的；均匀摊开反而空。\r\n    //\r\n    // 想再密/再稀就只改这五个数，位置逻辑一行都不用碰。\r\n\r\n    //   （模型尺寸见下面的 SizeMul）\r\n\r\n    /// 商品统一放大系数。**只改这一个数就能整体变大变小。**\r\n    ///\r\n    /// 原始尺寸是按\"真冰箱\"定的（0.11~0.28 m），但这是一只 30 cm 高的老鼠在\r\n    /// 24×20 m 的巨型冰箱里跑 —— 一件 17 cm 的罐头在 15 m 外只有几个像素，\r\n    /// 走进去看也像\"地上撒了点东西\"。放 1.5× 之后最矮的 0.17、最高的瓶子 0.42。\r\n    ///\r\n    /// **上限是 1.8，不是随便填的**：层内净空 = LayerH 0.56 − 板厚 0.05 = 0.51 m，\r\n    /// 最高的商品（酒瓶 0.28）乘 1.8 就是 0.50 —— 再大就顶穿上层搁板了。\r\n    internal const float SizeMul = 1.5f;\r\n\r\n    const int   BackCols = 8;      // 后壁一排几个堆头\r\n    const int   BackRows = 2;      // 后壁几排（沿 z 往里，靠后壁那两排）\r\n    const int   BackPer  = 3;      // 一个堆头几件\r\n    // 堆内间距必须跟着 SizeMul 走：模型放大 1.5 倍、间距不动的话，\r\n    // 一个堆头里的三件会插进彼此的身体里（0.34 的间距装 0.4 宽的蛋糕）。\r\n    const float BackGap  = 0.34f * SizeMul;   // 堆头内相邻两件的间距（米）\r\n    const float BackSpan = NbFridge.InnerW - 3.0f;   // 后壁一排铺开的宽度（x），以 CX 为中心，两侧各留 1.5 m 给侧壁货带\r\n    const float BackRowZ = 0.62f * SizeMul;   // 后壁两排之间的距离\r\n\r\n    const int   SideRuns = 6;      // 每侧壁几个堆头（沿 z 从后壁一直铺到房间前沿）\r\n    const int   SidePer  = 2;      // 侧壁一个堆头几件\r\n    const float SideGap  = 0.34f * SizeMul;\r\n    const float SideStep = 2.3f;   // 侧壁两个堆头之间的距离（够大，不跟 SizeMul 走）\r\n\r\n    /// 侧壁第一堆离后壁内面的距离。\r\n    /// 后壁第二排的中心在 0.55 + BackRowZ（=1.48），再加半件深 ≈ 0.21 ⇒ 占到 1.69。\r\n    /// 原来写 0.90，两侧第一堆正好塞进后壁两排之间 —— 放大 1.5 倍之后，\r\n    /// 四个角上后壁最外一件和侧壁第一件会互相插进去（离线复算里唯一的 6 处重叠）。\r\n    const float SideZ0 = 2.10f;\r\n\r\n    // ───────────────────────── 对外入口 ─────────────────────────\r\n\r\n    /// 往冰箱里摆装饰。返回摆成功的件数（0 = 三个包一个都没加载上，已退回几何体）。\r\n    internal static int DecorateFridge(Transform root)\r\n    {\r\n        _mats.Clear();\r\n        _colliders = 0;\r\n\r\n        Dictionary<string, GameObject> tpl = new Dictionary<string, GameObject>();\r\n        Harvest(GroceryPack, Grocery, tpl);\r\n        Harvest(VintagePack, Vintage, tpl);\r\n        HarvestPastry(tpl);\r\n\r\n        if (tpl.Count == 0)\r\n            Debug.LogWarning(\"[FoodArt] 三个食物包一个都没加载上（Resources/Food 里没有可用模型）——\" +\r\n                             \"架子会退回 NbFood 的几何体食物。检查 Unity 是否已把 .fbx/.glb 导入完。\");\r\n\r\n        string[] keys = new string[tpl.Count];\r\n        tpl.Keys.CopyTo(keys, 0);\r\n        System.Array.Sort(keys, string.CompareOrdinal);\r\n\r\n        int placed = 0, miss = 0, skip = 0;\r\n\r\n        for (int n = 0; n <= NbFridge.Layers; n++)\r\n        {\r\n            float y = NbFridge.Top(n);\r\n\r\n            // ① 后壁两排。这是\"这一层看着是满的\"最主要的来源 ——\r\n            //    玩家从门口往里看，看到的就是后壁那片货墙。\r\n            for (int row = 0; row < BackRows; row++)\r\n            {\r\n                float z = NbFridge.ZMin + NbFridge.WallT + 0.55f + row * BackRowZ;\r\n                for (int c = 0; c < BackCols; c++)\r\n                {\r\n                    float t = (BackCols <= 1) ? 0.5f : c / (float)(BackCols - 1);\r\n                    float x = NbFridge.CX + (t - 0.5f) * BackSpan;\r\n                    Cluster(root, tpl, keys, new Vector3(x, y, z), BackPer, BackGap,\r\n                        n * 131 + row * 29 + c * 7, n, ref placed, ref miss, ref skip);\r\n                }\r\n            }\r\n\r\n            // ② 两侧壁：从后壁一直铺到房间前沿。\r\n            //\r\n            //    这一条是\"堆满\"的关键，不是后壁。后壁那两排离门有 15~19 m，\r\n            //    玩家站在门口往里看，中间十几米是空地板 + 六个掩体，只有尽头一堵货墙 ——\r\n            //    看起来还是空的。侧壁铺满之后，从门口望进去是\"两条货带夹着中间过道\"，\r\n            //    这才是货架是满的那种观感，而且不挡路（东西全贴在内壁上）。\r\n            //\r\n            //    高层的房间浅，摆不下的 z 由 InRoom 判掉，不写死每层数量。\r\n            for (int side = 0; side < 2; side++)\r\n            {\r\n                float x = (side == 0) ? NbFridge.XMin + NbFridge.WallT + 0.55f\r\n                                      : NbFridge.XMax - NbFridge.WallT - 0.55f;\r\n                for (int c = 0; c < SideRuns; c++)\r\n                {\r\n                    float z = NbFridge.ZMin + NbFridge.WallT + SideZ0 + c * SideStep;\r\n                    if (!InRoom(n, z, 0.45f)) { skip++; continue; }\r\n                    Cluster(root, tpl, keys, new Vector3(x, y, z), SidePer, SideGap,\r\n                        n * 71 + side * 23 + c * 5, n, ref placed, ref miss, ref skip);\r\n                }\r\n            }\r\n\r\n            // ③ 台阶两侧的平台：单件。上下楼梯时它们正好在视线高度，\r\n            //    是\"我在往上爬\"这件事唯一的参照物 —— 少了它，六层灰板走起来一模一样。\r\n            //\r\n            //    x 不能写死：楼梯宽度和冰箱宽度都会变，写死就把商品摆到台阶上\r\n            //    （或者推进侧壁里）。按\"两侧各自的可用宽度\"取两个比例位置。\r\n            float wingL = NbFridge.StairX0 - NbFridge.Px(0f);\r\n            float wingR = NbFridge.Px(1f) - NbFridge.StairX1;\r\n            float[] lx =\r\n            {\r\n                NbFridge.Px(0f) + wingL * 0.40f, NbFridge.Px(0f) + wingL * 0.81f,\r\n                NbFridge.StairX1 + wingR * 0.19f, NbFridge.StairX1 + wingR * 0.60f,\r\n            };\r\n            float fz = PlatformZ(n);\r\n            for (int k = 0; k < lx.Length; k++)\r\n                Slot(root, tpl, keys, new Vector3(lx[k], y, fz + (k % 2) * 0.45f),\r\n                    n * 23 + k * 7 + 3, n * 13 + k, n, ref placed, ref miss, ref skip);\r\n        }\r\n\r\n        foreach (KeyValuePair<string, GameObject> kv in tpl)\r\n            if (kv.Value != null) Nb.Kill(kv.Value);\r\n\r\n        Debug.LogFormat(\"[FoodArt] 冰箱装饰完成：{0} 件（{1} 种模型 + 几何体兜底），贴在 {2} 层；\" +\r\n                        \"碰撞体 {3} 个，取不到模型 {4} 次，给奶酪/浅房间让位 {5} 次，材质 {6} 份。\",\r\n            placed, tpl.Count, NbFridge.Layers + 1, _colliders, miss, skip, _mats.Count);\r\n        return placed;\r\n    }\r\n\r\n    /// 一个\"堆头\"：把 count 件挤在 at 附近，肩并肩。\r\n    static void Cluster(Transform root, Dictionary<string, GameObject> tpl, string[] keys,\r\n                        Vector3 at, int count, float gap, int seed, int layer,\r\n                        ref int placed, ref int miss, ref int skip)\r\n    {\r\n        for (int i = 0; i < count; i++)\r\n        {\r\n            float x = at.x + (i - (count - 1) * 0.5f) * gap;\r\n            float z = at.z + Jit(seed + i * 11, 0.08f * SizeMul);\r\n            Slot(root, tpl, keys, new Vector3(x, at.y, z),\r\n                seed * 13 + i * 5, seed + i * 3, layer, ref placed, ref miss, ref skip);\r\n        }\r\n    }\r\n\r\n    /// 一个坑位：先看会不会挡住本层的奶酪，再放。\r\n    static void Slot(Transform root, Dictionary<string, GameObject> tpl, string[] keys,\r\n                     Vector3 at, int pickSeed, int yawSeed, int layer,\r\n                     ref int placed, ref int miss, ref int skip)\r\n    {\r\n        if (BlocksCheese(layer, at.x, at.z)) { skip++; return; }\r\n        Put(root, tpl, keys, pickSeed, at, yawSeed, ref placed, ref miss);\r\n    }\r\n\r\n    /// 这个坑位离**本层的奶酪**太近吗。\r\n    ///\r\n    /// 奶酪是全场唯一该被一眼看见的东西。奶酪总高 0.34、商品 0.17~0.42（已含 SizeMul），\r\n    /// 前面挡一瓶酒是真挡，不是\"看着有点挤\"。留出的距离**跟着 SizeMul 一起长** ——\r\n    /// 商品放大之后，还按旧的 0.60 m 留身位，等于让一件更大的东西贴得更近。\r\n    static bool BlocksCheese(int layer, float x, float z)\r\n    {\r\n        Vector3[] s = NbFridge.Spots;\r\n        float top = NbFridge.Top(layer);\r\n        float clear = 0.60f * SizeMul;\r\n        for (int i = 0; i < s.Length; i++)\r\n        {\r\n            if (Mathf.Abs(s[i].y - top) > 0.30f) continue;      // 不是这一层的\r\n            float dx = s[i].x - x, dz = s[i].z - z;\r\n            if (dx * dx + dz * dz < clear * clear) return true;\r\n        }\r\n        return false;\r\n    }\r\n\r\n    /// z 是否落在第 layer 层的**房间里**（不含门前那条缩进带 —— 那是楼梯）。\r\n    static bool InRoom(int layer, float z, float margin)\r\n    {\r\n        return z <= NbFridge.FrontZ(layer) - margin &&\r\n               z >= NbFridge.ZMin + NbFridge.WallT + margin;\r\n    }\r\n\r\n    /// 台阶两侧平台所在的 z。n < Layers 时站在\"上一层板往里缩\"形成的那条平台上\r\n    /// （头顶是空的）；顶层没有上一层，就退进房间里靠前沿一点。\r\n    static float PlatformZ(int n)\r\n    {\r\n        if (n < NbFridge.Layers) return NbFridge.FrontZ(n + 1) + 0.55f;\r\n        return NbFridge.FrontZ(n) - 0.85f;\r\n    }\r\n\r\n    /// 确定性抖动。不用 Random —— 每次进关的摆放必须一模一样，\r\n    /// 否则调参时看到的画面每次都不同，改了什么根本说不清。\r\n    static float Jit(int seed, float amp)\r\n    {\r\n        int h = seed * 1103515245 + 12345;\r\n        h = (h >> 9) & 0x7fff;\r\n        return (h / 32767f * 2f - 1f) * amp;\r\n    }\r\n\r\n    /// 在一个坑位上放一件：模型优先，拿不到就用几何体食物兜底。\r\n    /// **兜底不是洁癖**：素材包没导入完（或者被移走）时，冰箱里至少还有东西，\r\n    /// 而不是空货架 —— 空货架不会报错，只会让人以为\"食物模型没生效\"。\r\n    static void Put(Transform root, Dictionary<string, GameObject> tpl, string[] keys,\r\n                    int pickSeed, Vector3 at, int yawSeed, ref int placed, ref int miss)\r\n    {\r\n        Spec s;\r\n        if (Pick(keys, pickSeed, out s) && Place(root, tpl, s, at, yawSeed))\r\n        {\r\n            placed++;\r\n            return;\r\n        }\r\n\r\n        miss++;\r\n        GameObject geo = NbFood.Spawn(root, at, yawSeed, 0.24f * SizeMul, \"Food (geo)\");\r\n        AddCollider(geo);          // 兜底的几何体食物也一样要实心，否则只有它们能穿过去\r\n        placed++;\r\n    }\r\n\r\n    // ───────────────────────── 模板 ─────────────────────────\r\n\r\n    /// 把一个包实例化一次，把表里点到的节点摘出来做成\"模板\"。\r\n    ///\r\n    /// 为什么要摘出来：一个父节点只能挂一个位置，而同一个罐头要点 4 次。\r\n    /// 摘出来之后每个位置再 Instantiate 一份模板（网格是共享的，不额外占内存）。\r\n    ///\r\n    /// `SetParent(holder, true)` 保留**世界**变换 —— 只清 localPosition。\r\n    /// 不能直接 Reset 旋转：Blender 导出的 FBX 往往把 -90° X 的转正挂在父节点上，\r\n    /// 连旋转一起清掉的话，整排瓶子会躺在地上（而且不报错）。\r\n    static void Harvest(string path, Spec[] list, Dictionary<string, GameObject> tpl)\r\n    {\r\n        GameObject pack = Resources.Load<GameObject>(path);\r\n        if (pack == null)\r\n        {\r\n            Debug.LogWarning(\"[FoodArt] 加载不到 Resources/\" + path + \" —— 这一包的零件全部跳过。\");\r\n            return;\r\n        }\r\n\r\n        GameObject tmp = Object.Instantiate(pack);\r\n        tmp.name = path + \" (harvest)\";\r\n\r\n        int got = 0;\r\n        for (int i = 0; i < list.Length; i++)\r\n        {\r\n            Transform c = FindDeep(tmp.transform, list[i].item);\r\n            if (c == null)\r\n            {\r\n                Debug.LogWarning(\"[FoodArt] \" + path + \" 里找不到「\" + list[i].item + \"」。\");\r\n                continue;\r\n            }\r\n\r\n            GameObject holder = new GameObject(\"tpl \" + list[i].item);\r\n            c.SetParent(holder.transform, true);\r\n            c.localPosition = Vector3.zero;\r\n\r\n            Paint(holder, list[i].tex);       // 材质先换掉，后面 Instantiate 就不用再换\r\n            SetLayer(holder, Nb.DecorLayer);\r\n\r\n            tpl[list[i].item] = holder;\r\n            got++;\r\n        }\r\n\r\n        Nb.Kill(tmp);\r\n        Debug.LogFormat(\"[FoodArt] {0}：41/10 件里取了 {1} 件。\", path, got);\r\n    }\r\n\r\n    /// 面包那个 glb 只有**一个**网格（六个面包并成一体），没有可按名字挑的零件，\r\n    /// 所以整份当一件用。它自己的材质是 glTFast 建的、贴图内嵌，不动它。\r\n    static void HarvestPastry(Dictionary<string, GameObject> tpl)\r\n    {\r\n        GameObject pack = Resources.Load<GameObject>(PastryPack);\r\n        if (pack == null)\r\n        {\r\n            Debug.LogWarning(\"[FoodArt] 加载不到 Resources/\" + PastryPack + \" —— 跳过面包。\");\r\n            return;\r\n        }\r\n\r\n        GameObject go = Object.Instantiate(pack);\r\n        go.name = \"tpl pastry\";\r\n        SetLayer(go, Nb.DecorLayer);\r\n        tpl[\"pastry\"] = go;\r\n        Debug.Log(\"[FoodArt] 面包包已加载（单网格，六个面包作一件）。\");\r\n    }\r\n\r\n    // ───────────────────────── 摆放 ─────────────────────────\r\n\r\n    /// 按\"货架索引\"轮转挑一件。用固定的算术而不是 Random ——\r\n    /// 每次进关的摆放必须一模一样，否则调参时看到的画面每次都不同。\r\n    static bool Pick(string[] keys, int seed, out Spec spec)\r\n    {\r\n        spec = new Spec();\r\n        if (keys.Length == 0) return false;\r\n\r\n        int k = ((seed * 7 + 3) % keys.Length + keys.Length) % keys.Length;\r\n        string key = keys[k];\r\n\r\n        for (int i = 0; i < Grocery.Length; i++)\r\n            if (Grocery[i].item == key) { spec = Grocery[i]; return true; }\r\n        for (int i = 0; i < Vintage.Length; i++)\r\n            if (Vintage[i].item == key) { spec = Vintage[i]; return true; }\r\n\r\n        // 面包：统一按 0.20 高\r\n        spec = new Spec(key, null, 0.20f);\r\n        return true;\r\n    }\r\n\r\n    static bool Place(Transform root, Dictionary<string, GameObject> tpl, Spec s, Vector3 at, int seed)\r\n    {\r\n        GameObject src;\r\n        if (!tpl.TryGetValue(s.item, out src) || src == null) return false;\r\n\r\n        GameObject go = Object.Instantiate(src);\r\n        go.name = \"Food \" + s.item;\r\n        go.transform.SetParent(root, false);\r\n\r\n        // 稍微转个角度：一排商品全朝一个方向会像贴图拼的；转一下就有\"随手摆\"的感觉\r\n        float yaw = ((seed * 37 + 11) % 360);\r\n        go.transform.rotation = Quaternion.Euler(0f, yaw, 0f);\r\n\r\n        // 这里**不能**复用 CatCheeseSetup.FitAndGround：它靠向下打射线找地面，\r\n        // 而且取的是射线打到的**最低**那个面 ⇒ 在冰箱里会一路穿到最底层的地板，\r\n        // 七层的装饰全掉到 y=0。这里的高度是调用方给的，不用量。\r\n        //\r\n        // 归一化到目标高度（再乘统一放大系数），最后把**包围盒底面**落到 at.y、\r\n        // 中心对到 at.xz。缩放之后必须重新量一次包围盒 —— 模型的原点常常不在\r\n        // 底面中心，拿缩放前的包围盒去对位会整体偏移，越大的模型偏得越多。\r\n        Bounds b;\r\n        if (CatCheeseSetup.TryMeasureWorldBounds(go, out b) && b.size.y > 1e-5f)\r\n            go.transform.localScale *= s.h * SizeMul / b.size.y;\r\n\r\n        if (CatCheeseSetup.TryMeasureWorldBounds(go, out b))\r\n        {\r\n            Vector3 p = go.transform.position;\r\n            p.x += at.x - b.center.x;\r\n            p.z += at.z - b.center.z;\r\n            p.y += at.y - b.min.y;\r\n            go.transform.position = p;\r\n        }\r\n        else\r\n        {\r\n            go.transform.position = at;\r\n        }\r\n\r\n        // **位置定完之后才挂碰撞体。** 反过来的话，包围盒是量的旧比例，\r\n        // 碰撞体会跟模型错开一截（越大的模型偏得越多），而且看不出来。\r\n        AddCollider(go);\r\n        return true;\r\n    }\r\n\r\n    // ───────────────────────── 材质 ─────────────────────────\r\n\r\n    static readonly Dictionary<string, Material> _mats = new Dictionary<string, Material>();\r\n\r\n    static void Paint(GameObject go, string texPath)\r\n    {\r\n        Material m = MatFor(texPath);\r\n        Renderer[] rs = go.GetComponentsInChildren<Renderer>(true);\r\n        for (int i = 0; i < rs.Length; i++)\r\n            if (rs[i] != null) rs[i].sharedMaterial = m;\r\n    }\r\n\r\n    /// 同一个贴图共用一份材质 ⇒ URP 的 SRP Batcher 还能合批。\r\n    /// 每件商品一份新材质的话，几十件就是几十个 draw call。\r\n    static Material MatFor(string texPath)\r\n    {\r\n        string key = texPath == null ? \"\" : texPath;\r\n        Material m;\r\n        if (_mats.TryGetValue(key, out m) && m != null) return m;\r\n\r\n        Shader sh = Shader.Find(\"Universal Render Pipeline/Lit\");\r\n        if (sh == null) sh = Shader.Find(\"Standard\");\r\n\r\n        Texture2D tex = string.IsNullOrEmpty(texPath) ? null : Resources.Load<Texture2D>(texPath);\r\n        if (!string.IsNullOrEmpty(texPath) && tex == null)\r\n            Debug.LogWarning(\"[FoodArt] 找不到贴图 Resources/\" + texPath + \" —— 这件商品会是纯白。\");\r\n\r\n        m = new Material(sh);\r\n        m.name = \"FoodArt_\" + (string.IsNullOrEmpty(texPath) ? \"flat\" : texPath);\r\n        // URP/Lit 的主贴图槽是 _BaseMap、主色是 _BaseColor；mainTexture/color 这两个属性\r\n        // 走的是 [MainTexture]/[MainColor] 特性，换 Standard 也照样能设对。\r\n        m.mainTexture = tex;\r\n        m.color = Color.white;\r\n        if (m.HasProperty(\"_Smoothness\")) m.SetFloat(\"_Smoothness\", 0.15f);\r\n        if (m.HasProperty(\"_Metallic\")) m.SetFloat(\"_Metallic\", 0f);\r\n        if (m.HasProperty(\"_Glossiness\")) m.SetFloat(\"_Glossiness\", 0.15f);\r\n\r\n        _mats[key] = m;\r\n        return m;\r\n    }\r\n\r\n    // ───────────────────────── 碰撞体 ─────────────────────────\r\n\r\n    static int _colliders;\r\n\r\n    /// 给一件商品挂上贴合它自身形状的 BoxCollider。\r\n    ///\r\n    /// 为什么是 BoxCollider 而不是 MeshCollider：一件商品一进物理宽相，网格碰撞体就是\r\n    /// 一整个三角面集合；而这些模型是低模罐头/盒子/瓶子，盒子碰撞体在体感上没区别。\r\n    /// 四百多个网格碰撞体的代价是每帧的宽相与中相开销，而它们一秒钟都不会动。\r\n    ///\r\n    /// 为什么不能直接用 `Renderer.bounds`：那是**世界**轴对齐盒。商品都带随机 yaw，\r\n    /// 斜 45° 时世界 AABB 会比真实体积大出约 41% —— 人会隔着一拳的距离被挡在空气里。\r\n    /// 这里把网格包围盒的 8 个角点换回**物体局部坐标**再求 AABB，\r\n    /// 碰撞体于是挂在会转的那个节点上、跟着模型一起转，尺寸是量出来的不是猜的。\r\n    static void AddCollider(GameObject go)\r\n    {\r\n        if (go == null) return;\r\n        if (go.GetComponent<Collider>() != null) return;   // 模板自带碰撞体就别叠一个\r\n\r\n        Transform root = go.transform;\r\n        Matrix4x4 toLocal = root.worldToLocalMatrix;      // 含缩放 ⇒ 得到的是\"未缩放局部\"单位\r\n        Bounds b = new Bounds(Vector3.zero, Vector3.zero);\r\n        bool any = false;\r\n\r\n        MeshFilter[] mfs = go.GetComponentsInChildren<MeshFilter>(true);\r\n        for (int i = 0; i < mfs.Length; i++)\r\n        {\r\n            Mesh mesh = mfs[i].sharedMesh;\r\n            if (mesh == null) continue;\r\n\r\n            Bounds mb = mesh.bounds;\r\n            Matrix4x4 m = toLocal * mfs[i].transform.localToWorldMatrix;\r\n            for (int c = 0; c < 8; c++)\r\n            {\r\n                Vector3 corner = new Vector3(\r\n                    (c & 1) == 0 ? mb.min.x : mb.max.x,\r\n                    (c & 2) == 0 ? mb.min.y : mb.max.y,\r\n                    (c & 4) == 0 ? mb.min.z : mb.max.z);\r\n                Vector3 p = m.MultiplyPoint3x4(corner);\r\n                if (!any) { b = new Bounds(p, Vector3.zero); any = true; }\r\n                else b.Encapsulate(p);\r\n            }\r\n        }\r\n\r\n        if (!any) return;\r\n\r\n        // 太薄的轴给一个下限：贴图级别的薄片在球扫掠下会被穿过去。\r\n        Vector3 size = b.size;\r\n        size.x = Mathf.Max(size.x, 0.02f);\r\n        size.y = Mathf.Max(size.y, 0.02f);\r\n        size.z = Mathf.Max(size.z, 0.02f);\r\n\r\n        BoxCollider bc = go.AddComponent<BoxCollider>();\r\n        bc.center = b.center;\r\n        bc.size = size;\r\n        bc.isTrigger = false;\r\n        _colliders++;\r\n    }\r\n\r\n    // ───────────────────────── 小工具 ─────────────────────────\r\n\r\n    static Transform FindDeep(Transform t, string want)\r\n    {\r\n        if (t == null) return null;\r\n        string w = Norm(want);\r\n        if (w.Length > 0 && Norm(t.name).StartsWith(w)) return t;\r\n        for (int i = 0; i < t.childCount; i++)\r\n        {\r\n            Transform r = FindDeep(t.GetChild(i), want);\r\n            if (r != null) return r;\r\n        }\r\n        return null;\r\n    }\r\n\r\n    /// 去掉下划线/空格/点、转小写：FBX 里叫 \"rusted can\"，贴图叫 \"rusted_can.png\"，\r\n    /// 直接比字符串永远对不上。\r\n    static string Norm(string s)\r\n    {\r\n        if (string.IsNullOrEmpty(s)) return \"\";\r\n        System.Text.StringBuilder sb = new System.Text.StringBuilder(s.Length);\r\n        for (int i = 0; i < s.Length; i++)\r\n        {\r\n            char c = s[i];\r\n            if (c == '_' || c == ' ' || c == '.') continue;\r\n            sb.Append(char.ToLowerInvariant(c));\r\n        }\r\n        return sb.ToString();\r\n    }\r\n\r\n    static void SetLayer(GameObject go, int layer)\r\n    {\r\n        if (layer < 0) return;\r\n        go.layer = layer;\r\n        for (int i = 0; i < go.transform.childCount; i++)\r\n            SetLayer(go.transform.GetChild(i).gameObject, layer);\r\n    }\r\n}\r\n"},"NbFridge":{"path":"Assets/Scripts/NbFridge.cs","role":"Fridge level: six shelves, stair ascent, cover props, and the door that floods light on a timer.","source":"// @role Fridge level: six shelves, stair ascent, cover props, and the door that floods light on a timer.\r\n// @calls NbFood NbFoodArt NbLighting\r\n// @tune Layers:int:2-12:number of shelves\r\n// @tune LayerH:float:0.2-2:shelf spacing (floor-to-floor) m\r\n// @tune StepsPerLayer:int:1-10:stair steps between shelves\r\n\r\n// NbFridge.cs — 场景 03「冰箱里」\r\n//\r\n// ───────────────────────── 为什么这一关和前两关完全不同 ─────────────────────────\r\n// 街区/后院的威胁是**会动的**（猫、保安），这一关的威胁是**会开的门**：\r\n// 没有人追你，但每隔几秒冰箱门会被打开一次，强光灌进来。\r\n// 门开之前有 3 秒预警，你要在这 3 秒里跑到掩体后面 —— 慢一步就是 -10 血。\r\n//\r\n// 所以空间必须提供**可数的掩体**，而不是一片空地：\r\n//   · 每层 4 个掩体（牛奶箱 / 西瓜 / 面包箱 / 黄油块），高 0.4~0.5 m\r\n//   · 掩体必须**比玩家高**（玩家 0.30 m）—— 否则门光从头顶越过去，躲了也没用\r\n//   · 掩体必须**分散**：贴着同一面墙排成一行，玩家会一直站在墙边不动\r\n//\r\n// ───────────────────────── 六层怎么上去（这张图是整关的关键） ─────────────────────────\r\n//\r\n//       门 z = ZMax                                 后壁 z = ZMin\r\n//   ┌──────────────────────────────────────────────────┐\r\n//   │  前厅（头顶全空）                                   │\r\n//   ├──────────────────────────────────────────────────┤  ← L6 板\r\n//   │  ▓▓▓▓楼梯▓▓▓▓            架板 L6                  │\r\n//   ├──────────────────────────────────────────────────┤  ← L5 板\r\n//   │  ▓▓▓▓楼梯▓▓▓▓       架板 L5                       │\r\n//   ├──────────────────────────────────────────────────┤\r\n//   │      ... 每层重复 ...                             │\r\n//   └──────────────────────────────────────────────────┘\r\n//\r\n// **2026-10-17 改版：从\"跳上去\"改成\"走上去\"。**\r\n// 旧版是让玩家在板前沿按空格跳上去（靠跳跃倍率 1.75 硬跳 0.56 m）。实测跳不上去 ——\r\n// 所以现在每层之间是一段**真正的楼梯**：4 级、每级 0.14 m、踏面 0.30 m，\r\n// 正好铺满\"上一层板比这一层往里缩的那 1.2 m\"。玩家走过去就上去了，不需要按空格。\r\n//\r\n// 楼梯宽 8 m、居中（x 51~59）：出生点正对着它，不可能找不到。\r\n// 冰箱收窄到 24 m 之后，10 m 的楼梯会占到前沿的 42% —— 两侧各只剩 6.7 m 的活动面，\r\n// 落地后想绕开楼梯去房间另一侧要贴着墙走。8 m 正好是宽度的三分之一。\r\n// 而**不能**做成整宽 —— 楼梯如果横贯整个前沿，它就变成一堵墙，\r\n// 每层房间里的人被自己头上的那段楼梯挡住，永远进不去。\r\n//\r\n// 结构上依赖一件事：层高 0.56 必须整除成 4×0.14，且每层前沿往里缩的量 1.2 必须\r\n// 正好等于 4×0.30。改任一个数都要同时改另两个，否则最后一级台阶接不上板边（会有一个洞）。\r\n//\r\n// 层高 0.56、玩家 0.30 高 ⇒ 净空 0.51 m：够站、够走，层内跳不起来（会撞头）。\r\n// 楼梯靠 CharacterController.stepOffset 上行，冰箱里这个值从 0.08 抬到 0.17\r\n// （NbPlayer.SetStepUp）—— 0.14 的踏步必须小于它，否则会变成\"贴着台阶推不动\"。\r\n\r\n// ───────────────────────── 门 ─────────────────────────\r\n// 门板绕左侧铰链向外开 105°，同时一盏平行光从门口扫进来（NbGame 每帧渐变强度）。\r\n// 那盏灯是**运行时**才创建的，而且默认 intensity = 0 ——\r\n// NbLighting.Apply 会把场上最亮的平行光当主光、其余全关掉，门光如果先存在，\r\n// 主光就可能变成它（它平时是 0），整关的布光会当场错位。见 CreateDoorLight。\r\n\r\nusing UnityEngine;\r\n\r\ninternal static class NbFridge\r\n{\r\n    // ───────────────────────── 范围 ─────────────────────────\r\n\r\n    // **2026-10-17 收窄：30 m → 24 m。** 30×20 的空地对一只 0.30 m 高的老鼠\r\n    // 是一片仓库：站在门口看不见两侧的墙，掩体之间也远到\"3 s 预警跑不过去\"。\r\n    //\r\n    // 收窄只动这两个数 —— 所有横向位置都写成净宽的比例（见 Px），\r\n    // 不再有 45.5 / 47.0 这样的世界坐标字面量。\r\n    internal const float XMin = 43f, XMax = 67f;     // 24 m 宽\r\n    internal const float ZMin = -20f, ZMax = 0f;     // 20 m 深，门在 ZMax 这一侧\r\n\r\n    internal const float CX = (XMin + XMax) * 0.5f;  // 55\r\n    internal const float CZ = (ZMin + ZMax) * 0.5f;  // −10\r\n\r\n    internal const int Layers = 6;\r\n    internal const float LayerH = 0.56f;             // 层高（板顶到板顶）\r\n    internal const float Slab = 0.05f;               // 板厚\r\n    internal const float WallT = 0.30f;\r\n    internal const float CeilY = LayerH * (Layers + 1);   // 3.92：最高一层板顶 + 一个净空\r\n\r\n    // ───────────────────────── 横向比例 ─────────────────────────\r\n\r\n    /// 左右内壁之间的净宽（去掉两侧壁厚）。24 m 的外宽 ⇒ 23.4 m 可摆东西。\r\n    internal const float InnerW = XMax - XMin - WallT * 2f;\r\n\r\n    /// 横向比例换算：0 = 左内壁，1 = 右内壁。\r\n    ///\r\n    /// **掩体、奶酪点、商品堆头全部用它写**，不再写世界 x。\r\n    /// 原来这些位置是 45.5 / 47.0 / 63.5 这样的字面量，一改宽度就得逐个手算，\r\n    /// 漏掉一个的后果分别是\"掩体穿进墙里\"\"奶酪落在楼梯上\"\"商品浮在墙外\" ——\r\n    /// 三种都不会报错，只会在画面里慢慢露出来。\r\n    internal static float Px(float f) { return XMin + WallT + f * InnerW; }\r\n\r\n    // ───────────────────────── 楼梯 ─────────────────────────\r\n    //\r\n    // 层高 0.56 = 4 级 × 0.14；每层前沿往里缩 1.2 = 4 级 × 0.30。\r\n    // 这两个等式是**绑死**的：改层高就得改踏步数或踏步高，改缩进就得改踏面宽，\r\n    // 否则最后一级台阶接不上上一层板的边缘，中间会留一条能掉下去的缝。\r\n    internal const int   StepsPerLayer = 4;\r\n    internal const float StepRise = 0.14f;\r\n    internal const float StepRun  = 0.30f;\r\n    internal const float Recede    = 1.2f;           // = StepsPerLayer * StepRun\r\n\r\n    /// 楼梯宽度。居中的 8 m（24 m 宽的 1/3）—— 出生点正对，走两步就撞上，不存在\"找不到路\"。\r\n    /// 不能整宽：整宽的楼梯就是每层房间门口的一堵墙。\r\n    internal const float StairX0 = 51f, StairX1 = 59f;\r\n\r\n    /// 第 n 层（1 起）的板顶高度。n=1 ⇒ 0.56\r\n    internal static float Top(int n) { return LayerH * n; }\r\n\r\n    /// 从**脚底高度**反推\"第几层\"：1 = 底层地板，`Layers + 1` = 最顶层（7）。\r\n    ///\r\n    /// HUD 的 \"SHELF n\" 和定位器方块里的数字**必须共用这一个函数**。\r\n    /// 两处各写一份的话必然会在楼梯上打架（一个取整、一个 floor，差一级），\r\n    /// 玩家看到\"HUD 说 3 层、地图说 4 层\"只会以为定位器坏了。\r\n    /// 用 Round 而不是 Floor：0.56 的整数倍在 float 里常常是 0.5599999，\r\n    /// floor 会把它算成下一层。\r\n    internal static int ShelfOf(float y)\r\n    {\r\n        if (y <= 0f) return 1;\r\n        return Mathf.Clamp(Mathf.RoundToInt(y / LayerH) + 1, 1, Layers + 1);\r\n    }\r\n\r\n    /// 第 n 层（1 起）的板前沿 z。**往里缩 1.2 m / 层** —— 见文件头。\r\n    internal static float FrontZ(int n) { return ZMax - (4.5f + (n - 1) * Recede); }\r\n\r\n    /// 第 n 层**能自由走动**的最前沿 z（再往前就是通往上一层的楼梯，或者顶层的外沿）。\r\n    /// 摆掩体、摆装饰都用它来夹范围 —— 写死数字会在改了 Recede 之后全部错位。\r\n    internal static float FlatFrontZ(int n) { return FrontZ(Mathf.Min(n + 1, Layers)); }\r\n\r\n    // 常用高度，写成 const 是为了在 Spots 里能直接当字面量用\r\n    const float Y1 = LayerH, Y2 = LayerH * 2, Y3 = LayerH * 3, Y4 = LayerH * 4, Y5 = LayerH * 5,\r\n                Y6 = LayerH * 6;\r\n\r\n    // 出生点在门内侧的底层地面上，朝里（−z）。一进来就看见六层板一层层退进去。\r\n    internal static readonly Vector3 Start = new Vector3(CX, 0.02f, -1.8f);\r\n    internal static readonly Vector3 Forward = new Vector3(0f, 0f, -1f);\r\n\r\n    // ───────────────────────── 调色板 ─────────────────────────\r\n    // 冰箱内部是\"冷白塑料 + 淡蓝光\"，所有颜色都比真实世界低一档饱和，\r\n    // 否则在冷藏灯下会糊成一片白。\r\n\r\n    static readonly Color ShellCol = new Color(0.66f, 0.68f, 0.70f);  // 内壁\r\n    static readonly Color ShellD  = new Color(0.44f, 0.46f, 0.49f);   // 内壁阴影侧 / 后壁\r\n    static readonly Color Shelf   = new Color(0.74f, 0.77f, 0.79f);   // 搁板（半透明的错觉靠亮）\r\n    static readonly Color ShelfE  = new Color(0.52f, 0.56f, 0.60f);   // 搁板前沿卷边\r\n    static readonly Color Trim    = new Color(0.30f, 0.33f, 0.36f);\r\n    static readonly Color DoorCol = new Color(0.78f, 0.80f, 0.81f);\r\n    static readonly Color DoorIn  = new Color(0.62f, 0.65f, 0.67f);\r\n    static readonly Color Lamp    = new Color(0.86f, 0.94f, 1.00f);\r\n    static readonly Color Crate   = new Color(0.36f, 0.40f, 0.44f);\r\n    static readonly Color Carton  = new Color(0.80f, 0.80f, 0.76f);\r\n    static readonly Color CartonB = new Color(0.14f, 0.24f, 0.42f);\r\n    static readonly Color Melon   = new Color(0.16f, 0.32f, 0.15f);\r\n    static readonly Color MelonL  = new Color(0.22f, 0.40f, 0.18f);\r\n    static readonly Color Bread   = new Color(0.44f, 0.29f, 0.14f);\r\n    static readonly Color Butter  = new Color(0.84f, 0.76f, 0.42f);\r\n    static readonly Color StepCol = new Color(0.58f, 0.62f, 0.66f);   // 台阶侧面（比板暗一档，才有体积感）\r\n    static readonly Color StepEdge= new Color(0.40f, 0.76f, 0.92f);   // 踏面前沿的冷蓝亮线\r\n\r\n    // ───────────────────────── 12 个食物点 ─────────────────────────\r\n    //\r\n    // **顺序 = 出场顺序 = 由低到高。** 第 n 关取前 Cheese 个点，所以：\r\n    //   第 1 关两块在底层（家门口，先学会看门的节奏）\r\n    //   第 3 关第一次要爬楼梯上到第 1 层（4 块：底 2 + L1 2）\r\n    //   第 10 关 12 块铺满六层，一路爬到顶层\r\n    // 改顺序 = 难度曲线倒过来，而且第 1 关会变成\"先爬三层\"。\r\n    //\r\n    // 每个点的 y 是该层**板顶**，SpawnCheese 对冰箱场景不做贴地（见 UsesDoor 分支）——\r\n    // 贴地会把所有点压回 y=0，六层全塌成一层。\r\n    //\r\n    // x 一律写成 Px(比例)。比例取自\"收窄前\"的位置（原净宽 29.4 m），\r\n    // 所以 24 m 之后这 12 个点的**相对站位完全不变**，只是整体压紧了一点。\r\n\r\n    internal static readonly Vector3[] Spots =\r\n    {\r\n        new Vector3(Px(0.398f), 0f,  -6f),    // 底层 · 近\r\n        new Vector3(Px(0.704f), 0f, -13f),    // 底层 · 远\r\n        new Vector3(Px(0.330f), Y1,  -7f),    // L1\r\n        new Vector3(Px(0.772f), Y1, -12f),    // L1\r\n        new Vector3(Px(0.670f), Y2,  -9f),    // L2\r\n        new Vector3(Px(0.228f), Y2, -12f),    // L2\r\n        new Vector3(Px(0.500f), Y3, -15f),    // L3\r\n        new Vector3(Px(0.806f), Y3, -13f),    // L3\r\n        new Vector3(Px(0.330f), Y4, -16f),    // L4\r\n        new Vector3(Px(0.704f), Y4, -18f),    // L4\r\n        new Vector3(Px(0.534f), Y5, -13f),    // L5\r\n        new Vector3(Px(0.300f), Y6, -15f),    // L6 · 顶层（楼梯直通到这里，最后一关才用得上）\r\n    };\r\n\r\n    // 这一关没有猫：威胁只有门。NbScene.Routes 留空，SpawnCats 会摆 0 只。\r\n    internal static readonly Vector3[][] NoRoutes = new Vector3[0][];\r\n\r\n    // ───────────────────────── 写进当前场景 ─────────────────────────\r\n\r\n    internal static void Setup()\r\n    {\r\n        NbScene.Name  = \"INSIDE THE FRIDGE\";\r\n        NbScene.Code  = \"FRIDGE\";\r\n        NbScene.Blurb = \"Six shelves.  One door.  Nowhere to stand in the light.\";\r\n\r\n        NbScene.XMin = XMin;\r\n        NbScene.XMax = XMax;\r\n        NbScene.ZMin = ZMin;\r\n        NbScene.ZMax = ZMax;\r\n\r\n        NbScene.Start   = Start;\r\n        NbScene.Forward = Forward;\r\n        NbScene.Targets = Spots;\r\n        NbScene.Routes  = NoRoutes;\r\n        NbScene.MaxTargets = Spots.Length;\r\n        NbScene.MaxRoutes  = 0;\r\n    }\r\n\r\n    // ───────────────────────── 搭场景 ─────────────────────────\r\n\r\n    internal static Transform DoorHinge;\r\n    internal static Light DoorLight;\r\n\r\n    internal static void Build(Transform p)\r\n    {\r\n        Shell(p);\r\n        Shelves(p);\r\n        Covers(p);\r\n        Door(p);\r\n        Outside(p);\r\n\r\n        Debug.LogFormat(\"[Nb] 冰箱就位：{0:F0} × {1:F0} m，{2} 层板（层高 {3:F2}，净空 {4:F2}）；\" +\r\n                        \"楼梯 {5} 级（每级 {6:F2} 高 / {7:F2} 深，宽 {8:F0} m，居中）；{9} 个奶酪点、0 只猫。\",\r\n            XMax - XMin, ZMax - ZMin, Layers, LayerH, LayerH - Slab,\r\n            StepsPerLayer * Layers, StepRise, StepRun, StairX1 - StairX0, Spots.Length);\r\n    }\r\n\r\n    /// 内壁：底、顶、两侧、后壁。**全部实体**（玩家撞得着、门光也被它们收住）。\r\n    static void Shell(Transform p)\r\n    {\r\n        // 底板：顶面正好 y = 0，玩家出生就站在上面\r\n        Nb.Box(p, \"Fridge Floor\", new Vector3(CX, -WallT * 0.5f, CZ),\r\n            new Vector3(XMax - XMin, WallT, ZMax - ZMin), ShellD, true);\r\n\r\n        Nb.Box(p, \"Fridge Ceiling\", new Vector3(CX, CeilY + WallT * 0.5f, CZ),\r\n            new Vector3(XMax - XMin, WallT, ZMax - ZMin), ShellCol, true);\r\n\r\n        Nb.Box(p, \"Fridge Wall W\", new Vector3(XMin + WallT * 0.5f, CeilY * 0.5f, CZ),\r\n            new Vector3(WallT, CeilY, ZMax - ZMin), ShellCol, true);\r\n        Nb.Box(p, \"Fridge Wall E\", new Vector3(XMax - WallT * 0.5f, CeilY * 0.5f, CZ),\r\n            new Vector3(WallT, CeilY, ZMax - ZMin), ShellCol, true);\r\n        Nb.Box(p, \"Fridge Wall N\", new Vector3(CX, CeilY * 0.5f, ZMin + WallT * 0.5f),\r\n            new Vector3(XMax - XMin, CeilY, WallT), ShellD, true);\r\n\r\n        // 后壁的竖条纹：冰箱内胆的压花。纯视觉，加碰撞体没意义（后壁已经挡着了）。\r\n        for (int i = 0; i < 11; i++)\r\n        {\r\n            float x = XMin + 2.6f + i * 2.5f;\r\n            Nb.Box(p, \"Rib \" + i, new Vector3(x, CeilY * 0.5f, ZMin + WallT + 0.02f),\r\n                new Vector3(0.16f, CeilY - 0.5f, 0.04f), ShellCol, false);\r\n        }\r\n    }\r\n\r\n    /// 六层搁板。每层一块实体薄板 —— 它同时是地板、天花板和\"光的遮挡\"。\r\n    /// 每层前沿往里缩 1.2 m，缩出来的那一条就是**通往上一层的楼梯所占的坑位**（见 Stairs）。\r\n    static void Shelves(Transform p)\r\n    {\r\n        for (int n = 1; n <= Layers; n++)\r\n        {\r\n            float front = FrontZ(n);\r\n            float z0 = ZMin + WallT;\r\n            float depth = front - z0;\r\n            if (depth <= 1.0f) continue;      // 前沿退到头了就不要再放板\r\n\r\n            float y = Top(n);\r\n\r\n            Nb.Box(p, \"Shelf L\" + n, new Vector3(CX, y - Slab * 0.5f, z0 + depth * 0.5f),\r\n                new Vector3(XMax - XMin - WallT * 2f, Slab, depth), Shelf, true);\r\n\r\n            // 前沿卷边：比板稍微高一点点，是玩家用眼睛判断\"这里到边了\"的唯一参照。\r\n            // **楼梯那 8 m 要断开** —— 不断的话，最上面一级台阶的落点正好被一条\r\n            // 3.6 cm 的坎挡住，走上去会顿一下（0.14 的踏步配一条 0.036 的坎，很难解释）。\r\n            float wl = StairX0 - (XMin + WallT);\r\n            if (wl > 0.2f)\r\n                Nb.Box(p, \"Shelf Lip L\" + n + \" W\", new Vector3(XMin + WallT + wl * 0.5f, y + 0.018f, front - 0.05f),\r\n                    new Vector3(wl, 0.036f, 0.10f), ShelfE, false);\r\n            float wr = (XMax - WallT) - StairX1;\r\n            if (wr > 0.2f)\r\n                Nb.Box(p, \"Shelf Lip L\" + n + \" E\", new Vector3(StairX1 + wr * 0.5f, y + 0.018f, front - 0.05f),\r\n                    new Vector3(wr, 0.036f, 0.10f), ShelfE, false);\r\n\r\n            // 板下的一根加强筋：低头看这块板时，它给出\"我在板下面\"的明确证据\r\n            Nb.Box(p, \"Shelf Rib L\" + n, new Vector3(CX, y - Slab - 0.03f, z0 + depth * 0.5f),\r\n                new Vector3(XMax - XMin - WallT * 2.6f, 0.05f, 0.22f), ShelfE, false);\r\n        }\r\n\r\n        Stairs(p);\r\n\r\n        // 每层的灯带（自发光，只负责视觉；真正照度来自 NbLighting 的平行光）。\r\n        // 从\"前沿−1.2\"挪进房间：那个位置现在是楼梯，灯管会横在台阶上方。\r\n        for (int n = 1; n <= Layers; n++)\r\n        {\r\n            float y = Top(n) - 0.09f;\r\n            Nb.Box(p, \"Fridge Lamp L\" + n, new Vector3(CX, y, FlatFrontZ(n) - 0.90f),\r\n                new Vector3(XMax - XMin - WallT * 2f - 1.5f, 0.05f, 0.16f), Lamp, false);\r\n        }\r\n    }\r\n\r\n    /// 从地面一直到顶层的一段楼梯（每层 4 级）。\r\n    ///\r\n    /// 位置由两个量决定：第 n 层通往 n+1 层的那一段，占 z ∈ [FrontZ(n+1), FrontZ(n+1)+1.2]。\r\n    /// 也就是\"上一层板往里缩出来的那条坑\" —— 那里的头顶是空的，所以站得下人；\r\n    /// 而台阶的最深一级，板顶正好等于上一层的板顶，接缝在 FrontZ(n+1) 处对齐。\r\n    ///\r\n    /// 每一级都是一块**落到本层地面**的实体方块（不是架空的一片板）：\r\n    /// 架空的话走上去会看见台阶侧面一条缝，而且缝里能看见下一层。\r\n    static void Stairs(Transform p)\r\n    {\r\n        float w = StairX1 - StairX0;\r\n\r\n        for (int n = 0; n < Layers; n++)          // n = 起点所在层（0 = 地面）\r\n        {\r\n            float y0 = Top(n);\r\n            float zEnd = FrontZ(n + 1);          // 最深一级的位置，正好接上一层板边\r\n\r\n            for (int k = 1; k <= StepsPerLayer; k++)\r\n            {\r\n                float top = y0 + k * StepRise;\r\n                float z0 = zEnd + (StepsPerLayer - k) * StepRun;   // 这一级的近边\r\n                float cz = z0 + StepRun * 0.5f;\r\n\r\n                Nb.Box(p, \"Step L\" + (n + 1) + \".\" + k,\r\n                    new Vector3((StairX0 + StairX1) * 0.5f, (y0 + top) * 0.5f, cz),\r\n                    new Vector3(w, top - y0, StepRun), StepCol, true);\r\n\r\n                // 踏面前沿的一道亮线：24 级台阶排成一条斜线，从下往上看就是一条\"路\"。\r\n                // 没有它，六层灰板在冷光下会糊成一堵墙。\r\n                Nb.Box(p, \"Step Edge L\" + (n + 1) + \".\" + k,\r\n                    new Vector3((StairX0 + StairX1) * 0.5f, top + 0.006f, z0 + StepRun - 0.045f),\r\n                    new Vector3(w, 0.012f, 0.09f), StepEdge, false);\r\n            }\r\n        }\r\n    }\r\n\r\n    /// 掩体。**每层六个**：房间里四个（位置错开、高 0.40~0.50 m）+ 前沿一对（见下）。\r\n    /// 高度上限 0.50 是硬的：层内净空只有 0.51，再高就会插进上一层板里，\r\n    /// 玩家会看到一块西瓜从地板里穿出来 —— 而且它顶住板之后，玩家会被挤在缝里。\r\n    static void Covers(Transform p)\r\n    {\r\n        // n 从 0 起：**地面层也要有掩体**。开局玩家就站在门里，如果脚下这一层\r\n        // 一个能躲的东西都没有，门第一次开的时候他连\"该往哪跑\"都没有答案 ——\r\n        // 只能往上爬一层，而 3 秒不够。地面层的掩体摆在货架底下（z ≤ −6.5），\r\n        // 于是\"钻到板子底下\"这件事本身也成了躲法。\r\n        for (int n = 0; n <= Layers; n++)\r\n        {\r\n            float y = Top(n);\r\n\r\n            // 6 个掩体按**这一层实际可用的进深**铺成 3 排 × 2 列，不写死 z。\r\n            //\r\n            // 楼层越高房间越浅（FrontZ 每层退 1.2 m）：地面层可用 10.8 m，\r\n            // 到第 5/6 层只剩 4.8 m。写死 z 的话最后两层会有掩体叠在一起，\r\n            // 叠起来的东西既挡路又不好看 —— 而且两个正好同高的方块还会共面闪。\r\n            float zMin = ZMin + WallT + 2.4f;        // 后壁留 2.4 m 给商品货架\r\n            float zMax = FlatFrontZ(n) - 2.0f;       // 前沿留 2 m 给楼梯\r\n            if (zMax - zMin < 1.0f) continue;\r\n            float d = zMax - zMin;\r\n\r\n            // 最后那排贴着 zMax：玩家从楼梯落地在 FrontZ(n)+0.15，\r\n            // 走到这一排约 3.2 m（≈1.4 s），是\"听到预警还来得及\"的量级。\r\n            // 原来最近的掩体在 5 m 开外，预警 3 s 一响就只剩挨打。\r\n            //\r\n            // x 写成净宽的比例（Px），跟奶酪点同一套坐标 —— 这样\"掩体是否压住奶酪\"\r\n            // 在任何宽度下都只是同一组数字的比较，不会因为改了 XMin/XMax 而失效。\r\n            CoverAt(p, n, y, Px(0.177f), zMin + d * 0.12f, 0);\r\n            CoverAt(p, n, y, Px(0.891f), zMin + d * 0.12f, 3);\r\n            CoverAt(p, n, y, Px(0.449f), zMin + d * 0.50f, 1);\r\n            CoverAt(p, n, y, Px(0.228f), zMin + d * 0.50f, 2);\r\n            CoverAt(p, n, y, Px(0.755f), zMin + d * 0.88f, 2);\r\n            CoverAt(p, n, y, Px(0.228f), zMin + d * 0.88f, 0);\r\n        }\r\n    }\r\n\r\n    static void CoverAt(Transform p, int layer, float y, float x, float z, int variant)\r\n    {\r\n        // 夹进这一层的**房间**范围：后壁那头要给商品货架留 2.4 m，前沿那头要避开楼梯 2 m。\r\n        // 写死数字的话，改了 Recede / LayerH 之后掩体会跑到台阶上去（那样它会变成一个\r\n        // 谁都能站的观景台，而门光从它头顶越过 —— 这一关就废了）。\r\n        float zMin = ZMin + WallT + 2.4f;\r\n        float zMax = FlatFrontZ(layer) - 2.0f;\r\n        if (zMax - zMin < 1.0f) return;\r\n        z = Mathf.Clamp(z, zMin, zMax);\r\n\r\n        string n = \"Cover L\" + layer + \".\" + variant;\r\n\r\n        switch (variant)\r\n        {\r\n            case 0:   // 牛奶箱：三只纸盒并排，最经典的可躲物\r\n                for (int i = 0; i < 3; i++)\r\n                    Nb.Box(p, n + \" carton \" + i,\r\n                        new Vector3(x + (i - 1) * 0.52f, y + 0.24f, z),\r\n                        new Vector3(0.46f, 0.48f, 0.42f), Carton, true);\r\n                Nb.Box(p, n + \" band\", new Vector3(x, y + 0.10f, z + 0.215f),\r\n                    new Vector3(1.60f, 0.10f, 0.02f), CartonB, false);\r\n                break;\r\n\r\n            case 1:   // 西瓜：圆的，绕过去要跑半圈 —— 是四样里最好用的\r\n                Nb.Ball(p, n + \" melon\", new Vector3(x, y + 0.24f, z), 0.50f, Melon, true);\r\n                Nb.Ball(p, n + \" stripe\", new Vector3(x, y + 0.24f, z), 0.515f, MelonL, false);\r\n                break;\r\n\r\n            case 2:   // 面包箱：长条，能一次挡住两个人宽的光\r\n                Nb.Box(p, n + \" box\", new Vector3(x, y + 0.22f, z),\r\n                    new Vector3(1.35f, 0.44f, 0.55f), Bread, true);\r\n                Nb.Box(p, n + \" lid\", new Vector3(x, y + 0.45f, z),\r\n                    new Vector3(1.42f, 0.05f, 0.60f), new Color(0.30f, 0.19f, 0.09f), false);\r\n                break;\r\n\r\n            default:  // 黄油块：低一些（0.40），但宽\r\n                Nb.Box(p, n + \" butter\", new Vector3(x, y + 0.20f, z),\r\n                    new Vector3(1.10f, 0.40f, 0.80f), Butter, true);\r\n                Nb.Box(p, n + \" wrap\", new Vector3(x, y + 0.405f, z),\r\n                    new Vector3(1.14f, 0.02f, 0.84f), new Color(0.70f, 0.64f, 0.36f), false);\r\n                break;\r\n        }\r\n    }\r\n\r\n    /// 门：绕左侧铰链向外开 105°。板高到顶、宽到两侧，关着的时候就是一面墙。\r\n    static void Door(Transform p)\r\n    {\r\n        float w = XMax - XMin - WallT * 2f;\r\n\r\n        GameObject hinge = new GameObject(\"Fridge Door Hinge\");\r\n        hinge.transform.SetParent(p, false);\r\n        hinge.transform.position = new Vector3(XMin + WallT, 0f, ZMax - 0.07f);\r\n        hinge.transform.rotation = Quaternion.identity;\r\n        DoorHinge = hinge.transform;\r\n\r\n        // 门板挂在铰链的 +x 方向：旋转铰链 = 整块门绕左边缘转\r\n        Nb.Box(hinge.transform, \"Door Panel\", new Vector3(w * 0.5f, CeilY * 0.5f, 0f),\r\n            new Vector3(w, CeilY, 0.14f), DoorCol, true);\r\n        Nb.Box(hinge.transform, \"Door Inner\", new Vector3(w * 0.5f, CeilY * 0.5f, -0.09f),\r\n            new Vector3(w - 0.30f, CeilY - 0.30f, 0.04f), DoorIn, false);\r\n        // 门内侧的两道横档（搁物架）：冰箱门的经典结构，也给\"门开着\"多一个可读的形状\r\n        for (int i = 0; i < 2; i++)\r\n        {\r\n            float y = 1.10f + i * 1.30f;\r\n            Nb.Box(hinge.transform, \"Door Shelf \" + i, new Vector3(w * 0.5f, y, -0.24f),\r\n                new Vector3(w - 0.50f, 0.06f, 0.30f), DoorIn, false);\r\n            Nb.Box(hinge.transform, \"Door Shelf Lip \" + i, new Vector3(w * 0.5f, y + 0.09f, -0.38f),\r\n                new Vector3(w - 0.50f, 0.12f, 0.04f), DoorCol, false);\r\n        }\r\n\r\n        // 关门时门口那一圈密封条：玩家低头能看见自己站在门内侧\r\n        Nb.Box(p, \"Fridge Gasket W\", new Vector3(XMin + WallT * 0.5f, CeilY * 0.5f, ZMax - 0.16f),\r\n            new Vector3(WallT, CeilY, 0.08f), Trim, false);\r\n        Nb.Box(p, \"Fridge Gasket E\", new Vector3(XMax - WallT * 0.5f, CeilY * 0.5f, ZMax - 0.16f),\r\n            new Vector3(WallT, CeilY, 0.08f), Trim, false);\r\n    }\r\n\r\n    /// 门外：一小块地面 + 三面墙。\r\n    /// 为什么需要它：门打开时如果外面是虚空，玩家会看到\"冰箱浮在黑色里\"，一眼出戏。\r\n    /// 三面墙同时保证玩家不会在门开着的那两秒跑远（跑出去就回不来了）。\r\n    static void Outside(Transform p)\r\n    {\r\n        float d = 7f, w = XMax - XMin + 4f;\r\n        Nb.Box(p, \"Kitchen Floor\", new Vector3(CX, -0.16f, ZMax + d * 0.5f),\r\n            new Vector3(w, 0.30f, d), new Color(0.30f, 0.29f, 0.27f), true);\r\n        Nb.Box(p, \"Kitchen Wall W\", new Vector3(XMin - 2f, 2.2f, ZMax + d * 0.5f),\r\n            new Vector3(0.4f, 4.4f, d), new Color(0.20f, 0.19f, 0.18f), true);\r\n        Nb.Box(p, \"Kitchen Wall E\", new Vector3(XMax + 2f, 2.2f, ZMax + d * 0.5f),\r\n            new Vector3(0.4f, 4.4f, d), new Color(0.20f, 0.19f, 0.18f), true);\r\n        Nb.Box(p, \"Kitchen Wall S\", new Vector3(CX, 2.2f, ZMax + d),\r\n            new Vector3(w, 4.4f, 0.4f), new Color(0.20f, 0.19f, 0.18f), true);\r\n    }\r\n\r\n    // ───────────────────────── 门光 ─────────────────────────\r\n\r\n    /// **必须在 NbLighting.Apply 之后调用。**\r\n    /// Apply 会把场上最亮的平行光当主光、其余全部强度归零并 disabled；\r\n    /// 这盏门灯平时 intensity = 0，如果它先于 Apply 存在，排序就会把它当成\"无关的平行光\"关掉，\r\n    /// 之后 SetDoor 再把 intensity 抬起来也不会亮（enabled 已经是 false）。\r\n    internal static void CreateDoorLight(Transform root)\r\n    {\r\n        GameObject go = new GameObject(\"Fridge Door Light (auto)\");\r\n        go.transform.SetParent(root, false);\r\n        go.transform.position = new Vector3(CX, CeilY * 0.5f, ZMax + 5f);\r\n        // 从门口朝里、带 28° 俯角：光会斜着打在每一层板的前沿上，\r\n        // 于是\"门开了\"在画面上表现为**一排从门口往深处推的亮边**，一眼就懂。\r\n        go.transform.rotation = Quaternion.Euler(28f, 180f, 0f);\r\n\r\n        Light l = go.AddComponent<Light>();\r\n        l.type = LightType.Directional;\r\n        l.color = new Color(1.00f, 0.95f, 0.82f);\r\n        l.intensity = 0f;\r\n        l.shadows = LightShadows.None;      // 不开阴影：薄板 + 无贴图，开阴影只会出现条纹\r\n        l.enabled = false;\r\n        DoorLight = l;\r\n    }\r\n\r\n    static readonly Color AmbClosed = new Color(0.052f, 0.058f, 0.072f);\r\n    static readonly Color AmbOpen   = new Color(0.200f, 0.195f, 0.180f);\r\n\r\n    /// 门全开时的平行光强度。**不要往上调**：内壁是 0.66 的浅灰，\r\n    /// 2.6 会把整屏推到纯白 —— 那一刻玩家最需要的恰恰是\"看清自己站在哪\"，\r\n    /// 而不是\"被闪光弹打了一下\"。1.9 足够亮到认路，又还留着颜色。\r\n    const float DoorLightMax = 1.9f;\r\n\r\n    /// 开门程度：0 = 关，1 = 全开。门板角度、门光强度、环境光一起插值 ——\r\n    /// 三样必须同一条曲线，只改其中一样就会出现\"门还在关着但已经满屏白光\"。\r\n    internal static void SetDoor(float f)\r\n    {\r\n        f = Mathf.Clamp01(f);\r\n\r\n        if (DoorHinge != null)\r\n            DoorHinge.localRotation = Quaternion.Euler(0f, -105f * f, 0f);\r\n\r\n        if (DoorLight != null)\r\n        {\r\n            float want = DoorLightMax * f;\r\n            DoorLight.intensity = want;\r\n            bool on = want > 0.02f;\r\n            if (DoorLight.enabled != on) DoorLight.enabled = on;\r\n        }\r\n\r\n        RenderSettings.ambientLight = Color.Lerp(AmbClosed, AmbOpen, f);\r\n    }\r\n}\r\n"},"NbGuard":{"path":"Assets/Scripts/NbGuard.cs","role":"Yard night guard: random patrol, sweeping flashlight cone, chases and catches the mouse.","source":"// @role Yard night guard: random patrol, sweeping flashlight cone, chases and catches the mouse.\r\n// @calls NbGame NbGuardArt AudioManager\r\n// @tune Speed:float:0.3-3:patrol walk speed m/s\r\n// @tune Sweep:float:0.1-3:flashlight sweep pace (higher = faster)\r\n// @tune Range:float:5-40:flashlight beam range m\r\n// @tune Half:float:2-45:beam cone half-angle deg\r\n// @tune Damage:float:1-100:exposure gained per second in the beam\r\n// @tune ChaseSpeed:float:1-6:chase speed m/s (below player run)\r\n\r\n// NbGuard.cs — 夜巡保安（后院专属威胁）\r\n//\r\n// 设计意图（来自参考里的两条）：\r\n//   \"Nighttime human patrol: Humans move slowly at night, but their observation skills\r\n//    are heightened. Light will reveal your position.\"\r\n//   \"Light: lit areas eliminate player after fixed amount of time → avoid light\"\r\n//\r\n// 这一版把「光」从\"慢慢烧血的条\"改成了**一个会扑过来的人**：\r\n//   ① 平时 0.95 m/s 在**自己那一带随机游走**（航点 5~16 m、到点站住环顾 1~3 秒），\r\n//      手电 18 m 长、半角 11°，**四处扫**（前方 ±55° 为主、约 1/5 的机会甩到 ±95°，\r\n//      站住时整个人转过去看身后）—— 他在找，不是在追；\r\n//   ② 光扫到玩家的 0.3 秒后，他**抬头**：手电变红、直指玩家，然后以 2.55~3.45 m/s 冲过来\r\n//      （比玩家走路 2.30 快，比跑步 3.91 慢 —— 所以\"按 Shift\"是唯一的解，而不是可选项）；\r\n//   ③ 玩家躲到掩体后面，光被挡住 ⇒ 他会走到\"最后看见你的地方\"；\r\n//   ④ **只有跑到 5 m 之外的掩体后**才算脱身。躲在 2 m 的灌木后面，他会径直走过来，\r\n//      1 m 之内就算被抓住（-10 血），因为他的判定是\"身体碰到\"而不是\"看见\"。\r\n//\r\n// 巡逻为什么不是固定直线（用户明确要求「按不规则路线运动」）：\r\n//   固定直线有两个问题 —— 玩家站两次就能背下来，以及\"他什么时候背对我\"变成了时钟。\r\n//   现在每段路都是**当场抽的**：在自己那条路线两侧 ±7 m 的带子里随机取点，\r\n//   长度 5~16 m 之间、走的时候还带一点横向摆动，到点停 1~3 秒、整个人转过去照别处。\r\n//   于是\"他背对着我\"仍然会出现，但**不能靠数秒数等到**，只能当场看灯。\r\n//   底子还是关卡表里的那 4 条路线：抽点只在带子里抽，所以几个人不会挤到同一个角落。\r\n//\r\n// 判定用几何而不是 Light 组件：\r\n//   ① 距离 ≤ Range\r\n//   ② 与手电朝向夹角 ≤ Half\r\n//   ③ 从灯到玩家的射线**没有被掩体挡住**\r\n// 三条同时成立才算\"看见\"。第 ③ 条是整个后院玩法的支点 ——\r\n// 灌木、垃圾桶、柴垛、工具棚都是实体碰撞体，就是为了让这一条能成立。\r\n// 注意：灯挂在手上（约 1.0~1.4 m 高）且**俯仰会在 −24°~+6° 之间扫**，\r\n// 所以压低时远处脚下是暗的、贴到 4 m 以内反而照不到。这不是 bug：\r\n// 近身时的威胁是\"他撞上你\"，而不是\"他看见你\"。\r\n//\r\n// 曝光值的累积在 NbGame 里（因为要跨多个保安求和 + 和血量/HUD 一起结算），\r\n// 这里只负责回答两个问题：**这一帧我有没有看见他**、**我是不是在追他**。\r\n//\r\n// 外观：Resources/Guards/Walking（Mixamo 真人 + 原地走路动画），见 NbGuardArt.cs。\r\n// 模型只是**外观** —— 手电、判定、巡逻全都挂在保安根节点上，换模型动不到玩法；\r\n// 自动加载失败时退回几何体，两条路的身高一致（1.80 m），所以手感也不会变。\r\n\r\nusing UnityEngine;\r\n\r\ninternal class NbGuard : MonoBehaviour\r\n{\r\n    /// 关卡表里的那条路线。现在**不再被逐点走**，只用来定义这个人的\"地盘\"：\r\n    /// 航点在这条线段两侧 ±ZonePad 的带子里抽。见 PickWaypoint。\r\n    internal Vector3[] Route;\r\n\r\n    // ── 巡逻 ──\r\n    internal float Speed = 0.95f;       // m/s，比玩家走路（2.30）慢一半多\r\n    internal float Sweep = 0.55f;       // 扫灯节奏：数值越大转得越快、停得越短（关卡表 Sweep 列）\r\n    internal float Range = 18f;         // 手电射程\r\n    internal float Half = 11f;          // 光锥半角（度）\r\n    internal float Damage = 25f;        // 每秒累积多少曝光（满 100 被抓）\r\n\r\n    // ── 不规则游走 ──\r\n    /// 巡逻区半宽：航点在这条路线两侧各 ZonePad 米之内抽。\r\n    /// 7 m 大约是\"他站在路线上，往两边各走七八步\"的范围 ——\r\n    /// 再宽几个人就会互相穿场，那 4 条路线就等于没设。\r\n    internal const float ZonePad = 7f;\r\n\r\n    /// 一段路的最短 / 最长距离。太短会变成原地抖动，太长看起来像在赶路。\r\n    internal const float LegMin = 5f;\r\n    internal const float LegMax = 16f;\r\n\r\n    /// 离墙 / 离院子的边留多少。保安没有碰撞体，全靠这个数不让他走进砖墙里。\r\n    internal const float WallInset = 2.2f;\r\n\r\n    /// 出生点周围不让巡逻。Sense() 里本来就豁免了 6 m 安全区，\r\n    /// 但如果他就站在那儿扫灯，玩家看到的是\"我在光里怎么没事\" —— 那是自相矛盾的画面。\r\n    internal const float HomeClear = 8f;\r\n\r\n    // ── 被照到之后 ──\r\n    /// 追人速度。由 NbGame 按关卡从 2.55 拉到 3.45 —— **上限永远低于玩家跑步 3.91**，\r\n    /// 所以\"按住 Shift 一定跑得掉\"这条承诺在这一关同样成立。\r\n    internal float ChaseSpeed = 2.9f;\r\n\r\n    /// 被照到之后到起跑之间的迟滞。0.3 秒不是手感调参，是**可读性**：\r\n    /// 玩家需要一个\"他抬头了\"的瞬间，否则只会觉得自己凭空被撞了一下。\r\n    internal const float SpotDelay = 0.30f;\r\n\r\n    /// 脱身距离：光被挡住**并且**离他 ≥5 m 才算甩掉。\r\n    /// 躲得近他会直接走到你藏的那丛灌木前面 —— 这正是玩家必须\"跑起来\"的原因。\r\n    internal const float LoseDist = 5f;\r\n\r\n    /// 找不到人之后最多在附近搜多久。没有这一条，玩家躲进 5 m 内的掩体后\r\n    /// 会被永久钉在原地（他永远不走，你也永远不敢动）。\r\n    internal const float AlertHold = 6f;\r\n\r\n    /// 多近算被抓住。保安没有碰撞体（1.2 m 的走道要能从身边挤过去），\r\n    /// 所以\"撞上\"只能靠距离判定；这个数约等于一个身位。\r\n    internal const float CatchDist = 1.05f;\r\n\r\n    /// 站住环顾时整个人转过来的角速度（度/秒）。55°/s 左右是\"一个在张望的人\"，\r\n    /// 快了像在抽搐，慢了玩家会以为他卡住了。\r\n    internal const float LookTurnSpeed = 70f;\r\n\r\n    Transform _lamp;\r\n    Light _lampLight;\r\n    Transform _player;\r\n\r\n    /// 模型右手。有它就跟着手走（看起来是\"拿着\"），没有就退回固定位置。\r\n    Transform _hand;\r\n    Vector3 _lampLocal;        // 手电在保安根节点下的位置（每帧平滑跟随手掌）\r\n    NbGuardModel _model;       // 走路动画的播放器（追人时要加速，不然腿在原地慢走）\r\n\r\n    // ── 游走状态 ──\r\n    Vector3 _laneA, _laneB;    // 地盘的轴线（来自 Route 的首尾点）\r\n    Vector3 _wp;               // 当前航点\r\n    bool _hasWp;\r\n    float _pause;              // 到点后站住多久（这段时间在 LookAround）\r\n    float _lookT;              // 离下一次换\"看的方向\"还有多久\r\n    float _bodyYawWant;        // 站住时想转到哪个朝向（世界 yaw，度）\r\n    float _wobble, _wobbleAmp; // 走路时那条缓弯的相位 / 幅度\r\n    Vector3 _stuckFrom;        // 卡死检测：上一次\"确实挪动了\"的位置\r\n    float _stuckT;\r\n\r\n    // ── 扫灯状态 ──\r\n    float _scanYaw, _scanPitch;             // 当前灯角度（保安本地：yaw 绕 Y、pitch 绕 X）\r\n    float _scanYawWant, _scanPitchWant;     // 目标角\r\n    float _holdT;                           // 在这个方向上停多久\r\n\r\n    float _spotT;              // 本轮被照到的累计时间（到 SpotDelay 起跑）\r\n    float _lostT;              // 连续看不到人的时间\r\n    float _alertT;             // 追击 / 搜索的剩余时间\r\n    bool _chasing;\r\n    Vector3 _lastSeen;\r\n\r\n    internal bool Sees { get; private set; }\r\n    internal bool Chasing { get { return _chasing; } }\r\n    internal float _nextSound = -1;\r\n\r\n    internal Vector3 Eye { get { return _lamp != null ? _lamp.position : transform.position; } }\r\n\r\n    // ───────────────────────── 生成 ─────────────────────────\r\n\r\n    internal static NbGuard Spawn(Transform parent, Vector3[] route, float speed, float sweep,\r\n                                  float damage, float chaseSpeed)\r\n    {\r\n        GameObject go = new GameObject(\"Guard (auto)\");\r\n        go.transform.SetParent(parent, false);\r\n\r\n        Vector3 at = route != null && route.Length > 0 ? route[0] : Vector3.zero;\r\n        go.transform.position = new Vector3(at.x, 0f, at.z);\r\n\r\n        // 身体：优先用 Resources/Guards/Walking 的真人模型（带走路动画）。\r\n        // 读不到就退回旧的\"圆柱 + 头 + 帽子\" —— 这一关的玩法不能被一个资源缺失打断，\r\n        // 而且几何体版本和模型版本**身高一致**（NbGuardArt.Height = 1.80），手电位置和判定都不用变。\r\n        //\r\n        // 两条都不加碰撞体：保安要是能挡住玩家，1.2 m 的走道和后院的灌木间隙会把人卡死；\r\n        // 玩家应该能从他身边挤过去（真正危险的是光，不是他的身体）。\r\n        GameObject model = NbGuardArt.Attach(go.transform);\r\n        if (model == null)\r\n        {\r\n            Color coat = new Color(0.10f, 0.11f, 0.14f);\r\n            Color skin = new Color(0.38f, 0.30f, 0.24f);\r\n            Color cap  = new Color(0.07f, 0.08f, 0.10f);\r\n\r\n            Nb.Cyl(go.transform, \"Coat\", new Vector3(0f, 0.86f, 0f), 0.60f, 1.72f, coat, false);\r\n            Nb.Ball(go.transform, \"Head\", new Vector3(0f, 1.80f, 0f), 0.44f, skin, false);\r\n            Nb.Box(go.transform, \"Cap\", new Vector3(0f, 2.02f, 0f), new Vector3(0.52f, 0.10f, 0.52f), cap, false);\r\n        }\r\n\r\n        // 手电：一个**实体**（握把 + 灯头 + 会发光的镜片 + 一小盏点光），挂在灯泡节点下。\r\n        // 灯泡节点本身是保安的子物体 ⇒ 他转身，光就跟着转；额外的扫动由 Scan() 叠在 localRotation 上。\r\n        //\r\n        // **故意不把手电直接挂到手骨上。** 走路时手臂前后摆，会把 18 m 长的光锥一起甩成一条鞭子，\r\n        // 玩家就读不出\"光扫过去了没有\" —— 而这一关要求他能读出来。\r\n        // 现在的折中在 LateUpdate：**位置**跟着手掌走（看起来是拿在手里），**朝向**由保安控制。\r\n        GameObject lampGo = new GameObject(\"Torch\");\r\n        lampGo.transform.SetParent(go.transform, false);\r\n        lampGo.transform.localPosition = NbGuardArt.TorchLocal;\r\n        lampGo.transform.localRotation = Quaternion.Euler(-8f, 0f, 0f);\r\n\r\n        NbGuardArt.BuildTorch(lampGo.transform);\r\n\r\n        Light l = lampGo.AddComponent<Light>();\r\n        l.type = LightType.Spot;\r\n        l.range = 18f;\r\n        l.spotAngle = 22f;\r\n        l.innerSpotAngle = 12f;\r\n        l.intensity = 7f;\r\n        l.color = new Color(1f, 0.90f, 0.70f);\r\n        l.shadows = LightShadows.None;\r\n        l.renderMode = LightRenderMode.ForcePixel;\r\n\r\n        NbGuard g = go.AddComponent<NbGuard>();\r\n        g.Route = route;\r\n        g.Speed = speed;\r\n        g.Sweep = sweep;\r\n        g.Damage = damage;\r\n        g.ChaseSpeed = chaseSpeed;\r\n        g._lamp = lampGo.transform;\r\n        g._lampLight = l;\r\n        g._lampLocal = lampGo.transform.localPosition;\r\n        g._hand = NbGuardArt.FindHand(model);\r\n        g._model = model != null ? model.GetComponent<NbGuardModel>() : null;\r\n\r\n        // 地盘 = 这条路线的首尾点。少于两个点就退化成\"脚下一小圈\"。\r\n        g._laneA = at;\r\n        g._laneB = route != null && route.Length > 1 ? route[route.Length - 1] : at;\r\n        g._laneA.y = g._laneB.y = 0f;\r\n\r\n        g._wp = go.transform.position;\r\n        g._stuckFrom = go.transform.position;\r\n        g._bodyYawWant = go.transform.eulerAngles.y;\r\n        g._scanYaw = g._scanYawWant = 0f;\r\n        g._scanPitch = g._scanPitchWant = -8f;\r\n        g._holdT = 0.6f;\r\n        g._wobble = Random.Range(0f, 6.283f);\r\n\r\n        // 手在哪儿：模型是归一化过的，所以世界坐标直接换算到保安本地就行。\r\n        // 换算失败（手骨在世界原点之类的怪情况）就保留 TorchLocal，不报错也不影响玩法。\r\n        if (g._hand != null)\r\n        {\r\n            Vector3 hp = go.transform.InverseTransformPoint(g._hand.position);\r\n            if (hp.sqrMagnitude > 0.01f && hp.y > 0.3f) g._lampLocal = hp;\r\n        }\r\n\r\n        return g;\r\n    }\r\n\r\n    // ───────────────────────── 每帧 ─────────────────────────\r\n\r\n    void Update()\r\n    {\r\n        // 过关 / 失败之后所有人停在原地：否则\"已经赢了\"的画面里还有个人在冲你跑过来。\r\n        NbGame game = NbGame.I;\r\n        if (game != null && game.Finished) return;\r\n\r\n        Sense();\r\n        Think();\r\n\r\n        if (_chasing)\r\n        {\r\n            // 跑步的脚步声由 AudioManager 按距离播放（见 AudioManager 的脚步系统），\r\n            // 这里不再单独放一次性音效，否则会和它叠在一起。\r\n            Chase();\r\n        }\r\n        else if (_pause > 0f) LookAround();\r\n        else Walk();\r\n\r\n        // 追人并且还看得见 → 光钉在玩家身上（这是玩家唯一能读出\"他知道我在哪\"的东西）；\r\n        // 其余所有时候都在四处扫 —— 包括追丢了之后的那 6 秒搜索。\r\n        if (_chasing && Sees) Aim();\r\n        else Scan();\r\n\r\n        // 步频跟着速度走：巡逻 1.0×、追人最多 3.5×。不改这一项，\"加速\"只体现在位移上，\r\n        // 腿还在慢悠悠迈 —— 玩家看到的是一个人滑过来，而不是一个人跑过来。\r\n        if (_model != null)\r\n            _model.Rate = _chasing ? Mathf.Clamp(ChaseSpeed / Mathf.Max(0.1f, Speed), 1f, 3.5f) : 1f;\r\n\r\n        Paint();\r\n    }\r\n\r\n    /// 手电的**位置**跟着手掌走（平滑），朝向不跟 —— 见 Spawn 里的注释。\r\n    /// 放在 LateUpdate：走路动画是手动采样的，Update 里读到的还是上一帧的手。\r\n    void LateUpdate()\r\n    {\r\n        if (_lamp == null) return;\r\n\r\n        Vector3 want = _lampLocal;\r\n        if (_hand != null)\r\n        {\r\n            Vector3 p = transform.InverseTransformPoint(_hand.position);\r\n            // 手骨在手腕上；手电的握把是往**后** 0.18 m 的，所以灯头要放在手腕前 0.12 m，\r\n            // 手掌才刚好落在握把上。放 0 的话握把会插进小臂里。\r\n            want = p + transform.InverseTransformDirection(transform.forward * 0.12f);\r\n        }\r\n\r\n        float k = 1f - Mathf.Exp(-12f * Time.deltaTime);\r\n        _lamp.localPosition = Vector3.Lerp(_lamp.localPosition, want, k);\r\n    }\r\n\r\n    // ───────────────────────── 巡逻（不规则游走） ─────────────────────────\r\n\r\n    /// 走向当前航点。**没有固定直线**：航点是当场抽的，路径还带一点横向缓弯。\r\n    /// 避障只靠 Steer（他没有碰撞体），卡住了有 2 秒兜底换点。\r\n    void Walk()\r\n    {\r\n        float dt = Time.deltaTime;\r\n        if (!_hasWp) PickWaypoint();\r\n\r\n        Vector3 p = transform.position;\r\n        Vector3 d = new Vector3(_wp.x - p.x, 0f, _wp.z - p.z);\r\n        float dist = d.magnitude;\r\n\r\n        if (dist < 0.55f) { Arrive(); return; }\r\n\r\n        Vector3 dir = d / dist;\r\n\r\n        // 轻微横摆：把直线走成一条缓弯。幅度很小（≤0.18），终点不变，\r\n        // Steer 仍然接管避障 —— 这条只负责让\"他走的不是轨道\"。\r\n        _wobble += dt * 0.85f;\r\n        Vector3 side = Vector3.Cross(Vector3.up, dir);\r\n        Vector3 want = (dir + side * (Mathf.Sin(_wobble) * _wobbleAmp)).normalized;\r\n\r\n        Vector3 move = Steer(want);\r\n        transform.position = p + move * (Speed * dt);\r\n\r\n        // 转身不要瞬移：0.3 秒转过去，光锥扫过墙面的过程玩家能看见 —— 那是预警。\r\n        transform.rotation = Quaternion.Slerp(transform.rotation,\r\n            Quaternion.LookRotation(move, Vector3.up), 3.5f * dt);\r\n\r\n        // 卡住兜底：2 秒内几乎没挪动就换一个航点。Steer 是沿表面滑的，\r\n        // 偶尔会滑进灌木和墙的夹角里出不来 —— 没有这一条，他会站在墙角扫一晚上的灯。\r\n        if (Nb.FlatDist(transform.position, _stuckFrom) > 0.55f)\r\n        {\r\n            _stuckFrom = transform.position;\r\n            _stuckT = 0f;\r\n        }\r\n        else\r\n        {\r\n            _stuckT += dt;\r\n            if (_stuckT > 2f) { _hasWp = false; _stuckT = 0f; }\r\n        }\r\n    }\r\n\r\n    /// 到点：站住 1.2~3.0 秒，整个人转过去照别处（LookAround 接手）。\r\n    void Arrive()\r\n    {\r\n        _hasWp = false;\r\n        _pause = Random.Range(1.2f, 3.0f);\r\n        _lookT = 0f;\r\n        _stuckT = 0f;\r\n    }\r\n\r\n    /// 站住环顾。**整个人转过去**，而不是只拧手腕：\r\n    /// 手电拿在手里，手腕拧 140° 的画面是错的（握把会横穿过手掌），\r\n    /// 而\"这个人转过身去了\"也正是玩家敢横穿空地的那个窗口。\r\n    void LookAround()\r\n    {\r\n        float dt = Time.deltaTime;\r\n        _pause -= dt;\r\n        _lookT -= dt;\r\n\r\n        if (_lookT <= 0f)\r\n        {\r\n            _bodyYawWant = Mathf.Repeat(transform.eulerAngles.y + Random.Range(-135f, 135f), 360f);\r\n            _lookT = Random.Range(0.9f, 1.7f);\r\n        }\r\n\r\n        float y = Mathf.MoveTowardsAngle(transform.eulerAngles.y, _bodyYawWant, LookTurnSpeed * dt);\r\n        transform.rotation = Quaternion.Euler(0f, y, 0f);\r\n\r\n        if (_pause <= 0f) _lookT = 0f;\r\n    }\r\n\r\n    /// 在\"自己那条路线两侧 ±ZonePad\"的带子里抽一个航点。\r\n    /// 抽不出来（全是掩体 / 全在安全区 / 都太近）时退化成\"朝随机方向走 LegMin 米\"，\r\n    /// 下一段再抽 —— 不要为了抽一个完美点把这一帧卡住。\r\n    void PickWaypoint()\r\n    {\r\n        Vector3 along = _laneB - _laneA;\r\n        along.y = 0f;\r\n        float len = along.magnitude;\r\n        Vector3 perp = len > 0.01f ? Vector3.Cross(Vector3.up, along / len) : Vector3.right;\r\n\r\n        Vector3 best = Vector3.zero;\r\n        float bestScore = -1f;\r\n\r\n        for (int i = 0; i < 16; i++)\r\n        {\r\n            Vector3 q = _laneA + along * Random.value;\r\n            q += perp * Random.Range(-ZonePad, ZonePad);\r\n            q.y = 0f;\r\n            q.x = Mathf.Clamp(q.x, NbScene.XMin + WallInset, NbScene.XMax - WallInset);\r\n            q.z = Mathf.Clamp(q.z, NbScene.ZMin + WallInset, NbScene.ZMax - WallInset);\r\n\r\n            float leg = Nb.FlatDist(q, transform.position);\r\n            if (leg < LegMin || leg > LegMax) continue;\r\n            if (!Standable(q)) continue;\r\n\r\n            // 偏好 8 m 左右的一段路：太近像抖，太远像赶路。随机量让它不至于每段一样长。\r\n            float score = 1f - Mathf.Abs(leg - 8f) / 12f + Random.value * 0.6f;\r\n            if (score > bestScore) { bestScore = score; best = q; }\r\n        }\r\n\r\n        if (bestScore < 0f)\r\n        {\r\n            // 兜底：朝随机方向走 LegMin。Steer 会把它推到墙外，卡住检测会在 2 秒后重抽。\r\n            float a = Random.Range(0f, 6.283f);\r\n            best = transform.position + new Vector3(Mathf.Sin(a), 0f, Mathf.Cos(a)) * LegMin;\r\n            best.x = Mathf.Clamp(best.x, NbScene.XMin + WallInset, NbScene.XMax - WallInset);\r\n            best.z = Mathf.Clamp(best.z, NbScene.ZMin + WallInset, NbScene.ZMax - WallInset);\r\n        }\r\n\r\n        _wp = best;\r\n        _hasWp = true;\r\n        _pause = 0f;\r\n        _stuckFrom = transform.position;\r\n        _stuckT = 0f;\r\n        _wobbleAmp = Random.Range(0.04f, 0.18f);\r\n        _wobble = Random.Range(0f, 6.283f);\r\n    }\r\n\r\n    /// 这个点能不能站人（0.55 m 半径、膝盖到胸口这一段）。\r\n    /// 顺带把出生点附近的 8 m 排掉 —— 见 HomeClear。\r\n    bool Standable(Vector3 q)\r\n    {\r\n        NbGame game = NbGame.I;\r\n        if (game != null && Nb.FlatDist(q, game.Home) < HomeClear) return false;\r\n\r\n        return !Physics.CheckSphere(q + Vector3.up * 0.75f, 0.55f,\r\n            Physics.DefaultRaycastLayers, QueryTriggerInteraction.Ignore);\r\n    }\r\n\r\n    // ───────────────────────── 追击 / 搜索 ─────────────────────────\r\n\r\n    /// 追击 / 搜索。目标永远是**最后看见的位置**，不是玩家当前坐标 ——\r\n    /// 后者等于透视，玩家绕到灌木后面就变成了\"他隔着一丛树直线撞过来\"。\r\n    void Chase()\r\n    {\r\n        if (_player != null &&\r\n            Nb.FlatDist(transform.position, _player.position) <= CatchDist &&\r\n            Clear(transform.position + Vector3.up * 0.25f, _player.position + Vector3.up * 0.15f))\r\n        {\r\n            Catch();\r\n            return;\r\n        }\r\n\r\n        Vector3 p = transform.position;\r\n        Vector3 flat = new Vector3(_lastSeen.x - p.x, 0f, _lastSeen.z - p.z);\r\n        float d = flat.magnitude;\r\n        if (d < 0.35f) return;          // 到点了：原地扫灯（Scan 会接手）\r\n\r\n        Vector3 dir = flat / d;\r\n        Vector3 move = Steer(dir);\r\n        transform.position = p + move * (ChaseSpeed * Time.deltaTime);\r\n\r\n        // 追的时候转身更快：他是在扑，不是在散步。\r\n        transform.rotation = Quaternion.Slerp(transform.rotation,\r\n            Quaternion.LookRotation(move, Vector3.up), 8f * Time.deltaTime);\r\n    }\r\n\r\n    /// 中间有没有东西挡着（抓人用）。少了这一句，玩家隔着一层 0.4 m 的墙\r\n    /// 贴着保安站也会被\"抓\" —— 而这一关的掩体里有工具棚和柴垛，那种穿墙抓人的手感\r\n    /// 会让人根本分不清\"我到底躲好了没有\"。\r\n    bool Clear(Vector3 a, Vector3 b)\r\n    {\r\n        Vector3 d = b - a;\r\n        float m = d.magnitude;\r\n        if (m < 0.05f) return true;\r\n\r\n        RaycastHit h;\r\n        if (!Physics.Raycast(a, d / m, out h, m - 0.04f, Physics.DefaultRaycastLayers,\r\n                QueryTriggerInteraction.Ignore))\r\n            return true;\r\n\r\n        return h.collider != null && _player != null && h.collider.transform.root == _player.root;\r\n    }\r\n\r\n    /// 前方短距离球扫掠：撞到灌木 / 墙就沿表面滑开。\r\n    /// 保安没有碰撞体（不改场景、也不挡人），所以这一句是**唯一**阻止他穿进灌木里的东西。\r\n    Vector3 Steer(Vector3 dir)\r\n    {\r\n        RaycastHit h;\r\n        Vector3 o = transform.position + Vector3.up * 0.55f;\r\n        if (!Physics.SphereCast(o, 0.28f, dir, out h, 0.55f, Physics.DefaultRaycastLayers,\r\n                QueryTriggerInteraction.Ignore))\r\n            return dir;\r\n        if (h.collider == null) return dir;\r\n        if (_player != null && h.collider.transform.root == _player.root) return dir;\r\n\r\n        Vector3 n = h.normal;\r\n        n.y = 0f;\r\n        if (n.sqrMagnitude < 1e-4f) return dir;\r\n\r\n        Vector3 slide = Vector3.ProjectOnPlane(dir, n.normalized);\r\n        slide.y = 0f;\r\n        return slide.sqrMagnitude > 1e-4f ? slide.normalized : dir;\r\n    }\r\n\r\n    // ───────────────────────── 扫灯 ─────────────────────────\r\n\r\n    /// 四处扫：不断挑一个新的\"看的方向\"，线性转过去，停一会儿，再挑下一个。\r\n    /// 用角度线性推进（MoveTowardsAngle）而不是 sin 叠加 —— sin 的节奏是死的，\r\n    /// 玩家数两次就能踩点走；而\"随机目标 + 随机停留\"没有节拍可数。\r\n    void Scan()\r\n    {\r\n        float dt = Time.deltaTime;\r\n        bool alert = _alertT > 0f;      // 刚被甩掉、正在附近找人：转得更快、范围更大\r\n\r\n        _holdT -= dt;\r\n        if (_holdT <= 0f) NextLook();\r\n\r\n        float turn = Mathf.Min(100f, Sweep * 95f) * (alert ? 1.6f : 1f);\r\n        _scanYaw = Mathf.MoveTowardsAngle(_scanYaw, _scanYawWant, turn * dt);\r\n        _scanPitch = Mathf.MoveTowards(_scanPitch, _scanPitchWant, turn * 0.55f * dt);\r\n\r\n        _lamp.localRotation = Quaternion.Euler(_scanPitch, _scanYaw, 0f);\r\n    }\r\n\r\n    /// 挑下一个方向。**大部分时间扫前方一个扇形，约 1/5 的机会扫到侧面 / 身后** ——\r\n    /// 那一下必须真的看见，因为\"他背过身去了\"是玩家唯一敢横穿空地的窗口。\r\n    /// 俯仰也在变（−24°~+6°）：只左右扫的话，18 m 外的光斑是一条水平线，\r\n    /// 玩家会以为自己贴着地面走就安全，而实际上灯在 1.4 m 高、压 20° 时远处什么都照不到。\r\n    void NextLook()\r\n    {\r\n        bool alert = _alertT > 0f;\r\n        // 95° 是\"举着手电把手臂横出去\"的极限：再大，握把就会从掌心里横穿过去。\r\n        // 身后的那一片不靠拧手腕，靠站住时整个人转过去（LookAround）。\r\n        float wide = alert ? 110f : 95f;\r\n\r\n        if (Random.value < 0.22f)\r\n            _scanYawWant = (Random.value < 0.5f ? -1f : 1f) * Random.Range(58f, wide);\r\n        else\r\n            _scanYawWant = Random.Range(-55f, 55f);\r\n\r\n        _scanPitchWant = Random.Range(-6f, 24f);\r\n        _holdT = alert ? Random.Range(0.28f, 0.75f) : Random.Range(0.6f, 1.6f);\r\n    }\r\n\r\n    /// 追人的时候把光**钉在玩家身上**：这是玩家唯一能读出\"他知道我在哪\"的东西。\r\n    void Aim()\r\n    {\r\n        if (_player == null) { Scan(); return; }\r\n\r\n        Vector3 to = _player.position + Vector3.up * 0.10f - _lamp.position;\r\n        if (to.sqrMagnitude < 1e-4f) return;\r\n\r\n        Vector3 local = transform.InverseTransformDirection(to.normalized);\r\n        Quaternion want = Quaternion.LookRotation(local, Vector3.up);\r\n        _lamp.localRotation = Quaternion.Slerp(_lamp.localRotation, want, 9f * Time.deltaTime);\r\n    }\r\n\r\n    // ───────────────────────── 感知 / 状态机 ─────────────────────────\r\n\r\n    void Sense()\r\n    {\r\n        Sees = false;\r\n\r\n        NbGame game = NbGame.I;\r\n        if (_player == null && game != null) _player = game.Player;\r\n        if (_player == null) return;\r\n\r\n        // 被抓之后的 3 秒无敌期里，光当没照到：否则他会在你无敌的这 3 秒里\r\n        // 一直贴着你、把\"无敌\"变成\"被一个甩不掉的人顶着跑\"。\r\n        if (game != null && game.Invuln > 0f) return;\r\n\r\n        // 出生点 6 m 内是安全区（和猫共用同一条规矩）。没有这一条，\r\n        // 第 8 关那条中轴路线一上场，玩家一睁眼就站在手电里。\r\n        if (game != null && Nb.FlatDist(_player.position, game.Home) < 6f) return;\r\n\r\n        Vector3 eye = _lamp.position;\r\n        // 瞄胸口而不是脚下：玩家只有 0.30 m 高，瞄脚会先打到地面，永远判\"被挡住\"。\r\n        Vector3 to = _player.position + Vector3.up * 0.10f - eye;\r\n        float dist = to.magnitude;\r\n\r\n        if (dist < 0.05f || dist > Range) return;\r\n        if (Vector3.Angle(_lamp.forward, to) > Half) return;\r\n\r\n        // 被掩体挡住 ⇒ 看不见。射线短 0.15 m，免得终点落在玩家皮肤上还算\"被挡\"。\r\n        RaycastHit hit;\r\n        if (Physics.Raycast(eye, to / dist, out hit, dist - 0.15f, Physics.DefaultRaycastLayers,\r\n                QueryTriggerInteraction.Ignore))\r\n        {\r\n            if (hit.collider.transform.root != _player.root) return;\r\n        }\r\n\r\n        Sees = true;\r\n    }\r\n\r\n    /// 状态机：看见 → （迟滞 0.3 s）起跑 → 看不见 → 走到最后位置 → 到点/够远就放弃。\r\n    void Think()\r\n    {\r\n        float dt = Time.deltaTime;\r\n\r\n        if (Sees)\r\n        {\r\n            _lostT = 0f;\r\n            _alertT = AlertHold;\r\n            _lastSeen = _player != null ? _player.position : transform.position;\r\n\r\n            if (!_chasing)\r\n            {\r\n                _spotT += dt;\r\n                if (_spotT >= SpotDelay) Begin();\r\n            }\r\n            return;\r\n        }\r\n\r\n        _spotT = 0f;\r\n        if (!_chasing) return;\r\n\r\n        _lostT += dt;\r\n        _alertT -= dt;\r\n\r\n        float d = _player != null ? Nb.FlatDist(transform.position, _player.position) : 999f;\r\n\r\n        // 光被挡住 **并且** 人在 5 m 之外 ⇒ 脱身。这两条必须同时成立：\r\n        // 只判遮挡的话，蹲在 2 m 的灌木后就能让一个正在冲过来的人当场忘掉你。\r\n        if (_lostT > 1.2f && d >= LoseDist) { End(); return; }\r\n\r\n        // 兜底：搜了 6 秒还是没结果。玩家可以靠\"躲得近\"拖住他，但不能把他永久钉在那儿。\r\n        if (_alertT <= 0f) End();\r\n    }\r\n\r\n    void Begin()\r\n    {\r\n        _chasing = true;\r\n        _alertT = AlertHold;\r\n        _lostT = 0f;\r\n\r\n        Debug.LogFormat(\"[Guard] 手电扫到玩家（{0:F1} m），开始追击：{1:F2} m/s。\",\r\n            _player != null ? Nb.FlatDist(transform.position, _player.position) : -1f, ChaseSpeed);\r\n\r\n        if ( _nextSound <= Time.time)\r\n        {\r\n            AudioManager.PlaySound(SoundType.MAN_yell, 0.8f);\r\n            _nextSound = Time.time + AudioManager.GetSoundLength(SoundType.MAN_yell);\r\n        }\r\n        \r\n    }\r\n\r\n    void End()\r\n    {\r\n        AudioManager.StopSound();\r\n\r\n        _chasing = false;\r\n        _spotT = 0f;\r\n        _lostT = 0f;\r\n        _alertT = 0f;\r\n\r\n        // 从\"钉着玩家\"切回\"四处扫\"：把当前的灯角度接过来，别让 18 m 的光锥瞬移几十度 ——\r\n        // 而那正是玩家最需要看懂的一瞬间。\r\n        if (_lamp != null)\r\n        {\r\n            Vector3 e = _lamp.localEulerAngles;\r\n            _scanYaw = Norm180(e.y);\r\n            _scanPitch = Norm180(e.x);\r\n            _scanYawWant = _scanYaw;\r\n            _scanPitchWant = _scanPitch;\r\n            _holdT = 0.35f;\r\n        }\r\n\r\n        // 追丢之后先站住扫一圈再继续走：他会\"在原地找一下\"，而不是立刻若无其事地巡逻。\r\n        _hasWp = false;\r\n        _pause = 1.0f;\r\n        _lookT = 0f;\r\n    }\r\n\r\n    static float Norm180(float a)\r\n    {\r\n        return Mathf.Repeat(a + 180f, 360f) - 180f;\r\n    }\r\n\r\n    /// 撞上玩家：交给 NbGame 结算（扣血 / 红闪 / 所有人回起点 / 失败面板）。\r\n    void Catch()\r\n    {\r\n        NbGame game = NbGame.I;\r\n        if (game == null) { End(); return; }\r\n\r\n        End();\r\n        game.CaughtByGuard(this);\r\n    }\r\n\r\n    /// 看见人的一瞬间手电变红、变亮 —— 这是玩家唯一的即时反馈。\r\n    /// 只靠 HUD 上那根曝光条不够：抬头看条的时候人已经死了。\r\n    void Paint()\r\n    {\r\n        if (_lampLight == null) return;\r\n\r\n        if (Sees || _chasing)\r\n        {\r\n            _lampLight.color = new Color(1f, 0.34f, 0.24f);\r\n            _lampLight.intensity = 10f;\r\n        }\r\n        else\r\n        {\r\n            _lampLight.color = new Color(1f, 0.90f, 0.70f);\r\n            _lampLight.intensity = 7f;\r\n        }\r\n    }\r\n\r\n    /// 换关时把保安放回路线起点，并清掉这一关的游走状态。\r\n    internal void ResetToStart()\r\n    {\r\n        End();\r\n        _pause = 0f;\r\n        _holdT = 0.6f;\r\n        if (Route == null || Route.Length == 0) return;\r\n\r\n        Vector3 at = new Vector3(Route[0].x, 0f, Route[0].z);\r\n        transform.position = at;\r\n        _wp = at;\r\n        _stuckFrom = at;\r\n        _hasWp = false;\r\n        _stuckT = 0f;\r\n        _wobble = Random.Range(0f, 6.283f);\r\n        _bodyYawWant = transform.eulerAngles.y;\r\n    }\r\n}\r\n"},"NbGuardArt":{"path":"Assets/Scripts/NbGuardArt.cs","role":"Loads the Mixamo guard model and hand-samples its walk animation onto the yard guard.","source":"// @role Loads the Mixamo guard model and hand-samples its walk animation onto the yard guard.\r\n// @calls NbGuard\r\n\r\n// NbGuardArt.cs — 把「会走路的真人」装到后院保安身上\r\n//\r\n// 模型：Assets/Resources/Guards/Walking.fbx\r\n//   Mixamo 骨架（mixamorig:Hips / Spine / LeftArm …），110 根骨骼、11 块蒙皮网格、1976 个三角面，\r\n//   带一个 32 帧的**原地**走路动画：Hips 的位移只有 9 cm 横向摆动，首尾帧完全相同，\r\n//   没有前向位移 ⇒ 可以直接循环播，不会每个循环往前窜一段再被拉回来。\r\n//\r\n// 为什么必须放一份到 Resources 里：\r\n//   保安是**运行时生成**的（场景里没有它们的 prefab 实例），而 AssetDatabase 只在编辑器里存在。\r\n//   运行时加载资源的唯一入口是 Resources.Load，所以 Assets/walkinghuman/ 那份原件加载不到。\r\n//   这里放的是副本，**故意不带 .meta** —— 带过去会让两个文件抢同一个 GUID，Unity 会把它判成\r\n//   \"同一个资源的两份拷贝\"然后随机丢一个。\r\n//\r\n// 为什么不直接用 fbx 自带的材质：\r\n//   fbx 里只有两个空材质（Material.001 / Black.），**没有贴图**。默认导入在 URP 下是洋红或纯白，\r\n//   而这个角色在夜里应该是一块**比背景更黑**的剪影 —— 它靠手电的光锥被看见，不靠自身颜色。\r\n//   所以材质在这里重做：制服一份、鞋/头发一份，两件共用（SRP Batcher 还能合批）。\r\n//\r\n// 已知的、只能靠 Play 验收的两件事（都留了日志）：\r\n//   ① 朝向。按骨骼绑定姿势算出来是标准 Mixamo 朝向（左肩在 +X、脚朝 +Z），默认就当它面朝 +Z。\r\n//      如果进 Play 看见保安**倒着走**，把 ModelYaw 改成 180 就行 —— 只影响外观，\r\n//      手电和判定都挂在保安根节点上，与模型朝向无关。\r\n//   ② 走路动画的播放方式。Animator 需要 AnimatorController 资产，而 controller **无法在运行时创建**；\r\n//      Animation 组件只认 legacy 曲线，这个 fbx 是按 Generic 导入的。所以这里用\r\n//      AnimationClip.SampleAnimation 手动按时间采样 —— 没有状态机、没有 controller、不改导入设置。\r\n//      万一它在你的 Unity 版本里不生效，会退化成一个轻微的上下起伏（至少不是一块滑动的雕像），\r\n//      并在 Console 里留下 \"[GuardArt] 手动采样失败\"。\r\n\r\nusing UnityEngine;\r\n\r\ninternal static class NbGuardArt\r\n{\r\n    const string Folder = \"Guards\";          // Resources/Guards\r\n    const string Path   = \"Guards/Walking\";  // fbx 本体\r\n\r\n    /// 保安身高（米）。**和旧版几何体一致** —— 手电高度、被照到的高度都是从它算的。\r\n    internal const float Height = 1.80f;\r\n\r\n    /// 模型自身朝向与保安 forward 的夹角（度）。\r\n    /// 只在\"看起来倒着走\"时才需要改：0 = 模型面朝 +Z（Mixamo 的默认朝向），180 = 反了。\r\n    internal const float ModelYaw = 0f;\r\n\r\n    /// 手电在保安手里的局部位置。按身高比例给 —— 换身高不用再手算一遍。\r\n    /// 只在**找不到手骨**时用；正常情况下 NbGuard 会拿模型右手的位置覆盖它。\r\n    internal static Vector3 TorchLocal\r\n    {\r\n        get { return new Vector3(Height * 0.11f, Height * 0.80f, Height * 0.13f); }\r\n    }\r\n\r\n    // ───────────────────────── 手电本体 ─────────────────────────\r\n\r\n    /// 造一支**看得见**的手电：握把 + 灯头 + 自发光镜片 + 一小盏点光。\r\n    ///\r\n    /// 为什么光靠一个 Light 不够：夜里只看得见地上那块光斑，看不见\"谁在拿灯\"。\r\n    /// 玩家要读的是\"那个人转向那边了\" —— 手电本身得是个发光物体，视线才有落点。\r\n    /// 所有部件都不带碰撞体、留在 Ignore Raycast 层：保安自己的判定射线是从镜片发出的，\r\n    /// 留碰撞体的话\"照到人\"永远不会成立（这跟模型不带碰撞体是同一条理由）。\r\n    internal static void BuildTorch(Transform lamp)\r\n    {\r\n        Color body = new Color(0.10f, 0.10f, 0.11f);\r\n        Color grip = new Color(0.055f, 0.055f, 0.062f);\r\n\r\n        // Unity 原始圆柱的轴是 Y，所以要绕 X 转 90° 才对着灯节点的 +Z（= 照射方向）。\r\n        GameObject h = Nb.Cyl(lamp, \"Torch Grip\", new Vector3(0f, 0f, -0.09f), 0.052f, 0.18f, grip, false);\r\n        h.transform.localRotation = Quaternion.Euler(90f, 0f, 0f);\r\n\r\n        GameObject head = Nb.Cyl(lamp, \"Torch Head\", new Vector3(0f, 0f, 0.025f), 0.084f, 0.07f, body, false);\r\n        head.transform.localRotation = Quaternion.Euler(90f, 0f, 0f);\r\n\r\n        GameObject lens = Nb.Ball(lamp, \"Torch Lens\", new Vector3(0f, 0f, 0.062f), 0.072f,\r\n            new Color(1f, 0.95f, 0.80f), false);\r\n        Renderer lr = lens.GetComponent<Renderer>();\r\n        if (lr != null) lr.sharedMaterial = Nb.MatEmissive(new Color(1f, 0.94f, 0.78f), 3.4f);\r\n\r\n        // 3 m 的点光：它的作用是把\"手电在这儿\"变成画面里最亮的那个小点，\r\n        // 不是照亮院子（那是聚光灯的事，18 m）。\r\n        GameObject glow = new GameObject(\"Torch Glow\");\r\n        glow.transform.SetParent(lamp, false);\r\n        glow.transform.localPosition = new Vector3(0f, 0f, 0.085f);\r\n        Light pl = glow.AddComponent<Light>();\r\n        pl.type = LightType.Point;\r\n        pl.range = 3.2f;\r\n        pl.intensity = 1.8f;\r\n        pl.color = new Color(1f, 0.92f, 0.74f);\r\n        pl.shadows = LightShadows.None;\r\n    }\r\n\r\n    /// 找模型的右手骨。Mixamo 叫 \"mixamorig:RightHand\"，别的骨架可能叫 Hand_R / hand_r。\r\n    /// 找不到就返回 null —— 调用方退回固定的 TorchLocal，玩法不受影响。\r\n    internal static Transform FindHand(GameObject model)\r\n    {\r\n        if (model == null) return null;\r\n\r\n        Transform[] all = model.GetComponentsInChildren<Transform>(true);\r\n        string[] keys = { \"righthand\", \"right_hand\", \"hand_r\", \"handr\" };\r\n\r\n        // 先按**名字结尾**找：骨架里还有 RightHandIndex1…Thumb4，用\"包含\"会先命中\r\n        // 手指骨（层级顺序只保证父在子前，不保证兄弟里的顺序），灯就跑到指节上去了。\r\n        for (int k = 0; k < keys.Length; k++)\r\n        {\r\n            for (int i = 0; i < all.Length; i++)\r\n            {\r\n                if (all[i] == null) continue;\r\n                if (all[i].name.ToLowerInvariant().EndsWith(keys[k], System.StringComparison.Ordinal))\r\n                    return all[i];\r\n            }\r\n        }\r\n\r\n        // 退一步才是\"包含\"，给那些带前缀/后缀的骨架用。\r\n        for (int k = 0; k < keys.Length; k++)\r\n        {\r\n            for (int i = 0; i < all.Length; i++)\r\n            {\r\n                if (all[i] == null) continue;\r\n                if (all[i].name.ToLowerInvariant().IndexOf(keys[k], System.StringComparison.Ordinal) >= 0)\r\n                    return all[i];\r\n            }\r\n        }\r\n        return null;\r\n    }\r\n\r\n    static bool _warned;     // \"模型没导进来\"只报一次，别每关刷屏\r\n    static bool _reported;   // \"模型已就位\"只报一次（一关最多 4 个保安）\r\n\r\n    // ───────────────────────── 对外 ─────────────────────────\r\n\r\n    /// 往保安身上挂模型。成功返回模型根节点，失败返回 null（调用方退回几何体）。\r\n    internal static GameObject Attach(Transform guard)\r\n    {\r\n        GameObject src = Resources.Load<GameObject>(Path);\r\n        if (src == null)\r\n        {\r\n            if (!_warned)\r\n            {\r\n                _warned = true;\r\n                Debug.LogWarning(\"[GuardArt] 读不到 Resources/\" + Path + \" —— 保安退回几何体。\" +\r\n                                 \"确认 Unity 已经把 Assets/Resources/Guards/Walking.fbx 导入完\" +\r\n                                 \"（切回编辑器让它 Refresh 一次）。\");\r\n            }\r\n            return null;\r\n        }\r\n\r\n        GameObject go = Object.Instantiate(src);\r\n        go.name = \"Model\";\r\n        go.transform.SetParent(guard, false);\r\n        go.transform.localPosition = Vector3.zero;\r\n        go.transform.localRotation = Quaternion.Euler(0f, ModelYaw, 0f);\r\n        go.transform.localScale = Vector3.one;\r\n\r\n        // ① 拆掉自带的两类东西\r\n        //    · Animator：Generic 导入会带一个没有 controller 的 Animator，它和手动采样会抢同一批\r\n        //      transform —— 两个都留着就是\"有的骨头动、有的不动\"，而且很难看出是哪边在动。\r\n        //    · Collider：保安本来就不该挡人（1.2 m 的走道要靠从他身边挤过去），\r\n        //      更要紧的是手电判定是从灯泡朝玩家打一条射线 —— 自己身上的碰撞体会先把这条射线吃掉，\r\n        //      于是\"照到人\"永远不成立。\r\n        Animator an = go.GetComponentInChildren<Animator>(true);\r\n        if (an != null) Object.Destroy(an);\r\n        Collider[] cols = go.GetComponentsInChildren<Collider>(true);\r\n        for (int i = 0; i < cols.Length; i++) Object.Destroy(cols[i]);\r\n\r\n        Fit(go, guard);\r\n        Paint(go);\r\n        AttachMotion(go);\r\n\r\n        if (!_reported)\r\n        {\r\n            _reported = true;\r\n            Debug.Log(\"[GuardArt] 保安模型就位：\" + Path + \"（身高 \" + Height + \" m，朝向偏转 \" +\r\n                      ModelYaw + \"°）。\");\r\n        }\r\n        return go;\r\n    }\r\n\r\n    // ───────────────────────── 尺寸与落地 ─────────────────────────\r\n\r\n    /// 归一化到身高、水平居中、底面贴地。\r\n    ///\r\n    /// **不要用 Renderer.bounds 量** —— 蒙皮网格的 bounds 由根骨头推出来，会把骨头上的\r\n    /// 非单位缩放一起带上（本项目的老鼠模型曾因此从 1.7 cm 报成 8.5 m，差 515 倍，且不报错）。\r\n    /// TryMeasureWorldBounds 走的是 sharedMesh.bounds 的 8 个角点，是网格自己的量。\r\n    static void Fit(GameObject go, Transform guard)\r\n    {\r\n        Bounds b;\r\n        if (!CatCheeseSetup.TryMeasureWorldBounds(go, out b) || b.size.y < 1e-5f)\r\n        {\r\n            Debug.LogWarning(\"[GuardArt] 量不到模型网格尺寸 —— 不缩放、不贴地（会按 fbx 原比例站在原点）。\");\r\n            return;\r\n        }\r\n\r\n        float raw = b.size.y;\r\n        float k = Height / raw;\r\n\r\n        // 倍率夹一层：超出这个范围的\"实测高度\"只可能是量错了。硬缩会把模型缩没或者撑满整个院子，\r\n        // 而两种结果都不会报错 —— 所以宁可放弃缩放，让它在画面里明显不对，也不要静默地错。\r\n        if (k < 1e-3f || k > 1e3f)\r\n        {\r\n            Debug.LogWarningFormat(\"[GuardArt] 实测高 {0:F3} m，算出倍率 {1:F1} —— 不合理，已跳过缩放。\", raw, k);\r\n            return;\r\n        }\r\n        go.transform.localScale = go.transform.localScale * k;\r\n\r\n        Transform p = go.transform.parent != null ? go.transform.parent : guard;\r\n\r\n        // ② 水平居中：fbx 的原点常常不在两脚之间（这个模型 Hips 就在 x=6.8 / z=6.0 上），\r\n        //    不居中的话保安会绕着\"看不见的轴\"转身，看起来像在绕着脚画圈。\r\n        if (CatCheeseSetup.TryMeasureWorldBounds(go, out b))\r\n            go.transform.position -= new Vector3(b.center.x - p.position.x, 0f, b.center.z - p.position.z);\r\n\r\n        // ③ 贴地：包围盒底面压到保安脚下（保安根节点的 y 就是地面）\r\n        if (CatCheeseSetup.TryMeasureWorldBounds(go, out b))\r\n            go.transform.position += Vector3.up * (p.position.y - b.min.y);\r\n\r\n        if (CatCheeseSetup.TryMeasureWorldBounds(go, out b))\r\n            Debug.LogFormat(\"[GuardArt] 模型实测高 {0:F3} m，×{1:F4} → 现高 {2:F2} m，\" +\r\n                            \"占地 {3:F2}×{4:F2} m，底面 y={5:F3}（地面 {6:F2}）。\",\r\n                raw, k, b.size.y, b.size.x, b.size.z, b.min.y, p.position.y);\r\n    }\r\n\r\n    // ───────────────────────── 材质 ─────────────────────────\r\n\r\n    /// 夜里这个角色只该被\"看成一块影子\"：制服比背景更黑，鞋和头发再黑一档。\r\n    static void Paint(GameObject go)\r\n    {\r\n        Material coat = Mat(\"GuardCoat\", new Color(0.085f, 0.095f, 0.115f), 0.10f);\r\n        Material boot = Mat(\"GuardBoot\", new Color(0.040f, 0.042f, 0.048f), 0.05f);\r\n\r\n        Renderer[] rs = go.GetComponentsInChildren<Renderer>(true);\r\n        for (int i = 0; i < rs.Length; i++)\r\n        {\r\n            Material[] ms = rs[i].sharedMaterials;\r\n            if (ms.Length == 0) { rs[i].sharedMaterial = coat; }\r\n            else\r\n            {\r\n                for (int k = 0; k < ms.Length; k++)\r\n                {\r\n                    string n = ms[k] != null ? ms[k].name.ToLower() : \"\";\r\n                    ms[k] = n.Contains(\"black\") ? boot : coat;\r\n                }\r\n                rs[i].sharedMaterials = ms;\r\n            }\r\n\r\n            // 蒙皮网格的包围盒不会跟着动画更新 ⇒ 默认（false）会在角色走到画面边缘时\r\n            // 被视锥剔除掉，表现是\"保安走到屏幕边上忽然消失\"。\r\n            SkinnedMeshRenderer smr = rs[i] as SkinnedMeshRenderer;\r\n            if (smr != null) smr.updateWhenOffscreen = true;\r\n        }\r\n    }\r\n\r\n    static Material Mat(string name, Color c, float smooth)\r\n    {\r\n        Shader sh = Shader.Find(\"Universal Render Pipeline/Lit\");\r\n        if (sh == null) sh = Shader.Find(\"Standard\");\r\n\r\n        Material m = new Material(sh);\r\n        m.name = name;\r\n        // URP/Lit 的主色是 _BaseColor；mainColor 走 [MainColor] 特性，换 Standard 也能设对。\r\n        m.color = c;\r\n        if (m.HasProperty(\"_BaseColor\")) m.SetColor(\"_BaseColor\", c);\r\n        if (m.HasProperty(\"_Smoothness\")) m.SetFloat(\"_Smoothness\", smooth);\r\n        if (m.HasProperty(\"_Glossiness\")) m.SetFloat(\"_Glossiness\", smooth);\r\n        if (m.HasProperty(\"_Metallic\")) m.SetFloat(\"_Metallic\", 0f);\r\n        return m;\r\n    }\r\n\r\n    // ───────────────────────── 走路动画 ─────────────────────────\r\n\r\n    static void AttachMotion(GameObject go)\r\n    {\r\n        AnimationClip[] all = Resources.LoadAll<AnimationClip>(Folder);\r\n        AnimationClip clip = null;\r\n        for (int i = 0; i < all.Length; i++)\r\n        {\r\n            // 这个 fbx 只有一个 take。换模型时\"最长的那段 = 主循环\"仍然是最稳的规则。\r\n            if (all[i] != null && (clip == null || all[i].length > clip.length)) clip = all[i];\r\n        }\r\n\r\n        if (clip == null || clip.length <= 0.01f)\r\n        {\r\n            Debug.LogWarning(\"[GuardArt] Resources/\" + Folder + \" 里读不到可用的动画 —— 保安会走，但腿不动。\");\r\n            return;\r\n        }\r\n\r\n        NbGuardModel m = go.AddComponent<NbGuardModel>();\r\n        m.Setup(clip);\r\n\r\n        if (!_reported)\r\n            Debug.LogFormat(\"[GuardArt] 走路动画：'{0}'，{1:F2} 秒，按时间手动采样（无 Animator）。\",\r\n                clip.name, clip.length);\r\n    }\r\n}\r\n\r\n// ─────────────────────────────────────────────────────────────────────────────\r\n// 手动推进走路动画。\r\n//\r\n// 为什么不用 Animator / Animation 组件：\r\n//   · Animator 必须挂一个 AnimatorController，而 controller **只能在编辑器里创建**，\r\n//     运行时没有任何公开 API 能造一个出来；\r\n//   · Animation 组件只播 legacy 曲线，这个 fbx 是按 Generic 导入的（模型自带走路动画，\r\n//     通常就是这么导的）。改 `clip.legacy = true` 在运行时能不能生效，取决于版本 —— 赌不起。\r\n//\r\n// AnimationClip.SampleAnimation 是公开 API：按时间把曲线采样到整条层级上。没有状态机、\r\n// 没有 controller、不动导入设置，代价是循环和相位都得自己管（也就是下面这十几行）。\r\n// ─────────────────────────────────────────────────────────────────────────────\r\n\r\ninternal class NbGuardModel : MonoBehaviour\r\n{\r\n    AnimationClip _clip;\r\n    float _t;               // 当前播放时间（秒）\r\n    bool _sampling = true;  // 手动采样还能不能用\r\n    float _phase;           // 兜底起伏的相位\r\n\r\n    /// 播放倍率。走路动画本身是 1.6 m/s 左右的步频，而保安巡逻只有 0.95、追人是 2.55~3.45 ——\r\n    /// 不变速的话，追人的时候腿还在慢悠悠迈，人却在地上滑，一眼就看得出\"他在加速\"是假的。\r\n    internal float Rate = 1f;\r\n\r\n    Vector3 _basePos;\r\n    Quaternion _baseRot;\r\n    Vector3 _baseScale;\r\n\r\n    // 采样自检：SampleAnimation 在有的版本/导入设置下会**静默地什么都不做**——\r\n    // 不报错、不抛异常，模型就那么以绑定姿势站着。那是最难查的一类失败（看起来像\"动画没做好\"），\r\n    // 所以这里拿 Hips 当探针：0.6 秒内它一动没动，就在 Console 里说清楚。\r\n    Transform _probe;\r\n    Vector3 _probeLast;\r\n    float _probeT;\r\n    bool _probeDone;\r\n\r\n    internal void Setup(AnimationClip clip)\r\n    {\r\n        _clip = clip;\r\n        _basePos = transform.localPosition;\r\n        _baseRot = transform.localRotation;\r\n        _baseScale = transform.localScale;\r\n\r\n        // 相位错开：几个保安同时迈同一条腿，一眼就能看出是同一个模型复制出来的。\r\n        _t = Mathf.Repeat(GetInstanceID() * 0.37f, clip.length);\r\n\r\n        Transform[] all = GetComponentsInChildren<Transform>(true);\r\n        for (int i = 0; i < all.Length; i++)\r\n        {\r\n            if (all[i].name.IndexOf(\"Hips\", System.StringComparison.OrdinalIgnoreCase) < 0) continue;\r\n            _probe = all[i];\r\n            _probeLast = _probe.position;\r\n            break;\r\n        }\r\n    }\r\n\r\n    void Update()\r\n    {\r\n        float dt = Time.deltaTime;\r\n\r\n        if (_clip != null && _sampling)\r\n        {\r\n            _t = Mathf.Repeat(_t + dt * Mathf.Max(0.05f, Rate), _clip.length);\r\n            try\r\n            {\r\n                _clip.SampleAnimation(gameObject, _t);\r\n            }\r\n            catch (System.Exception e)\r\n            {\r\n                // 只报一次；之后退回下面的起伏兜底。\r\n                _sampling = false;\r\n                Debug.LogWarning(\"[GuardArt] 手动采样失败（\" + e.GetType().Name + \"：\" + e.Message +\r\n                                 \"）—— 保安改用地形起伏兜底，腿不会动。\");\r\n                Reset();\r\n                return;\r\n            }\r\n            Probe(dt);\r\n            return;\r\n        }\r\n\r\n        // 兜底：整体轻微上下起伏 + 一点点前倾。总比一块贴地滑动的雕像强。\r\n        _phase += dt * 7f;\r\n        transform.localPosition = _basePos + new Vector3(0f, Mathf.Abs(Mathf.Sin(_phase)) * 0.015f, 0f);\r\n        transform.localRotation = _baseRot;\r\n    }\r\n\r\n    /// 看一眼 Hips 到底有没有被推动。只查一次，查完就沉默。\r\n    void Probe(float dt)\r\n    {\r\n        if (_probeDone || _probe == null) return;\r\n\r\n        _probeT += dt;\r\n        if ((_probe.position - _probeLast).sqrMagnitude > 1e-7f)\r\n        {\r\n            _probeDone = true;                       // 动了 ⇒ 采样是有效的\r\n            return;\r\n        }\r\n        _probeLast = _probe.position;\r\n\r\n        if (_probeT > 0.6f)\r\n        {\r\n            _probeDone = true;\r\n            Debug.LogWarning(\"[GuardArt] 手动采样跑完了，但 0.6 秒内 Hips 一点没动 —— \" +\r\n                             \"这段动画在你的 Unity 版本里没被应用，保安会保持绑定姿势（多半是伸着手臂）。\" +\r\n                             \"换法：把 fbx 的 Animation Type 改成 Humanoid 并挂 Animator + Controller。\");\r\n        }\r\n    }\r\n\r\n    /// 换关时把模型摆回初始姿势（采样失败的路径下用得到）。\r\n    internal void Reset()\r\n    {\r\n        _t = 0f;\r\n        transform.localPosition = _basePos;\r\n        transform.localRotation = _baseRot;\r\n        transform.localScale = _baseScale;\r\n    }\r\n}\r\n"},"NbKitchen":{"path":"Assets/Scripts/NbKitchen.cs","role":"Kitchen level: six benches, five 1.2 m aisles, lethal light pools, dark-corner cats.","source":"// @role Kitchen level: six benches, five 1.2 m aisles, lethal light pools, dark-corner cats.\r\n// @calls NbScene Nb\r\n// @tune BenchW:float:1-10:bench width m\r\n// @tune AisleW:float:0.3-3:aisle width m\r\n\r\n// NbKitchen.cs — 场景 03「深夜厨房」\r\n//\r\n// 空间设计：\r\n//   六条纵向台面把 40 × 32 m 的房间切成**五条 1.2 m 宽的走道**。\r\n//   街区是 5 m 巷子（能并肩跑），这里是 1.2 m（勉强过一只老鼠）—— 相机贴地时压迫感完全不同：\r\n//   两侧台面比玩家高 3 倍，抬头只看得见台面边缘和天花板那一线。\r\n//\r\n// 两条硬约束：\r\n//   ① **主走道（x = 60.6）一根灯管都不放。** 它是玩家唯一的纵向安全通道，\r\n//      所有目标都藏在侧走道里 —— 于是\"拿一个、退回主道、再去下一个\"成了固定节奏。\r\n//      把灯也摆到主道上，这一关会变成\"无论怎么走都会死\"。\r\n//   ② 台面必须**留横通道**（z −18.5…−13.5）。没有它，五条走道就是五条死胡同，\r\n//      玩家进去捡完必须原路退回，第 6 关以后根本走不完。\r\n//\r\n// 机制：食物腐坏（每块独立倒计时、全场同时开始）+ 灯管下的光区致命 + 暗角里的猫只能靠声音发现。\r\n\r\nusing UnityEngine;\r\n\r\ninternal static class NbKitchen\r\n{\r\n    // ───────────────────────── 范围 ─────────────────────────\r\n\r\n    internal const float XMin = 40f, XMax = 80f;     // 40 m\r\n    internal const float ZMin = -32f, ZMax = 0f;     // 32 m\r\n\r\n    internal const float CX = (XMin + XMax) * 0.5f;  // 60\r\n    internal const float CZ = (ZMin + ZMax) * 0.5f;  // −16\r\n\r\n    internal static readonly Vector3 Start = new Vector3(60.6f, 0.10f, -28f);\r\n    internal static readonly Vector3 Forward = new Vector3(0f, 0f, 1f);\r\n\r\n    // 台面：宽 4.8、走道 1.2。中心线写死在这里，目标点和巡逻线全部由它推出来 ——\r\n    // 三处（几何 / 目标 / 路线）读同一组数，改一处不会互相错位。\r\n    internal static readonly float[] BenchX = { 45.6f, 51.6f, 57.6f, 63.6f, 69.6f, 75.6f };\r\n    internal const float BenchW = 4.8f;\r\n    internal const float AisleW = 1.2f;\r\n\r\n    // 五条走道的中轴\r\n    internal const float Ax0 = 48.6f, Ax1 = 54.6f, Ax2 = 60.6f, Ax3 = 66.6f, Ax4 = 72.6f;\r\n\r\n    // 台面长度 / 横通道\r\n    internal const float BenchS_Z0 = -26f, BenchS_Z1 = -18.5f;   // 南段\r\n    internal const float BenchN_Z0 = -13.5f, BenchN_Z1 = -6f;    // 北段\r\n\r\n    // ───────────────────────── 调色板 ─────────────────────────\r\n    // 冷白日光灯 + 不锈钢。比后院亮一些，但亮的地方只有灯下 ——\r\n    // 其余部分是纯黑，这正是\"看得见的地方更危险\"。\r\n    static readonly Color FloorCol = new Color(0.26f, 0.27f, 0.28f);\r\n    static readonly Color Steel    = new Color(0.22f, 0.23f, 0.24f);\r\n    static readonly Color SteelTop = new Color(0.31f, 0.32f, 0.33f);\r\n    static readonly Color WallK    = new Color(0.30f, 0.31f, 0.32f);\r\n    static readonly Color Crate    = new Color(0.28f, 0.21f, 0.13f);\r\n    static readonly Color Fridge   = new Color(0.35f, 0.36f, 0.37f);\r\n    static readonly Color Sink     = new Color(0.16f, 0.18f, 0.19f);\r\n    static readonly Color Tube     = new Color(1.00f, 0.96f, 0.84f);\r\n    static readonly Color Pool     = new Color(0.42f, 0.40f, 0.34f);\r\n\r\n    // ───────────────────────── 10 个目标点 ─────────────────────────\r\n    // 顺序仍然按\"离出生点由近到远\"。注意第 4 个开始就全部落在**侧走道**里，\r\n    // 主走道（x = 60.6）只在第 1 和第 10 个点上出现 —— 那是玩家的动线，不是目标的位置。\r\n\r\n    internal static readonly Vector3[] Spots =\r\n    {\r\n        new Vector3(Ax2, 0f, -24f),    // 主走道，门口                          4.0 m\r\n        new Vector3(Ax1, 0f, -24f),    // 西一                                  7.2 m\r\n        new Vector3(Ax3, 0f, -24f),    // 东一                                  7.2 m\r\n        new Vector3(Ax0, 0f, -21f),    // 最西                                  14.2 m\r\n        new Vector3(Ax4, 0f, -21f),    // 最东                                  14.2 m\r\n        new Vector3(Ax1, 0f, -12f),    // 西一·北段（横通道北侧）                16.9 m\r\n        new Vector3(Ax3, 0f, -12f),    // 东一·北段                             16.9 m\r\n        new Vector3(Ax0, 0f, -9f),     // 最西·北段（冰箱后）                    22.2 m\r\n        new Vector3(Ax4, 0f, -9f),     // 最东·北段                             22.2 m\r\n        new Vector3(Ax2, 0f, -6f),     // 主走道尽头（正对后门）                  22.0 m\r\n    };\r\n\r\n    // ───────────────────────── 10 条巡逻路线 ─────────────────────────\r\n    // 五条走道各切南北两段 ⇒ 正好 10 条。猫在第 10 关会同时占住五条纵向道，\r\n    // 玩家唯一的横向通路只剩中间那条 5 m 宽的横通道 —— 那是最危险的一段。\r\n\r\n    internal static readonly Vector3[][] Routes =\r\n    {\r\n        new[] { new Vector3(Ax1, 0f, -25f), new Vector3(Ax1, 0f, -19f) },\r\n        new[] { new Vector3(Ax1, 0f, -13f), new Vector3(Ax1, 0f,  -7f) },\r\n        new[] { new Vector3(Ax3, 0f, -25f), new Vector3(Ax3, 0f, -19f) },\r\n        new[] { new Vector3(Ax3, 0f, -13f), new Vector3(Ax3, 0f,  -7f) },\r\n        new[] { new Vector3(Ax0, 0f, -25f), new Vector3(Ax0, 0f, -19f) },\r\n        new[] { new Vector3(Ax0, 0f, -13f), new Vector3(Ax0, 0f,  -7f) },\r\n        new[] { new Vector3(Ax4, 0f, -25f), new Vector3(Ax4, 0f, -19f) },\r\n        new[] { new Vector3(Ax4, 0f, -13f), new Vector3(Ax4, 0f,  -7f) },\r\n        new[] { new Vector3(Ax2, 0f, -25f), new Vector3(Ax2, 0f, -19f) },\r\n        new[] { new Vector3(Ax2, 0f, -13f), new Vector3(Ax2, 0f,  -7f) },\r\n    };\r\n\r\n    // ───────────────────────── 灯管（光区）─────────────────────────\r\n    // 八个位置：四条侧走道 × 南北两段。**主走道一根都没有**。\r\n    // 灯下 4.4 × 4.4 m 是亮的，站进去累积曝光；这块亮斑同时也画在地上，\r\n    // 玩家能看见边界 —— 致命区不可见是最糟的设计，那叫背板不是关卡。\r\n\r\n    internal static readonly Vector2[] Lamps =\r\n    {\r\n        new Vector2(Ax0, -22f), new Vector2(Ax0, -10f),\r\n        new Vector2(Ax1, -22f), new Vector2(Ax1, -10f),\r\n        new Vector2(Ax3, -22f), new Vector2(Ax3, -10f),\r\n        new Vector2(Ax4, -22f), new Vector2(Ax4, -10f),\r\n    };\r\n\r\n    internal const float PoolHalf = 2.2f;\r\n\r\n    // ───────────────────────── 写进当前场景 ─────────────────────────\r\n\r\n    internal static void Setup()\r\n    {\r\n        NbScene.Name  = \"KITCHEN AT NIGHT\";\r\n        NbScene.Code  = \"KITCHEN\";\r\n        NbScene.Blurb = \"Six benches.  Five aisles.  Nothing keeps.\";\r\n\r\n        NbScene.XMin = XMin;\r\n        NbScene.XMax = XMax;\r\n        NbScene.ZMin = ZMin;\r\n        NbScene.ZMax = ZMax;\r\n\r\n        NbScene.Start   = Start;\r\n        NbScene.Forward = Forward;\r\n        NbScene.Targets = Spots;\r\n        NbScene.Routes  = Routes;\r\n        NbScene.MaxTargets = Spots.Length;\r\n        NbScene.MaxRoutes  = Routes.Length;\r\n    }\r\n\r\n    // ───────────────────────── 搭场景 ─────────────────────────\r\n\r\n    internal static void Build(Transform p)\r\n    {\r\n        Shell(p);\r\n        Benches(p);\r\n        Props(p);\r\n        Lamps3D(p);\r\n\r\n        Debug.LogFormat(\"[Nb] 厨房就位：{0:F0} × {1:F0} m，5 条 {2:F1} m 走道，\" +\r\n                        \"{3} 个目标点、{4} 段巡逻线、{5} 根灯管（主走道 0 根）。\",\r\n            XMax - XMin, ZMax - ZMin, AisleW, Spots.Length, Routes.Length, Lamps.Length);\r\n    }\r\n\r\n    static void Shell(Transform p)\r\n    {\r\n        // 地板（实体）。台面高 1.0，而玩家只有 0.3 —— 地面必须清楚，\r\n        // 否则在纯黑里连\"我在走道中间还是贴着台面\"都判断不了。\r\n        Nb.Box(p, \"Kitchen Floor\", new Vector3(CX, -0.20f, CZ),\r\n            new Vector3(XMax - XMin, 0.40f, ZMax - ZMin), FloorCol, true);\r\n\r\n        const float h = 3.0f, t = 0.40f;\r\n        Nb.Box(p, \"Kitchen Wall S\", new Vector3(CX, h * 0.5f, ZMin + t * 0.5f),\r\n            new Vector3(XMax - XMin, h, t), WallK, true);\r\n        Nb.Box(p, \"Kitchen Wall N\", new Vector3(CX, h * 0.5f, ZMax - t * 0.5f),\r\n            new Vector3(XMax - XMin, h, t), WallK, true);\r\n        Nb.Box(p, \"Kitchen Wall W\", new Vector3(XMin + t * 0.5f, h * 0.5f, CZ),\r\n            new Vector3(t, h, ZMax - ZMin), WallK, true);\r\n        Nb.Box(p, \"Kitchen Wall E\", new Vector3(XMax - t * 0.5f, h * 0.5f, CZ),\r\n            new Vector3(t, h, ZMax - ZMin), WallK, true);\r\n\r\n        // 天花板：只是视觉封顶（非实体），挡不住任何东西 —— 它的作用是让\"上方有东西\"这件事成立，\r\n        // 不然抬头是一片虚空，1.2 m 走道的压迫感会整个消失。\r\n        Nb.Box(p, \"Kitchen Ceiling\", new Vector3(CX, h - 0.05f, CZ),\r\n            new Vector3(XMax - XMin, 0.10f, ZMax - ZMin), new Color(0.09f, 0.09f, 0.10f), false);\r\n    }\r\n\r\n    /// 六条台面，每条切成南北两段，中间留 5 m 横通道。\r\n    static void Benches(Transform p)\r\n    {\r\n        float southLen = BenchS_Z1 - BenchS_Z0;\r\n        float southZ = (BenchS_Z0 + BenchS_Z1) * 0.5f;\r\n        float northLen = BenchN_Z1 - BenchN_Z0;\r\n        float northZ = (BenchN_Z0 + BenchN_Z1) * 0.5f;\r\n\r\n        for (int i = 0; i < BenchX.Length; i++)\r\n        {\r\n            float x = BenchX[i];\r\n\r\n            Nb.Box(p, \"Bench S\" + i, new Vector3(x, 0.50f, southZ),\r\n                new Vector3(BenchW, 1.00f, southLen), Steel, true);\r\n            Nb.Box(p, \"Bench S\" + i + \" top\", new Vector3(x, 1.03f, southZ),\r\n                new Vector3(BenchW + 0.10f, 0.06f, southLen + 0.10f), SteelTop, false);\r\n\r\n            Nb.Box(p, \"Bench N\" + i, new Vector3(x, 0.50f, northZ),\r\n                new Vector3(BenchW, 1.00f, northLen), Steel, true);\r\n            Nb.Box(p, \"Bench N\" + i + \" top\", new Vector3(x, 1.03f, northZ),\r\n                new Vector3(BenchW + 0.10f, 0.06f, northLen + 0.10f), SteelTop, false);\r\n        }\r\n    }\r\n\r\n    /// 道具：冰箱（最西）、水池（最东）、纸箱堆（横通道里，会挡路也会挡视线）。\r\n    static void Props(Transform p)\r\n    {\r\n        // 冰箱：贴着西墙，正好挡住最西走道的北段尽头\r\n        Nb.Box(p, \"Fridge\", new Vector3(XMin + 1.1f, 1.05f, -7.5f),\r\n            new Vector3(1.8f, 2.10f, 2.0f), Fridge, true);\r\n        Nb.Box(p, \"Fridge Door\", new Vector3(XMin + 2.02f, 1.10f, -7.5f),\r\n            new Vector3(0.06f, 1.80f, 1.70f), new Color(0.18f, 0.19f, 0.20f), false);\r\n\r\n        // 水池：东墙\r\n        Nb.Box(p, \"Sink\", new Vector3(XMax - 1.2f, 0.52f, -7.5f),\r\n            new Vector3(2.0f, 1.04f, 2.2f), Sink, true);\r\n        Nb.Box(p, \"Sink Rim\", new Vector3(XMax - 1.2f, 1.06f, -7.5f),\r\n            new Vector3(2.2f, 0.06f, 2.4f), SteelTop, false);\r\n\r\n        // 纸箱堆：横通道里两组，玩家横穿时必须绕 —— 也挡住横向的视线\r\n        Crates(p, 52.0f, -16.0f, 2);\r\n        Crates(p, 68.5f, -15.6f, 3);\r\n\r\n        // 地漏 / 排水沟：纯装饰，给地面一点纹理（否则一条 22 m 的长走道毫无距离感）\r\n        for (int i = 0; i < 6; i++)\r\n            Nb.Box(p, \"Drain \" + i, new Vector3(Ax2, 0.006f, -27f + i * 4.0f),\r\n                new Vector3(0.9f, 0.012f, 0.5f), Sink, false);\r\n    }\r\n\r\n    static void Crates(Transform p, float x, float z, int n)\r\n    {\r\n        for (int i = 0; i < n; i++)\r\n        {\r\n            float dx = (i % 2) * 1.3f;\r\n            float dz = (i / 2) * 1.3f;\r\n            float h = 1.0f + (i == 2 ? 0.9f : 0f);\r\n            Nb.Box(p, \"Crate \" + x + \"_\" + i, new Vector3(x + dx, h * 0.5f, z + dz),\r\n                new Vector3(1.2f, h, 1.2f), Crate, true);\r\n        }\r\n    }\r\n\r\n    /// 灯管：自发光的细长条 + 地上一块亮斑。\r\n    ///\r\n    /// **亮斑不是装饰，是判定区的可视化。** 玩家站进去会累积曝光，\r\n    /// 而那块 4.4 × 4.4 的方形亮斑就是判定的边界 —— 两者必须一样大。\r\n    /// 只做光、不做亮斑，玩家就只能靠死记位置，那这关会变成背板。\r\n    static void Lamps3D(Transform p)\r\n    {\r\n        for (int i = 0; i < Lamps.Length; i++)\r\n        {\r\n            Vector2 at = Lamps[i];\r\n\r\n            GameObject tube = GameObject.CreatePrimitive(PrimitiveType.Cube);\r\n            tube.name = \"Tube \" + i;\r\n            tube.transform.SetParent(p, false);\r\n            tube.transform.localPosition = new Vector3(at.x, 2.72f, at.y);\r\n            tube.transform.localScale = new Vector3(0.16f, 0.10f, 3.2f);\r\n            Nb.Kill(tube.GetComponent<Collider>());\r\n            Renderer tr = tube.GetComponent<Renderer>();\r\n            if (tr != null) tr.sharedMaterial = Nb.MatEmissive(Tube, 1.35f);\r\n            tube.layer = Nb.DecorLayer >= 0 ? Nb.DecorLayer : 0;\r\n\r\n            // 地面亮斑（非实体：玩家要能踩进去，只是\"被看见\"）\r\n            Nb.Box(p, \"Light Pool \" + i, new Vector3(at.x, 0.010f, at.y),\r\n                new Vector3(PoolHalf * 2f, 0.012f, PoolHalf * 2f), Pool, false);\r\n        }\r\n    }\r\n\r\n    /// 目标点是否落在某个灯管的光区里。NbGame 每帧问它一次，用来累积曝光。\r\n    internal static bool InLight(Vector3 p, int lampIndex)\r\n    {\r\n        Vector2 at = Lamps[lampIndex];\r\n        return Mathf.Abs(p.x - at.x) <= PoolHalf && Mathf.Abs(p.z - at.y) <= PoolHalf;\r\n    }\r\n}\r\n"},"NbLevels":{"path":"Assets/Scripts/NbLevels.cs","role":"Difficulty tables: 10 levels per scene (cheese/cats/speed/sight/guards/exposure/rot/door).","source":"// @role Difficulty tables: 10 levels per scene (cheese/cats/speed/sight/guards/exposure/rot/door).\r\n// @calls NbScene\r\n// @tune BiteDamage:int:1-50:health lost per catch\r\n// @tune StartHp:int:10-500:starting health\r\n// @tune Count:int:1-20:levels per scene\r\n\r\n// NbLevels.cs — 三个场景 × 10 关的难度表\r\n//\r\n// 一关 = 一组数字，没有别的。骨架四个字段三个场景共用：\r\n//   ① 场上有几个目标（= 必须带回几个）\r\n//   ② 场上有几只猫\r\n//   ③ 猫有多快（巡逻 / 追人）\r\n//   ④ 猫看多远\r\n// 后面几个字段只有对应场景才读：\r\n//   Guards / Exposure / Sweep  → 后院（保安数量、曝光速率、手电扫灯节奏）\r\n//   Rot / Lamps                → 厨房（食物腐烂秒数、亮着的灯管数）\r\n//\r\n// 速度这一列是有依据的，不是随手填的：\r\n//   玩家走着 2.30 m/s、跑着 3.91 m/s（见 NbPlayer.WalkSpeed / RunMul）。\r\n//   · 巡逻速度 **始终低于走路速度** ⇒ 正常走就能拉开，猫不是\"贴着你转的电锯\"；\r\n//   · 追击速度 **高于走路、始终低于跑步** ⇒ 被抓过一次之后必须按 Shift 才甩得掉。\r\n//   第 10 关 3.25 仍低于 3.91，所以\"跑一定能脱身\"这条底线在最后一关也成立 ——\r\n//   难度来自\"你跑不了那么久、跑的方向又是错的\"，而不是\"这游戏跑不过猫\"。\r\n//\r\n// 后院的速度比街区**低一档**：那里真正的威胁是手电，不是爪子。\r\n// 猫跑太快会让玩家只敢贴墙，而贴墙正是保安最想看到的行为。\r\n\r\nusing UnityEngine;\r\n\r\ninternal struct NbLevelCfg\r\n{\r\n    internal int No;          // 关卡号 1…10\r\n    internal int Cheese;      // 目标数 = 需要带回的数量\r\n    internal int Cats;        // 猫的数量\r\n    internal float Patrol;    // 巡逻速度 m/s\r\n    internal float Chase;     // 追击速度 m/s\r\n    internal float Sight;     // 视野距离 m\r\n\r\n    internal int Guards;      // 保安数量（后院）\r\n    internal float Exposure;  // 被手电照到时每秒累积多少曝光（后院）\r\n    internal float Sweep;     // 手电扫灯的节奏：越大转得越快、停得越短（后院）\r\n    internal float Rot;       // 食物从进关到腐烂的秒数（厨房）\r\n    internal int Lamps;       // 亮着的灯管数量（厨房）\r\n\r\n    internal float DoorGap;   // 两次开门之间隔多少秒（冰箱）\r\n    internal float DoorOpen;  // 门开着（强光灌进来）持续多少秒（冰箱）\r\n}\r\n\r\ninternal static class NbLevels\r\n{\r\n    internal const int Count = 10;\r\n\r\n    /// 每被抓一次扣多少血。100 血 ⇒ 一关之内最多被咬 10 口。\r\n    internal const int BiteDamage = 10;\r\n\r\n    internal const int StartHp = 100;\r\n\r\n    // ───────────────────────── 01 居民街区 ─────────────────────────\r\n    // 两条曲线分开走：奶酪 = 关卡数 + 1（封顶 10），猫 = 关卡数（封顶 10）。\r\n    // 两者相乘 ⇒ 第 10 关不是\"第 1 关多几只猫\"，而是\"路更长 + 可躲的道更少\"。\r\n\r\n    static readonly NbLevelCfg[] Street =\r\n    {\r\n        //  No  Cheese  Cats  Patrol  Chase  Sight\r\n        Lv( 1,    2,     1,   1.10f,  2.20f, 10f),\r\n        Lv( 2,    3,     2,   1.10f,  2.30f, 11f),\r\n        Lv( 3,    4,     3,   1.15f,  2.40f, 11f),\r\n        Lv( 4,    5,     4,   1.20f,  2.50f, 12f),\r\n        Lv( 5,    6,     5,   1.25f,  2.60f, 12f),\r\n        Lv( 6,    7,     6,   1.30f,  2.75f, 13f),\r\n        Lv( 7,    8,     7,   1.35f,  2.90f, 14f),\r\n        Lv( 8,    9,     8,   1.40f,  3.00f, 14f),\r\n        Lv( 9,   10,     9,   1.45f,  3.10f, 15f),\r\n        Lv(10,   10,    10,   1.55f,  3.25f, 16f),\r\n    };\r\n\r\n    // ───────────────────────── 02 夜巡后院 ─────────────────────────\r\n    // 这一关**没有猫**（Cats 恒为 0）：威胁全部来自手电。\r\n    // 被光扫到 0.3 秒后，那个人会以 2.55~3.45 m/s 冲过来 —— 比玩家走路（2.30）快、\r\n    // 比跑步（3.91）慢，所以\"按住 Shift 跑到 5 m 之外的掩体后面\"是唯一正确的反应。\r\n    //\r\n    // Exposure 18→38 只在**一直站在光里**时才致命（5.5 秒 → 2.6 秒）；\r\n    // 通常他会在那之前就撞上你（-10 血）。两根条各管一件事：\r\n    // 曝光条管\"别在光里站住\"，保安本人管\"别让他追到\"。\r\n    //\r\n    // Guards **从 2 起、封顶 4**。下限抬到 2 是因为\"一个人巡逻\"读不出\r\n    // \"这里有人在找东西\"——玩家只当那是一盏会动的灯。两个人才会形成\"这边扫过去、\r\n    // 那边扫过来\"的空档，而**空档正是这一关真正要玩家去读的东西**。\r\n    // 上限 4 受 patrol 路线数限制（NbGame.GuardLanes 四条），再多就得先加路线。\r\n\r\n    static readonly NbLevelCfg[] Yard =\r\n    {\r\n        //  No  Cheese  Cats  Patrol  Chase  Sight  Guards  Expo  Sweep\r\n        LvY( 1,    2,     0,   1.00f,  2.10f,  9f,     2,    18f, 0.45f),\r\n        LvY( 2,    3,     0,   1.00f,  2.20f, 10f,     2,    20f, 0.50f),\r\n        LvY( 3,    4,     0,   1.05f,  2.30f, 10f,     2,    22f, 0.58f),\r\n        LvY( 4,    5,     0,   1.05f,  2.40f, 11f,     3,    24f, 0.66f),\r\n        LvY( 5,    6,     0,   1.10f,  2.50f, 11f,     3,    26f, 0.72f),\r\n        LvY( 6,    7,     0,   1.10f,  2.60f, 12f,     3,    28f, 0.80f),\r\n        LvY( 7,    8,     0,   1.15f,  2.75f, 12f,     3,    30f, 0.90f),\r\n        LvY( 8,    9,     0,   1.15f,  2.85f, 13f,     4,    32f, 1.00f),\r\n        LvY( 9,   10,     0,   1.20f,  3.00f, 13f,     4,    34f, 1.12f),\r\n        LvY(10,   10,     0,   1.25f,  3.10f, 14f,     4,    38f, 1.25f),\r\n    };\r\n\r\n    // ───────────────────────── 03 深夜厨房 ─────────────────────────\r\n    // Rot 是这一关的独有轴：**全场食物同时开始倒计时**，所以最优解不是\"先捡最近的\"，\r\n    // 而是\"先冲最远的那块\"。60 → 26 秒的压缩，逼玩家在开局十秒内就规划完整条路线。\r\n    // Lamps 3→8：第 8 关起八根灯管全亮，五条侧走道没有一条是暗的，只剩主走道能走。\r\n\r\n    static readonly NbLevelCfg[] Kitchen =\r\n    {\r\n        //  No  Cheese  Cats  Patrol  Chase  Sight   Rot   Lamps\r\n        LvK( 1,    2,     1,   1.10f,  2.20f, 10f,    60f,   3),\r\n        LvK( 2,    3,     1,   1.10f,  2.30f, 10f,    56f,   3),\r\n        LvK( 3,    4,     2,   1.15f,  2.40f, 11f,    52f,   4),\r\n        LvK( 4,    5,     2,   1.15f,  2.50f, 11f,    48f,   5),\r\n        LvK( 5,    6,     2,   1.20f,  2.60f, 12f,    44f,   5),\r\n        LvK( 6,    7,     3,   1.20f,  2.75f, 12f,    40f,   6),\r\n        LvK( 7,    8,     3,   1.25f,  2.90f, 13f,    36f,   7),\r\n        LvK( 8,    9,     3,   1.30f,  3.00f, 13f,    32f,   8),\r\n        LvK( 9,   10,     4,   1.35f,  3.10f, 14f,    30f,   8),\r\n        LvK(10,   10,     4,   1.40f,  3.25f, 14f,    26f,   8),\r\n    };\r\n\r\n    // ───────────────────────── 03 冰箱（当前第三格） ─────────────────────────\r\n    // 这一关**没有猫**（Cats 恒为 0），唯一的威胁是门：\r\n    //   DoorGap  两次开门之间隔多久 —— 15 → 8 秒。这不是\"喘息时间\"，而是\r\n    //            \"你能连续跑几趟\"：跑完一趟（爬一层、捡两件、躲一次）大约 12 秒，\r\n    //            所以第 8 关之后，一次开门会把你正在做的事劈成两半。\r\n    //   DoorOpen 门开多久 —— 1.4 → 2.5 秒。这段时间里**只在开门那一刻判定一次**，\r\n    //            不是持续照射：玩家要么已经躲好了，要么没有，中间再冲过去不算数。\r\n    //            所以这一列实际控制的是\"你有多久不敢动\"，越长越像被钉在原地。\r\n    //\r\n    // 3 秒预警是写死的（NbGame.DoorWarnTime），不随关卡变 ——\r\n    // 它是玩家唯一能建立的条件反射，动了这个数，整关的节奏就没法靠身体记了。\r\n\r\n    static readonly NbLevelCfg[] Fridge =\r\n    {\r\n        //  No  Cheese Cats  Gap   Open     ← Gap = 两次开门之间的秒数（含 3 秒预警）\r\n        LvF( 1,   2,    0,  15.0f, 1.4f),\r\n        LvF( 2,   3,    0,  14.0f, 1.5f),\r\n        LvF( 3,   4,    0,  13.0f, 1.6f),\r\n        LvF( 4,   5,    0,  12.5f, 1.7f),\r\n        LvF( 5,   6,    0,  12.0f, 1.8f),\r\n        LvF( 6,   7,    0,  11.0f, 1.9f),\r\n        LvF( 7,   8,    0,  10.5f, 2.0f),\r\n        LvF( 8,   9,    0,  10.0f, 2.2f),\r\n        LvF( 9,  10,    0,   9.0f, 2.3f),\r\n        LvF(10,  12,    0,   8.0f, 2.5f),\r\n    };\r\n\r\n    // ───────────────────────── 工厂 ─────────────────────────\r\n\r\n    static NbLevelCfg Lv(int no, int cheese, int cats, float patrol, float chase, float sight)\r\n    {\r\n        NbLevelCfg c = new NbLevelCfg();\r\n        c.No = no; c.Cheese = cheese; c.Cats = cats;\r\n        c.Patrol = patrol; c.Chase = chase; c.Sight = sight;\r\n        c.Exposure = 0f; c.Sweep = 0f; c.Rot = 0f;\r\n        return c;\r\n    }\r\n\r\n    static NbLevelCfg LvY(int no, int cheese, int cats, float patrol, float chase, float sight,\r\n                          int guards, float exposure, float sweep)\r\n    {\r\n        NbLevelCfg c = Lv(no, cheese, cats, patrol, chase, sight);\r\n        c.Guards = guards;\r\n        c.Exposure = exposure;\r\n        c.Sweep = sweep;\r\n        return c;\r\n    }\r\n\r\n    static NbLevelCfg LvK(int no, int cheese, int cats, float patrol, float chase, float sight,\r\n                          float rot, int lamps)\r\n    {\r\n        NbLevelCfg c = Lv(no, cheese, cats, patrol, chase, sight);\r\n        c.Rot = rot;\r\n        c.Lamps = lamps;\r\n        return c;\r\n    }\r\n\r\n    static NbLevelCfg LvF(int no, int food, int cats, float gap, float open)\r\n    {\r\n        // 冰箱没有巡逻者，Patrol/Chase/Sight 一律给 0 —— 留着别的场景的默认值会让日志误导人。\r\n        NbLevelCfg c = Lv(no, food, cats, 0f, 0f, 0f);\r\n        c.DoorGap = gap;\r\n        c.DoorOpen = open;\r\n        return c;\r\n    }\r\n\r\n    // ───────────────────────── 取表 ─────────────────────────\r\n\r\n    /// 按当前场景取第 level 关。越界夹回 1…10，绝不返回空 ——\r\n    /// 这一关的所有数值都从这里出，返回空会让\"猫不生成 / 目标数为 0\"变成静默的空白关卡。\r\n    internal static NbLevelCfg Get(int level)\r\n    {\r\n        return Get(NbScene.Kind, level);\r\n    }\r\n\r\n    internal static NbLevelCfg Get(NbSceneKind kind, int level)\r\n    {\r\n        NbLevelCfg[] t = Table(kind);\r\n        int i = Mathf.Clamp(level - 1, 0, t.Length - 1);\r\n        return t[i];\r\n    }\r\n\r\n    static NbLevelCfg[] Table(NbSceneKind kind)\r\n    {\r\n        switch (kind)\r\n        {\r\n            case NbSceneKind.Yard:    return Yard;\r\n            case NbSceneKind.Kitchen: return Kitchen;\r\n            case NbSceneKind.Fridge:  return Fridge;\r\n            default:                  return Street;\r\n        }\r\n    }\r\n\r\n    internal static bool IsLast(int level)\r\n    {\r\n        return level >= Count;\r\n    }\r\n}\r\n"},"NbLighting":{"path":"Assets/Scripts/NeighbourhoodLighting.cs","role":"Re-lights the scene at night: a single moonlight key, faint fill, fog, and a night-sky clear colour.","source":"// @role Re-lights the scene at night: a single moonlight key, faint fill, fog, and a night-sky clear colour.\r\n// @calls NbScene NbFridge\r\n// @tune KeyPower:float:0-1.5:moon key light intensity\r\n// @tune FillPower:float:0-0.5:fill light intensity\r\n\r\n// NeighbourhoodLighting.cs — 把场景那套\"室内三点布光\"收成居民区夜里的一盏月光\r\n//\r\n// 为什么要有这个文件（2026-10-17 18:03 排查记录，别再拆掉）：\r\n//   现象：进游戏后 3D 区域一片纯白，HUD / 小地图正常。\r\n//   日志：相机 (70.55, 0.30, 9.50)、朝向 -z、清屏 Skybox、掩码全开、40 m 内 233 个渲染器 —— 场景是好的。\r\n//   截图：把用户那张 PNG 解码后按 4 像素采样 15950 个点，**只有一个颜色 (255,255,255)**。\r\n//   原因：场景里三盏平行光，强度 2.0 + 1.0 + 1.0，方向全部朝下（NdotL 分别 0.77 / 0.89 / 0.70），\r\n//        地面总辐照 ≈ 3.12。而 12 栋楼是 FBX 换过来的、**没有贴图的白材质**（albedo 1.0），\r\n//        1.0 × 3.12 ⇒ 三个通道全部 >1 ⇒ 被裁到 255。地砖 0.66×3.12、草地 0.48×3.12 同样爆掉。\r\n//        于是画面里没有任何边缘、阴影、纹理，全白。\r\n//        这也顺带解释了\"无法移动\"：走起来画面上没有任何变化，而小地图只有 3.46 px/m，走 1 m 才挪 3 px。\r\n//\r\n// 做法：不改场景文件（本工程的老规矩：运行时自装配），在进关卡时把灯光重排一遍 ——\r\n//   最亮那盏平行光留作主光（月光，冷色，0.62），其余降成一点点冷补光（0.07），\r\n//   环境光改成均匀的夜色，加一层深蓝雾做纵深，相机清屏换成纯色夜空。\r\n//   KeyPower 是这一关的总亮度旋钮：觉得太暗往上调，太白往下调。\r\n\r\nusing UnityEngine;\r\nusing UnityEngine.Rendering;\r\n\r\n// public：Assets/Editor 下的烘焙脚本在另一个程序集里，要调 Apply() 把夜色写进场景。\r\npublic static class NbLighting\r\n{\r\n    // ───────── 调色板 ─────────\r\n    // 现在是「入夜后的街区」（标题页那句 a residential block, after dark 就是这个调子）。\r\n    // 想改成白天：KeyPower 0.95、KeyColor 纯白 (1,1,1)、AmbCol (0.22,0.24,0.28)、\r\n    //             FogCol (0.62,0.68,0.78) + fogDensity 0.006、SkyColor (0.42,0.60,0.85)。\r\n    // 任何时候只要觉得\"太白看不出结构\"，先把 KeyPower 往下调 —— 判据是 KeyPower × albedo ≲ 1。\r\n    internal const float KeyPower = 0.62f;      // 主光（月光）\r\n    internal const float FillPower = 0.07f;     // 其余平行光：只留一点点，别让墙角死黑\r\n\r\n    static readonly Color KeyColor = new Color(0.78f, 0.85f, 1.00f);   // 冷白月光\r\n    static readonly Color FillColor = new Color(0.52f, 0.60f, 0.86f);  // 天光反射的蓝\r\n    static readonly Color SkyColor = new Color(0.026f, 0.036f, 0.062f); // 夜空（相机清屏）\r\n    static readonly Color FogCol = new Color(0.055f, 0.070f, 0.110f);\r\n    static readonly Color AmbCol = new Color(0.085f, 0.100f, 0.150f);\r\n\r\n    public static void Apply(Camera cam)\r\n    {\r\n        Apply(cam, NbSceneKind.Street);\r\n    }\r\n\r\n    /// 按场景换一套调色板。\r\n    ///   Street  0.62 —— 街区要能看清\"这条巷子里有没有猫\"，暗但可读；\r\n    ///   Yard    0.34 —— 后院故意压到几乎只剩轮廓，因为**唯一的亮源应该是保安的手电**；\r\n    ///   Kitchen 0.22 —— 室内没有月光，天花板的灯管才是光，抬到 0.6 会把它冲掉。\r\n    /// 这三个数别单独调：它们和各自场景里手电/灯管的强度是一套。\r\n    internal static void Apply(Camera cam, NbSceneKind kind)\r\n    {\r\n        float keyPower = KeyPower;\r\n        float fillPower = FillPower;\r\n        float fogDensity = 0.014f;\r\n        float sunPitch = 50f;\r\n\r\n        Color keyColor = KeyColor;\r\n        Color fillColor = FillColor;\r\n        Color skyColor = SkyColor;\r\n        Color fogCol = FogCol;\r\n        Color ambCol = AmbCol;\r\n\r\n        switch (kind)\r\n        {\r\n            case NbSceneKind.Yard:\r\n                keyPower = 0.34f;\r\n                fogDensity = 0.020f;\r\n                sunPitch = 42f;\r\n                keyColor = new Color(0.66f, 0.76f, 1.00f);\r\n                skyColor = new Color(0.014f, 0.020f, 0.038f);\r\n                fogCol = new Color(0.035f, 0.048f, 0.075f);\r\n                ambCol = new Color(0.050f, 0.060f, 0.095f);\r\n                break;\r\n\r\n            case NbSceneKind.Kitchen:\r\n                keyPower = 0.22f;\r\n                fillPower = 0.04f;\r\n                fogDensity = 0.010f;\r\n                sunPitch = 72f;\r\n                keyColor = new Color(0.72f, 0.76f, 0.82f);\r\n                fillColor = new Color(0.55f, 0.58f, 0.64f);\r\n                skyColor = new Color(0.010f, 0.010f, 0.012f);\r\n                fogCol = new Color(0.045f, 0.047f, 0.052f);\r\n                ambCol = new Color(0.060f, 0.062f, 0.072f);\r\n                break;\r\n\r\n            case NbSceneKind.Fridge:\r\n                // 冰箱关门时只有冷藏灯：冷白、几乎全直下（sunPitch 74°），\r\n                // 雾压得很浓 —— 那层雾就是\"冷气\"，它同时干掉了\"一眼看到 30 m 外\"这件事，\r\n                // 六层板才会显出层层退进去的深度。\r\n                // 环境光和 NbFridge.SetDoor 里的 AmbClosed **必须一样**：\r\n                // 两处都写这个数，是因为 SetDoor(0) 在 LoadLevel 里会把 Apply 的结果覆盖掉，\r\n                // 改一处不改另一处，会看到\"进关闪一下才变暗\"。\r\n                keyPower = 0.28f;\r\n                fillPower = 0.05f;\r\n                fogDensity = 0.032f;\r\n                sunPitch = 74f;\r\n                keyColor = new Color(0.80f, 0.88f, 1.00f);\r\n                fillColor = new Color(0.52f, 0.58f, 0.68f);\r\n                skyColor = new Color(0.008f, 0.010f, 0.014f);\r\n                fogCol = new Color(0.058f, 0.068f, 0.085f);\r\n                ambCol = new Color(0.052f, 0.058f, 0.072f);\r\n                break;\r\n        }\r\n\r\n        Light[] lights = Object.FindObjectsByType<Light>(FindObjectsInactive.Include, FindObjectsSortMode.None);\r\n\r\n        // 平行光按当前强度排序：最亮那盏当主光（保留它原来的颜色倾向之外的一切设置）\r\n        int key = -1;\r\n        float best = -1f;\r\n        int dirCount = 0;\r\n        float sumBefore = 0f;\r\n        for (int i = 0; i < lights.Length; i++)\r\n        {\r\n            Light l = lights[i];\r\n            if (l == null || l.type != LightType.Directional) continue;\r\n            dirCount++;\r\n            sumBefore += l.intensity;\r\n            if (l.intensity > best) { best = l.intensity; key = i; }\r\n        }\r\n\r\n        float sumAfter = 0f;\r\n        int fillUsed = 0;\r\n        int killed = 0;\r\n        for (int i = 0; i < lights.Length; i++)\r\n        {\r\n            Light l = lights[i];\r\n            if (l == null || l.type != LightType.Directional) continue;\r\n            if (i == key)\r\n            {\r\n                l.intensity = keyPower;\r\n                l.color = keyColor;\r\n                // 阴影不打开：楼体是薄壳模型 + 地面是多层薄板，开阴影容易出现自阴影条纹。\r\n                // 明暗已经靠\"不同朝向的面 NdotL 不同\"分开了，够读。\r\n                l.shadows = LightShadows.None;\r\n\r\n                // 方向也得给。这顶光原来几乎是**平着**照的（俯角很小）：竖着的墙面被照亮，\r\n                // 水平的路面拿不到光 ⇒ 站街上低头是一块死黑的砖、抬头是一面灰墙，\r\n                // 整个画面没有可读的明暗，走起来跟\"停在原地\"一模一样。\r\n                l.transform.rotation = Quaternion.Euler(sunPitch, 35f, 0f);\r\n            }\r\n            else if (fillUsed < 1)\r\n            {\r\n                // 只留一盏补光。以前是\"每盏都留 0.07\"，可运行时一数居然是 16 盏平行光，\r\n                // 15 × 0.07 = 1.05，光补光就把安全线 ~1.0 顶穿了（自检会一直报警）。\r\n                l.intensity = fillPower;\r\n                l.color = fillColor;\r\n                l.shadows = LightShadows.None;\r\n                fillUsed++;\r\n            }\r\n            else\r\n            {\r\n                // 其余整盏关掉：叠在一起既没人看得见，又让\"总辐照\"这个判据失效。\r\n                l.intensity = 0f;\r\n                l.enabled = false;\r\n                killed++;\r\n            }\r\n            sumAfter += l.intensity;\r\n        }\r\n\r\n        // 环境光：天空盒模式会跟着天空一起变亮，这里改成均匀夜色，亮度可控\r\n        RenderSettings.ambientMode = AmbientMode.Flat;\r\n        RenderSettings.ambientLight = ambCol;\r\n\r\n        // 雾：夜里过道尽头该化掉。指数平方，40 m 约 34%，80 m 约 81%\r\n        RenderSettings.fog = true;\r\n        RenderSettings.fogMode = FogMode.ExponentialSquared;\r\n        RenderSettings.fogColor = fogCol;\r\n        RenderSettings.fogDensity = fogDensity;\r\n\r\n        // 夜空：不要默认那个偏白的天光，纯色深蓝\r\n        if (cam != null)\r\n        {\r\n            cam.clearFlags = CameraClearFlags.SolidColor;\r\n            cam.backgroundColor = skyColor;\r\n        }\r\n\r\n        Debug.LogFormat(\"[Nb] 灯光收暗（{0}）：平行光 {1} 盏、强度合计 {2:F2} → 主光 {3:F2} + 补光 {4:F2}，其余 {5} 盏关掉；\" +\r\n                        \"环境光改夜色，雾开（{6:F3}）。合计超过 ~1.0 就会把白墙推到纯白。\",\r\n            kind, dirCount, sumBefore, keyPower, fillPower, killed, fogDensity);\r\n        Debug.LogFormat(\"[Nb] 灯光·校对 平行光强度合计现在是 {0:F2}（安全线 ≈ 1.0 以下）\", sumAfter);\r\n    }\r\n}\r\n"},"NbMap":{"path":"Assets/Scripts/NeighbourhoodMap.cs","role":"Bottom-right minimap: player arrow, cat/cheese dots, scale bar, per-scene bounds.","source":"// @role Bottom-right minimap: player arrow, cat/cheese dots, scale bar, per-scene bounds.\r\n// @calls NbGame NbScene NbCat NbCheese NbUi\r\n\r\n// NeighbourhoodMap.cs — 右下角的方形定位盘\r\n//\r\n// 显示四件事：\r\n//   ① 街区规模 —— 外框 + 右下角 20 m 比例尺 + 标题行的 \"70.9 × 81.0 m\"\r\n//   ② 自己的位置 —— 青色三角箭头，朝向取**真实位移方向**（不是相机朝向）\r\n//   ③ 敌人的位置 —— 每只猫一个红点（第 n 关 n 个），追你的时候变亮\r\n//   ④ 奶酪的位置 —— 金色小点（第 n 关 n+1 个），被捡走就消失\r\n//\r\n// 点是一次性按场地容量（10 块 / 10 只）建好的，每帧按本关实际数量开关 ——\r\n// 换关时不用重建 UI，少一个点就是\"这一关没有那只猫\"。\r\n//\r\n// 坐标映射：世界 -z 朝屏幕上方（玩家从大门进来是往\"上\"走），世界 +x 朝屏幕右方。\r\n// 所以 py 用的是 (ZMax - z)，这是全图唯一容易搞反的地方。\r\n\r\nusing System.Collections.Generic;\r\nusing TMPro;\r\nusing UnityEngine;\r\nusing UnityEngine.UI;\r\n\r\ninternal class NbMap : MonoBehaviour\r\n{\r\n    internal static NbMap I;\r\n\r\n    // 面板几何（单位：Canvas 参考像素）\r\n    const float CardW = 340f, CardH = 400f;\r\n\r\n    // 绘图区：地图内容能占的最大矩形。每个场景按自己的长宽比缩进这个框、再居中。\r\n    // 街区 71.8×81.4、后院 64×60、厨房 40×32 —— 宽高比差一倍多，用固定的 px/m\r\n    // 要么把厨房撑出面板，要么把后院缩成一个小方块。所以 K 是**算出来的**，不是常量。\r\n    const float AreaX = 35f, AreaY = 48f;\r\n    const float AreaW = 269.3f, AreaH = 305.3f;\r\n\r\n    static float MapX0 = AreaX, MapY0 = AreaY;   // 居中之后的左下角\r\n    static float K = 3.75f;                      // px per meter（Build 时重算）\r\n\r\n    static readonly Color CardBg = new Color(0.08f, 0.08f, 0.09f, 0.74f);\r\n    static readonly Color LineCol = new Color(0.86f, 0.80f, 0.66f, 0.55f);\r\n    static readonly Color BlockCol = new Color(0.62f, 0.62f, 0.64f, 0.92f);\r\n    static readonly Color CheeseCol = new Color(1.00f, 0.84f, 0.26f, 1f);\r\n    // 层号方块的配色：本层是实心金 + 近黑字，别层是暗铜 + 金字。\r\n    // 冰箱七层在俯视图上会叠成一团：全亮等于一片金点糊在中间；全暗又等于\r\n    // \"定位器上根本没有它\"。但只靠亮度分\"本层/别层\"仍然回答不了\r\n    // \"那一块在第几层\"—— 所以块里直接写层号，这一对颜色只负责强调本层。\r\n    static readonly Color ChipFarBg  = new Color(0.26f, 0.22f, 0.10f, 0.92f);\r\n    static readonly Color ChipFarInk = new Color(1.00f, 0.84f, 0.26f, 0.80f);\r\n    static readonly Color ChipInk    = new Color(0.14f, 0.10f, 0.02f, 1f);\r\n    static readonly Color CatCol = new Color(0.93f, 0.35f, 0.30f, 1f);\r\n    static readonly Color CatHotCol = new Color(1.00f, 0.18f, 0.10f, 1f);\r\n\r\n    // 后院：保安点。暖金 = 手电还亮着、在巡逻；红 = 已经看见你、正在追。\r\n    // 猫从后院删掉之后，地图上不能一个威胁都没有 —— 这一关要求玩家算\"往哪丛灌木跑 5 m\"，\r\n    // 看不见人在哪，那个计算就只能靠猜。\r\n    static readonly Color GuardCol = new Color(1.00f, 0.80f, 0.42f, 1f);\r\n    static readonly Color GuardHotCol = new Color(1.00f, 0.26f, 0.16f, 1f);\r\n    static readonly Color SelfCol = new Color(0.55f, 0.93f, 1.00f, 1f);\r\n    static readonly Color StairCol = new Color(0.34f, 0.62f, 0.78f, 0.55f);\r\n\r\n    /// 箭头追赶目标角度的速度（1/秒）。0 = 完全跟手但不平滑（快速甩鼠标会一帧跳 90°）；\r\n    /// 22 ≈ 90° 的转角 0.1 s 内走完九成 —— 看着是\"转过去\"而不是\"跳过去\"。\r\n    const float ArrowTurn = 22f;\r\n\r\n    readonly List<Image> _cheeseDots = new List<Image>();\r\n    readonly List<TextMeshProUGUI> _cheeseNums = new List<TextMeshProUGUI>();\r\n    readonly List<Image> _catDots = new List<Image>();\r\n    readonly List<Image> _guardDots = new List<Image>();\r\n    Image _self;\r\n    float _arrowAng;        // 当前箭头角度（度，0 = 屏幕正上方 = 世界 −z）\r\n    bool _arrowInit;        // 第一帧直接就位，别从 0° 转过来\r\n\r\n    internal static NbMap Create()\r\n    {\r\n        GameObject go = new GameObject(\"Neighbourhood Map (auto)\");\r\n        NbMap m = go.AddComponent<NbMap>();\r\n        m.Build();\r\n        return m;\r\n    }\r\n\r\n    void Awake()\r\n    {\r\n        I = this;\r\n    }\r\n\r\n    void OnDestroy()\r\n    {\r\n        if (I == this) I = null;\r\n    }\r\n\r\n    static Vector2 ToMap(float x, float z)\r\n    {\r\n        return new Vector2(MapX0 + (x - NbScene.XMin) * K, MapY0 + (NbScene.ZMax - z) * K);\r\n    }\r\n\r\n    // ── 场景专属地形（地图要看得出\"哪里不能走\"）──\r\n\r\n    static int DrawKitchen(RectTransform card)\r\n    {\r\n        float sLen = NbKitchen.BenchS_Z1 - NbKitchen.BenchS_Z0;\r\n        float sZ   = (NbKitchen.BenchS_Z0 + NbKitchen.BenchS_Z1) * 0.5f;\r\n        float nLen = NbKitchen.BenchN_Z1 - NbKitchen.BenchN_Z0;\r\n        float nZ   = (NbKitchen.BenchN_Z0 + NbKitchen.BenchN_Z1) * 0.5f;\r\n\r\n        int n = 0;\r\n        for (int i = 0; i < NbKitchen.BenchX.Length; i++)\r\n        {\r\n            float x = NbKitchen.BenchX[i];\r\n            n += MapRect(card, \"Bench S\" + i, x, sZ, NbKitchen.BenchW, sLen, BlockCol);\r\n            n += MapRect(card, \"Bench N\" + i, x, nZ, NbKitchen.BenchW, nLen, BlockCol);\r\n        }\r\n        return n;\r\n    }\r\n\r\n    static int DrawYard(RectTransform card)\r\n    {\r\n        int n = 0;\r\n        for (int i = 0; i < NbYard.MapCover.Length; i++)\r\n        {\r\n            Vector4 r = NbYard.MapCover[i];   // (x, z, 宽, 深) 存在 (.x, .y, .z, .w)\r\n            n += MapRect(card, \"Cover \" + i, r.x, r.y, r.z, r.w, BlockCol);\r\n        }\r\n        return n;\r\n    }\r\n\r\n    /// 冰箱：六层搁板的前沿线 + 中间那条楼梯。\r\n    ///\r\n    /// 这一支**必须存在**，否则会掉进下面的兜底分支，把街区的 12 栋楼画到冰箱的地图上 ——\r\n    /// NbColliders.Footprints 是街区留下的数据，切场景时没人清它，\r\n    /// 于是\"冰箱的平面图\"会长成一片居民区，而且不报错。\r\n    ///\r\n    /// 六条前沿线由浅到深排成一道看台，一眼就能看出\"越往上越靠里\"；\r\n    /// 中间那条竖着的亮带就是楼梯 —— 玩家在小地图上认路，靠的就是这条带。\r\n    static int DrawFridge(RectTransform card)\r\n    {\r\n        int n = 0;\r\n        float x0 = NbFridge.XMin + NbFridge.WallT;\r\n        float x1 = NbFridge.XMax - NbFridge.WallT;\r\n        float cx = (x0 + x1) * 0.5f;\r\n        float w = x1 - x0;\r\n\r\n        for (int i = 1; i <= NbFridge.Layers; i++)\r\n            n += MapRect(card, \"Shelf front L\" + i, cx, NbFridge.FrontZ(i), w, 0.12f, LineCol);\r\n\r\n        n += MapRect(card, \"Fridge back\", cx, NbFridge.ZMin + NbFridge.WallT + 0.06f, w, 0.12f, LineCol);\r\n\r\n        float sz0 = NbFridge.FrontZ(1) + NbFridge.StepsPerLayer * NbFridge.StepRun;  // 最下面一级的起点\r\n        float sz1 = NbFridge.FrontZ(NbFridge.Layers);                                // 最上面一级\r\n        n += MapRect(card, \"Stairs\",\r\n            (NbFridge.StairX0 + NbFridge.StairX1) * 0.5f, (sz0 + sz1) * 0.5f,\r\n            NbFridge.StairX1 - NbFridge.StairX0, Mathf.Abs(sz0 - sz1), StairCol);\r\n        return n;\r\n    }\r\n\r\n    static int MapRect(RectTransform card, string name, float x, float z, float w, float d, Color col)\r\n    {\r\n        Vector2 p = ToMap(x, z);\r\n        float bw = w * K, bd = d * K;\r\n        if (bw < 1f || bd < 1f) return 0;\r\n\r\n        RectTransform r = NbUi.Rect(name, card);\r\n        r.anchorMin = r.anchorMax = r.pivot = new Vector2(0f, 0f);\r\n        r.anchoredPosition = new Vector2(p.x - bw * 0.5f, p.y - bd * 0.5f);\r\n        r.sizeDelta = new Vector2(bw, bd);\r\n\r\n        Image im = r.gameObject.AddComponent<Image>();\r\n        im.sprite = NbUi.White;\r\n        im.color = col;\r\n        im.raycastTarget = false;\r\n        return 1;\r\n    }\r\n\r\n    void Build()\r\n    {\r\n        GameObject canvasGo = new GameObject(\"NbMap Canvas (auto)\", typeof(Canvas), typeof(CanvasScaler));\r\n        canvasGo.transform.SetParent(transform, false);\r\n        Canvas canvas = canvasGo.GetComponent<Canvas>();\r\n        canvas.renderMode = RenderMode.ScreenSpaceOverlay;\r\n        canvas.sortingOrder = 41;               // 压在 HUD 之上，红闪也不会盖住它\r\n\r\n        CanvasScaler scaler = canvasGo.GetComponent<CanvasScaler>();\r\n        scaler.uiScaleMode = CanvasScaler.ScaleMode.ScaleWithScreenSize;\r\n        scaler.referenceResolution = new Vector2(1920f, 1080f);\r\n        scaler.matchWidthOrHeight = 0.5f;\r\n\r\n        // 按当前场景的长宽比重算比例尺，并把地图在绘图区里居中。\r\n        // 这一步必须在**第一个 ToMap 调用之前** —— 后面的地面底色、楼块、点全都读 K。\r\n        K = Mathf.Min(AreaW / NbScene.Width, AreaH / NbScene.Depth);\r\n        MapX0 = AreaX + (AreaW - NbScene.Width * K) * 0.5f;\r\n        MapY0 = AreaY + (AreaH - NbScene.Depth * K) * 0.5f;\r\n\r\n        // ── 卡片 ──\r\n        RectTransform card = NbUi.Rect(\"Card\", canvasGo.transform);\r\n        card.anchorMin = card.anchorMax = card.pivot = new Vector2(1f, 0f);\r\n        card.anchoredPosition = new Vector2(-36f, 36f);\r\n        card.sizeDelta = new Vector2(CardW, CardH);\r\n\r\n        Image bg = card.gameObject.AddComponent<Image>();\r\n        bg.sprite = NbUi.Round;\r\n        bg.type = Image.Type.Sliced;\r\n        bg.color = CardBg;\r\n        bg.raycastTarget = false;\r\n\r\n        // ── 标题行 ──\r\n        TextMeshProUGUI title = NbUi.Text(\"Title\", card, NbScene.Code + \"  MAP\", 22f,\r\n            new Color(1f, 0.94f, 0.84f, 1f), TextAlignmentOptions.BottomLeft);\r\n        AnchorLeft(title.rectTransform, new Vector2(20f, CardH - 34f), new Vector2(200f, 26f));\r\n\r\n        TextMeshProUGUI size = NbUi.Text(\"Size\", card,\r\n            string.Format(\"{0:F1} x {1:F1} m\", NbScene.Width, NbScene.Depth), 18f,\r\n            new Color(1f, 1f, 1f, 0.55f), TextAlignmentOptions.BottomRight);\r\n        AnchorRight(size.rectTransform, new Vector2(-20f, CardH - 34f), new Vector2(200f, 24f));\r\n\r\n        // ── 地面底色（街区范围）──\r\n        Vector2 a = ToMap(NbScene.XMin, NbScene.ZMax);\r\n        Vector2 b = ToMap(NbScene.XMax, NbScene.ZMin);\r\n        RectTransform field = NbUi.Rect(\"Field\", card);\r\n        field.anchorMin = field.anchorMax = field.pivot = new Vector2(0f, 0f);\r\n        field.anchoredPosition = a;\r\n        field.sizeDelta = new Vector2(b.x - a.x, b.y - a.y);\r\n        Image fi = field.gameObject.AddComponent<Image>();\r\n        fi.sprite = NbUi.White;\r\n        // 底色是**地面**（沥青/铺装），不是草地：楼是亮块、巷道是暗底，过道一眼就能读出来。\r\n        fi.color = new Color(0.17f, 0.19f, 0.18f, 0.92f);\r\n        fi.raycastTarget = false;\r\n\r\n        // ── 楼栋：直接画 NbColliders 量到的**真实占地**（12 栋的世界 AABB）──\r\n        //\r\n        // 旧版是按「3 列 × 4 排 + 每列/每排各一个宽深」的网格画的。可这 12 栋是三种\r\n        // 不同模型混排的：实测占地是 16.9×7.7、13.1×13.2、16.9×13.1 三种，\r\n        // 而网格一律按 18.5/16.9/18.3 宽、14.4/13.2/13.2/14.7 深去画 ——\r\n        // 每块都比真正的楼大一圈，边缘压进巷道里，看起来就是\"方块和楼对不上\"。\r\n        // 现在不猜了：NbColliders 每局开头会按网格实测重算一次，这里直接照抄。\r\n        int drawn = 0;\r\n\r\n        // 后院 / 厨房没有\"楼\"，画它们自己的地形。\r\n        // 这两处的物体是运行时生成的、不进 NbColliders.Footprints，\r\n        // 但坐标全是 NbYard / NbKitchen 里的常量 —— 照着画，和 3D 里一处不差。\r\n        if (NbScene.Kind == NbSceneKind.Kitchen)\r\n        {\r\n            drawn += DrawKitchen(card);\r\n        }\r\n        else if (NbScene.Kind == NbSceneKind.Yard)\r\n        {\r\n            drawn += DrawYard(card);\r\n        }\r\n        else if (NbScene.Kind == NbSceneKind.Fridge)\r\n        {\r\n            drawn += DrawFridge(card);\r\n        }\r\n        else if (NbColliders.Footprints.Count > 0)\r\n        {\r\n            for (int i = 0; i < NbColliders.Footprints.Count; i++)\r\n            {\r\n                Bounds f = NbColliders.Footprints[i];\r\n                Vector2 p = ToMap(f.center.x, f.center.z);\r\n                float bw = f.size.x * K;\r\n                float bd = f.size.z * K;\r\n                if (bw < 1f || bd < 1f) continue;\r\n\r\n                RectTransform r = NbUi.Rect(\"Block \" + i, card);\r\n                r.anchorMin = r.anchorMax = r.pivot = new Vector2(0f, 0f);\r\n                r.anchoredPosition = new Vector2(p.x - bw * 0.5f, p.y - bd * 0.5f);\r\n                r.sizeDelta = new Vector2(bw, bd);\r\n                Image im = r.gameObject.AddComponent<Image>();\r\n                im.sprite = NbUi.White;\r\n                im.color = BlockCol;\r\n                im.raycastTarget = false;\r\n                drawn++;\r\n            }\r\n        }\r\n        else\r\n        {\r\n            // 兜底：场景里量不到楼（没有 Street Models，或校正失败）时退回网格近似 ——\r\n            // 至少地图上不是一片空地，但精度只能这样。\r\n            Debug.LogWarning(\"[Nb] 小地图：拿不到实测占地，退回网格近似 —— 方块位置可能有偏差。\");\r\n            for (int i = 0; i < Nb.Slots; i++)\r\n            {\r\n                Vector3 c = Nb.SlotCenter(i);\r\n                Vector2 p = ToMap(c.x, c.z);\r\n                float bw = Nb.ColW[i % Nb.Cols] * K;\r\n                float bd = Nb.RowD[i / Nb.Cols] * K;\r\n                RectTransform r = NbUi.Rect(\"Block \" + i, card);\r\n                r.anchorMin = r.anchorMax = r.pivot = new Vector2(0f, 0f);\r\n                r.anchoredPosition = new Vector2(p.x - bw * 0.5f, p.y - bd * 0.5f);\r\n                r.sizeDelta = new Vector2(bw, bd);\r\n                Image im = r.gameObject.AddComponent<Image>();\r\n                im.sprite = NbUi.White;\r\n                im.color = BlockCol;\r\n                im.raycastTarget = false;\r\n                drawn++;\r\n            }\r\n        }\r\n\r\n        // ── 围墙 ──\r\n        // 街区底边留大门缺口；后院和厨房是封闭空间，四边画满。\r\n        if (NbScene.Kind == NbSceneKind.Street)\r\n        {\r\n            Edge(card, Nb.XMin, Nb.ZMax, Nb.GateX0, Nb.ZMax);   // 前墙西段\r\n            Edge(card, Nb.GateX1, Nb.ZMax, Nb.XMax, Nb.ZMax);   // 前墙东段\r\n        }\r\n        else\r\n        {\r\n            Edge(card, NbScene.XMin, NbScene.ZMax, NbScene.XMax, NbScene.ZMax);\r\n        }\r\n        Edge(card, NbScene.XMin, NbScene.ZMin, NbScene.XMax, NbScene.ZMin);   // 后墙\r\n        Edge(card, NbScene.XMin, NbScene.ZMin, NbScene.XMin, NbScene.ZMax);   // 西墙\r\n        Edge(card, NbScene.XMax, NbScene.ZMin, NbScene.XMax, NbScene.ZMax);   // 东墙\r\n\r\n        // ── 奶酪点 ──\r\n        // 冰箱里是\"带层号的方块\"，别的场景是普通小点（16 px 的方块在街区图上太大）。\r\n        // 尺寸和文字都在 Update 里按场景设，这里只负责建出来。\r\n        for (int i = 0; i < NbScene.Targets.Length; i++)\r\n            _cheeseDots.Add(Chip(card, \"CheeseMark \" + i, _cheeseNums));\r\n\r\n        // ── 猫点 ──\r\n        for (int i = 0; i < NbScene.Routes.Length; i++)\r\n            _catDots.Add(Dot(card, \"CatDot \" + i, CatCol, 10f));\r\n\r\n        // ── 保安点（只有后院）──\r\n        // 建满路线容量（10），每帧按实际人数开关 —— 和猫点同一套做法。\r\n        if (NbScene.UsesGuards)\r\n            for (int i = 0; i < NbScene.Routes.Length; i++)\r\n                _guardDots.Add(Dot(card, \"GuardDot \" + i, GuardCol, 12f));\r\n\r\n        // ── 自己（三角形）──\r\n        // 锚点留在左下角（地图坐标就是从那儿算的），但**枢轴必须放中心**：\r\n        // 枢轴写在 (0,0) 时，localEulerAngles 是绕**左下角**转的 —— 箭头会一边指方向、\r\n        // 一边画一个半径 14 px 的圈。冰箱里比例尺 11 px/m，等于位置随转身抖动 ±1.3 m。\r\n        RectTransform selfRt = NbUi.Rect(\"Self\", card);\r\n        selfRt.anchorMin = selfRt.anchorMax = new Vector2(0f, 0f);\r\n        selfRt.pivot = new Vector2(0.5f, 0.5f);\r\n        selfRt.sizeDelta = new Vector2(20f, 20f);\r\n        _self = selfRt.gameObject.AddComponent<Image>();\r\n        _self.sprite = NbUi.Triangle;\r\n        _self.color = SelfCol;\r\n        _self.raycastTarget = false;\r\n\r\n        // 箭头外面加一圈深色描边，浅色草地上也能看清\r\n        RectTransform haloRt = NbUi.Rect(\"SelfHalo\", selfRt);\r\n        haloRt.anchorMin = Vector2.zero;\r\n        haloRt.anchorMax = Vector2.one;\r\n        haloRt.offsetMin = new Vector2(-2f, -2f);\r\n        haloRt.offsetMax = new Vector2(2f, 2f);\r\n        Image halo = haloRt.gameObject.AddComponent<Image>();\r\n        halo.sprite = NbUi.Triangle;\r\n        halo.color = new Color(0.05f, 0.10f, 0.12f, 0.85f);\r\n        halo.raycastTarget = false;\r\n        haloRt.SetAsFirstSibling();\r\n\r\n        BuildScaleBar(card);\r\n\r\n        // ── 图例：只有冰箱要 ──\r\n        // 一个方块里写的数字就是层号。玩家第一次看到那张图时必须**不用试错**就知道\r\n        // 这件事，否则他会把 3 读成\"这里有三块奶酪\"。\r\n        // 位置贴着绘图区上沿，不和标题行抢（冰箱的图只有 180 px 高，上面空着 70 px）。\r\n        // 文案全用 ASCII：HUD 字体是 Kindly Crunch，`·` / `→` 这类符号不一定有字形，\r\n        // 缺字形是\"静默空白\"，不会报错（见 memory）。\r\n        if (NbScene.Kind == NbSceneKind.Fridge)\r\n        {\r\n            TextMeshProUGUI lg = NbUi.Text(\"Legend\", card,\r\n                \"NUMBER = SHELF  (1 = BOTTOM)\", 14f,\r\n                new Color(1f, 1f, 1f, 0.60f), TextAlignmentOptions.BottomLeft);\r\n            AnchorLeft(lg.rectTransform, new Vector2(MapX0, MapY0 + NbScene.Depth * K + 12f),\r\n                new Vector2(280f, 18f));\r\n        }\r\n\r\n        Debug.LogFormat(\"[Nb] 小地图就位（{0}）：{1:F1} x {2:F1} m，比例尺 {3:F2} px/m，\" +\r\n                        \"地形 {4} 块，目标点 {5} 个、威胁点 {6} 个。\",\r\n            NbScene.Code, NbScene.Width, NbScene.Depth, K, drawn,\r\n            _cheeseDots.Count, _catDots.Count);\r\n    }\r\n\r\n    static void AnchorLeft(RectTransform rt, Vector2 pos, Vector2 size)\r\n    {\r\n        rt.anchorMin = rt.anchorMax = rt.pivot = new Vector2(0f, 0f);\r\n        rt.anchoredPosition = pos;\r\n        rt.sizeDelta = size;\r\n    }\r\n\r\n    static void AnchorRight(RectTransform rt, Vector2 pos, Vector2 size)\r\n    {\r\n        rt.anchorMin = rt.anchorMax = rt.pivot = new Vector2(1f, 0f);\r\n        rt.anchoredPosition = pos;\r\n        rt.sizeDelta = size;\r\n    }\r\n\r\n    /// 一格点：8~10 px 的小方块（四角略圆看不出来，直接用白图）\r\n    static Image Dot(Transform parent, string name, Color color, float px)\r\n    {\r\n        RectTransform rt = NbUi.Rect(name, parent);\r\n        rt.anchorMin = rt.anchorMax = rt.pivot = new Vector2(0f, 0f);\r\n        rt.sizeDelta = new Vector2(px, px);\r\n        Image im = rt.gameObject.AddComponent<Image>();\r\n        im.sprite = NbUi.White;\r\n        im.color = color;\r\n        im.raycastTarget = false;\r\n        return im;\r\n    }\r\n\r\n    /// 奶酪标记：16 px 的方块，中间写**层号**（1 = 底层，7 = 顶层）。\r\n    ///\r\n    /// 层号是这块地方唯一真正缺的信息。俯视图把七层压成一张，两块不同层的奶酪\r\n    /// 可能只差 9 px —— 只把别层的调暗，玩家知道\"它不在我这层\"，\r\n    /// 仍然不知道\"那是第几层\"，而这一关的全部玩法就是决定先爬哪一层。\r\n    static Image Chip(Transform parent, string name, List<TextMeshProUGUI> nums)\r\n    {\r\n        RectTransform rt = NbUi.Rect(name, parent);\r\n        rt.anchorMin = rt.anchorMax = rt.pivot = new Vector2(0f, 0f);\r\n        rt.sizeDelta = new Vector2(16f, 16f);\r\n\r\n        Image im = rt.gameObject.AddComponent<Image>();\r\n        im.sprite = NbUi.White;\r\n        im.color = CheeseCol;\r\n        im.raycastTarget = false;\r\n\r\n        TextMeshProUGUI t = NbUi.Text(\"N\", rt, \"\", 13f, ChipInk, TextAlignmentOptions.Center);\r\n        RectTransform tr = t.rectTransform;\r\n        tr.anchorMin = Vector2.zero;\r\n        tr.anchorMax = Vector2.one;\r\n        tr.offsetMin = Vector2.zero;\r\n        tr.offsetMax = Vector2.zero;\r\n\r\n        nums.Add(t);\r\n        return im;\r\n    }\r\n\r\n    // 错开时依次试的偏移（单位：自己的边长 + 1）。0 是原始位置，先试 0 再上下挪。\r\n    static readonly float[] ChipNudge = { 0f, -1f, 1f, -2f, 2f, -3f, 3f };\r\n\r\n    /// 开关一个奶酪标记。关整个 GameObject —— 数字是子物体，\r\n    /// 只关 Image 会留下一串\"没有方块的数字\"。\r\n    static void CheeseOn(Image dot, bool on)\r\n    {\r\n        if (dot.gameObject.activeSelf != on) dot.gameObject.SetActive(on);\r\n    }\r\n\r\n    /// 改变方块边长（单层场景 9 px / 冰箱 16 px）。尺寸没变就不碰 ——\r\n    /// 每帧写 sizeDelta 会让 RectTransform 一直标脏。\r\n    static void ChipSize(Image dot, float px)\r\n    {\r\n        if (!Mathf.Approximately(dot.rectTransform.sizeDelta.x, px))\r\n            dot.rectTransform.sizeDelta = new Vector2(px, px);\r\n    }\r\n\r\n    /// 把第 i 个标记放到 p（p 是投影中心），若和前面已放好的标记压在一起就上下错开。\r\n    ///\r\n    /// 实测（按 Spots 的 12 个点算）：16 px 的方块有 **1 处**正压 ——\r\n    /// (63, L2, -12) 与 (64, L4, -13) 在图上只差 9 px。那两块会叠成一个，\r\n    /// 而且留下的是后画的那个编号 ⇒ 玩家会照着错的层号白爬两层。\r\n    /// 所以这一个函数不是为了好看，是为了\"编号不会互相冒充\"。\r\n    ///\r\n    /// 每帧重算、按列表顺序扫前面的标记 ⇒ 结果稳定（不会抖），\r\n    /// 前面的那块被捡走之后后面的会自动回到原位。\r\n    void SettleChip(int i, Vector2 p, float px)\r\n    {\r\n        RectTransform rt = _cheeseDots[i].rectTransform;\r\n        float step = px + 1f;\r\n        float bx = p.x - px * 0.5f, by = p.y - px * 0.5f;\r\n\r\n        for (int k = 0; k < ChipNudge.Length; k++)\r\n        {\r\n            Vector2 q = new Vector2(bx, by + ChipNudge[k] * step);\r\n            if (!ChipBlocked(i, q, px)) { rt.anchoredPosition = q; return; }\r\n        }\r\n        rt.anchoredPosition = new Vector2(bx, by);   // 七个位置都满（不可能），认了\r\n    }\r\n\r\n    bool ChipBlocked(int i, Vector2 q, float px)\r\n    {\r\n        for (int j = 0; j < i; j++)\r\n        {\r\n            Image o = _cheeseDots[j];\r\n            if (o == null || !o.gameObject.activeSelf) continue;   // 已经被捡走的不占位\r\n            Vector2 r = o.rectTransform.anchoredPosition;\r\n            if (Mathf.Abs(q.x - r.x) < px && Mathf.Abs(q.y - r.y) < px) return true;\r\n        }\r\n        return false;\r\n    }\r\n\r\n    /// 沿世界坐标画一条边（2 px 粗）\r\n    static void Edge(Transform parent, float x0, float z0, float x1, float z1)\r\n    {\r\n        Vector2 a = ToMap(x0, z0);\r\n        Vector2 b = ToMap(x1, z1);\r\n        RectTransform rt = NbUi.Rect(\"Edge\", parent);\r\n        rt.anchorMin = rt.anchorMax = rt.pivot = new Vector2(0f, 0f);\r\n        rt.anchoredPosition = new Vector2(Mathf.Min(a.x, b.x) - 1f, Mathf.Min(a.y, b.y) - 1f);\r\n        rt.sizeDelta = new Vector2(Mathf.Abs(b.x - a.x) + 2f, Mathf.Abs(b.y - a.y) + 2f);\r\n        Image im = rt.gameObject.AddComponent<Image>();\r\n        im.sprite = NbUi.White;\r\n        im.color = LineCol;\r\n        im.raycastTarget = false;\r\n    }\r\n\r\n    void BuildScaleBar(Transform card)\r\n    {\r\n        // 20 m 的比例尺，画在地图下沿的留白里\r\n        float len = 20f * K;\r\n        RectTransform bar = NbUi.Rect(\"ScaleBar\", card);\r\n        bar.anchorMin = bar.anchorMax = bar.pivot = new Vector2(0f, 0f);\r\n        bar.anchoredPosition = new Vector2(MapX0, 18f);\r\n        bar.sizeDelta = new Vector2(len, 3f);\r\n        Image bi = bar.gameObject.AddComponent<Image>();\r\n        bi.sprite = NbUi.White;\r\n        bi.color = new Color(1f, 1f, 1f, 0.65f);\r\n        bi.raycastTarget = false;\r\n\r\n        // 两端竖线\r\n        for (int i = 0; i < 2; i++)\r\n        {\r\n            RectTransform tick = NbUi.Rect(\"Tick\" + i, card);\r\n            tick.anchorMin = tick.anchorMax = tick.pivot = new Vector2(0f, 0f);\r\n            tick.anchoredPosition = new Vector2(MapX0 + (i == 0 ? 0f : len) - 1f, 14f);\r\n            tick.sizeDelta = new Vector2(2f, 11f);\r\n            Image ti = tick.gameObject.AddComponent<Image>();\r\n            ti.sprite = NbUi.White;\r\n            ti.color = new Color(1f, 1f, 1f, 0.65f);\r\n            ti.raycastTarget = false;\r\n        }\r\n\r\n        TextMeshProUGUI label = NbUi.Text(\"ScaleLabel\", card, \"20 m\", 16f,\r\n            new Color(1f, 1f, 1f, 0.62f), TextAlignmentOptions.BottomLeft);\r\n        AnchorLeft(label.rectTransform, new Vector2(MapX0 + len + 8f, 13f), new Vector2(120f, 20f));\r\n    }\r\n\r\n    // ───────────────────────── 每帧 ─────────────────────────\r\n\r\n    void Update()\r\n    {\r\n        NbGame g = NbGame.I;\r\n        if (g == null) return;\r\n\r\n        // 奶酪：捡走就灭点（掉在地上时会重新亮，位置也跟着变）\r\n        //\r\n        // **多出来的点必须显式关掉。** 点是按场地容量（10 块 / 10 只）一次性建好的，\r\n        // 而第 1 关只有 2 块奶酪 —— 不关的话左下角会永远挂着 8 个不动的点，\r\n        // 看着像\"奶酪掉在墙外/地图外\"。这个循环因此遍历**所有**点，而不是只遍历到 Count。\r\n        //\r\n        // 关的是 **GameObject**，不是 Image 组件：标记里的数字是子物体，\r\n        // 只关 Image 的话方块没了、数字还留在原处 —— 看起来像地图上飘着一串 3。\r\n        //\r\n        // 多层场景（冰箱）里，\"我在第几层\"只算一次，然后每个标记自己比。\r\n        bool multi = NbScene.KeepsHeight;\r\n        int myShelf = (multi && g.Player != null) ? NbFridge.ShelfOf(g.Player.position.y) : 0;\r\n\r\n        for (int i = 0; i < _cheeseDots.Count; i++)\r\n        {\r\n            Image dot = _cheeseDots[i];\r\n            if (dot == null) continue;\r\n\r\n            if (i >= g.Cheeses.Count) { CheeseOn(dot, false); continue; }\r\n\r\n            NbCheese c = g.Cheeses[i];\r\n            if (c == null) { CheeseOn(dot, false); continue; }\r\n\r\n            // 冰箱是多层的：地图是俯视投影，七层的点全落在同一张图上。\r\n            //\r\n            // 旧版只显示**玩家脚下这一层**的目标 —— 结果玩家站在 L2 时，L5 那两块奶酪在\r\n            // 定位器上根本不存在，他能看见的只有手边一两块，\"定位器\"等于没用。\r\n            // 再往后是\"全部显示、只靠亮度分层\"：玩家知道它不在我这层，\r\n            // 但仍然不知道**它在第几层** —— 而这一关的策略就是决定先爬哪层。\r\n            //\r\n            // 所以现在每个标记里直接写层号，本层实心金、别层暗铜。\r\n            // 位置仍然是投影坐标 ⇒ \"它在我哪个方向\"照样读得对。\r\n            bool on = !c.Taken;\r\n            CheeseOn(dot, on);\r\n            if (!on) continue;\r\n\r\n            Vector2 p = ToMap(c.transform.position.x, c.transform.position.z);\r\n            TextMeshProUGUI num = (i < _cheeseNums.Count) ? _cheeseNums[i] : null;\r\n\r\n            // 单层场景（街区/后院/厨房）：退回普通小点，不写数字。\r\n            if (!multi)\r\n            {\r\n                if (num != null) num.text = \"\";\r\n                dot.color = CheeseCol;\r\n                ChipSize(dot, 9f);\r\n                dot.rectTransform.anchoredPosition = new Vector2(p.x - 4.5f, p.y - 4.5f);\r\n                continue;\r\n            }\r\n\r\n            int shelf = NbFridge.ShelfOf(c.transform.position.y);\r\n            bool here = shelf == myShelf;\r\n\r\n            dot.color = here ? CheeseCol : ChipFarBg;\r\n            if (num != null)\r\n            {\r\n                num.text = shelf.ToString();\r\n                num.color = here ? ChipInk : ChipFarInk;\r\n            }\r\n            ChipSize(dot, 16f);\r\n            SettleChip(i, p, 16f);\r\n        }\r\n\r\n        // 猫：同上，第 n 关只亮前 n 个点\r\n        for (int i = 0; i < _catDots.Count; i++)\r\n        {\r\n            Image dot = _catDots[i];\r\n            if (dot == null) continue;\r\n\r\n            if (i >= g.Cats.Count) { if (dot.enabled) dot.enabled = false; continue; }\r\n\r\n            NbCat c = g.Cats[i];\r\n            if (c == null) { if (dot.enabled) dot.enabled = false; continue; }\r\n\r\n            if (!dot.enabled) dot.enabled = true;\r\n            Vector2 p = ToMap(c.transform.position.x, c.transform.position.z);\r\n            dot.rectTransform.anchoredPosition = new Vector2(p.x - 5f, p.y - 5f);\r\n            dot.color = c.IsChasing ? CatHotCol : CatCol;\r\n        }\r\n\r\n        // 保安点：同上，按实际人数开关；追人的那一个变红。\r\n        // 它同时是\"5 m\"这件事的参照物 —— 玩家看地图上的距离远比在黑暗里目测可靠。\r\n        for (int i = 0; i < _guardDots.Count; i++)\r\n        {\r\n            Image dot = _guardDots[i];\r\n            if (dot == null) continue;\r\n\r\n            if (i >= g.Guards.Count || g.Guards[i] == null)\r\n            {\r\n                if (dot.enabled) dot.enabled = false;\r\n                continue;\r\n            }\r\n\r\n            if (!dot.enabled) dot.enabled = true;\r\n            Vector3 gp = g.Guards[i].transform.position;\r\n            Vector2 p = ToMap(gp.x, gp.z);\r\n            dot.rectTransform.anchoredPosition = new Vector2(p.x - 6f, p.y - 6f);\r\n            dot.color = g.Guards[i].Chasing ? GuardHotCol : GuardCol;\r\n        }\r\n\r\n        // 自己：位置 + 箭头朝向\r\n        if (_self != null && g.Player != null)\r\n        {\r\n            Vector3 pos = g.Player.position;\r\n            Vector2 p = ToMap(pos.x, pos.z);\r\n            // 枢轴在中心 ⇒ 这里直接给中心坐标（旧版按\"中心对齐\"减了半个边长，\r\n            // 但枢轴其实是角，减出来的位置只在 0° 时是对的）。\r\n            _self.rectTransform.anchoredPosition = p;\r\n\r\n            // 箭头 = 身体朝向。站着只转鼠标，它也要跟着转。\r\n            Vector3 h = g.Heading;\r\n            if (h.sqrMagnitude < 1e-4f) h = NbScene.Forward;\r\n\r\n            // 屏幕上方 = 世界 −z，所以是 Atan2(−x, −z)：\r\n            // 朝 −z ⇒ 0°（正上），朝 +x ⇒ −90°（转成顺时针 90°，指向右）。\r\n            float want = Mathf.Atan2(-h.x, -h.z) * Mathf.Rad2Deg;\r\n\r\n            // 按**角度**插值，不按向量。向量插值在两个方向接近相反时走哪边不确定，\r\n            // 旧代码只好用 Dot<0 直接跳过去 —— 快速环视时能看见箭头\"啪\"地掉一格。\r\n            // DeltaAngle 自动取最短弧，跨 ±180 也是连续的。\r\n            if (!_arrowInit) { _arrowAng = want; _arrowInit = true; }\r\n            float step = Mathf.Clamp01(ArrowTurn * Time.unscaledDeltaTime);\r\n            _arrowAng = Mathf.Repeat(_arrowAng + Mathf.DeltaAngle(_arrowAng, want) * step, 360f);\r\n            _self.rectTransform.localEulerAngles = new Vector3(0f, 0f, _arrowAng);\r\n        }\r\n    }\r\n}\r\n"},"NbMode":{"path":"Assets/Scripts/NeighbourhoodGame.cs","role":"Neighbourhood game manager: builds the scene, runs the 10-level loop, spawns cheese/cats/guards, resolves win/loss.","source":"// @role Neighbourhood game manager: builds the scene, runs the 10-level loop, spawns cheese/cats/guards, resolves win/loss.\r\n// @calls NbScene NbLevels NbBuilder NbPlayer NbGuard NbCat NbCheese NbHud NbMap NbLighting NbFridge NbFood NbFoodArt NbColliders NbBriefing NbSceneSelect AudioManager\r\n// @tune DoorWarnTime:float:1-6:fridge door-open warning seconds\r\n// @tune CatHeight:float:0.5-3:cat height m (feeds cat body probe scale)\r\n\r\n// NeighbourhoodGame.cs — 居民区关卡：10 关，猫和奶酪一起变多，被抓一次 -10 血\r\n//\r\n// 装配方式沿用本工程的老规矩：运行时自己 new 出所有物体，场景文件一行不改。\r\n//   ① 读你在场景里摆好的出生点（旧 FirstPersonController 的位置，只要在围墙以内）\r\n//   ② 搭环境（NbBuilder）\r\n//   ③ NbPlayer.Spawn 造一个**全新的**玩家（自带身体和相机；旧的那个整个关掉）\r\n//   ④ 按 NbLevels 的表装载第 1 关：摆 N 块奶酪、放 M 只猫\r\n//   ⑤ 建 HUD（含生命条）与方形小地图\r\n//\r\n// 关卡之间的差别只有四个数（奶酪数 / 猫数 / 猫速 / 视野），全部在 NbLevels.cs 里；\r\n// 这里负责的是**换关**：清掉上一关的物体、按新数字重摆一遍、血补满、人回出生点。\r\n// 血被咬光就停在失败面板上，按 R 重打本关；集满就是过关，按 R 进下一关。\r\n//\r\n// 玩家不再是\"场景里那个 FirstPersonController + 运行时补的组件\"，而是 NbPlayer.cs 里\r\n// 自己 new 出来的一个物体 —— 旧的任何一处被拖错/改坏都不会再传导到这一关。\r\n//\r\n// 猫的模型/奶酪模型都复用 Resources/GameProps 里现成的资源，以及 CatCheeseSetup 里\r\n// 已经调通过的「按网格实测归一化 + 贴地 + 按骨骼定朝向」那套工具。\r\n//\r\n// 旧玩法（猫吃奶酪）由 CatCheeseGame.cs 里的 `if (NbMode.Enabled) return;` 让位，\r\n// 把 Enabled 改成 false 就能完整回到旧关卡。\r\n\r\nusing System.Collections;\r\nusing System.Collections.Generic;\r\nusing UnityEngine;\r\nusing UnityEngine.InputSystem;\r\n\r\ninternal static class NbMode\r\n{\r\n    // 必须是 static readonly 而不是 const —— const 会让旧脚本里 `if (Enabled) return;`\r\n    // 后面的代码被判成不可达（CS0162），整个工程编不过。\r\n    internal static readonly bool Enabled = true;\r\n}\r\n\r\ninternal class NbGame : MonoBehaviour\r\n{\r\n    internal static NbGame I;\r\n\r\n    internal Transform Root;\r\n    internal Transform Player;       // 新玩家的身体（原点在脚底）\r\n    internal NbPlayer Rig;           // 新玩家本体：相机、眼高、俯仰都在它身上\r\n\r\n    internal int Collected;\r\n    internal bool Finished;\r\n    internal bool Won;\r\n    internal bool Failed;                                    // 血被咬光（和 Won 互斥）\r\n\r\n    // ── 关卡与生命 ──\r\n    internal int Level = 1;                                  // 当前关卡 1…NbLevels.Count\r\n    internal int Hp;                                         // 生命值 0…MaxHp\r\n    internal int MaxHp = NbLevels.StartHp;                    // 100：一关最多被咬 10 口\r\n    internal int CheeseNeeded = 1;                            // 本关要带回的奶酪数（= 场上奶酪数）\r\n    internal int CatCount;                                    // 本关猫数（HUD 显示用）\r\n\r\n    internal float Invuln;          // 被抓后的无敌时间\r\n    internal float Flash;           // 红闪强度 1 → 0\r\n    internal string Toast = \"\";\r\n    internal float ToastT;\r\n    internal float Speed;                                  // 实测水平速度 m/s（读数条与小地图共用）\r\n    internal Vector3 Heading = new Vector3(0f, 0f, -1f);   // 小地图箭头：身体朝向（静止时也会变）\r\n\r\n    internal readonly List<NbCheese> Cheeses = new List<NbCheese>();\r\n    internal readonly List<NbCat> Cats = new List<NbCat>();\r\n    internal readonly List<NbCheese> Held = new List<NbCheese>();\r\n    internal readonly List<NbGuard> Guards = new List<NbGuard>();\r\n\r\n    // ── 后院：曝光值 ──\r\n    // 0…100。被手电照到时按 cfg.Exposure 累积，脱离后按 32/s 回落。满 100 = 被抓一次。\r\n    // 用\"累积 + 回落\"而不是参考图里那句 \"eliminate after fixed amount of time\"：\r\n    // 后者在 1.2 m 走道 + 18 m 光锥下会变成\"路过就死\"，而累积式允许玩家\"快速冲过光斑\"。\r\n    // 这是有意偏离，不是漏做。\r\n    internal float Exposure;\r\n\r\n    /// 现在有没有保安在追你。HUD 拿它决定要不要亮那行 \"SPOTTED / SHIFT TO RUN\"。\r\n    internal bool Chased;\r\n\r\n    /// 这个时间点之前不要弹追击/脱身的提示（刚被撞的那两秒）。\r\n    float _quietUntil;\r\n\r\n    // ── 厨房：新鲜度 ──\r\n    // RotLeft 是**全场共用的**一根条：进关开始跑，到 0 时所有还没捡的食物一起烂掉。\r\n    // 共用而不是每块一个计时，是因为玩家在同一屏里要读的是\"我还有多久\"，不是十个数字。\r\n    internal float RotLeft;\r\n    internal float RotTotal;\r\n    internal bool Rotted;\r\n\r\n    // ── 冰箱：门 ──\r\n    // 门是这一关唯一会\"动\"的东西，所以它得有三个可读状态：关门 / 预警（3 s）/ 开着。\r\n    // **只在开门后 0.45 秒判一次**，不是持续照射 —— 玩家要么已经躲好，要么没有；\r\n    // 中途再冲过去不算数。持续判定会把\"擦着门缝跑\"这种走位全判死，\r\n    // 而这一关的层高只有 0.51 m，玩家根本没有绕的余地。\r\n    internal const float DoorWarnTime = 3.0f;    // 预警时长：写死，不随关卡变（见 NbLevels.Fridge）\r\n    internal float DoorT;                        // 距下次开门\r\n    float _doorGap;                              // 本关的间隔（MeterUpdate 要拿它算比例）\r\n    float _doorOpenFor;                          // 本关开门时长\r\n    float _doorOpenLeft;                         // 门还开着多久\r\n    bool  _doorHit;                              // 这一次开门是否已经判过\r\n    bool  _doorWarned;                           // 这一次预警是否已经播报过\r\n    float _doorVisual;                           // 门的视觉开合 0…1（平滑，不跟状态机硬跳）\r\n\r\n    Vector3 _lastPos;\r\n\r\n    // 移动看门狗：只在\"按着键却一步没动\"时报警一次。\r\n    // 上一轮\"满屏纯白 + 无法移动\"排查时最缺的就是这个 —— 光看日志根本分不清是没输入、被卡住，\r\n    // 还是画面全白导致看不出在动。\r\n    float _holdT = -1f;\r\n    Vector3 _holdPos;\r\n    bool _movedOnce;\r\n\r\n    [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]\r\n    static void Bootstrap()\r\n    {\r\n        if (!NbMode.Enabled) return;\r\n        if (UnityEngine.SceneManagement.SceneManager.GetActiveScene().name != \"SampleScene\") return;\r\n        if (I != null) return;\r\n        new GameObject(\"Neighbourhood Game (auto)\").AddComponent<NbGame>();\r\n    }\r\n\r\n    void Awake()\r\n    {\r\n        I = this;\r\n    }\r\n\r\n    void OnDestroy()\r\n    {\r\n        if (I == this) I = null;\r\n    }\r\n\r\n    void Start()\r\n    {\r\n        StartCoroutine(Boot());\r\n    }\r\n\r\n    IEnumerator Boot()\r\n    {\r\n        yield return null;          // 让标题页等其它 Bootstrap 先跑完一帧\r\n\r\n        // 把\"当前场景\"写进 NbScene 那组字段（第一次是街区，之后由场景选择页改 Kind）。\r\n        // 这一步必须在 Build / ResolveSpawn 之前 —— 它们全都从这里读边界和出生点。\r\n        NbScene.Select(NbScene.Kind);\r\n\r\n        // 出生点：优先用你已经在场景里摆好的那个位置（只要它落在本场景的场地以内）\r\n        Vector3 spawn;\r\n        float spawnYaw;\r\n        ResolveSpawn(out spawn, out spawnYaw);\r\n\r\n        Root = new GameObject(\"World \" + NbScene.Code).transform;\r\n        NbScene.Build(Root);\r\n\r\n        // 冰箱：把你自己导进来的三个食物包摆进去当商品（纯装饰、无碰撞体）。\r\n        // 必须在 Build 之后 —— 每个位置都是按 NbFridge 的层高 / 前沿算出来的。\r\n        if (NbScene.UsesDoor) NbFoodArt.DecorateFridge(Root);\r\n\r\n        // 12 栋楼是编辑器脚本换的模型，碰撞体在那个脚本里算错过一次（转置），\r\n        // 这里按网格本地包围盒重算一遍。后院/厨房没有这 12 栋楼，跑它只会白扫一遍场景。\r\n        if (NbScene.Kind == NbSceneKind.Street) NbColliders.Normalize();\r\n\r\n        // 造玩家。这一句之后：场景里那个 FirstPersonController 被整个关掉，\r\n        // 场上只剩一台相机 —— 就是玩家的眼睛。身体和相机都是新造的，不复用场景里的任何东西。\r\n        Rig = NbPlayer.Spawn(spawn, spawnYaw);\r\n        Player = Rig.transform;\r\n        // 冰箱是**走楼梯**上去的（每层 4 级、每级 0.14 m），所以台阶上限要从 0.08 抬到 0.20。\r\n        // 为什么给到 0.20 而不是刚好 0.14：CharacterController 上台阶靠的是\"先抬高再前推\"，\r\n        // 留 0.06 的余量才不会在帧率抖动的那一帧被判成\"前面是墙\"（表现是偶发地被台阶顶住）。\r\n        // 冰箱里唯一比 0.20 矮的竖直面就是台阶本身，所以抬高了也不会多爬上去什么。\r\n        // 其它场景必须**显式**设回 0.08 —— 不设的话会带着 0.20 在街上\"爬\"上路缘和奶酪，\r\n        // 而 0.20 这个数看不出任何异常，只是人会莫名其妙地蹬上花坛。\r\n        Rig.SetStepUp(NbScene.UsesDoor ? 0.20f : 0.08f);\r\n        _home = spawn;\r\n        _homeRot = Quaternion.Euler(0f, spawnYaw, 0f);\r\n        Heading = _homeRot * Vector3.forward;\r\n        _lastPos = spawn;\r\n\r\n        // 场景里三盏平行光叠出约 3.1 倍辐照，而楼体是没有贴图的白材质 ⇒ 不重排布光就满屏纯白\r\n        NbLighting.Apply(Rig.Cam, NbScene.Kind);\r\n\r\n        // 门光必须在 Apply **之后**造：Apply 会把场上最亮的平行光当主光、其余全部关掉，\r\n        // 而门光平时 intensity = 0 —— 它先存在的话会被判成\"无关的平行光\"直接 disabled，\r\n        // 之后怎么抬强度都不亮。道理写在 NbFridge.CreateDoorLight 的注释里。\r\n        if (NbScene.UsesDoor) NbFridge.CreateDoorLight(Root);\r\n\r\n        // HUD / 小地图先建好，再装载第 1 关 —— 反过来的话，装载时那些 \"HideEnd\" 之类的刷新\r\n        // 会静默打空（NbHud.I 还是 null），失败/过关面板的初始状态就没人负责了。\r\n        if (NbHud.I == null) NbHud.Create();\r\n        if (NbMap.I == null) NbMap.Create();\r\n\r\n        LoadLevel(1);\r\n\r\n        // 冰箱：先讲规则再放人。它同时会冻结玩家和**门**（DoorUpdate 里第一句就 return）——\r\n        // 只冻玩家不冻门的话，玩家读完规则的第一秒就是门开的时候。\r\n        if (NbScene.UsesDoor) NbBriefing.Show();\r\n\r\n        Debug.LogFormat(\"[Nb] 开局：玩家出生在 ({0:F1}, {1:F1})，共 {2} 关。\", _home.x, _home.z, NbLevels.Count);\r\n\r\n        StartCoroutine(SelfCheck());\r\n    }\r\n\r\n    // ───────────────────────── 自检 ─────────────────────────\r\n    // 只回答一个问题：标题页收起之后，相机到底站在哪、眼前有没有东西。\r\n    // 上面那行「玩家出生在 (...)」打印的是常量 Nb.PlayerStart，是「打算」不是「结果」——\r\n    // 玩家被别的东西挪走时它照样报得漂亮，所以必须回读 Player.position 本身。\r\n\r\n    IEnumerator SelfCheck()\r\n    {\r\n        // 不再用 `while (Time.timeScale < 0.01f)` 等标题页 —— 标题页万一一直没关，\r\n        // 那一行会让**所有诊断一起消失**，从日志上看到的就只是\"什么都没有发生\"。\r\n        // 现在按真实时间等，并且把\"世界还冻着\"这件事本身报出来。\r\n        yield return new WaitForSecondsRealtime(0.6f);\r\n        if (Player == null || Rig == null) yield break;\r\n\r\n        if (CatCheeseTitle.Showing)\r\n            Debug.LogWarning(\"[Nb] 自检：标题页还挡在前面（世界冻在 timeScale=0）。点画面 / 按任意键，或等 12 秒自动开始。\");\r\n\r\n        Vector3 drift = Player.position - _home;\r\n        drift.y = 0f;\r\n        Debug.LogFormat(\"[Nb] 自检·玩家实际位置 ({0:F2}, {1:F2}, {2:F2})，离出生点 {3:F2} m\",\r\n            Player.position.x, Player.position.y, Player.position.z, drift.magnitude);\r\n\r\n        // 以前这里会把玩家强行拽回出生点 —— 那等于「在 Play 里把他挪到想看的地方」直接做不到，\r\n        // 而且会把「开机时其实有东西推了他」这条线索一起抹掉。现在只报告，不动手。\r\n        if (drift.magnitude > 5f)\r\n            Debug.LogWarningFormat(\"[Nb] 玩家离出生点 {0:F1} m —— 是自己挪的就忽略；不是的话，说明开机时被什么东西推了。\",\r\n                drift.magnitude);\r\n\r\n        Camera cam = Rig != null ? Rig.Cam : null;\r\n        if (cam == null)\r\n        {\r\n            Debug.LogError(\"[Nb] 玩家相机为空 —— 画面必然是空的。\");\r\n            yield break;\r\n        }\r\n\r\n        Debug.LogFormat(\"[Nb] 自检·相机 位置 ({0:F2}, {1:F2}, {2:F2})，朝向 ({3:F2}, {4:F2}, {5:F2})，启用 {6}，清屏 {7}，FOV {8}，掩码 0x{9:X}\",\r\n            cam.transform.position.x, cam.transform.position.y, cam.transform.position.z,\r\n            cam.transform.forward.x, cam.transform.forward.y, cam.transform.forward.z,\r\n            cam.enabled, cam.clearFlags, cam.fieldOfView, cam.cullingMask);\r\n\r\n        Collider[] nearby = Physics.OverlapSphere(cam.transform.position, 0.08f, ~0, QueryTriggerInteraction.Ignore);\r\n        Debug.LogFormat(\"[Nb] 自检·相机位置被 {0} 个碰撞体占着{1}\", nearby.Length,\r\n            nearby.Length > 0 ? \"：\" + string.Join(\", \", System.Array.ConvertAll(nearby, c => c.name)) : \"（正常，没卡在墙里）\");\r\n\r\n        // 输入链：键盘设备在不在、移动脚本开着没、世界冻着没 —— 这三样任何一样不对，\r\n        // 表现都是\"走不动\"，但修法完全不同，所以先分开报。\r\n        Debug.LogFormat(\"[Nb] 自检·输入 键盘={0} 鼠标={1} 光标={2} 可操作={3} timeScale={4:F2} 重力={5:F2} \" +\r\n                        \"CC.enabled={6} 眼高={7:F2} Pitch={8:F0}° 实测速度={9:F2}\",\r\n            Keyboard.current != null, Mouse.current != null, Cursor.lockState,\r\n            Rig != null && Rig.AcceptInput, Time.timeScale, Physics.gravity.y,\r\n            Rig != null && Rig.Cc != null && Rig.Cc.enabled,\r\n            Rig != null && Rig.Cam != null ? Rig.Cam.transform.position.y - Rig.transform.position.y : -1f,\r\n            Rig != null ? Rig.Pitch : 0f, Speed);\r\n\r\n        Renderer[] rends = Object.FindObjectsByType<Renderer>(FindObjectsSortMode.None);\r\n        int within = 0;\r\n        Renderer closest = null;\r\n        float best = float.MaxValue;\r\n        for (int i = 0; i < rends.Length; i++)\r\n        {\r\n            if (rends[i] == null) continue;\r\n            float d = (rends[i].bounds.center - cam.transform.position).sqrMagnitude;\r\n            if (d < 1600f) within++;\r\n            if (d < best) { best = d; closest = rends[i]; }\r\n        }\r\n        Debug.LogFormat(\"[Nb] 自检·渲染器 全场 {0} 个，相机 40 m 内 {1} 个；最近「{2}」{3:F1} m\",\r\n            rends.Length, within, closest != null ? closest.name : \"无\",\r\n            closest != null ? Mathf.Sqrt(best) : -1f);\r\n\r\n        // 灯光合计：这一项 >1 时，白材质（换模型之后楼体就是白材质）会整片裁到 255 —— 满屏纯白。\r\n        // 所以它不是\"美术参数\"，是\"能不能看见\"的判据。\r\n        Light[] lights = Object.FindObjectsByType<Light>(FindObjectsSortMode.None);\r\n        int dirN = 0;\r\n        float dirSum = 0f;\r\n        for (int i = 0; i < lights.Length; i++)\r\n        {\r\n            if (lights[i] == null || lights[i].type != LightType.Directional) continue;\r\n            dirN++;\r\n            dirSum += lights[i].intensity;\r\n        }\r\n        Debug.LogFormat(\"[Nb] 自检·灯光 平行光 {0} 盏、强度合计 {1:F2}（>1 会把白墙推到纯白）；\" +\r\n                        \"环境光 {2:F2} 均匀色，雾 {3}，相机清屏 {4}\",\r\n            dirN, dirSum, RenderSettings.ambientLight.grayscale, RenderSettings.fog, cam.clearFlags);\r\n        if (dirSum > 1.3f)\r\n            Debug.LogWarning(\"[Nb] 平行光强度合计大于 1.3 —— 白材质会被裁到纯白，检查 NbLighting 有没有跑。\");\r\n\r\n        Canvas[] canvases = Object.FindObjectsByType<Canvas>(FindObjectsSortMode.None);\r\n        for (int i = 0; i < canvases.Length; i++)\r\n        {\r\n            Canvas cv = canvases[i];\r\n            Debug.LogFormat(\"[Nb] 自检·Canvas「{0}」order={1} mode={2} 子物体 {3} 个\",\r\n                cv.name, cv.sortingOrder, cv.renderMode, cv.transform.childCount);\r\n        }\r\n\r\n        if (within == 0)\r\n            Debug.LogError(\"[Nb] 相机 40 m 内一个渲染器都没有 —— 相机不在这片街区里，画面空白跟材质无关。\");\r\n\r\n        ProbeCamera();\r\n    }\r\n\r\n    /// 判据：**镜头正前方到底是什么**。\r\n    /// 这里不能用 Physics.Raycast —— Nb.Style 把装饰物（过道、树、灯、围墙压顶）的碰撞体全删了，\r\n    /// 射线会直接穿过去，报\"前面什么都没有\"，而我们明明贴着一面墙。\r\n    /// 所以改用 Renderer.bounds.IntersectRay：不问物理，直接问\"这条视线上有哪些东西的包围盒\"。\r\n    void ProbeCamera()\r\n    {\r\n        Camera cam = Rig != null ? Rig.Cam : null;\r\n        if (cam == null) return;\r\n        Vector3 p = cam.transform.position;\r\n        Ray ray = new Ray(p, cam.transform.forward);\r\n\r\n        Renderer[] all = Object.FindObjectsByType<Renderer>(FindObjectsSortMode.None);\r\n        Renderer f1 = null, f2 = null, f3 = null;\r\n        float d1 = float.MaxValue, d2 = float.MaxValue, d3 = float.MaxValue;\r\n        int inside = 0;\r\n        string insideNames = \"\";\r\n\r\n        for (int i = 0; i < all.Length; i++)\r\n        {\r\n            Renderer r = all[i];\r\n            if (r == null || !r.enabled) continue;\r\n            if (Player != null && r.transform.IsChildOf(Player)) continue;\r\n\r\n            Bounds b = r.bounds;\r\n            if (b.Contains(p))\r\n            {\r\n                inside++;\r\n                if (insideNames.Length < 160)\r\n                    insideNames += (insideNames.Length > 0 ? \", \" : \"\") + r.name;\r\n            }\r\n\r\n            float hit;\r\n            if (!b.IntersectRay(ray, out hit)) continue;\r\n            if (hit < d1) { d3 = d2; f3 = f2; d2 = d1; f2 = f1; d1 = hit; f1 = r; }\r\n            else if (hit < d2) { d3 = d2; f3 = f2; d2 = hit; f2 = r; }\r\n            else if (hit < d3) { d3 = hit; f3 = r; }\r\n        }\r\n\r\n        Debug.LogFormat(\"[Nb] 自检·正前方最靠前的三样东西：{0} | {1} | {2}\",\r\n            f1 != null ? string.Format(\"{0:F2} m「{1}」包围盒尺寸({2:F1},{3:F1},{4:F1})\",\r\n                d1, f1.name, f1.bounds.size.x, f1.bounds.size.y, f1.bounds.size.z) : \"无\",\r\n            f2 != null ? string.Format(\"{0:F2} m「{1}」\", d2, f2.name) : \"无\",\r\n            f3 != null ? string.Format(\"{0:F2} m「{1}」\", d3, f3.name) : \"无\");\r\n\r\n        Debug.LogFormat(\"[Nb] 自检·相机被 {0} 个渲染器的包围盒包着{1}\", inside,\r\n            inside > 0 ? \"：\" + insideNames : \"（正常）\");\r\n\r\n        // 再补一条**物理射线**版本。上面那套用的是 `Renderer.bounds.IntersectRay`，\r\n        // 而它对\"射线起点就在盒子内部\"是直接返回 false 的 —— 也就是说，**镜头正贴着一面墙时它报\"无\"**。\r\n        // 这个盲区让上一轮的\"整屏一块平涂色\"被误判成\"前方 14 m 才有东西\"。用射线+碰撞体再问一遍。\r\n        if (cam != null)\r\n        {\r\n            RaycastHit[] hits = Physics.RaycastAll(cam.transform.position, cam.transform.forward, 60f, ~0, QueryTriggerInteraction.Ignore);\r\n            System.Array.Sort(hits, (a, b) => a.distance.CompareTo(b.distance));\r\n            var sb = new List<string>();\r\n            for (int i = 0; i < hits.Length && sb.Count < 3; i++)\r\n            {\r\n                if (hits[i].collider == null) continue;\r\n                if (Player != null && hits[i].collider.transform.root == Player.root) continue;\r\n                sb.Add(string.Format(\"{0:F2} m「{1}」\", hits[i].distance, hits[i].collider.name));\r\n            }\r\n            Debug.LogFormat(\"[Nb] 自检·视线上的碰撞体（60 m 内）：{0}\",\r\n                sb.Count == 0 ? \"一个都没有 —— 前面是空的\" : string.Join(\" | \", sb.ToArray()));\r\n        }\r\n\r\n        if (f1 != null && d1 < 1.0f)\r\n            Debug.LogErrorFormat(\"[Nb] 镜头 1 m 内就顶着「{0}」—— 除 HUD 外整屏都会是它，跟走不走得动无关。\", f1.name);\r\n        if (inside > 0)\r\n            Debug.LogErrorFormat(\"[Nb] 相机站在 {0} 个物体的包围盒内部（{1}）—— 看到的是它们的背面，整屏一片平涂色。\", inside, insideNames);\r\n    }\r\n\r\n    // ───────────────────────── 出生点 ─────────────────────────\r\n\r\n    /// 本局真正的出生点（脚底坐标）：开机时定一次，之后重开都回这里。\r\n    /// **不能写成 `= Nb.PlayerStart`** —— 字段初始化器在类型加载时跑，那时 NbScene 还没 Select，\r\n    /// 读到的永远是街区坐标，换到后院就会被送回街区正中。Boot 里赋值。\r\n    Vector3 _home = Vector3.zero;\r\n    Quaternion _homeRot = Quaternion.identity;\r\n\r\n    /// 出生点对猫来说是一块「安全区」：玩家可以把它摆在任意位置，而纵向通道 A 那只猫的\r\n    /// 巡逻线正好从街区正中穿过 —— 人只要站那儿，就会被反复扑。\r\n    internal Vector3 Home { get { return _home; } }\r\n\r\n    /// 决定出生点：**优先用你在场景里摆好的那个位置**（只要它落在围墙以内）。\r\n    ///\r\n    /// 这里读的是场景里那个旧玩家 `FirstPersonController` 的 Transform —— 它马上就会被\r\n    /// NbPlayer.Spawn 整个关掉，但\"你摆在哪、朝哪\"这个信息必须先取出来用掉。\r\n    void ResolveSpawn(out Vector3 feet, out float yaw)\r\n    {\r\n        Transform old = NbPlayer.FindScenePlayer();\r\n        if (old != null)\r\n        {\r\n            Vector3 p = old.position;\r\n            // 判据换成**当前场景**的边界。换到后院/厨房之后，这个位置几乎必然落在场外，\r\n            // 于是自动退回 NbScene.Start —— 不用为每个场景单独写一份出生点解析。\r\n            if (NbScene.Inside(p, 1f))\r\n            {\r\n                feet = new Vector3(p.x, 0.12f, p.z);\r\n                yaw = old.eulerAngles.y;\r\n                Debug.LogFormat(\"[Nb] 出生点用你在场景里摆的位置 ({0:F2}, {1:F2})，朝向 {2:F0}°。\",\r\n                    feet.x, feet.z, yaw);\r\n                return;\r\n            }\r\n            Debug.LogFormat(\"[Nb] 场景里的旧玩家在 ({0:F2}, {1:F2}, {2:F2})，不在本场景场地内 ⇒ 出生点改用 {3} 的设定位置 ({4:F1}, {5:F1})。\",\r\n                p.x, p.y, p.z, NbScene.Code, NbScene.Start.x, NbScene.Start.z);\r\n        }\r\n        else\r\n        {\r\n            Debug.LogFormat(\"[Nb] 场景里找不到 FirstPersonController —— 出生点用 {0} 的设定位置。\", NbScene.Code);\r\n        }\r\n\r\n        feet = NbScene.Start;\r\n        yaw = Quaternion.LookRotation(NbScene.Forward, Vector3.up).eulerAngles.y;\r\n    }\r\n\r\n    internal void PlacePlayer() { PlacePlayer(_home, _homeRot); }\r\n\r\n    /// 归位：走 NbPlayer.Teleport（关-改-开 CharacterController，否则位置会被它吃掉），\r\n    /// 同时俯仰归零、贴地。旧版那一整套 DetachPlayer / EnsureStanding / HideOwnBody 全部作废了 ——\r\n    /// 新玩家是自己 new 出来的根物体、缩放 1、身上只有 CharacterController，没有\"被拖错\"的余地。\r\n    internal void PlacePlayer(Vector3 at, Quaternion rot)\r\n    {\r\n        if (Rig == null) return;\r\n        Rig.Teleport(at, rot.eulerAngles.y);\r\n        _lastPos = Rig.transform.position;\r\n        Heading = rot * Vector3.forward;\r\n    }\r\n\r\n    // ───────────────────────── 关卡装载 ─────────────────────────\r\n\r\n    /// 装载第 n 关：清掉上一关的奶酪和猫，按 NbLevels 的表重新摆一遍，血补满，人回出生点。\r\n    ///\r\n    /// 没有\"场景重载\"这一步是刻意的 —— 关卡之间只有四个数字不同，重建 12 栋楼和 160 个装饰\r\n    /// 既慢又会把玩家已经熟悉的地标重排一遍。这里只换**会变的东西**：奶酪、猫、计数、血。\r\n    internal void LoadLevel(int n)\r\n    {\r\n        Level = Mathf.Clamp(n, 1, NbLevels.Count);\r\n        NbLevelCfg cfg = NbLevels.Get(Level);\r\n\r\n        ClearProps();\r\n\r\n        Hp = MaxHp;\r\n        Failed = false;\r\n        Finished = false;\r\n        Won = false;\r\n        Collected = 0;\r\n        Invuln = 3.0f;                  // 开场缓冲：先让你看清这一关的街道，再让猫动起来\r\n        Flash = 0f;\r\n        Toast = \"LEVEL \" + Level;\r\n        ToastT = 2.6f;\r\n\r\n        SpawnCheese(cfg.Cheese);\r\n        SpawnCats(cfg);\r\n        SpawnGuards(cfg);\r\n\r\n        Exposure = 0f;\r\n        Chased = false;\r\n        _quietUntil = 0f;\r\n        RotTotal = Mathf.Max(1f, cfg.Rot);\r\n        RotLeft  = RotTotal;\r\n        Rotted   = false;\r\n\r\n        // 冰箱的门从头开始计时：每关都给你完整的第一段安全时间，\r\n        // 否则\"上一关刚好开着门\"会带进新一关，玩家一进来就被照。\r\n        _doorGap     = Mathf.Max(4f, cfg.DoorGap);\r\n        _doorOpenFor = Mathf.Max(0.8f, cfg.DoorOpen);\r\n        DoorT        = _doorGap;\r\n        _doorOpenLeft = 0f;\r\n        _doorHit      = false;\r\n        _doorWarned   = false;\r\n        _doorVisual   = 0f;\r\n        if (NbScene.UsesDoor) NbFridge.SetDoor(0f);\r\n\r\n        if (Rig != null)\r\n        {\r\n            PlacePlayer();              // 回出生点：每关都从头开始，不吃上一关的站位便宜\r\n            Rig.AcceptInput = true;\r\n            Rig.LockCursor();\r\n        }\r\n        if (NbHud.I != null) NbHud.I.HideEnd();\r\n\r\n        Debug.LogFormat(\"[Nb] 第 {0}/{1} 关：{2} 块奶酪（全要带回）、{3} 只猫；\" +\r\n                        \"猫速 巡逻 {4:F2} / 追击 {5:F2}，视野 {6:F0} m；生命 {7}/{8}。\",\r\n            Level, NbLevels.Count, CheeseNeeded, CatCount, cfg.Patrol, cfg.Chase, cfg.Sight, Hp, MaxHp);\r\n    }\r\n\r\n    /// 删掉上一关的奶酪、光晕、猫。用 Nb.Kill：编辑模式下 Destroy 是不生效的\r\n    /// （会刷一条 \"Destroy may not be called from edit mode!\" 而物体还在）。\r\n    void ClearProps()\r\n    {\r\n        for (int i = 0; i < Cheeses.Count; i++)\r\n        {\r\n            NbCheese c = Cheeses[i];\r\n            if (c == null) continue;\r\n            if (c.Halo != null) Nb.Kill(c.Halo.gameObject);   // 光晕挂在 Root 下，不是奶酪的子物体\r\n            Nb.Kill(c.gameObject);\r\n        }\r\n        Cheeses.Clear();\r\n        Held.Clear();\r\n\r\n        for (int i = 0; i < Cats.Count; i++)\r\n            if (Cats[i] != null) Nb.Kill(Cats[i].gameObject);\r\n        Cats.Clear();\r\n\r\n        for (int i = 0; i < Guards.Count; i++)\r\n            if (Guards[i] != null) Nb.Kill(Guards[i].gameObject);\r\n        Guards.Clear();\r\n    }\r\n\r\n    // ───────────────────────── 奶酪 ─────────────────────────\r\n\r\n    /// 只摆前 count 个奶酪点。Nb.CheeseSpots 已按\"离出生点由近到远\"排好序，\r\n    /// 所以前几关的奶酪就在家门口，第 9、10 关才要横穿整个街区。\r\n    void SpawnCheese(int count)\r\n    {\r\n        // 街区 / 后院：场上摆几块就要求带回几块（\"全部带回\"）。\r\n        // 厨房：摆满容量，只要求带回 count 块 —— 多出来的几块是**腐烂的缓冲**。\r\n        // 少了这个缓冲，第 10 关只要有一条走道被猫堵住就必死，那不叫难度，那叫死局。\r\n        int n = NbScene.UsesRot\r\n            ? Mathf.Clamp(NbScene.MaxTargets, 1, NbScene.Targets.Length)\r\n            : Mathf.Clamp(count, 1, NbScene.Targets.Length);\r\n\r\n        CheeseNeeded = NbScene.UsesRot ? Mathf.Clamp(count, 1, n) : n;\r\n\r\n        for (int i = 0; i < n; i++)\r\n        {\r\n            Vector3 spot = NbScene.Targets[i];\r\n\r\n            // 冰箱的每个目标点**自带层高**（y 就是那一层板的顶面）；其它场景全场 y=0，\r\n            // 贴地只是保险（铺装层之间有 3~4 cm 高差）。\r\n            // 这里必须是 KeepsHeight 而不是\"总是 Grounded\" —— 后者会把六层的点全压回 y=0，\r\n            // 整关塌成一层，而且不报错。\r\n            Vector3 at = NbScene.KeepsHeight ? spot : Nb.Grounded(spot);\r\n\r\n            GameObject go;\r\n\r\n            // **四个场景的目标物统一是奶酪。** 冰箱以前摆的是几何体瓜果蔬菜，\r\n            // 现在那批东西只当装饰（NbFoodArt 装真模型），目标回归成\"把奶酪带回去\"。\r\n            go = CatCheeseSetup.SpawnModel(\"GameProps/Cheese_0001_LOD0\",\r\n                new Color(0.95f, 0.78f, 0.20f), \"Cheese \" + (i + 1));\r\n            CatCheeseSetup.WireCheeseTexture(go);\r\n\r\n            if (NbScene.UsesDoor)\r\n            {\r\n                // 冰箱：y 由奶酪点自己带着（那一层的板顶），所以只做归一化 + 坐实，\r\n                // **不能**走 FitAndGround —— 它向下打射线取\"最低\"那个面，\r\n                // 六层的奶酪会被一路穿到最底层的地板上，整关塌成一层而且不报错。\r\n                // 也不挂碰撞体：冰箱里没有猫，而 0.34 高的盒子在 0.51 净空的层里\r\n                // 只会把人从奶酪旁边顶开（这是当年街区改用 IgnoreCollision 的同一个理由）。\r\n                Seat(go, 0.34f, at);\r\n            }\r\n            else\r\n            {\r\n                CatCheeseSetup.FitAndGround(go, 0.34f, at, \"奶酪 \" + (i + 1));\r\n                // 实体碰撞体：必须在缩放/贴地之后加，尺寸才对得上模型。\r\n                // 奶酪有 0.34 高，而玩家现在只有 0.30 高、台阶上限 8 cm —— 不豁免的话\r\n                // 老鼠会被一块奶酪硬生生挡在过道里（而且离得够近就自动捡走了，根本不该撞上）。\r\n                // 真正需要这个碰撞体的是猫：NbCat.Steer 靠它\"看见\"奶酪并绕开。\r\n                Collider chCol = CatCheeseSetup.AddSolidBoxCollider(go);\r\n                if (chCol != null && Rig != null && Rig.Cc != null)\r\n                    Physics.IgnoreCollision(Rig.Cc, chCol, true);\r\n            }\r\n\r\n            // 脚下的光晕单独放在世界空间：食物/奶酪根节点的缩放被改过，\r\n            // 挂在它下面会让光晕跟着一起缩放、还随它一起转。\r\n            // y 跟着所在层走 —— 冰箱里如果还写死 0.055，六层的光晕会全掉到底层地板上。\r\n            GameObject halo = Nb.Cyl(Root, \"Cheese Halo \" + (i + 1),\r\n                new Vector3(at.x, at.y + 0.014f, at.z), 1.15f, 0.012f, new Color(1f, 0.86f, 0.32f), false);\r\n\r\n            NbCheese c = go.AddComponent<NbCheese>();\r\n            c.Index = i;\r\n            c.Halo = halo.transform;\r\n            Cheeses.Add(c);\r\n        }\r\n    }\r\n\r\n    /// 把模型\"坐到\"一个**已知高度**上：按目标高度归一化 → 底面落在 at.y → 水平中心对到 at.xz。\r\n    /// 和 CatCheeseSetup.FitAndGround 的唯一区别是**不找地面**，y 由调用方给。\r\n    /// 冰箱必须这样：FitAndGround 向下打射线并取**最低**那个命中面（它当初是为了避开天花板，\r\n    /// 在\"一整块地面\"的街区里是对的），放进六层的冰箱就会把每块奶酪都穿到最底层的地板上 ——\r\n    /// 而且一条警告都不会打。\r\n    static void Seat(GameObject go, float height, Vector3 at)\r\n    {\r\n        Bounds b;\r\n        if (CatCheeseSetup.TryMeasureWorldBounds(go, out b) && b.size.y > 1e-5f)\r\n            go.transform.localScale *= height / b.size.y;\r\n\r\n        if (!CatCheeseSetup.TryMeasureWorldBounds(go, out b))\r\n        {\r\n            go.transform.position = at;\r\n            return;\r\n        }\r\n\r\n        Vector3 p = go.transform.position;\r\n        p.x += at.x - b.center.x;\r\n        p.z += at.z - b.center.z;\r\n        p.y += at.y - b.min.y;\r\n        go.transform.position = p;\r\n    }\r\n\r\n    // ───────────────────────── 猫 ─────────────────────────\r\n\r\n    /// 猫的高度。玩家是 0.16 m 眼高（NbPlayer.EyeHeight）的老鼠，猫必须够大才成立：\r\n    /// 0.95 m 高、体长约 1.8 m —— 站在 5.1 m 宽的过道里就是一辆堵路的车，\r\n    /// 抬头看它的时候，头和肩膀会顶到画面外。这个数字和眼高是一套比例，别单独改。\r\n    internal const float CatHeight = 0.95f;\r\n\r\n    /// 摆前 cfg.Cats 只猫，速度/视野全部按这一关的表给。\r\n    /// 路线是**按段切开**的（见 Nb.CatRoutes），前 n 条互不重叠，所以猫多起来也不会叠在一起走。\r\n    void SpawnCats(NbLevelCfg cfg)\r\n    {\r\n        // 下限从 1 改成 0：冰箱那一关**一只猫都没有**（用户明确要求），\r\n        // 而 Clamp(x, 1, …) 会把 0 悄悄变成 1 —— 一只凭空出现的猫站在冰箱里，还不报错。\r\n        int n = Mathf.Clamp(cfg.Cats, 0, Mathf.Max(0, NbScene.Routes.Length));\r\n        CatCount = n;\r\n\r\n        if (n <= 0)\r\n        {\r\n            Debug.Log(\"[Nb] 本场景没有猫。\");\r\n            return;\r\n        }\r\n\r\n        for (int i = 0; i < n; i++)\r\n        {\r\n            Vector3[] route = NbScene.Routes[i];\r\n            GameObject cat = CatCheeseSetup.SpawnModel(\"GameProps/Cat walk\",\r\n                new Color(0.16f, 0.12f, 0.10f), \"Cat \" + (i + 1) + \" (auto)\");\r\n            CatCheeseSetup.OrientCatByBones(cat, Vector3.forward);\r\n            Bounds box = CatCheeseSetup.FitAndGround(cat, CatHeight, Nb.Grounded(route[0]), \"猫 \" + (i + 1));\r\n            CatCheeseSetup.PlayWalkAnimation(cat);\r\n\r\n            NbCat c = cat.AddComponent<NbCat>();\r\n            c.Route = route;\r\n            c.Speed = cfg.Patrol;\r\n            c.ChaseSpeed = cfg.Chase;\r\n            c.SightDist = cfg.Sight;\r\n            // 扫掠/视线/抓人距离全部按**实测体型**给：猫从 0.5 m 长到 0.95 m 高以后，\r\n            // 还沿用写死的 0.17 半径 = 猫的鼻子能捅进墙里、爪子却有半个身子够不到人。\r\n            c.ConfigureBody(box, CatHeight);\r\n\r\n            // 后院最后一只改成**埋伏**：蹲在路线上不动、也不巡逻，玩家进 2.5 m 才起身。\r\n            // 参考里的 \"Cat ambush: some cats will hide in the dark and sneakily attack players\r\n            // when they are not paying attention.\" —— 它惩罚的是\"低头看小地图\"的那两秒。\r\n            c.Ambush = NbScene.UsesGuards && i == n - 1;\r\n\r\n            Cats.Add(c);\r\n        }\r\n    }\r\n\r\n    /// 保安的**地盘**段号（巡逻区和猫共用 NbScene.Routes 这套路线）。\r\n    /// 现在保安不再沿线段来回走，而是拿这条线段当轴线、在两侧 ±7 m 的带子里随机游走\r\n    /// （见 NbGuard.PickWaypoint）—— 所以这里挑的是\"谁守哪一带\"，不是\"他走哪条线\"。\r\n    ///\r\n    /// 选段的理由没变：1 号沿空地北缘、5 号横穿空地南缘、2 号直穿空地中央 ——\r\n    /// 三条正好把\"必须横穿的那块空地\"封成三层；3 号是西侧纵线，第 4 关起加进来，\r\n    /// 让西半边也有灯在走（前三条都压在中轴和东西横线上，西侧一直是个稳定的暗角）。\r\n    ///\r\n    /// **顺序是有约束的：2 号必须排在最后。** 它的起点 (72, −46) 离玩家出生点 (72, −54)\r\n    /// 只有 8 m，而手电射程 18 m、中途没有遮挡 —— 它一旦上场，玩家一出生就站在光里。\r\n    /// （游走本来也不许进出生点 8 m 内，但那只是兜底，不是可以松掉这条约束的理由。）\r\n    /// 所以让它在第 8 关（4 人）才出现，前七关都不在。这条约束别在调顺序时弄丢。\r\n    static readonly int[] GuardLanes = { 1, 5, 3, 2 };\r\n\r\n    void SpawnGuards(NbLevelCfg cfg)\r\n    {\r\n        int n = Mathf.Clamp(cfg.Guards, 0, GuardLanes.Length);\r\n\r\n        // 追人速度：2.55 → 3.45。**上限必须低于玩家跑步 3.91** —— 那是这一关唯一的解，\r\n        // 也是整个游戏对玩家唯一的承诺（按住 Shift 一定跑得掉）。\r\n        float chase = Mathf.Lerp(2.55f, 3.45f, (Level - 1) / (float)Mathf.Max(1, NbLevels.Count - 1));\r\n\r\n        for (int i = 0; i < n; i++)\r\n        {\r\n            int lane = GuardLanes[i] % NbScene.Routes.Length;\r\n            NbGuard g = NbGuard.Spawn(Root, NbScene.Routes[lane], 0.95f, cfg.Sweep, cfg.Exposure, chase);\r\n            Guards.Add(g);\r\n        }\r\n\r\n        if (n > 0)\r\n        {\r\n            // 路线号按**实际上场人数**拼：写死 3 个下标的话，队伍一扩就会漏报第 4 条，\r\n            // 而日志是排查\"为什么某条路线上没人\"的唯一线索。\r\n            string lanes = \"\";\r\n            for (int i = 0; i < n; i++) lanes += (i == 0 ? \"\" : \"/\") + GuardLanes[i];\r\n\r\n            Debug.LogFormat(\"[Nb] 保安 {0} 名（地盘 {1}），手电 18 m、半角 11°、扫灯节奏 {2:F2}；\" +\r\n                            \"在自己的地盘里随机游走（航点 5~16 m、到点站住 1~3 秒环顾），\" +\r\n                            \"曝光 {3:F0}/s ⇒ 站在光里 {4:F1} 秒被抓；被照到会以 {5:F2} m/s 追人\" +\r\n                            \"（玩家跑步 3.91）。\",\r\n                n, lanes, cfg.Sweep, cfg.Exposure, 100f / Mathf.Max(1f, cfg.Exposure), chase);\r\n        }\r\n    }\r\n\r\n    // ───────────────────────── 每帧 ─────────────────────────\r\n\r\n    void Update()\r\n    {\r\n        var kb = Keyboard.current;\r\n\r\n        // 先把\"能不能动\"的三个开关钉一遍，再谈玩法（标题页期间会自动跳过）\r\n        EnsurePlayable();\r\n\r\n        if (Finished)\r\n        {\r\n            // 过关 / 失败都停在这里等一个 R：过关进下一关，失败重打本关，通关之后从第 1 关重来。\r\n            // 不自动跳关是刻意的 —— 被抓死和过关都用同一块面板，自动推进会让\"我刚才是不是死了\"\r\n            // 变成一个需要回想的问题。\r\n            if (kb != null && kb.rKey.wasPressedThisFrame) NextOrRetry();\r\n            return;\r\n        }\r\n        if (Player == null) return;\r\n\r\n        if (Invuln > 0f) Invuln -= Time.deltaTime;\r\n        if (Flash > 0f) Flash = Mathf.Max(0f, Flash - Time.deltaTime * 1.6f);\r\n        if (ToastT > 0f) ToastT -= Time.deltaTime;\r\n\r\n        TrackHeading();\r\n        CollectCheck();\r\n        ThreatUpdate();\r\n        MoveWatchdog(kb);\r\n    }\r\n\r\n    // ───────────────────────── 场景专属威胁 ─────────────────────────\r\n\r\n    void ThreatUpdate()\r\n    {\r\n        if (NbScene.UsesGuards) GuardUpdate();\r\n        if (NbScene.UsesRot)    RotUpdate();\r\n        if (NbScene.UsesDoor)   DoorUpdate();\r\n        MeterUpdate();\r\n    }\r\n\r\n    /// 底部那根条每帧刷一次。颜色本身就是读数：\r\n    /// 曝光 金 → 红（越红越接近被抓），新鲜度 绿 → 红（越红越快烂完）。\r\n    void MeterUpdate()\r\n    {\r\n        NbHud hud = NbHud.I;\r\n        if (hud == null) return;\r\n\r\n        if (NbScene.UsesGuards)\r\n        {\r\n            float t = Mathf.Clamp01(Exposure / 100f);\r\n            hud.SetMeter(\"EXPOSURE\", t,\r\n                Color.Lerp(new Color(1f, 0.84f, 0.35f), new Color(1f, 0.30f, 0.22f), t));\r\n        }\r\n        else if (NbScene.UsesRot)\r\n        {\r\n            float t = RotTotal > 0f ? Mathf.Clamp01(RotLeft / RotTotal) : 0f;\r\n            hud.SetMeter(\"FRESH\", t,\r\n                Color.Lerp(new Color(0.92f, 0.25f, 0.20f), new Color(0.55f, 0.82f, 0.42f), t));\r\n        }\r\n        else if (NbScene.UsesDoor)\r\n        {\r\n            // 三种读数：门正开着 / 3 秒预警（条在倒数）/ 平时（条是\"距下次开门\"的比例）。\r\n            // 预警和平时分开，是因为这两件事对玩家的含义完全不同 ——\r\n            // 平时那条是\"我还能跑多久\"，预警那条是\"我还能跑几步\"。\r\n            if (_doorOpenLeft > 0f)\r\n            {\r\n                hud.SetMeter(\"DOOR  OPEN  -  STAY  DOWN\", 1f, new Color(1f, 0.95f, 0.78f));\r\n                AudioManager.PlaySound(SoundType.hum, 0.6f);\r\n            }\r\n            else if (DoorT <= DoorWarnTime)\r\n            {\r\n                float t = Mathf.Clamp01(DoorT / DoorWarnTime);\r\n                hud.SetMeter(\"DOOR  IN  \" + Mathf.CeilToInt(Mathf.Max(0f, DoorT)) + \"  -  HIDE\", t,\r\n                    Color.Lerp(new Color(1f, 0.26f, 0.18f), new Color(1f, 0.88f, 0.42f), t));\r\n            }\r\n            else\r\n            {\r\n                float t = _doorGap > 0.1f ? Mathf.Clamp01(DoorT / _doorGap) : 0f;\r\n                hud.SetMeter(\"NEXT  DOOR  \" + Mathf.CeilToInt(DoorT), t,\r\n                    new Color(0.56f, 0.80f, 1f));\r\n            }\r\n        }\r\n        else\r\n        {\r\n            hud.SetMeter(null, 0f, Color.white);\r\n        }\r\n    }\r\n\r\n    /// 后院：把这一帧\"有没有人看见我\"折成一个曝光值。\r\n    ///\r\n    /// 为什么是累积而不是\"进光就死\"：光锥 18 m 长、保安还在扫，玩家经常会**擦着光斑边缘**跑过去。\r\n    /// 一刀切的判定会把这种走位全部判死，逼人只敢贴墙 —— 而贴墙正是保安最喜欢的行为。\r\n    /// 累积 + 每秒 32 的回落，等于告诉玩家：冲过去可以，但别停。\r\n    void GuardUpdate()\r\n    {\r\n        if (Finished) return;\r\n\r\n        float rate = 0f;\r\n        bool chasing = false;\r\n        for (int i = 0; i < Guards.Count; i++)\r\n        {\r\n            NbGuard g = Guards[i];\r\n            if (g == null) continue;\r\n            if (g.Chasing) chasing = true;\r\n            // 被抓后的 3 秒无敌里，光也不该继续烧血\r\n            if (g.Sees && Invuln <= 0f) rate += g.Damage;\r\n        }\r\n\r\n        // 从\"没人发现\"变成\"被追\"的那一帧要把话说明白。\r\n        // 玩家第一次的本能是继续走（2.30 m/s），而追他的人比走路快 ——\r\n        // 所以这行提示不是装饰，是机制的一部分：SHIFT 是唯一的解。\r\n        bool was = Chased;\r\n        if (chasing != was)\r\n        {\r\n            if (chasing)\r\n            {\r\n                if (Time.time >= _quietUntil)\r\n                {\r\n                    Toast = \"SPOTTED  -  SHIFT  TO  RUN\";\r\n                    ToastT = 2.2f;\r\n                    Debug.Log(\"[Nb] 被手电照到：保安开始追击。跑到 5 m 之外的掩体后面才能脱身。\");\r\n                }\r\n            }\r\n            else if (Time.time >= _quietUntil)\r\n            {\r\n                Toast = \"YOU LOST HIM\";\r\n                ToastT = 1.6f;\r\n                Debug.Log(\"[Nb] 甩掉了保安：光被掩体挡住且距离 5 m 以上。\");\r\n            }\r\n        }\r\n        Chased = chasing;\r\n\r\n        if (rate > 0f)\r\n        {\r\n            Exposure = Mathf.Min(100f, Exposure + rate * Time.deltaTime);\r\n            if (Exposure >= 100f) BustedByGuard();\r\n        }\r\n        else\r\n        {\r\n            Exposure = Mathf.Max(0f, Exposure - 32f * Time.deltaTime);\r\n        }\r\n    }\r\n\r\n    /// 被追到（保安撞上你）。和\"站在光里被烧满\"分开结算：\r\n    ///   · 被撞：立刻 -10，所有人回路线起点 —— 否则他会在原地继续顶着你，无敌一过又抓一次；\r\n    ///   · 烧满：也是 -10，但那是\"你站着不动\"的结果，人不用被搬走。\r\n    /// 玩家留在原地（不传送）：院子太大，传送会让人彻底失去方位感。\r\n    internal void CaughtByGuard(NbGuard g)\r\n    {\r\n        if (Finished || Invuln > 0f) return;\r\n\r\n        Invuln = 3.0f;\r\n        Flash = 1f;\r\n        Exposure = 0f;\r\n        Hp = Mathf.Max(0, Hp - NbLevels.BiteDamage);\r\n\r\n        // 接下来两秒别再弹 \"YOU LOST HIM\" —— 人刚被撞，说\"甩掉了\"是在骗人。\r\n        _quietUntil = Time.time + 2.5f;\r\n\r\n        Toast = \"CAUGHT  BY  THE  PATROL\";\r\n        ToastT = 2.4f;\r\n\r\n        if (Rig != null) Rig.Nudge(g != null ? g.transform.position : Player.position - Player.forward, 1.8f);\r\n        for (int i = 0; i < Guards.Count; i++)\r\n            if (Guards[i] != null) Guards[i].ResetToStart();\r\n\r\n        Debug.LogFormat(\"[Nb] 被保安追到：生命 {0}/{1}，玩家在 ({2:F1}, {3:F1})，{4} 名保安已回路线起点。\",\r\n            Hp, MaxHp, Player.position.x, Player.position.z, Guards.Count);\r\n\r\n        if (Hp <= 0) { Hp = 0; Fail(); }\r\n    }\r\n\r\n    void BustedByGuard()\r\n    {\r\n        Exposure = 0f;\r\n        Invuln = 3.0f;\r\n        Flash = 1f;\r\n        Hp -= NbLevels.BiteDamage;\r\n\r\n        Toast = \"SPOTTED!  MINUS 10 HP\";\r\n        ToastT = 2.4f;\r\n\r\n        // 保安回路线起点、玩家留在原地：院子太大，传送会让人彻底失去方位感，\r\n        // 而且\"我明明还站在这儿\"比\"我被搬走了\"更容易读懂刚刚发生了什么。\r\n        for (int i = 0; i < Guards.Count; i++)\r\n            if (Guards[i] != null) Guards[i].ResetToStart();\r\n\r\n        Debug.LogFormat(\"[Nb] 被保安手电抓到：生命 {0}/{1}，玩家在 ({2:F1}, {3:F1})，已把 {4} 名保安送回路线起点。\",\r\n            Hp, MaxHp, Player.position.x, Player.position.z, Guards.Count);\r\n\r\n        if (Hp <= 0) { Hp = 0; Fail(); }\r\n    }\r\n\r\n    /// 厨房：一根全场共用的新鲜度条。归零时还没捡的全部烂掉 ——\r\n    /// 已经捡到手的不受影响（那是\"吃掉了\"，不是\"还摆着\"）。\r\n    void RotUpdate()\r\n    {\r\n        if (Finished || RotLeft <= 0f) return;\r\n\r\n        RotLeft -= Time.deltaTime;\r\n        if (RotLeft > 0f) return;\r\n\r\n        RotLeft = 0f;\r\n        Rotted = true;\r\n\r\n        for (int i = 0; i < Cheeses.Count; i++)\r\n        {\r\n            NbCheese c = Cheeses[i];\r\n            if (c == null || c.Taken) continue;\r\n            if (c.Halo != null) c.Halo.gameObject.SetActive(false);\r\n            c.gameObject.SetActive(false);\r\n            c.Rotted = true;\r\n        }\r\n\r\n        Toast = \"IT ALL SPOILED\";\r\n        ToastT = 2.6f;\r\n\r\n        // 需求没凑够 = 这一关已经不可能完成，直接判失败。\r\n        // 让它\"继续走但永远赢不了\"是更糟的处理：玩家会把剩下的十分钟花在找不存在的东西上。\r\n        if (Collected < CheeseNeeded)\r\n        {\r\n            Debug.LogFormat(\"[Nb] 食物腐烂：{0}/{1}，不够 {2} 块 ⇒ 第 {3} 关失败。\",\r\n                Collected, Cheeses.Count, CheeseNeeded, Level);\r\n            Fail();\r\n        }\r\n        else\r\n        {\r\n            Debug.LogFormat(\"[Nb] 食物腐烂，但已经够了（{0}/{1}）。\", Collected, CheeseNeeded);\r\n        }\r\n    }\r\n\r\n    // ───────────────────────── 冰箱：门 ─────────────────────────\r\n\r\n    /// 门的三个状态：关门（倒计时）/ 预警（3 秒，门缝漏光）/ 开着（光灌进来，判一次）。\r\n    ///\r\n    /// 为什么只在开门 0.45 秒之后判**一次**，而不是持续照射：\r\n    /// 这一关层高只有 0.51 m、掩体就摆在旁边，玩家要么已经在掩体后面、要么还在空地上，\r\n    /// 中间并不存在\"擦着光边跑过去\"这种走位。持续判定只会做出一件事 ——\r\n    /// 把\"我明明躲好了\"判成没躲好（掩体只挡住了身体的一部分高度，射线却总有擦边的角度）。\r\n    void DoorUpdate()\r\n    {\r\n        if (Finished || Player == null) return;\r\n\r\n        // 教学面板还开着的时候门不走。玩家在读规则、倒计时在跑，读完规则先挨一下 ——\r\n        // 这不是\"难\"，这是骗人。\r\n        if (NbBriefing.Showing) return;\r\n\r\n        float dt = Time.deltaTime;\r\n\r\n        if (_doorOpenLeft > 0f)\r\n        {\r\n            _doorOpenLeft -= dt;\r\n\r\n            if (!_doorHit && _doorOpenLeft <= _doorOpenFor - 0.45f)\r\n            {\r\n                _doorHit = true;\r\n                if (Invuln <= 0f && !IsHidden()) BurnInDoorLight();\r\n            }\r\n\r\n            if (_doorOpenLeft <= 0f)\r\n            {\r\n                AudioManager.StopSound();\r\n                _doorOpenLeft = 0f;\r\n                // **必须在这里把间隔重新装上。** 少了这一句，DoorT 还是 0，\r\n                // 下一帧立刻又满足 \"DoorT <= 0\" ⇒ 门关上的同一帧就又开了，\r\n                // 表现是\"门再也关不上\"，而且不报错、HUD 的倒计时一直显示 0。\r\n                DoorT = _doorGap;\r\n                _doorWarned = false;\r\n                AudioManager.PlaySound(SoundType.FRIDGE_close);\r\n\r\n                // 关门那一刻如果玩家跑到门外的厨房地板上，把他收回来。\r\n                // 不收的话他就被封在冰箱外面了 —— 食物全在里面，而\"下一次开门\"要等 8~15 秒，\r\n                // 这一段他只能对着门站着，而画面上没有任何东西告诉他这是暂时的。\r\n                if (Player.position.z > NbFridge.ZMax - 0.30f)\r\n                {\r\n                    Rig.Teleport(new Vector3(Player.position.x, Player.position.y, NbFridge.ZMax - 1.3f), Rig.Yaw);\r\n                    Debug.Log(\"[Nb] 关门时玩家在门外，已收回冰箱内。\");\r\n                }\r\n            }\r\n        }\r\n        else\r\n        {\r\n            DoorT -= dt;\r\n\r\n            if (!_doorWarned && DoorT <= DoorWarnTime)\r\n            {\r\n                AudioManager.PlaySound(SoundType.FRIDGE_open);\r\n                _doorWarned = true;\r\n                Toast = \"THE DOOR IS OPENING\";\r\n                ToastT = 1.7f;\r\n                Debug.LogFormat(\"[Nb] 预警：{0:F1} 秒后冰箱门打开 —— 现在要躲到掩体后面。\", DoorT);\r\n            }\r\n\r\n            if (DoorT <= 0f)\r\n            {\r\n                DoorT = 0f;\r\n                _doorOpenLeft = _doorOpenFor;\r\n                _doorHit = false;\r\n                \r\n                Debug.LogFormat(\"[Nb] 冰箱门打开（{0:F1} s）。玩家在 ({1:F1}, {2:F1}, y={3:F2})，{4}。\",\r\n                    _doorOpenFor, Player.position.x, Player.position.z, Player.position.y,\r\n                    IsHidden() ? \"藏在掩体后面\" : \"暴露在空地上\");\r\n            }\r\n        }\r\n\r\n        // 视觉：开着 → 全开；预警 → 门缝里一条光，随着倒计时一下一下地跳；\r\n        // 平时 → 关死。\r\n        // 预警的 0.11 不是随手写的：门光最大 1.9，0.11 ⇒ 约 0.21 的强度，\r\n        // 刚好让玩家**脚下的地面亮起来**（平行光有 −0.47 的 y 分量），\r\n        // 人不用回头也知道背后那扇门在动。再低就只有屏幕底部那根条在提示了。\r\n        // 不能跟状态机硬跳 —— 否则关门那一帧门板会\"啪\"地瞬移回原位。\r\n        float target = _doorOpenLeft > 0f ? 1f\r\n                     : DoorT <= DoorWarnTime ? 0.11f + 0.05f * Mathf.Sin(Time.time * 14f)\r\n                     : 0f;\r\n        _doorVisual = Mathf.MoveTowards(_doorVisual, target, dt * (target > 0.5f ? 9f : 3.2f));\r\n        NbFridge.SetDoor(_doorVisual);\r\n    }\r\n\r\n    /// 门开着时，玩家是不是被东西挡住了。\r\n    ///\r\n    /// 从门口内侧、**玩家所在那一层的高度**朝玩家打一条粗射线，看中间有没有碰撞体。\r\n    /// 三个必须排掉的东西：\r\n    ///   · 搁板（名字以 \"Shelf\" 开头）—— 它是水平的，光从门平着进来撞不到它，\r\n    ///     但射线会擦到板的边缘。不排掉的话，玩家只要站在板后面（哪怕板在脚下）就永远安全。\r\n    ///   · 商品/装饰（Ignore Raycast 层）—— 见下面的掩码注释，这一条最要命。\r\n    ///   · 玩家自己。\r\n    bool IsHidden()\r\n    {\r\n        if (Player == null) return false;\r\n\r\n        Vector3 p = Player.position;\r\n        Vector3 src = new Vector3(NbFridge.CX, p.y + 0.13f, NbFridge.ZMax - 0.25f);\r\n        Vector3 dst = new Vector3(p.x, p.y + 0.15f, p.z);\r\n        Vector3 d = dst - src;\r\n        float dist = d.magnitude;\r\n\r\n        if (dist < 0.40f) return false;      // 贴着门口 = 门一开一定被看见\r\n\r\n        // **掩码不能写 ~0。** 商品现在是实心的（每件一个 BoxCollider，见 NbFoodArt.AddCollider），\r\n        // 它们留在 Ignore Raycast 层，而 `~0` 是\"所有层都算\"—— 全在的话，冰箱里 470 多件\r\n        // 商品随便哪一件挡在门口和你之间，你就\"藏好了\"。门一开，整个货架区都是安全区，\r\n        // 这一关就只剩\"走到架子边上站着\"。\r\n        // DefaultRaycastLayers = 除 Ignore Raycast 以外的所有层 ⇒ 商品不算遮挡，掩体/楼梯/墙照算。\r\n        RaycastHit[] hits = Physics.SphereCastAll(src, 0.05f, d / dist, dist,\r\n            Physics.DefaultRaycastLayers, QueryTriggerInteraction.Ignore);\r\n        for (int i = 0; i < hits.Length; i++)\r\n        {\r\n            Collider c = hits[i].collider;\r\n            if (c == null) continue;\r\n            if (c.transform.IsChildOf(Player)) continue;\r\n            string n = c.name;\r\n            // 结构件不算掩体：搁板（水平光撞不到，但粗射线会擦边）、楼梯（实心方块）。\r\n            // 楼梯这条**必须排除**：它每层都是 0.56 m 高的实心块，正好横在门口与玩家之间，\r\n            // 不排除的话每层中间那 8 m 会变成永久安全区，\"躲掩体\"这一关就没了。\r\n            if (!string.IsNullOrEmpty(n) && (n.StartsWith(\"Shelf\") || n.StartsWith(\"Step\"))) continue;\r\n            if (hits[i].distance < dist - 0.10f) return true;\r\n        }\r\n        return false;\r\n    }\r\n\r\n    /// 被门光照到：-10 血、红闪、2.6 秒无敌。\r\n    /// **不传送、不弹开** —— 玩家是自己没躲好，位置本身没问题；\r\n    /// 把他搬走反而会让他分不清\"我是被门照到，还是又被抓了一次\"。\r\n    void BurnInDoorLight()\r\n    {\r\n        Invuln = 2.6f;\r\n        Flash = 1f;\r\n        Hp = Mathf.Max(0, Hp - NbLevels.BiteDamage);\r\n\r\n        Toast = \"THE DOOR OPENED ON YOU!  MINUS 10 HP\";\r\n        ToastT = 2.4f;\r\n\r\n        Debug.LogFormat(\"[Nb] 被门光抓到：生命 -{0} → {1}/{2}，玩家在 ({3:F1}, {4:F1}, y={5:F2})。\",\r\n            NbLevels.BiteDamage, Hp, MaxHp, Player.position.x, Player.position.z, Player.position.y);\r\n\r\n        if (Hp <= 0) Fail();\r\n    }\r\n\r\n    // ───────────────────────── 「为什么动不了」的三个开关 ─────────────────────────\r\n\r\n    /// 这一关最容易被误诊的一种故障：世界被冻在 timeScale=0，或者可操作状态 / CharacterController\r\n    /// 被关掉了。三者都不报错、画面照常，唯一的症状就是\"按了没反应\"。\r\n    /// 这里每帧钉一遍，任一项不对就自己修回来，并留下一条能查的日志。\r\n    void EnsurePlayable()\r\n    {\r\n        // 标题页 / 场景选择页期间本来就该冻着。\r\n        // **这里必须把选择页也算进去**：这个方法是\"每帧把开关钉回可操作\"，\r\n        // 少列一个遮罩页，玩家就会在选择卡片底下走来走去 —— 而且完全看不到，\r\n        // 因为选择页是不透明的。这种\"看不见的移动\"比卡住更难查。\r\n        if (CatCheeseTitle.Showing || NbSceneSelect.Showing || NbBriefing.Showing) return;\r\n\r\n        if (Time.timeScale < 0.01f)\r\n        {\r\n            Time.timeScale = 1f;\r\n            Debug.LogWarning(\"[Nb] 世界被冻在 timeScale=0，但标题页已经不在了 —— 已自动放开。\");\r\n        }\r\n        if (Finished) return;\r\n        if (Rig == null) return;\r\n\r\n        if (!Rig.AcceptInput)\r\n        {\r\n            // 新玩家的移动读的是 unscaledDeltaTime，timeScale=0 也拦得住它，\r\n            // 所以\"能不能动\"完完全全只由这一个开关决定 —— 它掉了就什么都不动。\r\n            Rig.AcceptInput = true;\r\n            Debug.LogWarning(\"[Nb] 玩家被设成不可操作（标题页没交还？），已自动恢复。\");\r\n        }\r\n        if (Rig.Cc != null && !Rig.Cc.enabled)\r\n        {\r\n            Rig.Cc.enabled = true;\r\n            Debug.LogWarning(\"[Nb] CharacterController 被关掉了，已自动打开。\");\r\n        }\r\n    }\r\n\r\n    /// 判据：按着 WASD 持续 0.8 秒、位移 < 8 cm ⇒ 不是\"没按键\"，是走不动。\r\n    /// 计时必须用 unscaledDeltaTime —— 如果 timeScale 被冻在 0，用 deltaTime 的话这个看门狗自己也不会触发。\r\n    void MoveWatchdog(Keyboard kb)\r\n    {\r\n        bool any = kb != null && (kb.wKey.isPressed || kb.aKey.isPressed || kb.sKey.isPressed || kb.dKey.isPressed ||\r\n                                  kb.upArrowKey.isPressed || kb.downArrowKey.isPressed ||\r\n                                  kb.leftArrowKey.isPressed || kb.rightArrowKey.isPressed);\r\n        if (!any)\r\n        {\r\n            _holdT = -1f;\r\n            return;\r\n        }\r\n\r\n        if (_holdT < 0f)\r\n        {\r\n            _holdT = 0f;\r\n            _holdPos = Player.position;\r\n            return;\r\n        }\r\n\r\n        _holdT += Time.unscaledDeltaTime;\r\n        if (_holdT < 0.8f) return;\r\n\r\n        _holdT = -1f;\r\n        float moved = Nb.FlatDist(Player.position, _holdPos);\r\n        if (moved >= 0.08f)\r\n        {\r\n            if (!_movedOnce)\r\n            {\r\n                _movedOnce = true;\r\n                Debug.LogFormat(\"[Nb] 玩家已经能动：0.8 秒走出 {0:F2} m（输入 → CharacterController 这条链是通的）。\", moved);\r\n            }\r\n            return;\r\n        }\r\n\r\n        CharacterController cc = Player.GetComponent<CharacterController>();\r\n\r\n        // 顺手量一下\"身上贴着谁\" —— 这是「输入通了但一步没动」最常见的原因，\r\n        // 而且它自己是不会报错的：被自己的子物体顶住、站在别人的盒子里，都只是\"不动\"。\r\n        float r = cc != null ? cc.radius : 0.3f;\r\n        float h = cc != null ? Mathf.Max(cc.height, r * 2f) : 1.8f;\r\n        Vector3 mid = Player.position + Vector3.up * (h * 0.5f);\r\n        Collider[] hits = Physics.OverlapCapsule(mid + Vector3.up * (h * 0.5f - r),\r\n                                                mid - Vector3.up * (h * 0.5f - r),\r\n                                                r * 0.95f, ~0, QueryTriggerInteraction.Ignore);\r\n        var names = new List<string>();\r\n        for (int i = 0; i < hits.Length; i++)\r\n        {\r\n            if (hits[i] == null) continue;\r\n            if (hits[i].transform.root == Player.root) continue;   // 自己身上的一律不算\r\n            names.Add(hits[i].name);\r\n        }\r\n\r\n        Debug.LogWarningFormat(\r\n            \"[Nb] 按着移动键 0.8 秒，玩家只挪了 {0:F3} m —— 不是输入没进来。\" +\r\n            \"timeScale={1:F2}，可操作={2}，cc.enabled={3}，光标={4}，位置 ({5:F2},{6:F2},{7:F2})，\" +\r\n            \"身上贴着 {8} 个碰撞体{9}\",\r\n            moved, Time.timeScale, Rig != null && Rig.AcceptInput, cc != null && cc.enabled,\r\n            Cursor.lockState, Player.position.x, Player.position.y, Player.position.z,\r\n            names.Count, names.Count > 0 ? \"（\" + string.Join(\", \", names.ToArray()) + \"）\" : \"\");\r\n    }\r\n\r\n    /// 小地图箭头 = **身体朝向**，不是「上一帧往哪走」。\r\n    ///\r\n    /// 旧版取真实位移方向：站着不动、只转鼠标时位移恒为 0，箭头就冻在最后一次\r\n    /// 移动的方向上 —— 明明面朝北，小地图上却指着东；而玩家看小地图时第一个\r\n    /// 问题恰恰是\"我面朝哪\"。位移方向只在**移动时**才有意义，作为朝向来源是错的。\r\n    ///\r\n    /// 现在直接取 `Rig.Facing`（由 Yaw 得来，转身/静立转鼠标都会变）。\r\n    /// 会不会因此\"侧走时箭头不横过来\"？会 —— 但这也正是小地图的标准语义：\r\n    /// 箭头回答\"我朝哪\"，画面本身回答\"我在往哪挪\"。\r\n    void TrackHeading()\r\n    {\r\n        Vector3 d = Player.position - _lastPos;\r\n        d.y = 0f;\r\n        float dist = d.magnitude;\r\n        // 速度单独记一份：读数条上直接显示\"你这一帧真的动了多少\"。\r\n        // 它比任何日志都直接 —— 画面均匀时人眼分不出\"没动\"和\"看不出在动\"，但 v 会。\r\n        // 速度直接用玩家自己算的那一份（它按 unscaledDeltaTime 算）：\r\n        // 世界被冻在 timeScale=0 时，用 Time.deltaTime 算出来永远是 0 —— 那正好是\r\n        // 「明明在走，读数条却显示 0」的来源，也是这一轮反复误判的推手。\r\n        Speed = Rig != null ? Rig.Speed : (Time.deltaTime > 0.0001f ? dist / Time.deltaTime : 0f);\r\n\r\n        if (Rig != null)\r\n        {\r\n            Vector3 f = Rig.Facing;\r\n            if (f.sqrMagnitude > 1e-6f) Heading = f;\r\n        }\r\n        _lastPos = Player.position;\r\n    }\r\n\r\n    void CollectCheck()\r\n    {\r\n        for (int i = 0; i < Cheeses.Count; i++)\r\n        {\r\n            NbCheese c = Cheeses[i];\r\n            if (c == null || c.Taken || c.Rotted) continue;\r\n            // 捡取半径按**老鼠的体型**给：0.62 m ≈ 6 个身位。\r\n            // 原来 1.15 m 是给成年人（1.8 m 高）用的，对 0.3 m 的老鼠等于\"离着两米就吸走了\"，\r\n            // 奶酪的 halo 直径正好 1.15 —— 现在必须踩进光晕里才算捡到。\r\n            if (Nb.FlatDist(c.transform.position, Player.position) > 0.62f) continue;\r\n\r\n            // 冰箱是多层的，而 FlatDist 只算平面距离 —— 不卡高度的话，\r\n            // 站在第 4 层能把**正下方**第 1 层的食物一起捡走（平面距离 0）。\r\n            // 0.45 是刻意的：它小于层高 0.56（隔层一定捡不到），又大于同层内的任何高差。\r\n            if (NbScene.KeepsHeight &&\r\n                Mathf.Abs(c.transform.position.y - Player.position.y) > 0.45f) continue;\r\n\r\n            c.Taken = true;\r\n            if (c.Halo != null) c.Halo.gameObject.SetActive(false);\r\n            c.gameObject.SetActive(false);\r\n            Held.Add(c);\r\n\r\n            AudioManager.PlaySound(SoundType.nom, 0.9f);\r\n            Collected++;\r\n            Toast = Collected >= CheeseNeeded ? \"THAT IS ENOUGH\" : (CheeseNeeded - Collected) + \" MORE TO GO\";\r\n            ToastT = 1.3f;\r\n\r\n            if (Collected >= CheeseNeeded) Win();\r\n        }\r\n    }\r\n\r\n    // ───────────────────────── 被抓 / 胜负 ─────────────────────────\r\n\r\n    internal void Caught(NbCat cat)\r\n    {\r\n        if (Finished || Invuln > 0f) return;\r\n\r\n        Invuln = 3.5f;\r\n        Flash = 1f;\r\n\r\n        // 每被咬一口 -10。生命条是这一关真正的资源：咬满 10 口就整关重来（LoadLevel 会把血补满）。\r\n        // 掉一块奶酪的老规矩也保留 —— 两种惩罚指向不同：血说\"别被追上\"，奶酪说\"被追上要再跑一趟\"。\r\n        Hp = Mathf.Max(0, Hp - NbLevels.BiteDamage);\r\n\r\n        if (Held.Count > 0)\r\n        {\r\n            // 掉一块在\"被抓的地方\"，重新变得可捡 —— 不销毁物体，计数和场景永远对得上\r\n            NbCheese c = Held[Held.Count - 1];\r\n            Held.RemoveAt(Held.Count - 1);\r\n            Collected--;\r\n\r\n            // 掉在**身后** 0.9 m，不是身前。理由很硬：这一关是\"全部带回\"，\r\n            // 一块落进楼体里的奶酪 = 这一关永远打不通（而身前 0.9 m 正好是撞墙时最容易被推进去的那一格）。\r\n            // 身后是你一秒钟前刚走过的地面，一定站得住；同时它在 0.62 m 捡取半径之外，\r\n            // 所以不是\"立刻又捡回来\"—— 你得转身，而猫就在旁边。\r\n            Vector3 drop = Nb.Grounded(Player.position - Player.forward * 0.9f);\r\n            c.transform.position = drop + Vector3.up * 0.05f;\r\n            if (c.Halo != null)\r\n            {\r\n                c.Halo.position = new Vector3(drop.x, 0.055f, drop.z);\r\n                c.Halo.gameObject.SetActive(true);\r\n            }\r\n            c.Taken = false;\r\n            c.gameObject.SetActive(true);\r\n            Toast = \"CAUGHT!  MINUS 10 HP  AND  A CHEESE\";\r\n        }\r\n        else\r\n        {\r\n            Toast = \"CAUGHT!  MINUS 10 HP\";\r\n        }\r\n        ToastT = 2.4f;\r\n\r\n        // **不再把人搬回出生点 —— 这正是\"永远动不了\"的根源。**\r\n        // 旧写法：被抓住 → PlacePlayer() 传送回起点 → 猫的 ResetChase() 只是\"换了个路点索引\"、\r\n        // 猫本人还站在原地 → 无敌一过同一只猫立刻又扑上来。日志里连着二十多条\r\n        // 「被 Cat 1 抓住」全是同一处、同一只猫，玩家感受到的就是\"按键没用\"。\r\n        // 现在：只把人从猫的方向弹开 2.2 m，猫被真的挪到路线远端（NbCat.ResetChase(true)）。\r\n        Knock(cat != null ? cat.transform.position : Player.position - Player.forward);\r\n        // 只有抓人的那一只被搬回路线远端；其余就地放弃追击（全搬走会让人看见一片猫同时瞬移）。\r\n        for (int i = 0; i < Cats.Count; i++)\r\n            if (Cats[i] != null) Cats[i].ResetChase(Cats[i] == cat);\r\n        Debug.LogFormat(\"[Nb] 被「{0}」抓住：生命 -{1} → {2}/{3}；弹开、猫回路线远端、无敌 {4:F1} s。玩家仍在 ({5:F1}, {6:F1})，本关奶酪 {7}/{8}。\",\r\n            cat != null ? cat.name : \"猫\", NbLevels.BiteDamage, Hp, MaxHp, Invuln,\r\n            Player.position.x, Player.position.z, Collected, CheeseNeeded);\r\n\r\n        // 血光就结束这一关。放在弹开之后：玩家能看见自己是被哪只猫顶到墙角的，\r\n        // 而不是\"画面一闪、忽然就失败了\"。\r\n        if (Hp <= 0) Fail();\r\n    }\r\n\r\n    /// 被猫扑到时的推开：沿\"背离猫\"的方向推 2.2 m，撞到东西就少推一点。\r\n    /// 为什么不用传送：传送会把相机/朝向一起重置，玩家会失去方位感 —— 而且这关的视野本来就很暗，\r\n    /// 一传送就等于\"画面闪一下、我还在原地\"，跟卡死没区别。\r\n    void Knock(Vector3 from)\r\n    {\r\n        if (Rig == null) return;\r\n        Rig.Nudge(from, 2.2f);\r\n        _lastPos = Player.position;\r\n    }\r\n\r\n    /// 本关奶酪集满。**不再直接 \"挑战成功\"** —— 现在是 10 关，过关只是\"进下一关的凭据\"。\r\n    void Win()\r\n    {\r\n        Finished = true;\r\n        Won = true;\r\n        Failed = false;\r\n        Cursor.lockState = CursorLockMode.None;\r\n        Cursor.visible = true;\r\n        if (Rig != null) Rig.AcceptInput = false;\r\n\r\n        // 记进度（自由选择模式：三个场景各记各的最高关卡，互不影响）\r\n        NbProgress.Reach(NbScene.Kind, Mathf.Min(Level + 1, NbLevels.Count));\r\n\r\n        bool last = NbLevels.IsLast(Level);\r\n        if (NbHud.I != null)\r\n        {\r\n            if (last)\r\n                NbHud.I.ShowEnd(NbScene.Code + \" CLEARED\",\r\n                    CheeseNeeded + \" OF \" + CheeseNeeded + \" BROUGHT BACK.  \" + NbScene.Name + \" IS QUIET.\",\r\n                    \"PRESS  R  TO  PLAY  AGAIN\", true);\r\n            else\r\n                NbHud.I.ShowEnd(\"LEVEL \" + Level + \" CLEAR\",\r\n                    CheeseNeeded + \" OF \" + CheeseNeeded + \" BROUGHT BACK.  NEXT IS LEVEL \" + (Level + 1) + \".\",\r\n                    \"PRESS  R  TO  CONTINUE\", true);\r\n        }\r\n\r\n        Debug.LogFormat(\"[Nb] 第 {0} 关通过（生命 {1}/{2}）。{3}\",\r\n            Level, Hp, MaxHp, last ? \"已是最后一关。\" : \"按 R 进入第 \" + (Level + 1) + \" 关。\");\r\n    }\r\n\r\n    /// 血被咬光。和过关共用一块面板，但标题、颜色、按键文案全不一样 ——\r\n    /// 玩家必须一眼分清\"我赢了\"和\"我死了\"，这两件事后面接的动作是相反的。\r\n    internal void Fail()\r\n    {\r\n        if (Finished) return;\r\n        Finished = true;\r\n        Won = false;\r\n        Failed = true;\r\n        Hp = 0;\r\n        Cursor.lockState = CursorLockMode.None;\r\n        Cursor.visible = true;\r\n        if (Rig != null) Rig.AcceptInput = false;\r\n\r\n        // 失败的原因每个场景不一样，标题必须说清\"是谁弄死我的\"：\r\n        // 后院的猫只是干扰，真正扣血的是保安；厨房扣血的还是猫，但更常见的是食物全烂了。\r\n        string cause = Rotted ? \"THE FOOD IS GONE\"\r\n                     : NbScene.UsesGuards ? \"THE NIGHT PATROL GOT YOU\"\r\n                     : NbScene.UsesDoor ? \"THE LIGHT CAUGHT YOU\"\r\n                     : \"THE CATS GOT YOU\";\r\n\r\n        if (NbHud.I != null)\r\n            NbHud.I.ShowEnd(cause,\r\n                \"OUT OF HEALTH ON LEVEL \" + Level + \".\",\r\n                \"PRESS  R  TO  TRY  AGAIN\", false);\r\n\r\n        Debug.LogFormat(\"[Nb] 生命归零 —— 第 {0} 关失败（本关奶酪 {1}/{2}）。\", Level, Collected, CheeseNeeded);\r\n    }\r\n\r\n    /// 过关面板上的那一个按键：\r\n    ///   · 赢了且不是最后一关 → 进下一关\r\n    ///   · 赢了且是最后一关   → 从第 1 关重来一整个流程\r\n    ///   · 输了               → 重打本关（血补满、奶酪重摆）\r\n    void NextOrRetry()\r\n    {\r\n        if (Won && !NbLevels.IsLast(Level)) { LoadLevel(Level + 1); return; }\r\n        if (Won) { Debug.Log(\"[Nb] 十关通关，回到第 1 关重来。\"); LoadLevel(1); return; }\r\n        LoadLevel(Level);\r\n    }\r\n\r\n    /// 外部（旧脚本 / 调试）调用的\"重开一局\"：等价于重打本关。\r\n    internal void Restart()\r\n    {\r\n        LoadLevel(Level);\r\n    }\r\n\r\n    // ───────────────────────── 换场景 ─────────────────────────\r\n\r\n    bool _switching;\r\n\r\n    /// 由场景选择页调用。**重建整个世界**，而不是只换一组数字 ——\r\n    /// 12 栋楼、地面、围墙都是场景文件里实实在在的物体，后院/厨房得把它们整体关掉\r\n    /// （NbScene.HideOriginal）再搭自己的。只换数据是搭不出新场景的。\r\n    internal void EnterScene(NbSceneKind k)\r\n    {\r\n        if (_switching) return;\r\n        StartCoroutine(SwitchTo(k));\r\n    }\r\n\r\n    IEnumerator SwitchTo(NbSceneKind k)\r\n    {\r\n        _switching = true;\r\n        Debug.LogFormat(\"[Nb] 切换场景 → {0}\", k);\r\n\r\n        ClearProps();\r\n\r\n        if (Root != null) Nb.Kill(Root.gameObject);\r\n        if (Rig != null) Nb.Kill(Rig.gameObject);\r\n        Root = null;\r\n        Rig = null;\r\n        Player = null;\r\n\r\n        // HUD / 小地图是独立根物体、不在 Root 下面，得单独拆。\r\n        // Kill 之后必须等一帧：Destroy 是延迟到帧末的，这一帧旧 Canvas 还在，\r\n        // 紧接着 Create 会让两套 HUD 短暂叠在一起（数值不同，看起来像画面重影）。\r\n        if (NbHud.I != null) Nb.Kill(NbHud.I.gameObject);\r\n        if (NbMap.I != null) Nb.Kill(NbMap.I.gameObject);\r\n        yield return null;\r\n\r\n        NbScene.Kind = k;\r\n        yield return StartCoroutine(Boot());\r\n\r\n        _switching = false;\r\n    }\r\n}\r\n\r\n// ───────────────────────── 奶酪 ─────────────────────────\r\n\r\ninternal class NbCheese : MonoBehaviour\r\n{\r\n    internal int Index;\r\n    internal Transform Halo;\r\n    internal bool Taken;\r\n\r\n    /// 厨房专属：腐烂后整块消失，**不能再被捡起**。\r\n    /// 和 Taken 分开两个字段是必须的 —— Taken 是\"我拿在手里\"，Rotted 是\"它不存在了\"，\r\n    /// 用同一个字段会让 Restart 把烂掉的又变回好的。\r\n    internal bool Rotted;\r\n\r\n    void Update()\r\n    {\r\n        if (Taken) return;\r\n        transform.Rotate(0f, 42f * Time.deltaTime, 0f, Space.World);\r\n    }\r\n}\r\n\r\n// ───────────────────────── 猫 ─────────────────────────\r\n\r\n/// 沿固定路线来回走；玩家进入视野且没有遮挡就追。追的时候不看路线，追丢了再回到最近的路点。\r\ninternal class NbCat : MonoBehaviour\r\n{\r\n    internal Vector3[] Route;\r\n    internal float Speed = 1.55f;\r\n    internal float ChaseSpeed = 3.15f;\r\n\r\n    // 视野。**按关卡给**（NbLevels.Sight：第 1 关 10 m → 第 10 关 16 m），不再写死 16。\r\n    // 这条是\"难度层层递进\"里最隐蔽的一档：猫没变多、没变快，只是更早抬头看你。\r\n    internal float SightDist = 16f;\r\n    // 这个距离以内不看朝向也能察觉 —— 不随关卡变，否则会出现\"猫从背后踩过去却没看见你\"。\r\n    internal const float SightClose = 4f;\r\n\r\n    /// 后院专属：**蹲守**。蹲着的时候不巡逻、也不扫视，玩家进 AmbushTrigger 才起身追。\r\n    /// 它不看，它等 —— 这才是参考图里 \"hide in the dark and sneakily attack players\r\n    /// when they are not paying attention\" 的意思。用视野锥做不出\"偷袭\"，\r\n    /// 因为视野锥在玩家靠近之前就已经开始转头了。\r\n    internal bool Ambush;\r\n    internal float AmbushTrigger = 2.5f;\r\n\r\n    Transform _player;\r\n    int _idx = 1;\r\n    int _dir = 1;               // 路线走到头就掉头\r\n    float _wait;\r\n    float _lost;\r\n    bool _chasing;\r\n    Vector3 _lastSeen;\r\n\r\n    internal bool IsChasing { get { return _chasing; } }\r\n\r\n    // ── 体型相关（由 NbGame.SpawnCats 按**实测包围盒**写进来，不再写死）──\r\n    // 猫从 0.5 m 长到 0.95 m 高之后，原来那组常数（探针 0.35 高、半径 0.17、\r\n    // 抓人 1.15 m）全都对不上了：探针会从奶酪上方飘过去、抓人距离比猫的身子还短，\r\n    // 玩家能站在猫的肚子底下不被抓。\r\n    internal float ProbeUp = 0.55f;        // 扫掠/视线起点离地高度（约胸高）\r\n    internal float ProbeRadius = 0.30f;    // 扫掠球半径（约半个身宽）\r\n    internal float ProbeDist = 0.85f;      // 前瞻距离\r\n    internal float CatchDist = 1.10f;      // 多近算抓住（半个体长 + 玩家半径 + 余量）\r\n    internal float BodyLength = 1.80f;     // 最大水平尺寸，只用于日志与判断\r\n\r\n    internal void ConfigureBody(Bounds box, float height)\r\n    {\r\n        float span = Mathf.Max(box.size.x, box.size.z);\r\n        if (span <= 0.01f) span = height * 1.7f;      // 量不到网格时的兜底\r\n\r\n        BodyLength = span;\r\n        ProbeUp = Mathf.Clamp(height * 0.55f, 0.2f, 2.5f);\r\n        ProbeRadius = Mathf.Clamp(span * 0.16f, 0.12f, 0.6f);\r\n        ProbeDist = Mathf.Max(0.45f, ProbeRadius * 2.9f);\r\n        // 抓人的判定中心在猫的根节点（脚下），所以距离必须≥半个体长，\r\n        // 否则\"看得见、追得上、就是抓不到\"。\r\n        CatchDist = span * 0.5f + 0.25f;\r\n\r\n        Debug.LogFormat(\"[Nb] 「{0}」体型：高 {1:F2} m，水平 {2:F2}×{3:F2} m ⇒ 扫掠 半径{4:F2}/前探{5:F2}，\" +\r\n                        \"抓人距离 {6:F2} m，视线起点离地 {7:F2} m。\",\r\n            name, height, box.size.x, box.size.z, ProbeRadius, ProbeDist, CatchDist, ProbeUp);\r\n    }\r\n\r\n    void Start()\r\n    {\r\n        if (NbGame.I != null) _player = NbGame.I.Player;\r\n        if (Route != null && Route.Length > 1) _idx = 1;\r\n    }\r\n\r\n    /// 放弃追击、回路线。\r\n    /// `relocate = false`（追丢时用）：只挑**离自己最近**的路点，猫就地继续巡逻。\r\n    /// `relocate = true`（被抓之后用）：挑**离玩家最远**的路点，并且真的把猫搬过去。\r\n    ///   —— 这一点是这轮的关键：旧版不管哪种情况都只改 `_idx`，猫的身体一动不动。\r\n    ///   于是\"被抓 → 猫就在你脚边 → 无敌一过又抓\"，日志里连成串。\r\n    internal void ResetChase(bool relocate = false)\r\n    {\r\n        _chasing = false;\r\n        _lost = 0f;\r\n        _wait = 0f;\r\n        if (Route == null || Route.Length == 0) return;\r\n\r\n        int best = 0;\r\n        float bestScore = float.MaxValue;\r\n        for (int i = 0; i < Route.Length; i++)\r\n        {\r\n            // 求\"最远\" ⇒ 拿负距离当分数比最小\r\n            float score = (relocate && _player != null)\r\n                ? -Nb.FlatDist(Route[i], _player.position)\r\n                : Nb.FlatDist(transform.position, Route[i]);\r\n            if (score < bestScore) { bestScore = score; best = i; }\r\n        }\r\n        _idx = best;\r\n\r\n        if (!relocate) return;\r\n\r\n        Vector3 dest = Route[best];\r\n        // 落点朝向路线里\"另一个方向\"的那一头，免得刚落地就正对着玩家\r\n        int other = Route.Length > 1 ? (best == 0 ? 1 : best - 1) : best;\r\n        Vector3 look = Route[other] - dest;\r\n        look.y = 0f;\r\n\r\n        transform.position = new Vector3(dest.x, transform.position.y, dest.z);\r\n        if (look.sqrMagnitude > 1e-3f) transform.rotation = Quaternion.LookRotation(look.normalized);\r\n        Debug.LogFormat(\"[Nb] 「{0}」被送回路线远端 ({1:F1}, {2:F1})，离玩家 {3:F1} m。\",\r\n            name, dest.x, dest.z, _player != null ? Nb.FlatDist(dest, _player.position) : -1f);\r\n    }\r\n\r\n    bool _wasSeeing = false;\r\n    float _nextMeow = 0;\r\n    float _nextHiss = 0;\r\n    void Update()\r\n    {\r\n        if (NbGame.I == null || NbGame.I.Finished) return;\r\n        if (_player == null && NbGame.I != null) _player = NbGame.I.Player;\r\n        if (Route == null || Route.Length == 0) return;\r\n\r\n        // 埋伏猫：蹲在路线上不动，玩家进 2.5 m 才起身。起身之后走正常的追击逻辑。\r\n        if (Ambush && !_chasing)\r\n        {\r\n            if (_player == null || Nb.FlatDist(transform.position, _player.position) > AmbushTrigger)\r\n                return;                        // 不动、不巡逻、不转头 —— 它只是一块影子\r\n\r\n            _chasing = true;\r\n            _lastSeen = _player.position;\r\n            _lost = 0f;\r\n            Debug.LogFormat(\"[Nb] 埋伏的「{0}」起身了（玩家离 {1:F1} m）。\", name,\r\n                Nb.FlatDist(transform.position, _player.position));\r\n        }\r\n\r\n        bool see = CanSee();\r\n        bool justSaw = see && !_wasSeeing;\r\n        _wasSeeing = see;                       // update immediately, before any early return\r\n\r\n        if (see)\r\n        {\r\n            if (justSaw && Time.time >= _nextMeow)\r\n            {\r\n                AudioManager.PlaySound(SoundType.CAT_Meow, 0.5f);\r\n                _nextMeow = Time.time + AudioManager.GetSoundLength(SoundType.CAT_Meow);\r\n                _nextHiss = _nextMeow + 0.5f;     // don't hiss right on top of the meow\r\n            }\r\n            else if (_chasing && Time.time >= _nextHiss)\r\n            {\r\n                AudioManager.PlaySound(SoundType.CAT_Hiss, 0.7f);\r\n                _nextHiss = Time.time + AudioManager.GetSoundLength(SoundType.CAT_Hiss) + 0.5f;\r\n            }\r\n\r\n            _chasing = true;\r\n            _lost = 0f;\r\n            _lastSeen = _player.position;\r\n        }\r\n        else if (_chasing)\r\n        {\r\n            _lost += Time.deltaTime;\r\n            if (_lost > 3.2f)\r\n            {\r\n                _chasing = false;\r\n                ResetChase();\r\n            }\r\n        }\r\n\r\n        // 抓到人（放在移动之前判断：猫已经贴到身上时不该再往前挤）\r\n        if (_chasing && _player != null &&\r\n            Nb.FlatDist(transform.position, _player.position) < CatchDist)\r\n        {\r\n            NbGame.I.Caught(this);\r\n            return;\r\n        }\r\n\r\n        // 追的时候朝\"最后看见的位置\"走，而不是玩家当前的坐标 ——\r\n        // 后者会让猫隔着一整栋楼抄直线穿墙过去。\r\n        Vector3 target = _chasing ? _lastSeen : Route[_idx];\r\n        float speed = _chasing ? ChaseSpeed : Speed;\r\n\r\n        Vector3 flat = new Vector3(target.x - transform.position.x, 0f, target.z - transform.position.z);\r\n        float dist = flat.magnitude;\r\n\r\n        if (!_chasing && dist < 0.7f)\r\n        {\r\n            _wait += Time.deltaTime;\r\n            if (_wait < 0.45f) { Face(flat); return; }\r\n            _wait = 0f;\r\n            StepRoute();\r\n            return;\r\n        }\r\n\r\n        // 追到了\"最后看见的位置\"还是没人（玩家绕走了）：停下来重新张望\r\n        if (_chasing && dist < 0.8f)\r\n        {\r\n            _chasing = false;\r\n            ResetChase();\r\n            return;\r\n        }\r\n\r\n        if (dist < 0.001f) return;\r\n        Vector3 move = Steer(flat / dist);\r\n        transform.position += move * speed * Time.deltaTime;\r\n        Face(move);\r\n    }\r\n\r\n    /// 前方短距离球扫掠：撞到楼体或围墙就沿表面滑开。\r\n    /// 这里没有 NavMesh，不这么做的话猫会直接穿墙走过去。\r\n    Vector3 Steer(Vector3 dir)\r\n    {\r\n        RaycastHit h;\r\n        Vector3 o = transform.position + Vector3.up * ProbeUp;\r\n        if (!Physics.SphereCast(o, ProbeRadius, dir, out h, ProbeDist, ~0, QueryTriggerInteraction.Ignore))\r\n            return dir;\r\n        if (h.collider == null) return dir;\r\n        if (_player != null && h.collider.transform.root == _player.root) return dir;  // 撞到人：交给距离判定\r\n\r\n        // 奶酪：贴地的小方盒，正面撞上去时\"沿表面投影\"是零向量，会被下面的兜底原样返回 →\r\n        // 猫就那么从奶酪中间穿过去了。所以奶酪单独处理：往自己当前那一侧绕。\r\n        NbCheese cheese = h.collider.GetComponentInParent<NbCheese>();\r\n        if (cheese != null)\r\n        {\r\n            Vector3 toObs = cheese.transform.position - transform.position;\r\n            toObs.y = 0f;\r\n            Vector3 right = Vector3.Cross(Vector3.up, dir);\r\n            if (right.sqrMagnitude < 1e-6f) return dir;\r\n            right.Normalize();\r\n            Vector3 side = Vector3.Dot(right, toObs) > 0f ? -right : right;   // 障碍在右就往左绕\r\n            Vector3 round = (dir * 0.45f + side).normalized;\r\n            return round.sqrMagnitude > 1e-4f ? round : dir;\r\n        }\r\n\r\n        Vector3 n = h.normal;\r\n        n.y = 0f;\r\n        if (n.sqrMagnitude < 1e-4f) return dir;\r\n        Vector3 slide = Vector3.ProjectOnPlane(dir, n.normalized);\r\n        slide.y = 0f;\r\n        return slide.sqrMagnitude > 1e-4f ? slide.normalized : dir;\r\n    }\r\n\r\n    void StepRoute()\r\n    {\r\n        if (Route.Length <= 1) return;\r\n        _idx += _dir;\r\n        if (_idx >= Route.Length)\r\n        {\r\n            _idx = Route.Length - 2;\r\n            _dir = -1;\r\n        }\r\n        else if (_idx < 0)\r\n        {\r\n            _idx = 1;\r\n            _dir = 1;\r\n        }\r\n    }\r\n\r\n    void Face(Vector3 dir)\r\n    {\r\n        if (dir.sqrMagnitude < 1e-5f) return;\r\n        dir.y = 0f;\r\n        Quaternion want = Quaternion.LookRotation(dir);\r\n        transform.rotation = Quaternion.Slerp(transform.rotation, want, 7f * Time.deltaTime);\r\n    }\r\n\r\n    /// 视野：SightDist（本关给定，10~16 m）内、身前约 140° 的锥形；SightClose（4 m）内不看方向也能察觉。\r\n    /// 中间不能隔着楼或围墙。\r\n    bool CanSee()\r\n    {\r\n\r\n        if (_player == null) return false;\r\n\r\n        // 出生点周围 6 m 是安全区：猫不追进来。\r\n        // 玩家可以自己把出生点摆在任意位置，而\"纵向通道 A 那只\"的巡逻线正好穿过街区正中 ——\r\n        // 站在出生点上就永远躲不开，手感上就是\"动不了\"。离开 6 m 之后猫照旧追。\r\n        if (NbGame.I != null && Nb.FlatDist(_player.position, NbGame.I.Home) < 6f) return false;\r\n\r\n        // 猫的眼睛在胸高；看的是**玩家的眼睛**，不是\"头顶上方 1 m\"——\r\n        // 老鼠只有 0.30 m 高，盯着 1 m 高的地方等于在看墙。\r\n        Vector3 eye = transform.position + Vector3.up * ProbeUp;\r\n        Vector3 at = (NbPlayer.I != null && NbPlayer.I.Eye != null)\r\n            ? NbPlayer.I.Eye.position\r\n            : _player.position + Vector3.up * 0.16f;\r\n        Vector3 d = at - eye;\r\n        float dist = d.magnitude;\r\n        if (dist > SightDist) return false;\r\n\r\n        Vector3 flat = new Vector3(d.x, 0f, d.z);\r\n        if (flat.sqrMagnitude < 1e-4f) return true;\r\n\r\n        if (dist > SightClose)\r\n        {\r\n            Vector3 fwd = new Vector3(transform.forward.x, 0f, transform.forward.z).normalized;\r\n            if (Vector3.Dot(fwd, flat.normalized) < 0.35f) return false;\r\n        }\r\n\r\n        RaycastHit hit;\r\n        if (Physics.Linecast(eye, at, out hit, ~0, QueryTriggerInteraction.Ignore))\r\n        {\r\n            if (hit.collider != null && hit.collider.transform.root != _player.root) return false;\r\n        }\r\n\r\n        \r\n        return true;\r\n    }\r\n}\r\n"},"NbPlayer":{"path":"Assets/Scripts/NbPlayer.cs","role":"First-person mouse controller: builds its own body and camera; walk/run/jump, look, idle squeak.","source":"// @role First-person mouse controller: builds its own body and camera; walk/run/jump, look, idle squeak.\r\n// @calls NbGame AudioManager\r\n// @tune WalkSpeed:float:1-4:walk speed m/s\r\n// @tune RunMul:float:1-3:run multiplier on WalkSpeed\r\n// @tune JumpSpeed:float:1-6:jump take-off velocity m/s\r\n// @tune Gravity:float:-40--5:gravity acceleration m/s2\r\n// @tune LookSens:float:0.02-0.5:mouse look sensitivity deg/pixel\r\n\r\n// NbPlayer.cs — 第一人称玩家（全新一套：自己造身体、自己造相机，不读场景里任何东西）\r\n//\r\n// ───────────────────────── 为什么要重写 ─────────────────────────\r\n// 旧版的第一人称是四样东西拼起来的：\r\n//   ① 场景里那个 FirstPersonController（可能被拖到别的物体下面、改了缩放）\r\n//   ② 它自带的 CapsuleCollider（半径 0.5、中心 (0,0,0)：一半埋在地下）\r\n//   ③ 运行时补的 CharacterController（和 ② 套在一起互顶）\r\n//   ④ 场景里那台本地 y = 0.26 的 Main Camera（眼睛在膝盖高度，还横歪 88°）\r\n// 任何一样出问题，表现都只有一句「按 WASD 不动」，而且 Console 一声不响。\r\n//\r\n// 这一版把四样合成一个**自己新建的**物体，场景里那个老玩家直接整个关掉：\r\n//   · 根物体 = 胶囊，原点在**脚底**（CharacterController 高 0.30、半径 0.10、中心 (0,0.15,0)）\r\n//   · 子物体 Eye = 相机，本地 y = 0.16（**老鼠眼高**），只负责俯仰\r\n//   · 偏航转根物体、俯仰转 Eye —— 两边各写各的，谁也覆盖不掉谁\r\n//   · 出生时把场上**所有别的相机、所有 AudioListener 全部关掉**，永远只有一个相机在画\r\n//   · 位移用 unscaledDeltaTime：世界被 timeScale 冻住时人也照样能走\r\n//     （标题页期间由 AcceptInput = false 挡住，不靠 timeScale）\r\n//\r\n// 键位：WASD / 方向键走，Shift 跑，Space 跳，鼠标转视角，Q/E 键盘左右转（鼠标失灵时的兜底），\r\n//       Esc 释放鼠标，点画面重新锁定。\r\n\r\nusing System.Collections;\r\nusing System.Collections.Generic;\r\nusing UnityEngine;\r\nusing UnityEngine.InputSystem;\r\nusing UnityEngine.SceneManagement;\r\n\r\ninternal class NbPlayer : MonoBehaviour\r\n{\r\n    internal static NbPlayer I;\r\n\r\n    // ───────────────────────── 尺寸（都不是可调参数，写死） ─────────────────────────\r\n    // **这一关的玩家是一只老鼠，不是成年人。**\r\n    // 眼高 0.16 m —— 比成年人脚踝还低；走过的路面在视野里是一片向远处铺开的平面，\r\n    // 楼是两侧的墙，垃圾桶是一只桶，猫是 0.95 m 高的巨兽（见 NbGame.CatHeight）。\r\n    // 比例感全靠这一组数，改动要连带想清楚猫 / 奶酪 / 路缘（0.03 m）的相对大小。\r\n    //\r\n    // 提醒：旧版在这里踩过一个坑 —— 眼高掉到 0.29 m 时\"看着像卡死\"，\r\n    // 原因是当时地面没有贴图、光照又平，整屏是一个纯色渐变的平面，走起来画面几乎不变。\r\n    // 现在过道里铺了石子/裂纹/落叶/井盖（NbBuilder.BuildGroundDetail），近距离有参照物，\r\n    // 低眼高才真的像\"老鼠视角\"，而不是\"卡在地板里\"。\r\n    internal const float EyeHeight = 0.16f;\r\n    internal const float BodyHeight = 0.30f;\r\n    internal const float BodyRadius = 0.10f;\r\n\r\n    // ───────────────────────── 手感 ─────────────────────────\r\n    // 老鼠的体型小，同样的绝对速度在低视角下会被放大很多倍（近处东西唰唰地过）。\r\n    // 2.80 → **2.30**：慢下来的理由不是\"太快看不清\"，而是**关卡需要速度差**：\r\n    //   猫的巡逻 1.10~1.55、追击 2.20~3.25（见 NbLevels），\r\n    //   走路 2.30 刚好夹在两者之间 —— 走能甩开巡逻，甩不开追击；\r\n    //   跑 2.30×1.70 = 3.91 快过最快的猫，所以\"按住 Shift 一定跑得掉\"是这游戏对玩家唯一的承诺。\r\n    //   把走路调到 2.8，猫的追击就永远追不上，生命条也就没有意义了。\r\n    internal float WalkSpeed = 2.3f;\r\n    internal float RunMul = 1.70f;\r\n    internal float JumpSpeed = 3.2f;\r\n\r\n    /// 起跳速度的倍率。0.16 m 眼高的老鼠，3.2 m/s 起跳 = **0.26 m 高**，刚好跨过路缘和台阶\r\n    /// （街区/后院要的就是这个数：跳太高会变成\"随时在飘\"）。\r\n    /// 冰箱曾经把它调到 1.75 硬跳 0.56 m 的层高 —— 实测跳不上去，已经改成**走楼梯**，\r\n    /// 所以现在四个场景都是 1。留着这个字段是为了以后调手感，不是给某个场景专用的开关。\r\n    internal float JumpMul = 1f;\r\n    internal float Gravity = -20f;\r\n    internal float LookSens = 0.10f;       // 度 / 像素\r\n\r\n    internal CharacterController Cc;\r\n    internal Transform Eye;\r\n    internal Camera Cam;\r\n\r\n    internal float Yaw;                    // 身体朝向（度）\r\n    internal float Pitch;                  // 眼睛俯仰（度），正数低头\r\n    internal float Speed;                  // 实测水平速度 m/s（读数条 / 小地图共用）\r\n\r\n    /// 水平朝向（单位向量，已去掉俯仰）。\r\n    ///\r\n    /// **站着不动、只转鼠标时它也会变** —— 小地图箭头要的正是这个。\r\n    /// 别再拿\"上一帧位移方向\"当朝向：静止时那是 0，方向只能靠最后一次移动残留，\r\n    /// 于是\"面朝北站着转了一圈\"箭头一动不动。\r\n    internal Vector3 Facing\r\n    {\r\n        get\r\n        {\r\n            Vector3 f = transform.forward;\r\n            f.y = 0f;\r\n            // 俯仰接近 ±90° 时投影会退化；这时退回上一帧的 Yaw，别返回零向量\r\n            if (f.sqrMagnitude < 1e-6f)\r\n                return new Vector3(Mathf.Sin(Yaw * Mathf.Deg2Rad), 0f, Mathf.Cos(Yaw * Mathf.Deg2Rad));\r\n            return f.normalized;\r\n        }\r\n    }\r\n\r\n    /// 能不能操作。标题页、结算页把它设成 false —— 拦截方式**不是** timeScale，\r\n    /// 所以不存在\"世界被冻住、人也没法走\"这种连坐。\r\n    internal bool AcceptInput = true;\r\n\r\n    float _vy;\r\n    float _noLookUntil;\r\n    float _unlockedAt = -99f;\r\n    bool _escaped;                          // 按过 Esc：不再自动锁光标，等玩家自己点回来\r\n    float _stuckT;\r\n    float _movedTotal;\r\n    bool _loggedMove;\r\n    bool _loggedStuck;\r\n    float _idleT;                           // 距上次\"移动输入\"的秒数（满 3 秒吱一声）\r\n    Vector3 _spawn;                         // 出生点（贴地之后的真实值），掉出世界时回这里\r\n\r\n    // ───────────────────────── 出生 ─────────────────────────\r\n\r\n    /// 造一个全新的玩家。`feet` 是**脚底**的世界坐标，`yaw` 是身体朝向（度）。\r\n    /// 调用前场景里的老玩家还在也没关系 —— 这里会把它整个关掉。\r\n    internal static NbPlayer Spawn(Vector3 feet, float yaw)\r\n    {\r\n        if (I != null) return I;\r\n\r\n        // ① 场景里那个老玩家整个关掉（连带它自带的胶囊、相机、AudioListener、旧移动脚本一起停）\r\n        Transform old = FindScenePlayer();\r\n        string oldInfo = \"无\";\r\n        if (old != null)\r\n        {\r\n            oldInfo = string.Format(\"「{0}」位置 ({1:F2},{2:F2},{3:F2}) 缩放 ({4:F2},{5:F2},{6:F2})\",\r\n                old.name, old.position.x, old.position.y, old.position.z,\r\n                old.lossyScale.x, old.lossyScale.y, old.lossyScale.z);\r\n            old.gameObject.SetActive(false);\r\n        }\r\n\r\n        // ② 场上所有别的相机 / 音频监听器全部关掉：两个相机同时画、其中一个还没有 AudioListener，\r\n        //    表现可能是\"画面是另一个相机看到的\"——而且完全不报错。\r\n        int camOff = 0, listenOff = 0;\r\n        Camera[] cams = Object.FindObjectsByType<Camera>(FindObjectsInactive.Include, FindObjectsSortMode.None);\r\n        for (int i = 0; i < cams.Length; i++)\r\n        {\r\n            if (cams[i] == null || !cams[i].enabled) continue;\r\n            cams[i].enabled = false;\r\n            camOff++;\r\n        }\r\n        AudioListener[] listeners = Object.FindObjectsByType<AudioListener>(FindObjectsInactive.Include, FindObjectsSortMode.None);\r\n        for (int i = 0; i < listeners.Length; i++)\r\n        {\r\n            if (listeners[i] == null || !listeners[i].enabled) continue;\r\n            listeners[i].enabled = false;\r\n            listenOff++;\r\n        }\r\n\r\n        // ③ 新身体\r\n        GameObject go = new GameObject(\"Player (new)\");\r\n        go.transform.position = feet;\r\n        go.transform.rotation = Quaternion.Euler(0f, yaw, 0f);\r\n        go.transform.localScale = Vector3.one;\r\n\r\n        CharacterController cc = go.AddComponent<CharacterController>();\r\n        cc.height = BodyHeight;\r\n        cc.radius = BodyRadius;\r\n        cc.center = new Vector3(0f, BodyHeight * 0.5f, 0f);   // 原点在脚底\r\n        cc.slopeLimit = 52f;\r\n        // 老鼠只有 0.30 高：台阶上限必须跟着压到 8 cm（铺装层之间差 3~4 cm，够跨）。\r\n        // 原来 0.32 是为了让成年人一步跨过 0.34 m 高的奶酪，现在这一步由\r\n        // SpawnCheese 里的 Physics.IgnoreCollision 负责，不再靠 teleport 式的台阶。\r\n        cc.stepOffset = 0.08f;\r\n        cc.skinWidth = 0.012f;\r\n        cc.minMoveDistance = 0f;\r\n\r\n        // ④ 眼睛（相机）\r\n        GameObject eyeGo = new GameObject(\"Eye\");\r\n        eyeGo.transform.SetParent(go.transform, false);\r\n        eyeGo.transform.localPosition = new Vector3(0f, EyeHeight, 0f);\r\n        eyeGo.transform.localRotation = Quaternion.identity;\r\n\r\n        Camera cam = eyeGo.AddComponent<Camera>();\r\n        // 老鼠视角：近裁剪面必须很小，否则贴着地面/墙走时会\"切\"出一条空缝；\r\n        // FOV 放宽到 72° —— 小动物眼睛的视野本来就宽，而且低机位配宽视场能把\r\n        // 两侧楼体的透视压得更陡，显得楼更高、自己更小。\r\n        cam.nearClipPlane = 0.02f;\r\n        cam.farClipPlane = 400f;\r\n        cam.fieldOfView = 72f;\r\n        cam.depth = 50f;\r\n        cam.clearFlags = CameraClearFlags.SolidColor;\r\n        cam.backgroundColor = new Color(0.035f, 0.045f, 0.075f);\r\n        cam.allowHDR = true;\r\n        cam.allowMSAA = true;\r\n        cam.cullingMask = ~0;             // 什么都不剔除：宁可多画，也不要\"图层被剔掉只剩一片底色\"\r\n        eyeGo.tag = \"MainCamera\";         // Camera.main 要能找到它（NbLighting / 自检都靠这个）\r\n\r\n        eyeGo.AddComponent<AudioListener>();\r\n\r\n        NbPlayer p = go.AddComponent<NbPlayer>();\r\n        p.Cc = cc;\r\n        p.Eye = eyeGo.transform;\r\n        p.Cam = cam;\r\n        p.Yaw = yaw;\r\n        p.Pitch = 0f;\r\n        I = p;\r\n\r\n        Debug.LogFormat(\"[Player] 新玩家已生成：(脚底) {0:F2},{1:F2},{2:F2}，朝向 {3:F0}°；\" +\r\n                        \"胶囊 高{4:F2}/半径{5:F2}，眼高 {6:F2}。\" +\r\n                        \"关掉旧玩家 {7}；关掉其它相机 {8} 台、其它 AudioListener {9} 个。\",\r\n            feet.x, feet.y, feet.z, yaw, BodyHeight, BodyRadius, EyeHeight,\r\n            oldInfo, camOff, listenOff);\r\n\r\n        return p;\r\n    }\r\n\r\n    /// 找场景里原来那个玩家（不管它是不是被关掉、挂在哪一层）。\r\n    internal static Transform FindScenePlayer()\r\n    {\r\n        Scene scene = SceneManager.GetActiveScene();\r\n        foreach (GameObject root in scene.GetRootGameObjects())\r\n        {\r\n            if (root.name == \"FirstPersonController\") return root.transform;\r\n            Transform t = root.transform.Find(\"FirstPersonController\");\r\n            if (t != null) return t;\r\n        }\r\n        foreach (GameObject root in scene.GetRootGameObjects())\r\n        {\r\n            foreach (Transform t in root.GetComponentsInChildren<Transform>(true))\r\n                if (t.name == \"FirstPersonController\") return t;\r\n        }\r\n        return null;\r\n    }\r\n\r\n    // ───────────────────────── 生命周期 ─────────────────────────\r\n\r\n    IEnumerator Start()\r\n    {\r\n        GroundSnap();\r\n        _spawn = transform.position;\r\n        _noLookUntil = Time.unscaledTime + 0.45f;   // 刚出生别吃鼠标跳变\r\n\r\n        LogSetup();\r\n\r\n        yield return new WaitForSecondsRealtime(0.9f);\r\n        Probe(\"开场\");\r\n    }\r\n\r\n    void OnDestroy()\r\n    {\r\n        if (I == this) I = null;\r\n        Cursor.lockState = CursorLockMode.None;\r\n        Cursor.visible = true;\r\n    }\r\n\r\n    void LogSetup()\r\n    {\r\n        Debug.LogFormat(\"[Player] 就位：世界位置 ({0:F2},{1:F2},{2:F2})，Yaw {3:F0}°，Pitch {4:F0}°；\" +\r\n                        \"Eye 世界 ({5:F2},{6:F2},{7:F2})；相机 enabled={8} depth={9} 清屏={10} FOV={11:F0} 掩码 0x{12:X} near={13:F2}\",\r\n            transform.position.x, transform.position.y, transform.position.z, Yaw, Pitch,\r\n            Eye.position.x, Eye.position.y, Eye.position.z,\r\n            Cam != null && Cam.enabled, Cam != null ? Cam.depth : -1f,\r\n            Cam != null ? Cam.clearFlags.ToString() : \"?\", Cam != null ? Cam.fieldOfView : 0f,\r\n            Cam != null ? Cam.cullingMask : 0, Cam != null ? Cam.nearClipPlane : 0f);\r\n\r\n        int live = 0;\r\n        Camera[] all = Object.FindObjectsByType<Camera>(FindObjectsInactive.Include, FindObjectsSortMode.None);\r\n        for (int i = 0; i < all.Length; i++) if (all[i] != null && all[i].enabled && all[i].gameObject.activeInHierarchy) live++;\r\n        Debug.LogFormat(\"[Player] 场上启用中的相机共 {0} 台（必须正好 1 台，就是玩家眼睛）。\", live);\r\n        if (live != 1)\r\n            Debug.LogError(\"[Player] 相机数量不是 1 —— 画面可能来自别人的相机，这就足以让「你看到的东西」和「玩家所在的位置」完全脱节。\");\r\n    }\r\n\r\n    // ───────────────────────── 每帧 ─────────────────────────\r\n\r\n    void Update()\r\n    {\r\n        if (Cc == null || Eye == null) return;      // Spawn 还没把字段塞进来（同帧竞态，理论上不会）\r\n\r\n        float raw = Time.unscaledDeltaTime;\r\n        float dt = Mathf.Clamp(raw, 0f, 0.05f);\r\n\r\n        Keyboard kb = Keyboard.current;\r\n        Mouse mouse = Mouse.current;\r\n\r\n        ManageCursor(kb, mouse);\r\n\r\n        // ── 视角 ──\r\n        if (AcceptInput)\r\n        {\r\n            if (mouse != null && Time.unscaledTime >= _noLookUntil)\r\n            {\r\n                // 不看 lockState：Input System 的 delta 在未锁定时也照常给，\r\n                // 这样\"锁光标失败\"不会顺带把转视角也废掉（旧版就是栽在这上面）。\r\n                Vector2 d = mouse.delta.ReadValue();\r\n                d.x = Mathf.Clamp(d.x, -70f, 70f);      // 锁光标那一帧会有一次巨大跳变，夹住而不是丢掉\r\n                d.y = Mathf.Clamp(d.y, -70f, 70f);\r\n                Yaw += d.x * LookSens;\r\n                // 旧版这里一次 −2000 px 的跳变能把俯仰顶到 −89°：整屏只剩脚下一块地砖，\r\n                // 而那地砖没有贴图、光照又平 ⇒ 走起来画面几乎不变 ⇒「卡死了」。\r\n                Pitch = Mathf.Clamp(Pitch - d.y * LookSens, -80f, 80f);\r\n            }\r\n\r\n            if (kb != null)\r\n            {\r\n                float turn = 0f;\r\n                if (kb.qKey.isPressed) turn -= 1f;\r\n                if (kb.eKey.isPressed) turn += 1f;\r\n                if (turn != 0f) Yaw += turn * 100f * dt;\r\n            }\r\n\r\n            transform.rotation = Quaternion.Euler(0f, Yaw, 0f);\r\n            Eye.localRotation = Quaternion.Euler(Pitch, 0f, 0f);\r\n        }\r\n\r\n        // ── 位移 ──\r\n        float h = 0f, v = 0f;\r\n        if (AcceptInput && kb != null)\r\n        {\r\n            if (kb.wKey.isPressed || kb.upArrowKey.isPressed) v += 1f;\r\n            if (kb.sKey.isPressed || kb.downArrowKey.isPressed) v -= 1f;\r\n            if (kb.aKey.isPressed || kb.leftArrowKey.isPressed) h -= 1f;\r\n            if (kb.dKey.isPressed || kb.rightArrowKey.isPressed) h += 1f;\r\n        }\r\n\r\n        Quaternion yawQ = Quaternion.Euler(0f, Yaw, 0f);\r\n        Vector3 wish = yawQ * Vector3.forward * v + yawQ * Vector3.right * h;\r\n        if (wish.sqrMagnitude > 1f) wish.Normalize();\r\n\r\n        bool running = AcceptInput && kb != null && (kb.leftShiftKey.isPressed || kb.rightShiftKey.isPressed);\r\n        float speed = WalkSpeed * (running ? RunMul : 1f);\r\n\r\n        if (Cc.isGrounded)\r\n        {\r\n            if (_vy < 0f) _vy = -3f;                                  // 贴地小下压，让 isGrounded 稳定\r\n            if (AcceptInput && kb != null && kb.spaceKey.wasPressedThisFrame) _vy = JumpSpeed * JumpMul;\r\n        }\r\n        _vy += Gravity * dt;\r\n\r\n        Vector3 before = transform.position;\r\n        Cc.Move(wish * speed * dt + Vector3.up * (_vy * dt));\r\n        Vector3 delta = transform.position - before;\r\n        delta.y = 0f;\r\n\r\n        Speed = raw > 0.0001f ? delta.magnitude / raw : 0f;\r\n        _movedTotal += delta.magnitude;\r\n\r\n        // 掉出世界兜底：某段过道漏了碰撞体时人会一直往下掉，屏幕上只剩天空/雾 ——\r\n        // 那看起来和\"卡住\"一模一样，而且一路往下掉时也是\"什么都不动\"。\r\n        if (transform.position.y < _spawn.y - 8f)\r\n        {\r\n            Debug.LogWarningFormat(\"[Player] 掉到 y={0:F1}（出生点 y={1:F1}）—— 脚底下有段地面没有碰撞体，已送回出生点。\",\r\n                transform.position.y, _spawn.y);\r\n            Teleport(_spawn, Yaw);\r\n        }\r\n\r\n        // ── 两条自证日志（只打一次，不刷屏）──\r\n        if (!_loggedMove && _movedTotal > 1.2f)\r\n        {\r\n            _loggedMove = true;\r\n            Debug.LogFormat(\"[Player] 已经在移动：累计 {0:F2} m，速度 {1:F2} m/s —— 输入 → CharacterController 这条链是通的。\" +\r\n                            \"（如果你看到的画面还是不动，问题在画面上，不在输入上）\", _movedTotal, Speed);\r\n        }\r\n\r\n        if (wish.sqrMagnitude > 0.01f && delta.sqrMagnitude < 0.000001f)\r\n        {\r\n            _stuckT += raw;\r\n            if (_stuckT > 0.7f && !_loggedStuck)\r\n            {\r\n                _loggedStuck = true;\r\n                Debug.LogWarningFormat(\"[Player] 按着键却一步没动（位置 {0:F2},{1:F2},{2:F2}）：{3}\",\r\n                    transform.position.x, transform.position.y, transform.position.z, Blockers());\r\n            }\r\n        }\r\n        else _stuckT = 0f;\r\n\r\n        // ── 闲置吱吱叫 ──\r\n        // 只认**移动输入**（WASD / 方向键 / 跳）：站着转头、Shift、Q/E 都不算。\r\n        // 满 3 秒吱一声，之后每满 3 秒再吱；一旦重新移动，立刻停。\r\n        bool moveInput = h != 0f || v != 0f || (kb != null && kb.spaceKey.wasPressedThisFrame);\r\n        if (moveInput)\r\n        {\r\n            _idleT = 0f;\r\n        }\r\n        else\r\n        {\r\n            _idleT += raw;\r\n            if (_idleT >= 3f)\r\n            {\r\n                _idleT = 0f;\r\n                AudioManager.PlaySqueak();\r\n            }\r\n        }\r\n    }\r\n\r\n    string Blockers()\r\n    {\r\n        Vector3 mid = transform.position + Vector3.up * (BodyHeight * 0.5f);\r\n        float r = BodyRadius * 0.92f;\r\n        Collider[] hits = Physics.OverlapCapsule(mid + Vector3.up * (BodyHeight * 0.5f - r),\r\n                                                mid - Vector3.up * (BodyHeight * 0.5f - r),\r\n                                                r, ~0, QueryTriggerInteraction.Ignore);\r\n        var names = new List<string>();\r\n        for (int i = 0; i < hits.Length; i++)\r\n        {\r\n            if (hits[i] == null) continue;\r\n            if (hits[i] is CharacterController && hits[i].transform == transform) continue;\r\n            names.Add(hits[i].name);\r\n        }\r\n        if (names.Count == 0)\r\n            return \"胶囊没有和任何碰撞体重叠 ⇒ 不是被卡住，检查 Cc.enabled 与地面高度\";\r\n        return \"胶囊被 \" + names.Count + \" 个碰撞体包着：\" + string.Join(\", \", names.ToArray());\r\n    }\r\n\r\n    // ───────────────────────── 对外的动作 ─────────────────────────\r\n\r\n    /// 台阶上限。**冰箱必须调高**：那一关是走上楼梯（每级 0.14 m），\r\n    /// 而默认的 0.08 是按街区那些 3~4 cm 的铺装高差定的 ——\r\n    /// 用 0.08 去走 0.14 的踏步，表现是\"贴着台阶推不动\"，\r\n    /// 而且角色控制器不会报任何错，看上去就像那里有一堵透明的墙。\r\n    /// 切场景时**每次都要显式设**（街区/后院要设回 0.08），否则会带着高台阶上限在街上走。\r\n    internal void SetStepUp(float h)\r\n    {\r\n        // 上限卡在 0.75×身高：stepOffset 一旦接近身高，CharacterController 会把\r\n        // 任何齐腰的坎都当成\"台阶\"—— 在冰箱里刚好够用（0.14 的踏步），再多就是作弊。\r\n        if (Cc != null) Cc.stepOffset = Mathf.Clamp(h, 0.02f, BodyHeight * 0.75f);\r\n    }\r\n\r\n    /// 传送到某处（脚底坐标）。关-改-开 CharacterController，否则位置会被它吃掉。\r\n    internal void Teleport(Vector3 feet, float yaw)\r\n    {\r\n        bool was = Cc != null && Cc.enabled;\r\n        if (Cc != null) Cc.enabled = false;\r\n\r\n        transform.position = feet;\r\n        transform.rotation = Quaternion.Euler(0f, yaw, 0f);\r\n        Yaw = yaw;\r\n        Pitch = 0f;\r\n        _vy = 0f;\r\n        Speed = 0f;\r\n        _stuckT = 0f;\r\n        if (Eye != null) Eye.localRotation = Quaternion.identity;\r\n\r\n        if (Cc != null) Cc.enabled = was;\r\n        GroundSnap();\r\n        _noLookUntil = Time.unscaledTime + 0.2f;\r\n    }\r\n\r\n    /// 沿「背离 from」的方向推开一段距离（被猫扑到用），撞墙就少推一点。\r\n    internal void Nudge(Vector3 from, float dist)\r\n    {\r\n        Vector3 dir = transform.position - from;\r\n        dir.y = 0f;\r\n        if (dir.sqrMagnitude < 0.04f) dir = -transform.forward;\r\n        dir.y = 0f;\r\n        if (dir.sqrMagnitude < 0.0001f) dir = Vector3.back;\r\n        dir.Normalize();\r\n\r\n        RaycastHit hit;\r\n        Vector3 origin = transform.position + Vector3.up * (BodyHeight * 0.5f);\r\n        if (Physics.SphereCast(origin, BodyRadius, dir, out hit, dist, ~0, QueryTriggerInteraction.Ignore) &&\r\n            hit.collider != null && !hit.collider.transform.IsChildOf(transform))\r\n        {\r\n            dist = Mathf.Max(0.6f, hit.distance - 0.15f);\r\n        }\r\n\r\n        Teleport(transform.position + dir * dist, Yaw);\r\n    }\r\n\r\n    /// 把脚底贴到地面上（正下方 6 m 内最近的实体表面）。\r\n    internal void GroundSnap()\r\n    {\r\n        Vector3 from = transform.position + Vector3.up * 0.6f;\r\n        RaycastHit[] hits = Physics.RaycastAll(from, Vector3.down, 8f, ~0, QueryTriggerInteraction.Ignore);\r\n        float best = float.MaxValue;\r\n        for (int i = 0; i < hits.Length; i++)\r\n        {\r\n            if (hits[i].collider == null) continue;\r\n            if (hits[i].collider.transform.IsChildOf(transform)) continue;   // 别量到自己身上\r\n            if (hits[i].distance < best) best = hits[i].distance;\r\n        }\r\n        if (best < float.MaxValue)\r\n        {\r\n            float y = from.y - best + 0.02f;\r\n            if (Mathf.Abs(y - transform.position.y) > 0.001f)\r\n            {\r\n                bool was = Cc != null && Cc.enabled;\r\n                if (Cc != null) Cc.enabled = false;\r\n                transform.position = new Vector3(transform.position.x, y, transform.position.z);\r\n                if (Cc != null) Cc.enabled = was;\r\n                Debug.LogFormat(\"[Player] 贴地：脚底 y {0:F3} → {1:F3}（正下方地面 {2:F2} m）。\",\r\n                    transform.position.y, y, best);\r\n            }\r\n        }\r\n        else\r\n        {\r\n            Debug.LogWarning(\"[Player] 脚底正下方 6 m 内没有地面 —— 人会一直往下掉。检查过道/地面有没有碰撞体。\");\r\n        }\r\n    }\r\n\r\n    internal void LockCursor()\r\n    {\r\n        Cursor.lockState = CursorLockMode.Locked;\r\n        Cursor.visible = false;\r\n        _escaped = false;\r\n        _noLookUntil = Time.unscaledTime + 0.25f;\r\n    }\r\n\r\n    // ───────────────────────── 光标 ─────────────────────────\r\n\r\n    void ManageCursor(Keyboard kb, Mouse mouse)\r\n    {\r\n        if (!AcceptInput)\r\n        {\r\n            if (Cursor.lockState != CursorLockMode.None)\r\n            {\r\n                Cursor.lockState = CursorLockMode.None;\r\n                Cursor.visible = true;\r\n            }\r\n            return;\r\n        }\r\n\r\n        if (Cursor.lockState == CursorLockMode.Locked) return;\r\n\r\n        // Esc 放手：记下\"是玩家主动放开的\"，之后不再自动锁回来，等他自己点画面\r\n        if (kb != null && kb.escapeKey.wasPressedThisFrame)\r\n        {\r\n            Cursor.lockState = CursorLockMode.None;\r\n            Cursor.visible = true;\r\n            _escaped = true;\r\n            _unlockedAt = Time.unscaledTime;\r\n            return;\r\n        }\r\n\r\n        bool clicked = mouse != null && mouse.leftButton.wasPressedThisFrame;\r\n        if (clicked)\r\n        {\r\n            LockCursor();\r\n            return;\r\n        }\r\n        if (!_escaped && Time.unscaledTime - _unlockedAt > 2.0f)\r\n        {\r\n            // 一直没锁上（编辑器切窗口、系统把锁丢了）就自己锁回来：\r\n            // 不锁光标时鼠标能飘出游戏窗口，转视角也会跟着卡。\r\n            LockCursor();\r\n        }\r\n    }\r\n\r\n    // ───────────────────────── 诊断 ─────────────────────────\r\n\r\n    /// 只回答一个问题：眼睛现在站在哪、朝哪、眼前有没有东西挡着。\r\n    internal void Probe(string tag)\r\n    {\r\n        if (Cam == null) return;\r\n\r\n        Vector3 p = Cam.transform.position;\r\n        Vector3 f = Cam.transform.forward;\r\n        Debug.LogFormat(\"[Player] 自检({0}) 眼位 ({1:F2},{2:F2},{3:F2})，朝向 ({4:F2},{5:F2},{6:F2})，\" +\r\n                        \"Yaw {7:F0}° Pitch {8:F0}°，离地 {9:F2} m\",\r\n            tag, p.x, p.y, p.z, f.x, f.y, f.z, Yaw, Pitch, p.y - GroundY());\r\n\r\n        RaycastHit[] hits = Physics.RaycastAll(p, f, 60f, ~0, QueryTriggerInteraction.Ignore);\r\n        System.Array.Sort(hits, (a, b) => a.distance.CompareTo(b.distance));\r\n        var sb = new List<string>();\r\n        for (int i = 0; i < hits.Length && sb.Count < 4; i++)\r\n        {\r\n            if (hits[i].collider == null) continue;\r\n            sb.Add(string.Format(\"{0:F2} m「{1}」\", hits[i].distance, hits[i].collider.name));\r\n        }\r\n        Debug.LogFormat(\"[Player] 自检({0}) 视线上的碰撞体（60 m）：{1}\",\r\n            tag, sb.Count == 0 ? \"一个都没有 —— 前面是空的\" : string.Join(\" | \", sb.ToArray()));\r\n    }\r\n\r\n    float GroundY()\r\n    {\r\n        RaycastHit[] hits = Physics.RaycastAll(transform.position + Vector3.up * 0.6f, Vector3.down, 8f, ~0, QueryTriggerInteraction.Ignore);\r\n        float best = float.MaxValue;\r\n        for (int i = 0; i < hits.Length; i++)\r\n        {\r\n            if (hits[i].collider == null) continue;\r\n            if (hits[i].collider.transform.IsChildOf(transform)) continue;\r\n            if (hits[i].distance < best) best = hits[i].distance;\r\n        }\r\n        if (best == float.MaxValue) return transform.position.y;\r\n        return transform.position.y + 0.6f - best;\r\n    }\r\n}\r\n"},"NbScene":{"path":"Assets/Scripts/NbScene.cs","role":"Scene shell: selects the active scene (Street/Yard/Kitchen/Fridge), holds its bounds/spawn/targets/routes, hides the street original.","source":"// @role Scene shell: selects the active scene (Street/Yard/Kitchen/Fridge), holds its bounds/spawn/targets/routes, hides the street original.\r\n// @calls NbYard NbKitchen NbFridge NbBuilder\r\n\r\n// NbScene.cs — 三个场景的公共外壳\r\n//\r\n// 为什么需要这一层：\r\n//   原来 Nb 这个静态类把街区的几何（XMin/XMax、ColX/RowZ、CheeseSpots、CatRoutes）全写死了，\r\n//   NbGame 直接读它。再加两个场景就没地方放数据 —— 于是把\"当前场景\"抽成一组静态字段，\r\n//   由 NbScene.Select 在开机时写一次，NbGame / NbMap / HUD 只认这组字段，不认具体是哪个场景。\r\n//\r\n// 三个场景共用同一套玩法骨架（收齐 N 个目标、被 N 个威胁抓、10 关递进），但压力来源不同：\r\n//   Street   猫巡逻 + 视野锥          —— 走廊本身有风险\r\n//   Yard     保安 + 手电锥（会追人）  —— 掩体之间是空地，被照到就得跑\r\n//   Kitchen  食物腐烂 + 灯管 + 黑猫   —— 走道窄到躲不开灯\r\n//\r\n// 还有一件容易被忽略的事：**原始 SampleScene 里那 12 栋楼、地面、围墙是街区专用的。**\r\n// 后院和厨房必须把它们整体关掉，否则会在别人的场地上凭空出现一片居民区。\r\n// 这件事由 HideOriginal 负责，切回街区时再打开 —— 只关不恢复会让第二次进街区变成空地。\r\n\r\nusing UnityEngine;\r\nusing UnityEngine.SceneManagement;\r\n\r\n// Kitchen 保留在枚举里、但已经不挂在选择页上了：第三格换成了冰箱（Fridge = 3）。\r\n// 之所以不删这个值 —— NbKitchen.cs 还在，NbLevels 里那张表也还在，\r\n// 想换回去只要把选择页的 Order 改一格，别的一行都不用动。\r\ninternal enum NbSceneKind { Street = 0, Yard = 1, Kitchen = 2, Fridge = 3 }\r\n\r\ninternal static class NbScene\r\n{\r\n    internal static NbSceneKind Kind = NbSceneKind.Street;\r\n\r\n    // ───────────────────────── 当前场景 ─────────────────────────\r\n\r\n    internal static string Name  = \"RESIDENTIAL BLOCK\";\r\n    internal static string Code  = \"BLOCK\";\r\n    internal static string Blurb = \"Twelve houses, five alleys, no light.\";\r\n\r\n    internal static float XMin = Nb.XMin;\r\n    internal static float XMax = Nb.XMax;\r\n    internal static float ZMin = Nb.ZMin;\r\n    internal static float ZMax = Nb.ZMax;\r\n\r\n    internal static Vector3    Start   = Nb.PlayerStart;\r\n    internal static Vector3    Forward = Nb.PlayerForward;\r\n    internal static Vector3[]  Targets = Nb.CheeseSpots;\r\n    internal static Vector3[][] Routes  = Nb.CatRoutes;\r\n\r\n    internal static int MaxTargets = 10;\r\n    internal static int MaxRoutes  = 10;\r\n\r\n    // 机制开关：NbGame 只问\"这个场景要不要跑这套逻辑\"，不问\"你是哪个场景\"。\r\n    internal static bool UsesGuards { get { return Kind == NbSceneKind.Yard; } }\r\n    internal static bool UsesRot    { get { return Kind == NbSceneKind.Kitchen; } }\r\n    internal static bool UsesLamps  { get { return Kind == NbSceneKind.Kitchen; } }\r\n\r\n    /// 冰箱：威胁是\"人开门 + 3 秒预警\"。开着这一项时 NbGame 会跑 DoorUpdate，\r\n    /// 并且**跳过贴地**（目标点各自带着层高 y，贴地会把六层全压回 0）。\r\n    internal static bool UsesDoor   { get { return Kind == NbSceneKind.Fridge; } }\r\n\r\n    /// 目标点是否自带高度。只有冰箱是 true —— 别的场景全场 y=0，贴地只是保险。\r\n    internal static bool KeepsHeight { get { return Kind == NbSceneKind.Fridge; } }\r\n\r\n    internal static float Width   { get { return XMax - XMin; } }\r\n    internal static float Depth   { get { return ZMax - ZMin; } }\r\n    internal static float CenterX { get { return (XMin + XMax) * 0.5f; } }\r\n    internal static float CenterZ { get { return (ZMin + ZMax) * 0.5f; } }\r\n\r\n    internal static bool Inside(Vector3 p, float margin)\r\n    {\r\n        return p.x > XMin + margin && p.x < XMax - margin &&\r\n               p.z > ZMin + margin && p.z < ZMax - margin;\r\n    }\r\n\r\n    // ───────────────────────── 切换 ─────────────────────────\r\n\r\n    internal static void Select(NbSceneKind k)\r\n    {\r\n        Kind = k;\r\n        switch (k)\r\n        {\r\n            case NbSceneKind.Yard:    NbYard.Setup();    break;\r\n            case NbSceneKind.Kitchen: NbKitchen.Setup(); break;\r\n            case NbSceneKind.Fridge:  NbFridge.Setup();  break;\r\n            default:                  SetupStreet();     break;\r\n        }\r\n        HideOriginal(k != NbSceneKind.Street);\r\n    }\r\n\r\n    static void SetupStreet()\r\n    {\r\n        Name  = \"RESIDENTIAL BLOCK\";\r\n        Code  = \"BLOCK\";\r\n        Blurb = \"Twelve houses, five alleys, no light.\";\r\n\r\n        XMin = Nb.XMin; XMax = Nb.XMax;\r\n        ZMin = Nb.ZMin; ZMax = Nb.ZMax;\r\n\r\n        Start   = Nb.PlayerStart;\r\n        Forward = Nb.PlayerForward;\r\n        Targets = Nb.CheeseSpots;\r\n        Routes  = Nb.CatRoutes;\r\n        MaxTargets = Targets.Length;\r\n        MaxRoutes  = Routes.Length;\r\n    }\r\n\r\n    // ───────────────────────── 搭场景 ─────────────────────────\r\n\r\n    internal static void Build(Transform root)\r\n    {\r\n        switch (Kind)\r\n        {\r\n            case NbSceneKind.Yard:    NbYard.Build(root);    break;\r\n            case NbSceneKind.Kitchen: NbKitchen.Build(root); break;\r\n            case NbSceneKind.Fridge:  NbFridge.Build(root);  break;\r\n            default:                  NbBuilder.Build(root); break;\r\n        }\r\n    }\r\n\r\n    /// 原始场景里属于「居民街区」的根物体。换场景时整体关掉，切回来再打开。\r\n    /// 'Plane' 也在里面 —— 它是街区那块 200×200 的大地面；后院/厨房有各自的地板，\r\n    /// 留着它会把新场景的地面整个盖住（而且是亮灰色，一眼就穿帮）。\r\n    static readonly string[] OriginalRoots =\r\n    {\r\n        \"Street Models (auto)\", \"Street\", \"Plane\",\r\n        \"===Residential Area===\", \"===Interior Hallway===\", \"CatMoveSpace\",\r\n    };\r\n\r\n    internal static void HideOriginal(bool hide)\r\n    {\r\n        Scene s = SceneManager.GetActiveScene();\r\n        if (!s.IsValid()) return;\r\n\r\n        GameObject[] roots = s.GetRootGameObjects();\r\n        int n = 0;\r\n        for (int i = 0; i < roots.Length; i++)\r\n        {\r\n            GameObject go = roots[i];\r\n            if (go == null) continue;\r\n            for (int j = 0; j < OriginalRoots.Length; j++)\r\n            {\r\n                if (go.name != OriginalRoots[j]) continue;\r\n                if (go.activeSelf != !hide) n++;\r\n                go.SetActive(!hide);\r\n                break;\r\n            }\r\n        }\r\n        Debug.LogFormat(\"[Nb] 原始街区物体 {0} 个：{1}。\", n, hide ? \"已关闭\" : \"已恢复\");\r\n    }\r\n}\r\n\r\n/// 场景进度。**自由选择**模式：三个场景都能进，各自记\"最高打到第几关\"。\r\n/// 用 PlayerPrefs 而不是文件：这个工程没有存档系统，PlayerPrefs 在 Editor 里跨 Play 也能留住，\r\n/// 而且不会因为路径/权限问题静默失败（写到一半失败比不存更糟）。\r\ninternal static class NbProgress\r\n{\r\n    const string Key = \"nb.scene.best.\";\r\n\r\n    /// 返回该场景可以进入的最高关卡（1 起）。默认 1。\r\n    internal static int Best(NbSceneKind k)\r\n    {\r\n        return Mathf.Clamp(PlayerPrefs.GetInt(Key + (int)k, 1), 1, NbLevels.Count);\r\n    }\r\n\r\n    internal static void Reach(NbSceneKind k, int level)\r\n    {\r\n        if (level <= Best(k)) return;\r\n        PlayerPrefs.SetInt(Key + (int)k, Mathf.Clamp(level, 1, NbLevels.Count));\r\n        PlayerPrefs.Save();\r\n    }\r\n\r\n    internal static void ClearAll()\r\n    {\r\n        for (int i = 0; i < 4; i++) PlayerPrefs.DeleteKey(Key + i);\r\n        PlayerPrefs.Save();\r\n    }\r\n}\r\n"},"NbSceneSelect":{"path":"Assets/Scripts/NbSceneSelect.cs","role":"Scene-select page after the title: pick Street/Yard/Fridge, each with its own best-level progress.","source":"// @role Scene-select page after the title: pick Street/Yard/Fridge, each with its own best-level progress.\r\n// @calls NbGame NbScene NbProgress NbUi\r\n\r\n// NbSceneSelect.cs — 标题页之后的场景选择页\r\n//\r\n// 为什么单独一页、而不是做进标题页：\r\n//   标题页只负责\"这是什么东西\"，选择页负责\"我今天想玩哪一个\"。挤在一页会有两个主按钮，\r\n//   玩家会先点错再回来 —— 而这三个场景的难度起点完全一样（都是第 1 关），\r\n//   选错的代价是重新走一遍标题页。\r\n//\r\n// 交互沿用标题页那套：RectTransformUtility 手动判定 + Mouse.current，不依赖 EventSystem。\r\n//   鼠标悬停变亮、点击进入；键盘 1 / 2 / 3 也能选（测试时比找鼠标快得多）。\r\n//\r\n// 三个场景**自由选择**：没有解锁条件，各自记自己的最高关卡（NbProgress）。\r\n// 这一条是用户明确选的 —— 换成顺序解锁的话，每次验收新场景都得先打 10 关。\r\n\r\nusing System.Collections;\r\nusing TMPro;\r\nusing UnityEngine;\r\nusing UnityEngine.InputSystem;\r\nusing UnityEngine.UI;\r\n\r\ninternal class NbSceneSelect : MonoBehaviour\r\n{\r\n    internal static NbSceneSelect I;\r\n    internal static bool Showing { get; private set; }\r\n\r\n    static readonly NbSceneKind[] Order =\r\n    {\r\n        NbSceneKind.Street, NbSceneKind.Yard, NbSceneKind.Fridge,\r\n    };\r\n\r\n    // 每个场景一个主色。**不是装饰**：三张卡片的颜色会一路延续到那一关的 HUD 提示色上，\r\n    // 玩家选完之后就知道\"我在蓝的那一关里\"，不用再看标题。\r\n    static readonly Color[] Accent =\r\n    {\r\n        new Color(1.00f, 0.76f, 0.32f),   // 街区：路灯的暖黄\r\n        new Color(0.46f, 0.68f, 1.00f),   // 后院：月光与手电的冷蓝\r\n        new Color(0.62f, 0.84f, 1.00f),   // 冰箱：冷藏灯的白\r\n    };\r\n\r\n    static readonly string[] Title =\r\n    {\r\n        \"RESIDENTIAL\\nBLOCK\",\r\n        \"BACKYARD\\nPATROL\",\r\n        \"THE\\nFRIDGE\",\r\n    };\r\n\r\n    static readonly string[] Sub =\r\n    {\r\n        \"Twelve houses.  Five alleys.\\nA cat on every corner.\",\r\n        \"One open lawn.\\nNowhere to hide in the middle.\",\r\n        \"Six shelves.  One door.\\nNowhere to stand in the light.\",\r\n    };\r\n\r\n    static readonly Color PanelCol = new Color(0.07f, 0.07f, 0.08f, 0.94f);\r\n    static readonly Color DimCol   = new Color(1f, 1f, 1f, 0.55f);\r\n    static readonly Color TextCol  = new Color(1f, 0.97f, 0.91f, 1f);\r\n\r\n    readonly RectTransform[] _cards = new RectTransform[3];\r\n    readonly Image[] _cardBg = new Image[3];\r\n    readonly TextMeshProUGUI[] _cardHint = new TextMeshProUGUI[3];\r\n\r\n    CanvasGroup _group;\r\n    int _hover = -1;\r\n    bool _picked;\r\n\r\n    // ───────────────────────── 创建 ─────────────────────────\r\n\r\n    internal static NbSceneSelect Show()\r\n    {\r\n        if (I != null) return I;\r\n\r\n        GameObject go = new GameObject(\"Scene Select (auto)\");\r\n        NbSceneSelect s = go.AddComponent<NbSceneSelect>();\r\n        s.Build();\r\n        return s;\r\n    }\r\n\r\n    void Awake()\r\n    {\r\n        I = this;\r\n    }\r\n\r\n    void OnDestroy()\r\n    {\r\n        if (I == this) I = null;\r\n        Showing = false;\r\n    }\r\n\r\n    void Build()\r\n    {\r\n        Showing = true;\r\n\r\n        GameObject canvasGo = new GameObject(\"SceneSelect Canvas (auto)\",\r\n            typeof(Canvas), typeof(CanvasScaler), typeof(CanvasGroup));\r\n        canvasGo.transform.SetParent(transform, false);\r\n\r\n        Canvas canvas = canvasGo.GetComponent<Canvas>();\r\n        canvas.renderMode = RenderMode.ScreenSpaceOverlay;\r\n        canvas.sortingOrder = 60;                 // 压过 HUD(40) 和小地图(41)\r\n\r\n        CanvasScaler scaler = canvasGo.GetComponent<CanvasScaler>();\r\n        scaler.uiScaleMode = CanvasScaler.ScaleMode.ScaleWithScreenSize;\r\n        scaler.referenceResolution = new Vector2(1920f, 1080f);\r\n        scaler.matchWidthOrHeight = 0.5f;\r\n\r\n        _group = canvasGo.GetComponent<CanvasGroup>();\r\n\r\n        Transform c = canvasGo.transform;\r\n\r\n        // 遮罩：选择页是**独立的一屏**，不是浮在游戏上的小窗。\r\n        // 背景要压到几乎全黑，否则背后的街区会争夺注意力。\r\n        RectTransform shade = NbUi.Rect(\"Shade\", c);\r\n        shade.anchorMin = Vector2.zero;\r\n        shade.anchorMax = Vector2.one;\r\n        shade.offsetMin = Vector2.zero;\r\n        shade.offsetMax = Vector2.zero;\r\n        Image sh = shade.gameObject.AddComponent<Image>();\r\n        sh.color = new Color(0.02f, 0.02f, 0.03f, 0.90f);\r\n        sh.raycastTarget = false;\r\n\r\n        TextMeshProUGUI head = NbUi.Text(\"Head\", c, \"CHOOSE  A  DISTRICT\", 46f, TextCol,\r\n            TextAlignmentOptions.Center);\r\n        Center(head.rectTransform, new Vector2(0f, 330f), new Vector2(1200f, 60f));\r\n\r\n        TextMeshProUGUI note = NbUi.Text(\"Note\", c,\r\n            \"Three places, ten levels each.  Pick any one.  They all start at level 1.\",\r\n            20f, DimCol, TextAlignmentOptions.Center);\r\n        Center(note.rectTransform, new Vector2(0f, 278f), new Vector2(1400f, 34f));\r\n\r\n        for (int i = 0; i < 3; i++) BuildCard(c, i);\r\n\r\n        TextMeshProUGUI foot = NbUi.Text(\"Foot\", c,\r\n            \"CLICK  A  CARD   /   PRESS  1  2  3\", 18f,\r\n            new Color(1f, 1f, 1f, 0.40f), TextAlignmentOptions.Center);\r\n        Center(foot.rectTransform, new Vector2(0f, -352f), new Vector2(900f, 30f));\r\n\r\n        Debug.Log(\"[Nb] 场景选择页就位：街区 / 后院 / 冰箱，自由选择。\");\r\n    }\r\n\r\n    void BuildCard(Transform c, int i)\r\n    {\r\n        RectTransform card = NbUi.Rect(\"Card \" + i, c);\r\n        Center(card, new Vector2(-540f + i * 540f, -20f), new Vector2(480f, 470f));\r\n        _cards[i] = card;\r\n\r\n        Image bg = card.gameObject.AddComponent<Image>();\r\n        bg.sprite = NbUi.Round;\r\n        bg.type = Image.Type.Sliced;\r\n        bg.color = PanelCol;\r\n        bg.raycastTarget = false;\r\n        _cardBg[i] = bg;\r\n\r\n        // 顶部色条：这一页唯一的\"颜色身份\"，也是 hover 时唯一会亮的东西\r\n        RectTransform bar = NbUi.Rect(\"Accent\", card);\r\n        bar.anchorMin = bar.anchorMax = bar.pivot = new Vector2(0.5f, 1f);\r\n        bar.anchoredPosition = new Vector2(0f, -22f);\r\n        bar.sizeDelta = new Vector2(120f, 6f);\r\n        Image bi = bar.gameObject.AddComponent<Image>();\r\n        bi.sprite = NbUi.Round;\r\n        bi.type = Image.Type.Sliced;\r\n        bi.color = Accent[i];\r\n        bi.raycastTarget = false;\r\n\r\n        TextMeshProUGUI no = NbUi.Text(\"No\", card, \"0\" + (i + 1), 26f,\r\n            new Color(Accent[i].r, Accent[i].g, Accent[i].b, 0.55f), TextAlignmentOptions.Center);\r\n        Center(no.rectTransform, new Vector2(0f, 178f), new Vector2(200f, 34f));\r\n\r\n        TextMeshProUGUI name = NbUi.Text(\"Name\", card, Title[i], 40f, TextCol,\r\n            TextAlignmentOptions.Center);\r\n        Center(name.rectTransform, new Vector2(0f, 96f), new Vector2(440f, 120f));\r\n\r\n        TextMeshProUGUI sub = NbUi.Text(\"Sub\", card, Sub[i], 21f,\r\n            new Color(1f, 0.97f, 0.91f, 0.66f), TextAlignmentOptions.Center);\r\n        Center(sub.rectTransform, new Vector2(0f, 6f), new Vector2(420f, 80f));\r\n\r\n        RectTransform rule = NbUi.Rect(\"Rule\", card);\r\n        rule.anchorMin = rule.anchorMax = rule.pivot = new Vector2(0.5f, 0.5f);\r\n        rule.anchoredPosition = new Vector2(0f, -54f);\r\n        rule.sizeDelta = new Vector2(360f, 1f);\r\n        Image ri = rule.gameObject.AddComponent<Image>();\r\n        ri.color = new Color(1f, 1f, 1f, 0.12f);\r\n        ri.raycastTarget = false;\r\n\r\n        int best = NbProgress.Best(Order[i]);\r\n        string prog = best >= NbLevels.Count ? \"ALL  TEN  CLEARED\" : \"BEST  LEVEL  \" + best;\r\n        TextMeshProUGUI pr = NbUi.Text(\"Prog\", card, prog, 20f,\r\n            new Color(Accent[i].r, Accent[i].g, Accent[i].b, 0.92f), TextAlignmentOptions.Center);\r\n        Center(pr.rectTransform, new Vector2(0f, -92f), new Vector2(420f, 30f));\r\n\r\n        TextMeshProUGUI hint = NbUi.Text(\"Hint\", card, \"CLICK  TO  ENTER\", 19f,\r\n            new Color(1f, 1f, 1f, 0.35f), TextAlignmentOptions.Center);\r\n        Center(hint.rectTransform, new Vector2(0f, -168f), new Vector2(420f, 30f));\r\n        _cardHint[i] = hint;\r\n    }\r\n\r\n    // ───────────────────────── 交互 ─────────────────────────\r\n\r\n    void Update()\r\n    {\r\n        if (_picked) return;\r\n\r\n        var mouse = Mouse.current;\r\n        var kb = Keyboard.current;\r\n\r\n        Vector2 mp = mouse != null ? mouse.position.ReadValue() : Vector2.zero;\r\n\r\n        int hover = -1;\r\n        for (int i = 0; i < _cards.Length; i++)\r\n        {\r\n            if (_cards[i] == null) continue;\r\n            if (RectTransformUtility.RectangleContainsScreenPoint(_cards[i], mp))\r\n            {\r\n                hover = i;\r\n                break;\r\n            }\r\n        }\r\n\r\n        if (hover != _hover)\r\n        {\r\n            _hover = hover;\r\n            Repaint();\r\n        }\r\n\r\n        if (mouse != null && mouse.leftButton.wasPressedThisFrame && _hover >= 0)\r\n        {\r\n            Pick(_hover);\r\n            return;\r\n        }\r\n\r\n        if (kb != null)\r\n        {\r\n            if (kb.digit1Key.wasPressedThisFrame) { Pick(0); return; }\r\n            if (kb.digit2Key.wasPressedThisFrame) { Pick(1); return; }\r\n            if (kb.digit3Key.wasPressedThisFrame) { Pick(2); return; }\r\n        }\r\n    }\r\n\r\n    /// 悬停只改两样东西：底板亮度和底部那句提示。\r\n    /// 不做缩放/位移动画 —— 三张卡片是并排的，一张放大就会推挤另外两张的视觉重量。\r\n    void Repaint()\r\n    {\r\n        for (int i = 0; i < _cards.Length; i++)\r\n        {\r\n            bool on = i == _hover;\r\n            if (_cardBg[i] != null)\r\n            {\r\n                _cardBg[i].color = on\r\n                    ? new Color(Accent[i].r * 0.22f, Accent[i].g * 0.22f, Accent[i].b * 0.22f, 0.97f)\r\n                    : PanelCol;\r\n            }\r\n            if (_cardHint[i] != null)\r\n            {\r\n                _cardHint[i].text = on ? \"ENTER  THIS  DISTRICT\" : \"CLICK  TO  ENTER\";\r\n                _cardHint[i].color = on ? Accent[i] : new Color(1f, 1f, 1f, 0.35f);\r\n            }\r\n        }\r\n    }\r\n\r\n    void Pick(int i)\r\n    {\r\n        if (_picked) return;\r\n        _picked = true;\r\n\r\n        // **这里不关 Showing。** 淡出还有 0.22 秒，这期间 EnsurePlayable 会每帧\r\n        // 把 AcceptInput 钉回 true —— 要是现在就放开，玩家会带着\"已经走了一段\"的状态进场。\r\n        // 交给 FadeAndGo 的最后一刻再放。\r\n        NbSceneKind k = Order[i];\r\n        Debug.LogFormat(\"[Nb] 选中场景 {0}（{1}）\", i + 1, k);\r\n\r\n        PlayerPrefs.SetInt(\"nb.scene.last\", i);\r\n        PlayerPrefs.Save();\r\n\r\n        StartCoroutine(FadeAndGo(k));\r\n    }\r\n\r\n    IEnumerator FadeAndGo(NbSceneKind k)\r\n    {\r\n        float d = 0.22f, t = 0f;\r\n        while (t < d)\r\n        {\r\n            t += Time.unscaledDeltaTime;\r\n            if (_group != null) _group.alpha = Mathf.Clamp01(1f - t / d);\r\n            yield return null;\r\n        }\r\n\r\n        // 先让世界重建，再销毁自己：反过来的话，这一帧没有任何东西接管输入，\r\n        // 玩家会看到黑屏停在原地（而且不会报错）。\r\n        Showing = false;                       // 交接的一刻才放开操作权\r\n        if (NbGame.I != null) NbGame.I.EnterScene(k);\r\n        else Debug.LogWarning(\"[Nb] 场景选择页找不到 NbGame —— 世界不会重建。\");\r\n\r\n        Destroy(gameObject);\r\n    }\r\n\r\n    static void Center(RectTransform rt, Vector2 pos, Vector2 size)\r\n    {\r\n        rt.anchorMin = rt.anchorMax = rt.pivot = new Vector2(0.5f, 0.5f);\r\n        rt.anchoredPosition = pos;\r\n        rt.sizeDelta = size;\r\n    }\r\n}\r\n"},"NbUi":{"path":"Assets/Scripts/NeighbourhoodHud.cs","role":"In-game HUD: cheese count, toasts, health pips, exposure/rot/door meters, win/fail overlay.","source":"// @role In-game HUD: cheese count, toasts, health pips, exposure/rot/door meters, win/fail overlay.\r\n// @calls NbGame NbScene NbLevels NbUi NbFridge\r\n\r\n// NeighbourhoodHud.cs — 左上角奶酪计数 + 提示条 + 成功面板 + 被抓红闪\r\n//\r\n// 和工程里现成的 CheeseHud 同一套路：运行时建 Canvas，贴图全部程序化生成，\r\n// 字体走 Resources/GameProps/HudFont（指向工程 UI 用的那款 Kindly Crunch）。\r\n\r\nusing TMPro;\r\nusing UnityEngine;\r\nusing UnityEngine.InputSystem;\r\nusing UnityEngine.UI;\r\n\r\n/// 造 UI 用的小工具箱（地图面板也用这里的）\r\ninternal static class NbUi\r\n{\r\n    static Sprite _white, _round, _tri;\r\n    static TMP_FontAsset _font;\r\n    static bool _fontTried;\r\n\r\n    internal static Sprite White\r\n    {\r\n        get\r\n        {\r\n            if (_white == null)\r\n            {\r\n                Texture2D t = new Texture2D(4, 4, TextureFormat.RGBA32, false);\r\n                Color[] px = new Color[16];\r\n                for (int i = 0; i < px.Length; i++) px[i] = Color.white;\r\n                t.SetPixels(px);\r\n                t.Apply();\r\n                t.hideFlags = HideFlags.HideAndDontSave;\r\n                _white = Sprite.Create(t, new Rect(0f, 0f, 4f, 4f), new Vector2(0.5f, 0.5f));\r\n                _white.hideFlags = HideFlags.HideAndDontSave;\r\n            }\r\n            return _white;\r\n        }\r\n    }\r\n\r\n    internal static Sprite Round\r\n    {\r\n        get\r\n        {\r\n            if (_round == null) _round = MakeRounded(48, 12f);\r\n            return _round;\r\n        }\r\n    }\r\n\r\n    /// 朝上的三角形，用来做小地图上的\"自己\"\r\n    internal static Sprite Triangle\r\n    {\r\n        get\r\n        {\r\n            if (_tri == null) _tri = MakeTriangle(64);\r\n            return _tri;\r\n        }\r\n    }\r\n\r\n    internal static TMP_FontAsset Font\r\n    {\r\n        get\r\n        {\r\n            if (!_fontTried)\r\n            {\r\n                _fontTried = true;\r\n                HudFontRef r = Resources.Load<HudFontRef>(\"GameProps/HudFont\");\r\n                if (r != null && r.font != null) _font = r.font;\r\n                else\r\n                {\r\n                    _font = TMP_Settings.defaultFontAsset;\r\n                    Debug.LogWarning(\"[Nb] 取不到 Resources/GameProps/HudFont，UI 退回 TMP 默认字体。\");\r\n                }\r\n            }\r\n            return _font;\r\n        }\r\n    }\r\n\r\n    internal static RectTransform Rect(string name, Transform parent)\r\n    {\r\n        GameObject go = new GameObject(name, typeof(RectTransform));\r\n        RectTransform rt = (RectTransform)go.transform;\r\n        rt.SetParent(parent, false);\r\n        return rt;\r\n    }\r\n\r\n    internal static Image Img(string name, Transform parent, Color color, Sprite sprite = null)\r\n    {\r\n        RectTransform rt = Rect(name, parent);\r\n        Image im = rt.gameObject.AddComponent<Image>();\r\n        im.sprite = sprite != null ? sprite : White;\r\n        im.type = Image.Type.Simple;\r\n        im.color = color;\r\n        im.raycastTarget = false;\r\n        return im;\r\n    }\r\n\r\n    internal static TextMeshProUGUI Text(string name, Transform parent, string s, float size, Color color,\r\n        TextAlignmentOptions align)\r\n    {\r\n        RectTransform rt = Rect(name, parent);\r\n        TextMeshProUGUI t = rt.gameObject.AddComponent<TextMeshProUGUI>();\r\n        TMP_FontAsset f = Font;\r\n        if (f != null) t.font = f;\r\n        t.fontSize = size;\r\n        t.color = color;\r\n        t.alignment = align;\r\n        t.textWrappingMode = TextWrappingModes.NoWrap;\r\n        t.overflowMode = TextOverflowModes.Overflow;\r\n        t.raycastTarget = false;\r\n        t.text = s;\r\n        ApplyOutline(t, new Color32(18, 14, 10, 255), 0.16f);\r\n        return t;\r\n    }\r\n\r\n    /// TMP 的描边只能改 SDF 材质：启用 OUTLINE_ON 关键字再写宽度，加组件没用\r\n    internal static void ApplyOutline(TextMeshProUGUI t, Color32 color, float width)\r\n    {\r\n        Material m = t.fontMaterial;\r\n        if (m == null || !m.HasProperty(\"_OutlineWidth\")) return;\r\n        m.EnableKeyword(\"OUTLINE_ON\");\r\n        m.SetFloat(\"_OutlineWidth\", width);\r\n        m.SetColor(\"_OutlineColor\", color);\r\n    }\r\n\r\n    static Sprite MakeRounded(int size, float radius)\r\n    {\r\n        Texture2D t = new Texture2D(size, size, TextureFormat.RGBA32, false);\r\n        t.wrapMode = TextureWrapMode.Clamp;\r\n        t.filterMode = FilterMode.Bilinear;\r\n        Color[] px = new Color[size * size];\r\n        float r = Mathf.Min(radius, size * 0.5f - 1f);\r\n        for (int y = 0; y < size; y++)\r\n        {\r\n            for (int x = 0; x < size; x++)\r\n            {\r\n                float fx = x + 0.5f, fy = y + 0.5f;\r\n                float cx = Mathf.Clamp(fx, r, size - r);\r\n                float cy = Mathf.Clamp(fy, r, size - r);\r\n                float d = Mathf.Sqrt((fx - cx) * (fx - cx) + (fy - cy) * (fy - cy));\r\n                float a = Mathf.Clamp01(r - d + 0.5f);\r\n                px[y * size + x] = new Color(1f, 1f, 1f, a);\r\n            }\r\n        }\r\n        t.SetPixels(px);\r\n        t.Apply();\r\n        t.hideFlags = HideFlags.HideAndDontSave;\r\n        Sprite s = Sprite.Create(t, new Rect(0f, 0f, size, size), new Vector2(0.5f, 0.5f), 100f,\r\n            0, SpriteMeshType.FullRect, new Vector4(r, r, r, r));\r\n        s.hideFlags = HideFlags.HideAndDontSave;\r\n        return s;\r\n    }\r\n\r\n    static Sprite MakeTriangle(int size)\r\n    {\r\n        Texture2D t = new Texture2D(size, size, TextureFormat.RGBA32, false);\r\n        t.wrapMode = TextureWrapMode.Clamp;\r\n        t.filterMode = FilterMode.Bilinear;\r\n        Color[] px = new Color[size * size];\r\n        for (int y = 0; y < size; y++)\r\n        {\r\n            float v = (y + 0.5f) / size;                 // 0 = 底部, 1 = 顶部\r\n            float halfW = 0.46f * (1f - v);              // 越往上越窄 → 朝上的三角形\r\n            for (int x = 0; x < size; x++)\r\n            {\r\n                float u = (x + 0.5f) / size - 0.5f;\r\n                float a = Mathf.Clamp01((halfW - Mathf.Abs(u)) * size * 1.1f + 0.5f);\r\n                px[y * size + x] = new Color(1f, 1f, 1f, a);\r\n            }\r\n        }\r\n        t.SetPixels(px);\r\n        t.Apply();\r\n        t.hideFlags = HideFlags.HideAndDontSave;\r\n        Sprite s = Sprite.Create(t, new Rect(0f, 0f, size, size), new Vector2(0.5f, 0.5f));\r\n        s.hideFlags = HideFlags.HideAndDontSave;\r\n        return s;\r\n    }\r\n}\r\n\r\ninternal class NbHud : MonoBehaviour\r\n{\r\n    internal static NbHud I;\r\n\r\n    static readonly Color Cream = new Color(1.00f, 0.97f, 0.90f, 1f);\r\n    static readonly Color Gold = new Color(1.00f, 0.86f, 0.36f, 1f);\r\n    static readonly Color Dim = new Color(0.86f, 0.82f, 0.74f, 1f);\r\n    static readonly Color Panel = new Color(0.10f, 0.09f, 0.08f, 0.62f);\r\n\r\n    TextMeshProUGUI _level;\r\n    TextMeshProUGUI _count;\r\n    TextMeshProUGUI _catLine;\r\n    TextMeshProUGUI _pickLabel;     // 目标物标签：四个场景都叫 CHEESE\r\n    TextMeshProUGUI _toast;\r\n    TextMeshProUGUI _probe;\r\n    TextMeshProUGUI _hpText;\r\n    TextMeshProUGUI _alert;         // \"SPOTTED - SHIFT TO RUN\"（只在被保安追时出现）\r\n\r\n    /// 生命条被画成 **10 个小格子**，一格 = 一口 = 10 点血。\r\n    /// 不用一条连续的长条，是因为\"还能挨几口\"是这个游戏唯一需要瞬间读出的数字；\r\n    /// 连续条的 70% 和 60% 在余光里分不出来，少一格却一眼就看见。\r\n    readonly Image[] _hpSegs = new Image[NbLevels.StartHp / NbLevels.BiteDamage];\r\n\r\n    Image _flash;\r\n\r\n    GameObject _endRoot;\r\n    TextMeshProUGUI _endTitle;\r\n    TextMeshProUGUI _endSub;\r\n    TextMeshProUGUI _endKey;\r\n\r\n    // ── 场景专属的第二根条 ──\r\n    // 后院是曝光（EXPOSURE），厨房是新鲜度（FRESH）。\r\n    // **只做一个控件、换标签和颜色**，因为这两件事永远不会同时出现；\r\n    // 各做一套只会让 Build() 里多一倍坐标要维护，而且两套永远有一套是死的。\r\n    GameObject _meterRoot;\r\n    TextMeshProUGUI _meterLabel;\r\n    Image _meterFill;\r\n    const float MeterW = 520f;\r\n\r\n    // ── 底部排版（改之前先看这张表）──\r\n    // 旧版这一块是**叠着**的：吐司条占 y 66…118，而曝光条的标签正好在 66…94，两行字直接压在一起；\r\n    // 左下角那行操作提示宽 1040 px，一直伸到屏幕中间，从曝光条下面穿过去；F1 读数条同理。\r\n    // 现在每个东西都有自己的水平区间和高度：\r\n    //   吐司    y 134…186（宽 1100，居中）\r\n    //   警告    y 192…236（宽 1000，居中）\r\n    //   状态条  y  58…120，其中标签 97…125（宽 560，居中 ⇒ 屏幕 x 680…1240）\r\n    //   左下两行 **宽度一律 ≤620 px**（x 36…656），永远碰不到中间那根条。\r\n    const float ToastY = 160f;\r\n    const float AlertY = 214f;\r\n    const float LeftW = 620f;\r\n\r\n    internal static NbHud Create()\r\n    {\r\n        GameObject go = new GameObject(\"Neighbourhood HUD (auto)\");\r\n        NbHud hud = go.AddComponent<NbHud>();\r\n        hud.Build();\r\n        return hud;\r\n    }\r\n\r\n    void Awake()\r\n    {\r\n        I = this;\r\n    }\r\n\r\n    void OnDestroy()\r\n    {\r\n        if (I == this) I = null;\r\n    }\r\n\r\n    void Build()\r\n    {\r\n        GameObject canvasGo = new GameObject(\"Nb Canvas (auto)\", typeof(Canvas), typeof(CanvasScaler));\r\n        canvasGo.transform.SetParent(transform, false);\r\n        Canvas canvas = canvasGo.GetComponent<Canvas>();\r\n        canvas.renderMode = RenderMode.ScreenSpaceOverlay;\r\n        canvas.sortingOrder = 40;\r\n\r\n        CanvasScaler scaler = canvasGo.GetComponent<CanvasScaler>();\r\n        scaler.uiScaleMode = CanvasScaler.ScaleMode.ScaleWithScreenSize;\r\n        scaler.referenceResolution = new Vector2(1920f, 1080f);\r\n        scaler.matchWidthOrHeight = 0.5f;\r\n\r\n        Transform c = canvasGo.transform;\r\n\r\n        // ── 被抓时全屏红闪（最底层）──\r\n        RectTransform flashRt = NbUi.Rect(\"Flash\", c);\r\n        flashRt.anchorMin = Vector2.zero;\r\n        flashRt.anchorMax = Vector2.one;\r\n        flashRt.offsetMin = Vector2.zero;\r\n        flashRt.offsetMax = Vector2.zero;\r\n        _flash = flashRt.gameObject.AddComponent<Image>();\r\n        _flash.sprite = NbUi.White;\r\n        _flash.color = new Color(0.75f, 0.08f, 0.06f, 0f);\r\n        _flash.raycastTarget = false;\r\n\r\n        // ── 左上角：关卡 / 奶酪 / 猫数 ──\r\n        RectTransform card = NbUi.Rect(\"CheeseCard\", c);\r\n        card.anchorMin = card.anchorMax = card.pivot = new Vector2(0f, 1f);\r\n        card.anchoredPosition = new Vector2(36f, -36f);\r\n        card.sizeDelta = new Vector2(320f, 196f);\r\n\r\n        RectTransform cardBg = NbUi.Rect(\"Bg\", card);\r\n        cardBg.anchorMin = Vector2.zero;\r\n        cardBg.anchorMax = Vector2.one;\r\n        cardBg.offsetMin = Vector2.zero;\r\n        cardBg.offsetMax = Vector2.zero;\r\n        Image bg = cardBg.gameObject.AddComponent<Image>();\r\n        bg.sprite = NbUi.Round;\r\n        bg.type = Image.Type.Sliced;\r\n        bg.color = Panel;\r\n        bg.raycastTarget = false;\r\n\r\n        _level = NbUi.Text(\"Level\", card, \"LEVEL  1 / 10\", 24f, Gold, TextAlignmentOptions.TopLeft);\r\n        Place(_level.rectTransform, new Vector2(22f, -12f), new Vector2(280f, 30f));\r\n\r\n        TextMeshProUGUI label = NbUi.Text(\"Label\", card, \"CHEESE\", 22f, Dim, TextAlignmentOptions.TopLeft);\r\n        Place(label.rectTransform, new Vector2(22f, -46f), new Vector2(260f, 26f));\r\n        _pickLabel = label;\r\n\r\n        _count = NbUi.Text(\"Count\", card, \"0 / 2\", 58f, Cream, TextAlignmentOptions.TopLeft);\r\n        Place(_count.rectTransform, new Vector2(20f, -72f), new Vector2(230f, 66f));\r\n\r\n        _catLine = NbUi.Text(\"Cats\", card, \"CATS  1\", 22f, Gold, TextAlignmentOptions.TopLeft);\r\n        Place(_catLine.rectTransform, new Vector2(22f, -146f), new Vector2(260f, 28f));\r\n\r\n        // ── 左上角第二块：生命条 ──\r\n        RectTransform hpCard = NbUi.Rect(\"HpCard\", c);\r\n        hpCard.anchorMin = hpCard.anchorMax = hpCard.pivot = new Vector2(0f, 1f);\r\n        hpCard.anchoredPosition = new Vector2(36f, -244f);\r\n        hpCard.sizeDelta = new Vector2(320f, 96f);\r\n\r\n        RectTransform hpBg = NbUi.Rect(\"Bg\", hpCard);\r\n        hpBg.anchorMin = Vector2.zero;\r\n        hpBg.anchorMax = Vector2.one;\r\n        hpBg.offsetMin = Vector2.zero;\r\n        hpBg.offsetMax = Vector2.zero;\r\n        Image hpBgImg = hpBg.gameObject.AddComponent<Image>();\r\n        hpBgImg.sprite = NbUi.Round;\r\n        hpBgImg.type = Image.Type.Sliced;\r\n        hpBgImg.color = Panel;\r\n        hpBgImg.raycastTarget = false;\r\n\r\n        TextMeshProUGUI hpLabel = NbUi.Text(\"Label\", hpCard, \"HEALTH\", 22f, Dim, TextAlignmentOptions.TopLeft);\r\n        Place(hpLabel.rectTransform, new Vector2(22f, -12f), new Vector2(160f, 26f));\r\n\r\n        _hpText = NbUi.Text(\"Value\", hpCard, \"100 / 100\", 22f, Cream, TextAlignmentOptions.TopRight);\r\n        Place(_hpText.rectTransform, new Vector2(152f, -12f), new Vector2(146f, 26f));\r\n\r\n        // 10 格：宽 (276 - 9*3) / 10 = 24.9，节距 27.9\r\n        const float segW = 24.9f, segGap = 3f;\r\n        for (int i = 0; i < _hpSegs.Length; i++)\r\n        {\r\n            // 用纯白方块而不是圆角图：这是一排\"电池格\"，圆角切开后每格只剩两条竖边，\r\n            // 看起来像进度条被拉长了 —— 方格才数得清\"还剩几口\"。\r\n            Image seg = NbUi.Img(\"Seg\" + i, hpCard, new Color(0.55f, 0.78f, 0.42f, 1f));\r\n            seg.rectTransform.anchorMin = seg.rectTransform.anchorMax = seg.rectTransform.pivot = new Vector2(0f, 1f);\r\n            seg.rectTransform.anchoredPosition = new Vector2(22f + i * (segW + segGap), -48f);\r\n            seg.rectTransform.sizeDelta = new Vector2(segW, 20f);\r\n            _hpSegs[i] = seg;\r\n        }\r\n\r\n        // ── 底部提示条 ──\r\n        // 挪到曝光条**上方**（160 而不是 92）。92 的时候它和曝光条的标签（97…125）完全重合，\r\n        // 三个场景都会出现 \"LEVEL 1\" 压在 \"EXPOSURE\" 上。\r\n        _toast = NbUi.Text(\"Toast\", c, \"\", 38f, Cream, TextAlignmentOptions.Center);\r\n        RectTransform tr = _toast.rectTransform;\r\n        tr.anchorMin = tr.anchorMax = tr.pivot = new Vector2(0.5f, 0f);\r\n        tr.anchoredPosition = new Vector2(0f, ToastY);\r\n        tr.sizeDelta = new Vector2(1100f, 52f);\r\n        _toast.color = new Color(Cream.r, Cream.g, Cream.b, 0f);\r\n\r\n        // ── 被发现的警告 ──\r\n        // 只回答\"现在该做什么\"。玩家已经知道自己被发现了（手电变红、人正冲过来），\r\n        // 所以这里不写 \"YOU WERE SEEN\"，直接写距离；按键由同一秒弹出的吐司负责。\r\n        _alert = NbUi.Text(\"Alert\", c, \"SPOTTED  -  HIDE  5 m  AWAY\", 34f,\r\n            new Color(1f, 0.42f, 0.30f, 0f), TextAlignmentOptions.Center);\r\n        RectTransform ar = _alert.rectTransform;\r\n        ar.anchorMin = ar.anchorMax = ar.pivot = new Vector2(0.5f, 0f);\r\n        ar.anchoredPosition = new Vector2(0f, AlertY);\r\n        ar.sizeDelta = new Vector2(1000f, 44f);\r\n\r\n        // ── 操作提示（左下角）──\r\n        // 宽度压到 620：旧版 1040 会横穿屏幕中央，被曝光条压住一半。\r\n        TextMeshProUGUI hint = NbUi.Text(\"Hint\", c, \"WASD  MOVE     SHIFT  RUN     SPACE  JUMP     Q E  TURN\", 18f,\r\n            new Color(1f, 1f, 1f, 0.42f), TextAlignmentOptions.BottomLeft);\r\n        RectTransform hr = hint.rectTransform;\r\n        hr.anchorMin = hr.anchorMax = hr.pivot = new Vector2(0f, 0f);\r\n        hr.anchoredPosition = new Vector2(36f, 30f);\r\n        hr.sizeDelta = new Vector2(LeftW, 26f);\r\n\r\n        // ── 读数条（左下角，提示行上方一行）──\r\n        // 存在的理由很具体：画面一片均匀时，人眼分不清\"玩家没动\"和\"看不出在动\"。\r\n        // 这一行直接把坐标和实测速度摊开 —— 数字在跳就说明人真的在走。\r\n        // 字号 16、宽 620：它和上面那行一样，不能伸进屏幕中央（那里是状态条）。\r\n        _probe = NbUi.Text(\"Probe\", c, \"\", 16f, new Color(1f, 1f, 1f, 0.55f), TextAlignmentOptions.BottomLeft);\r\n        // 默认**开着**：这一行就是\"为什么动不了\"的现场读数（timeScale / MOVE / CC / 速度）。\r\n        // 默认关掉的话，出问题时还是只能靠日志猜 —— 而这正是前几轮反复卡住的地方。\r\n        _probe.enabled = true;\r\n        _probe.text = \"READOUT ...\";\r\n        RectTransform pr = _probe.rectTransform;\r\n        pr.anchorMin = pr.anchorMax = pr.pivot = new Vector2(0f, 0f);\r\n        pr.anchoredPosition = new Vector2(36f, 60f);\r\n        pr.sizeDelta = new Vector2(LeftW, 24f);\r\n\r\n        BuildMeter(c);\r\n        BuildEnd(c);\r\n        Debug.Log(\"[Nb] HUD 就位（关卡行 / 奶酪计数 / 猫数 / 10 格生命条）。\");\r\n    }\r\n\r\n    static void Place(RectTransform rt, Vector2 anchored, Vector2 size)\r\n    {\r\n        rt.anchorMin = rt.anchorMax = rt.pivot = new Vector2(0f, 1f);\r\n        rt.anchoredPosition = anchored;\r\n        rt.sizeDelta = size;\r\n    }\r\n\r\n    /// 底部中间那条状态条。放在这里而不是左上角，是因为它读的不是\"我有多少资源\"，\r\n    /// 而是\"我还能撑多久\"—— 这是在跑动中要看的，视线应该留在画面中央附近。\r\n    void BuildMeter(Transform c)\r\n    {\r\n        RectTransform root = NbUi.Rect(\"Meter\", c);\r\n        root.anchorMin = root.anchorMax = root.pivot = new Vector2(0.5f, 0f);\r\n        root.anchoredPosition = new Vector2(0f, 58f);\r\n        root.sizeDelta = new Vector2(560f, 62f);\r\n\r\n        RectTransform bg = NbUi.Rect(\"Bg\", root);\r\n        bg.anchorMin = bg.anchorMax = bg.pivot = new Vector2(0.5f, 0.5f);\r\n        bg.anchoredPosition = new Vector2(0f, -10f);\r\n        bg.sizeDelta = new Vector2(560f, 30f);\r\n        Image bgi = bg.gameObject.AddComponent<Image>();\r\n        bgi.sprite = NbUi.Round;\r\n        bgi.type = Image.Type.Sliced;\r\n        bgi.color = new Color(0.06f, 0.06f, 0.07f, 0.72f);\r\n        bgi.raycastTarget = false;\r\n\r\n        RectTransform track = NbUi.Rect(\"Track\", bg);\r\n        track.anchorMin = track.anchorMax = track.pivot = new Vector2(0f, 0.5f);\r\n        track.anchoredPosition = new Vector2(16f, 0f);\r\n        track.sizeDelta = new Vector2(MeterW, 12f);\r\n        Image ti = track.gameObject.AddComponent<Image>();\r\n        ti.sprite = NbUi.Round;\r\n        ti.type = Image.Type.Sliced;\r\n        ti.color = new Color(1f, 1f, 1f, 0.10f);\r\n        ti.raycastTarget = false;\r\n\r\n        RectTransform fill = NbUi.Rect(\"Fill\", track);\r\n        fill.anchorMin = fill.anchorMax = fill.pivot = new Vector2(0f, 0.5f);\r\n        fill.anchoredPosition = Vector2.zero;\r\n        fill.sizeDelta = new Vector2(0f, 12f);\r\n        _meterFill = fill.gameObject.AddComponent<Image>();\r\n        _meterFill.sprite = NbUi.Round;\r\n        _meterFill.type = Image.Type.Sliced;\r\n        _meterFill.color = Gold;\r\n        _meterFill.raycastTarget = false;\r\n\r\n        _meterLabel = NbUi.Text(\"Label\", root, \"EXPOSURE\", 22f, Dim, TextAlignmentOptions.Center);\r\n        PlaceCenter(_meterLabel.rectTransform, new Vector2(0f, 22f), new Vector2(560f, 28f));\r\n\r\n        _meterRoot = root.gameObject;\r\n        _meterRoot.SetActive(false);\r\n    }\r\n\r\n    /// label 传空 = 收起整条（街区没有这根条）。\r\n    /// t 是 0…1 的比例，col 决定\"这根条现在是什么心情\"：\r\n    /// 曝光用金→红，新鲜度用绿→红，玩家不需要读数字。\r\n    internal void SetMeter(string label, float t, Color col)\r\n    {\r\n        if (_meterRoot == null) return;\r\n\r\n        bool on = !string.IsNullOrEmpty(label);\r\n        if (_meterRoot.activeSelf != on) _meterRoot.SetActive(on);\r\n        if (!on) return;\r\n\r\n        _meterLabel.text = label;\r\n        _meterLabel.color = col;\r\n        _meterFill.color = col;\r\n\r\n        RectTransform rt = _meterFill.rectTransform;\r\n        Vector2 sz = rt.sizeDelta;\r\n        sz.x = Mathf.Clamp01(t) * MeterW;\r\n        rt.sizeDelta = sz;\r\n    }\r\n\r\n    void BuildEnd(Transform c)\r\n    {\r\n        RectTransform root = NbUi.Rect(\"End\", c);\r\n        root.anchorMin = root.anchorMax = root.pivot = new Vector2(0.5f, 0.5f);\r\n        root.anchoredPosition = Vector2.zero;\r\n        root.sizeDelta = new Vector2(780f, 300f);\r\n\r\n        Image bg = root.gameObject.AddComponent<Image>();\r\n        bg.sprite = NbUi.Round;\r\n        bg.type = Image.Type.Sliced;\r\n        bg.color = new Color(0.08f, 0.07f, 0.06f, 0.90f);\r\n        bg.raycastTarget = false;\r\n\r\n        // 文案全部由 NbGame 在过关 / 失败那一刻填 —— 这里是 10 关，同一块面板要报\r\n        // \"第几关通过 / 全部通关 / 第几关死了\" 三种完全不同的结果，写死的字一定会说错话。\r\n        _endTitle = NbUi.Text(\"Title\", root, \"LEVEL  1  CLEAR\", 54f, Gold, TextAlignmentOptions.Center);\r\n        PlaceCenter(_endTitle.rectTransform, new Vector2(0f, 74f), new Vector2(720f, 80f));\r\n\r\n        _endSub = NbUi.Text(\"Sub\", root, \"\", 26f, Cream, TextAlignmentOptions.Center);\r\n        PlaceCenter(_endSub.rectTransform, new Vector2(0f, 6f), new Vector2(720f, 40f));\r\n\r\n        _endKey = NbUi.Text(\"Key\", root, \"PRESS  R  TO  CONTINUE\", 24f, Dim, TextAlignmentOptions.Center);\r\n        PlaceCenter(_endKey.rectTransform, new Vector2(0f, -74f), new Vector2(720f, 36f));\r\n\r\n        _endRoot = root.gameObject;\r\n        _endRoot.SetActive(false);\r\n    }\r\n\r\n    static void PlaceCenter(RectTransform rt, Vector2 anchored, Vector2 size)\r\n    {\r\n        rt.anchorMin = rt.anchorMax = rt.pivot = new Vector2(0.5f, 0.5f);\r\n        rt.anchoredPosition = anchored;\r\n        rt.sizeDelta = size;\r\n    }\r\n\r\n    /// 过关 / 失败共用一块面板。`good = true` 用金色标题（过关），false 用红色（血被咬光）。\r\n    internal void ShowEnd(string title, string sub, string key, bool good)\r\n    {\r\n        if (_endRoot == null) return;\r\n\r\n        Color head = good ? Gold : new Color(0.95f, 0.36f, 0.30f, 1f);\r\n        if (_endTitle != null) { _endTitle.text = title; _endTitle.color = head; }\r\n        if (_endSub != null) _endSub.text = sub;\r\n        if (_endKey != null) _endKey.text = key;\r\n\r\n        _endRoot.SetActive(true);\r\n    }\r\n\r\n    internal void HideEnd()\r\n    {\r\n        if (_endRoot != null) _endRoot.SetActive(false);\r\n        if (_toast != null) _toast.color = new Color(Cream.r, Cream.g, Cream.b, 0f);\r\n    }\r\n\r\n    void Update()\r\n    {\r\n        NbGame g = NbGame.I;\r\n        if (g == null) return;\r\n\r\n        if (_level != null) _level.text = \"LEVEL  \" + g.Level + \" / \" + NbLevels.Count;\r\n\r\n        if (_count != null)\r\n        {\r\n            int need = Mathf.Max(1, g.CheeseNeeded);\r\n            int shown = Mathf.Clamp(g.Collected, 0, need);\r\n            _count.text = shown + \" / \" + need;\r\n            _count.color = shown >= need ? Gold : Cream;\r\n        }\r\n\r\n        if (_catLine != null)\r\n        {\r\n            if (NbScene.UsesDoor)\r\n            {\r\n                // 冰箱里没有猫，但玩家会**在六层之间迷路** —— 这才是这一行该回答的问题。\r\n                // 层号与定位器上的方块数字共用 NbFridge.ShelfOf，两处不会差一级。\r\n                // 总层数是 Layers + 1（底层地板 + 六块板的顶面 = 7 个可站的层）。\r\n                float y = g.Player != null ? g.Player.position.y : 0f;\r\n                int shelf = NbFridge.ShelfOf(y);\r\n                _catLine.text = \"SHELF  \" + shelf + \" / \" + (NbFridge.Layers + 1);\r\n                _catLine.color = new Color(0.62f, 0.84f, 1f, 1f);\r\n            }\r\n            else if (NbScene.UsesGuards)\r\n            {\r\n                // 后院没有猫了（用户要求删掉），这一行改报**保安人数**。\r\n                // 写死 \"CATS 0\" 会让玩家以为猫还没刷出来，而不是\"这关本来就没有猫\"。\r\n                _catLine.text = \"GUARDS  \" + g.Guards.Count;\r\n                _catLine.color = g.Chased ? new Color(1f, 0.42f, 0.30f, 1f) : Gold;\r\n            }\r\n            else\r\n            {\r\n                // 猫多起来的时候把这一行染红：第 8 关往后\"全是猫\"这件事应该在余光里就能看见。\r\n                _catLine.text = \"CATS  \" + g.CatCount;\r\n                _catLine.color = g.CatCount >= 8 ? new Color(0.95f, 0.42f, 0.34f, 1f) : Gold;\r\n            }\r\n        }\r\n\r\n        // 四个场景的目标物**都是奶酪**，标签不再跟着场景变。\r\n        if (_pickLabel != null) _pickLabel.text = \"CHEESE\";\r\n\r\n        if (_hpText != null) _hpText.text = g.Hp + \" / \" + g.MaxHp;\r\n\r\n        // 一格 = 一口 = BiteDamage 点。满血全亮，掉血从右往左灭 —— 读起来就是\"被咬掉一块\"。\r\n        int bite = Mathf.Max(1, NbLevels.BiteDamage);\r\n        int live = Mathf.Clamp(g.Hp / bite, 0, _hpSegs.Length);\r\n        Color segOn = live >= 7 ? new Color(0.55f, 0.78f, 0.42f, 1f)\r\n                    : live >= 4 ? new Color(0.98f, 0.74f, 0.28f, 1f)\r\n                                : new Color(0.92f, 0.28f, 0.22f, 1f);\r\n        for (int i = 0; i < _hpSegs.Length; i++)\r\n        {\r\n            if (_hpSegs[i] == null) continue;\r\n            _hpSegs[i].color = i < live ? segOn : new Color(0.20f, 0.17f, 0.15f, 0.85f);\r\n        }\r\n\r\n        if (_toast != null)\r\n        {\r\n            bool on = g.ToastT > 0f && !string.IsNullOrEmpty(g.Toast);\r\n            _toast.text = g.Toast;\r\n            float a = on ? Mathf.Clamp01(g.ToastT * 2f) : 0f;\r\n            _toast.color = new Color(Cream.r, Cream.g, Cream.b, a);\r\n            _toast.rectTransform.anchoredPosition = new Vector2(0f, ToastY + (1f - a) * -8f);\r\n        }\r\n\r\n        if (_flash != null)\r\n        {\r\n            float a = Mathf.Clamp01(g.Flash) * 0.42f;\r\n            _flash.color = new Color(0.75f, 0.08f, 0.06f, a);\r\n        }\r\n\r\n        // 被追的时候这条会**呼吸**：静止的红字在余光里会被当成 HUD 的一部分，闪的不会。\r\n        // 结算面板出现后立刻收掉 —— 那时候\"快跑\"已经没有意义了。\r\n        if (_alert != null)\r\n        {\r\n            bool on = g.Chased && !g.Finished;\r\n            float a = on ? 0.70f + 0.30f * Mathf.Abs(Mathf.Sin(Time.unscaledTime * 4f)) : 0f;\r\n            _alert.color = new Color(1f, 0.42f, 0.30f, a);\r\n        }\r\n\r\n        // ── 读数条：坐标 / 实测速度 / 最近的猫 ──\r\n        // 这一行是给\"到底走没走\"这个问题用的：画面均匀时人眼分不清，\r\n        // 但 SPEED 只要不是 0 就说明输入 → CharacterController 这条链是通的。\r\n        if (_probe != null)\r\n        {\r\n            var kb = Keyboard.current;\r\n            if (kb != null && kb.f1Key.wasPressedThisFrame) _probe.enabled = !_probe.enabled;\r\n\r\n            if (_probe.enabled && g.Player != null)\r\n            {\r\n                Vector3 p = g.Player.position;\r\n\r\n                // EYE / PIT 这两项是给\"画面一动不动\"用的：\r\n                // EYE 是眼睛离脚底的高度（0.16 才对）；PIT 接近 ±80 说明相机被锁死低头/抬头。\r\n                // 两个都会让人以为\"走不动\"，因为画面里没有可参照的东西。\r\n                // 标签压到 3~4 个字母不是偷懒：这一行必须 ≤620 px（见 LeftW 的注释），\r\n                // 而且不能出现 `°` 这类符号 —— HUD 字体缺字形时是**静默空白**。\r\n                Camera cam = g.Rig != null ? g.Rig.Cam : null;\r\n                float eye = cam != null ? cam.transform.position.y - p.y : 0f;\r\n                float pitch = g.Rig != null ? g.Rig.Pitch : 0f;\r\n\r\n                _probe.text = string.Format(\r\n                    \"POS {0:F1}/{1:F1}  SPD {2:F1}  EYE {3:F2}  PIT {4:F0}  tS {5:F2}  MOVE {6}  CC {7}\",\r\n                    p.x, p.z, g.Speed, eye, pitch, Time.timeScale,\r\n                    (g.Rig != null && g.Rig.AcceptInput) ? \"ON\" : \"OFF\",\r\n                    (g.Rig != null && g.Rig.Cc != null && g.Rig.Cc.enabled) ? \"ON\" : \"OFF\");\r\n            }\r\n        }\r\n    }\r\n}\r\n"},"NbYard":{"path":"Assets/Scripts/NbYard.cs","role":"Backyard level: scattered cover points around a wide-open centre, patrolled by guards with flashlights.","source":"// @role Backyard level: scattered cover points around a wide-open centre, patrolled by guards with flashlights.\r\n// @calls NbScene Nb\r\n\r\n// NbYard.cs — 场景 02「夜巡后院」\r\n//\r\n// 这一关和街区唯一的区别就是**空间**，所以空间不能随便摆：\r\n//   街区 = 墙就是掩体，通道 5 m 宽，压力来自\"这条巷子里有没有猫\"；\r\n//   后院 = 掩体是点状的，中央 20 × 20 m 完全没有遮挡，压力来自\"从这丛灌木跑到那个垃圾桶要几秒\"。\r\n//\r\n// 两条硬约束，改场景时别破坏：\r\n//   ① 掩体必须**散**。排成一排就成了第二条街。\r\n//   ② 中央必须**空**（x 62…82，z −38…−18）。这块空地是整关的核心：\r\n//      玩家跑过去要 3~4 秒，而保安的手电 18 m 长 —— 快没用，得等光扫过去。\r\n//\r\n// 威胁是「保安 + 手电」，**没有猫**（用户明确要求删掉）：\r\n//   保安走 0.95 m/s（玩家走 2.30），慢得可笑，但手电锥 18 m、而且**四处扫**：\r\n//   走的时候在前方 ±55° 里乱扫（偶尔甩到 ±78°），到点站住 1~3 秒、整个人转过去照身后。\r\n//   他在自己那一带**随机游走**（航点 5~16 m、路径带缓弯），不是来回走直线 ——\r\n//   所以\"他什么时候背对我\"不能靠数秒数等到，只能当场看灯。\r\n//   被光扫到 0.3 秒后他会以 2.55~3.45 m/s 冲过来 —— 比走路快、比跑步慢，\r\n//   所以玩家的正确反应只有一个：按 Shift 跑到 5 m 之外的掩体后面。\r\n//   掩体不是装饰，是**唯一能切断\"他看见你\"的东西**（Sense 的第三条：射线被挡住）。\r\n//\r\n// 所有尺寸单位是米，地面 y = 0。\r\n\r\nusing UnityEngine;\r\n\r\ninternal static class NbYard\r\n{\r\n    // ───────────────────────── 范围 ─────────────────────────\r\n\r\n    internal const float XMin = 40f, XMax = 104f;    // 64 m\r\n    internal const float ZMin = -60f, ZMax = 0f;     // 60 m\r\n\r\n    internal const float CX = (XMin + XMax) * 0.5f;  // 72\r\n    internal const float CZ = (ZMin + ZMax) * 0.5f;  // −30\r\n\r\n    // 出生点在南侧小径上，朝北 —— 一进来看见整片院子，也看见那片躲不开的空地。\r\n    internal static readonly Vector3 Start = new Vector3(CX, 0.10f, -54f);\r\n    internal static readonly Vector3 Forward = new Vector3(0f, 0f, 1f);\r\n\r\n    // ───────────────────────── 调色板 ─────────────────────────\r\n    // 整体比街区更黑更绿：月光下草坪是墨绿，砖墙是发灰的暗红。\r\n    static readonly Color Grass   = new Color(0.13f, 0.19f, 0.12f);\r\n    static readonly Color Dirt    = new Color(0.22f, 0.18f, 0.14f);\r\n    static readonly Color WallCol = new Color(0.24f, 0.19f, 0.17f);\r\n    static readonly Color WallCap = new Color(0.31f, 0.27f, 0.23f);\r\n    static readonly Color HouseCol = new Color(0.20f, 0.19f, 0.19f);\r\n    static readonly Color Door    = new Color(0.09f, 0.07f, 0.06f);\r\n    static readonly Color BushA   = new Color(0.09f, 0.17f, 0.10f);\r\n    static readonly Color BushB   = new Color(0.12f, 0.22f, 0.12f);\r\n    static readonly Color BinA    = new Color(0.14f, 0.16f, 0.15f);\r\n    static readonly Color BinB    = new Color(0.11f, 0.13f, 0.12f);\r\n    static readonly Color Wood    = new Color(0.20f, 0.15f, 0.10f);\r\n    static readonly Color RoofCol = new Color(0.16f, 0.13f, 0.11f);\r\n    static readonly Color ShedCol = new Color(0.17f, 0.16f, 0.14f);\r\n    static readonly Color Cloth   = new Color(0.34f, 0.33f, 0.31f);\r\n    static readonly Color Soil    = new Color(0.15f, 0.12f, 0.09f);\r\n\r\n    // ───────────────────────── 10 个目标点 ─────────────────────────\r\n    // **反过来是刻意的**：街区的顺序是\"离出生点由近到远\"，后院也是 ——\r\n    // 但后院的\"近\"指的是沿掩体走，不是直线。第 1 关两块就在门口，\r\n    // 第 10 关最后一块在东北角柴垛后面，要横穿整片空地。\r\n    //\r\n    // 距离基准是出生点 (72, −54)，平面直线距离写在行尾。\r\n\r\n    internal static readonly Vector3[] Spots =\r\n    {\r\n        new Vector3(72f, 0f, -48f),    // 出生点正前的小径上             6.0 m\r\n        new Vector3(60f, 0f, -46f),    // 西南灌木丛旁                  14.4 m\r\n        new Vector3(86f, 0f, -44f),    // 东南灌木丛旁                  17.2 m\r\n        new Vector3(52f, 0f, -40f),    // 西南角                        24.1 m\r\n        new Vector3(96f, 0f, -40f),    // 东南角                        27.7 m\r\n        new Vector3(48f, 0f, -26f),    // 西侧中段（工具棚后）           36.9 m\r\n        new Vector3(100f, 0f, -26f),   // 东侧中段                      39.7 m\r\n        new Vector3(56f, 0f, -12f),    // 西北（狗屋旁）                 44.8 m\r\n        new Vector3(72f, 0f, -6f),     // 北侧正中（主屋后门）           48.0 m\r\n        new Vector3(100f, 0f, -12f),   // 东北（柴垛后）                 50.6 m\r\n    };\r\n\r\n    // ───────────────────────── 10 条巡逻地带 ─────────────────────────\r\n    // 保安**不再沿线段来回走**，而是拿这条线段当轴线、在两侧 ±7 m 里随机取航点\r\n    // （见 NbGuard.PickWaypoint）—— 所以这一组数据定义的是\"谁守哪一带\"，不是\"他走哪条线\"。\r\n    // **地带的轴线是穿过空地的**（第 2、5 条）——\r\n    // 空地既是玩家的风险，也是巡逻者的主导区域；如果地带只沿着围墙，\r\n    // 玩家可以一直贴着掩体走，这一关就没有\"必须横穿\"的时刻了。\r\n    // （猫已经删掉了，但 Routes 仍然是 NbScene 的通用接口：别的场景还要用。）\r\n\r\n    internal static readonly Vector3[][] Routes =\r\n    {\r\n        new[] { new Vector3(48f, 0f, -50f), new Vector3(96f, 0f, -50f) },    // 0 南侧横扫\r\n        new[] { new Vector3(48f, 0f, -20f), new Vector3(96f, 0f, -20f) },    // 1 北侧横扫（穿空地北缘）\r\n        new[] { new Vector3(72f, 0f, -46f), new Vector3(72f, 0f, -10f) },    // 2 中轴纵穿（直穿空地）\r\n        new[] { new Vector3(56f, 0f, -40f), new Vector3(56f, 0f, -14f) },    // 3 西中纵线\r\n        new[] { new Vector3(88f, 0f, -40f), new Vector3(88f, 0f, -14f) },    // 4 东中纵线\r\n        new[] { new Vector3(44f, 0f, -34f), new Vector3(100f, 0f, -34f) },   // 5 横穿空地南缘\r\n        new[] { new Vector3(44f, 0f, -6f),  new Vector3(100f, 0f, -6f) },    // 6 沿主屋\r\n        new[] { new Vector3(46f, 0f, -44f), new Vector3(46f, 0f, -8f) },     // 7 沿西墙\r\n        new[] { new Vector3(100f, 0f, -44f), new Vector3(100f, 0f, -8f) },   // 8 沿东墙\r\n        new[] { new Vector3(56f, 0f, -52f), new Vector3(88f, 0f, -30f) },    // 9 斜穿（会从出生点前方掠过）\r\n    };\r\n\r\n    // ───────────────────────── 小地图要画的掩体 ─────────────────────────\r\n    //\r\n    // (x, z, 宽, 深)。**必须和 Cover() 里摆的尺寸一致** ——\r\n    // 地图上多一块或漏一块，玩家就会按错误的地形做决策，而这一关的全部玩法就是地形。\r\n    // 灌木在 3D 里是球，这里按外接方框画：小地图只负责\"这块能不能躲\"，不需要形状精度。\r\n\r\n    internal static readonly Vector4[] MapCover =\r\n    {\r\n        new Vector4(60.0f, -46f, 3.0f, 3.0f),   // Bush SW\r\n        new Vector4(86.0f, -44f, 3.2f, 3.2f),   // Bush SE\r\n        new Vector4(52.0f, -25f, 2.8f, 2.8f),   // Bush W\r\n        new Vector4(94.0f, -24f, 3.0f, 3.0f),   // Bush E\r\n        new Vector4(66.0f, -11f, 2.9f, 2.9f),   // Bush NW\r\n        new Vector4(82.0f, -13f, 2.6f, 2.6f),   // Bush NE\r\n        new Vector4(47.5f, -44f, 2.8f, 2.6f),   // Bins W\r\n        new Vector4(98.0f, -38f, 2.8f, 2.6f),   // Bins E\r\n        new Vector4(99.0f, -14f, 2.6f, 1.4f),   // Woodpile\r\n        new Vector4(56.0f, -10f, 2.2f, 2.0f),   // Dog House\r\n        new Vector4(44.5f, -17f, 3.4f, 3.0f),   // Shed\r\n    };\r\n\r\n    // ───────────────────────── 写进当前场景 ─────────────────────────\r\n\r\n    internal static void Setup()\r\n    {\r\n        NbScene.Name  = \"BACKYARD PATROL\";\r\n        NbScene.Code  = \"YARD\";\r\n        NbScene.Blurb = \"One open lawn.  Nothing to hide behind in the middle.\";\r\n\r\n        NbScene.XMin = XMin;\r\n        NbScene.XMax = XMax;\r\n        NbScene.ZMin = ZMin;\r\n        NbScene.ZMax = ZMax;\r\n\r\n        NbScene.Start   = Start;\r\n        NbScene.Forward = Forward;\r\n        NbScene.Targets = Spots;\r\n        NbScene.Routes  = Routes;\r\n        NbScene.MaxTargets = Spots.Length;\r\n        NbScene.MaxRoutes  = Routes.Length;\r\n    }\r\n\r\n    // ───────────────────────── 搭场景 ─────────────────────────\r\n\r\n    internal static void Build(Transform p)\r\n    {\r\n        Ground(p);\r\n        Walls(p);\r\n        House(p);\r\n        Cover(p);\r\n        Clothesline(p, \"Line W\", -42f, 34f);\r\n        Clothesline(p, \"Line E\", -24f, 30f);\r\n        Beds(p);\r\n\r\n        Debug.LogFormat(\"[Nb] 后院就位：{0:F0} × {1:F0} m，中央 20 × 20 m 空地无掩体，\" +\r\n                        \"{2} 个目标点、{3} 段巡逻线。\",\r\n            XMax - XMin, ZMax - ZMin, Spots.Length, Routes.Length);\r\n    }\r\n\r\n    /// 地面是一块**实体**薄板（玩家要站在上面），土路只是贴在地上的色块、不参与碰撞。\r\n    static void Ground(Transform p)\r\n    {\r\n        Nb.Box(p, \"Yard Ground\", new Vector3(CX, -0.20f, CZ),\r\n            new Vector3(XMax - XMin, 0.40f, ZMax - ZMin), Grass, true);\r\n\r\n        Nb.Box(p, \"Path N-S\", new Vector3(CX, 0.004f, CZ),\r\n            new Vector3(2.2f, 0.008f, ZMax - ZMin - 1.5f), Dirt, false);\r\n        Nb.Box(p, \"Path E-W\", new Vector3(CX, 0.006f, -34f),\r\n            new Vector3(XMax - XMin - 1.5f, 0.008f, 2.0f), Dirt, false);\r\n    }\r\n\r\n    /// 南 / 西 / 东三面砖墙，北面是主屋自己挡着。墙厚 0.4、高 2.6 ——\r\n    /// 比玩家高 8 倍，比保安的视线高 2 倍，靠跳是看不到院外的。\r\n    static void Walls(Transform p)\r\n    {\r\n        const float h = 2.6f, t = 0.40f;\r\n\r\n        Nb.Box(p, \"Yard Wall S\", new Vector3(CX, h * 0.5f, ZMin + t * 0.5f),\r\n            new Vector3(XMax - XMin, h, t), WallCol, true);\r\n        Nb.Box(p, \"Yard Wall W\", new Vector3(XMin + t * 0.5f, h * 0.5f, CZ),\r\n            new Vector3(t, h, ZMax - ZMin), WallCol, true);\r\n        Nb.Box(p, \"Yard Wall E\", new Vector3(XMax - t * 0.5f, h * 0.5f, CZ),\r\n            new Vector3(t, h, ZMax - ZMin), WallCol, true);\r\n\r\n        // 压顶：给墙一条亮边，夜里才看得出\"这是边界\"而不是一片黑\r\n        Nb.Box(p, \"Yard Cap S\", new Vector3(CX, h + 0.06f, ZMin + t * 0.5f),\r\n            new Vector3(XMax - XMin, 0.12f, t + 0.12f), WallCap, false);\r\n        Nb.Box(p, \"Yard Cap W\", new Vector3(XMin + t * 0.5f, h + 0.06f, CZ),\r\n            new Vector3(t + 0.12f, 0.12f, ZMax - ZMin), WallCap, false);\r\n        Nb.Box(p, \"Yard Cap E\", new Vector3(XMax - t * 0.5f, h + 0.06f, CZ),\r\n            new Vector3(t + 0.12f, 0.12f, ZMax - ZMin), WallCap, false);\r\n    }\r\n\r\n    /// 北侧的主屋（玩家从后院看是\"房子背面\"）。它同时是北边界和一整片遮挡 ——\r\n    /// 第 8、9、10 关的目标点藏在它的屋檐下。\r\n    static void House(Transform p)\r\n    {\r\n        Nb.Box(p, \"House Back\", new Vector3(CX, 2.0f, ZMax + 1.8f),\r\n            new Vector3(XMax - XMin, 4.0f, 3.6f), HouseCol, true);\r\n\r\n        // 后门 + 门前的两级台阶（台阶是装饰，不挡人）\r\n        Nb.Box(p, \"Back Door\", new Vector3(CX, 1.05f, ZMax - 0.03f),\r\n            new Vector3(1.10f, 2.10f, 0.10f), Door, false);\r\n        Nb.Box(p, \"Step Low\", new Vector3(CX, 0.07f, ZMax - 0.55f),\r\n            new Vector3(1.60f, 0.14f, 0.90f), WallCap, false);\r\n        Nb.Box(p, \"Step High\", new Vector3(CX, 0.16f, ZMax - 0.20f),\r\n            new Vector3(1.30f, 0.10f, 0.50f), WallCap, false);\r\n\r\n        // 两扇窗（自发光的暗黄）：夜里给北侧一点可辨的方向\r\n        for (int i = 0; i < 2; i++)\r\n        {\r\n            float x = CX + (i == 0 ? -9.5f : 9.5f);\r\n            Nb.Box(p, \"Window \" + i, new Vector3(x, 2.15f, ZMax - 0.02f),\r\n                new Vector3(1.30f, 1.05f, 0.06f), new Color(0.34f, 0.27f, 0.14f), false);\r\n        }\r\n    }\r\n\r\n    /// 掩体。**中央那块空地不许放任何东西** —— 见文件头。\r\n    static void Cover(Transform p)\r\n    {\r\n        // ── 灌木（球体碰撞：挡人、也挡保安的视线）──\r\n        Bush(p, \"Bush SW\", 60f, -46f, 3.0f);\r\n        Bush(p, \"Bush SE\", 86f, -44f, 3.2f);\r\n        Bush(p, \"Bush W\",  52f, -25f, 2.8f);\r\n        Bush(p, \"Bush E\",  94f, -24f, 3.0f);\r\n        Bush(p, \"Bush NW\", 66f, -11f, 2.9f);\r\n        Bush(p, \"Bush NE\", 82f, -13f, 2.6f);\r\n\r\n        // ── 垃圾桶堆（三只一组，靠墙）──\r\n        Bins(p, \"Bins W\", 47.5f, -44f);\r\n        Bins(p, \"Bins E\", 98.0f, -38f);\r\n\r\n        // ── 柴垛 / 狗屋 / 工具棚 ──\r\n        Nb.Box(p, \"Woodpile\", new Vector3(99f, 0.65f, -14f),\r\n            new Vector3(2.6f, 1.30f, 1.4f), Wood, true);\r\n        Nb.Box(p, \"Woodpile Cap\", new Vector3(99f, 1.36f, -14f),\r\n            new Vector3(2.9f, 0.14f, 1.7f), RoofCol, false);\r\n\r\n        Nb.Box(p, \"Dog House\", new Vector3(56f, 0.75f, -10f),\r\n            new Vector3(2.2f, 1.50f, 2.0f), Wood, true);\r\n        Nb.Box(p, \"Dog Roof\", new Vector3(56f, 1.62f, -10f),\r\n            new Vector3(2.7f, 0.22f, 2.5f), RoofCol, false);\r\n\r\n        Nb.Box(p, \"Shed\", new Vector3(44.5f, 1.05f, -17f),\r\n            new Vector3(3.4f, 2.10f, 3.0f), ShedCol, true);\r\n        Nb.Box(p, \"Shed Roof\", new Vector3(44.5f, 2.16f, -17f),\r\n            new Vector3(3.8f, 0.16f, 3.4f), RoofCol, false);\r\n    }\r\n\r\n    static void Bush(Transform p, string n, float x, float z, float d)\r\n    {\r\n        // 主球是实体的：它既是视觉主体，也是保安视线的遮挡物。\r\n        Nb.Ball(p, n, new Vector3(x, d * 0.30f, z), d, BushA, true);\r\n        // 两个小一点的副球不挡人，只是把轮廓打碎，别让灌木看起来像一个台球。\r\n        Nb.Ball(p, n + \" b\", new Vector3(x + d * 0.26f, d * 0.20f, z + d * 0.18f), d * 0.66f, BushB, false);\r\n        Nb.Ball(p, n + \" c\", new Vector3(x - d * 0.22f, d * 0.16f, z - d * 0.20f), d * 0.58f, BushB, false);\r\n    }\r\n\r\n    static void Bins(Transform p, string n, float x, float z)\r\n    {\r\n        Nb.Cyl(p, n + \" a\", new Vector3(x, 0.55f, z), 1.15f, 1.10f, BinA, true);\r\n        Nb.Cyl(p, n + \" b\", new Vector3(x + 0.95f, 0.50f, z + 0.55f), 1.05f, 1.00f, BinB, true);\r\n        Nb.Cyl(p, n + \" c\", new Vector3(x - 0.60f, 0.45f, z + 0.80f), 0.95f, 0.90f, BinA, true);\r\n    }\r\n\r\n    /// 晾衣绳：两根柱子是实体的（能挡人），绳子和布是装饰（挡不了人、也挡不了视线）。\r\n    /// 它横在院子里有两个作用：视觉上把空间切开，跑动时又不会真的挡路 ——\r\n    /// 玩家会本能地绕开它，于是路线被\"软\"约束了，这是空地设计的一部分。\r\n    static void Clothesline(Transform p, string n, float z, float len)\r\n    {\r\n        float hw = len * 0.5f;\r\n        Nb.Box(p, n + \" Post W\", new Vector3(CX - hw, 1.10f, z),\r\n            new Vector3(0.14f, 2.20f, 0.14f), Wood, true);\r\n        Nb.Box(p, n + \" Post E\", new Vector3(CX + hw, 1.10f, z),\r\n            new Vector3(0.14f, 2.20f, 0.14f), Wood, true);\r\n        Nb.Box(p, n + \" Rope\", new Vector3(CX, 2.08f, z),\r\n            new Vector3(len, 0.03f, 0.03f), Cloth, false);\r\n\r\n        for (int i = 0; i < 3; i++)\r\n        {\r\n            float x = CX - len * 0.30f + i * len * 0.28f;\r\n            Nb.Box(p, n + \" Cloth \" + i, new Vector3(x, 1.58f, z),\r\n                new Vector3(0.75f, 0.95f, 0.04f), Cloth, false);\r\n        }\r\n    }\r\n\r\n    /// 菜畦：只有 20 cm 高，**故意不加碰撞体** ——\r\n    /// 它是地面上唯一有颜色的东西，用来让玩家在暗处还能量距离（一条 3.6 m 的畦 ≈ 一秒半的跑动）。\r\n    static void Beds(Transform p)\r\n    {\r\n        float[] xs = { 62f, 68f, 76f, 82f };\r\n        for (int i = 0; i < xs.Length; i++)\r\n        {\r\n            Nb.Box(p, \"Bed \" + i, new Vector3(xs[i], 0.10f, -47f),\r\n                new Vector3(3.6f, 0.20f, 1.4f), Soil, false);\r\n            Nb.Box(p, \"Bed \" + i + \" Crop\", new Vector3(xs[i], 0.22f, -47f),\r\n                new Vector3(3.2f, 0.10f, 1.0f), BushB, false);\r\n        }\r\n    }\r\n}\r\n"},"Reset":{"path":"Assets/Scripts/Reset.cs","role":"Reset button: hides the current screen and brings the title screen back.","source":"// @role Reset button: hides the current screen and brings the title screen back.\r\n\r\nusing UnityEngine;\r\nusing UnityEngine.UI;\r\n\r\npublic class Reset : MonoBehaviour\r\n{\r\n    public Button reset;\r\n    public Canvas TitleScreen;\r\n    private Canvas canvas;\r\n    // Start is called once before the first execution of Update after the MonoBehaviour is created\r\n    void Start()\r\n    {\r\n        canvas = GetComponentInParent<Canvas>();\r\n        reset.onClick.AddListener(ResetScene);\r\n    }\r\n\r\n    // Update is called once per frame\r\n    void Update()\r\n    {\r\n        \r\n    }\r\n\r\n    private void ResetScene()\r\n    {\r\n        canvas.gameObject.SetActive(false);\r\n        TitleScreen.gameObject.SetActive(true);\r\n    }\r\n\r\n    private void OnDestroy()\r\n    {\r\n        reset.onClick.RemoveListener(ResetScene);\r\n    }\r\n}\r\n"}}};
